(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-antiquities-4-e", [{"sp": "HDR", "t": "Ἰουδαϊκὴ Ἀρχαιολογία"}, {"sp": "HDR", "t": "Βιβλίον ΙΒʹ", "st": "12"}, {"sp": "N", "t": "Ἀλέξανδρος μὲν οὖν ὁ τῶν Μακεδόνων βασιλεὺς καταλύσας τὴν Περσῶν ἡγεμονίαν καὶ τὰ κατὰ τὴν Ἰουδαίαν τὸν προειρημένον καταστησάμενος τρόπον τελευτᾷ τὸν βίον. μεταπεσούσης δ’ εἰς πολλοὺς τῆς ἀρχῆς Ἀντίγονος μὲν τῆς Ἀσίας ἐπικρατεῖ, Σέλευκος δὲ Βαβυλῶνος καὶ τῶν κεῖθι ἐθνῶν, Λυσίμαχός τε τὸν Ἑλλήσποντον διεῖπεν, τὴν δὲ Μακεδονίαν εἶχεν Κάσσανδρος, Πτολεμαῖος δὲ ὁ Λάγου τὴν Αἴγυπτον εἰλήφει. στασιαζόντων δὲ τούτων καὶ πρὸς ἀλλήλους φιλοτιμουμένων ὑπὲρ τῆς ἰδίας ἀρχῆς πολέμους τε συνεχεῖς καὶ μακροὺς συνέβη γίγνεσθαι καὶ τὰς πόλεις κακοπαθεῖν καὶ πολλοὺς ἐν τοῖς ἀγῶσιν ἀποβάλλειν τῶν οἰκητόρων, ὡς καὶ τὴν Συρίαν ἅπασαν ὑπὸ Πτολεμαίου τοῦ Λάγου τότε Σωτῆρος χρηματίζοντος τἀναντία παθεῖν αὐτοῦ τῇ ἐπικλήσει. κατέσχε δὲ οὗτος καὶ τὰ Ἱεροσόλυμα δόλῳ καὶ ἀπάτῃ χρησάμενος· ἐλθὼν γὰρ σαββάτοις εἰς τὴν πόλιν ὡς θύσων, μήτε τῶν Ἰουδαίων αὐτὸν ἀμυνομένων, οὐδὲν γὰρ ὑπενόουν πολέμιον, καὶ διὰ τὸ ἀνύποπτον καὶ τὴν ἡμέραν ἐν ἀργίᾳ καὶ ῥαθυμίᾳ τυγχανόντων, ἀπόνως ἐγκρατὴς γίγνεται τῆς πόλεως καὶ πικρῶς ἦρχεν αὐτῆς. μαρτυρεῖ δὲ τῷ λόγῳ τούτῳ καὶ Ἀγαθαρχίδης ὁ Κνίδιος ὁ τὰς τῶν διαδόχων πράξεις συγγραψάμενος, ὀνειδίζων ἡμῖν δεισιδαιμονίαν ὡς δι’ αὐτὴν ἀποβαλοῦσι τὴν ἐλευθερίαν, λέγων οὕτως· ἔστιν ἔθνος Ἰουδαίων λεγόμενον, οἳ πόλιν ὀχυρὰν καὶ μεγάλην ἔχοντες Ἱεροσόλυμα ταύτην ὑπερεῖδον ὑπὸ Πτολεμαίῳ γενομένην ὅπλα λαβεῖν οὐ θελήσαντες, ἀλλὰ διὰ τὴν ἄκαιρον δεισιδαιμονίαν χαλεπὸν ὑπέμειναν ἔχειν δεσπότην. Ἀγαθαρχίδης μὲν οὖν ταῦτα περὶ τοῦ ἔθνους ἡμῶν ἀπεφήνατο. ὁ δὲ Πτολεμαῖος πολλοὺς αἰχμαλώτους λαβὼν ἀπό τε τῆς ὀρεινῆς Ἰουδαίας καὶ τῶν περὶ Ἱεροσόλυμα τόπων καὶ τῆς Σαμαρείτιδος καὶ τῶν ἐν Γαριζείν, κατῴκισεν ἅπαντας εἰς Αἴγυπτον ἀγαγών. ἐπεγνωκὼς δὲ τοὺς ἀπὸ τῶν Ἱεροσολύμων περί τε τὴν τῶν ὅρκων φυλακὴν καὶ τὰς πίστεις βεβαιοτάτους ὑπάρχοντας ἐξ ὧν ἀπεκρίναντο Ἀλεξάνδρῳ πρεσβευσαμένῳ πρὸς αὐτοὺς μετὰ τὸ κρατῆσαι Δαρείου τῇ μάχῃ, πολλοὺς αὐτῶν εἰς τὰ φρούρια καταλοχίσας καὶ τοῖς Μακεδόσιν ἐν Ἀλεξανδρείᾳ ποιήσας ἰσοπολίτας ὅρκους ἔλαβεν παρ’ αὐτῶν, ὅπως τοῖς ἐκγόνοις τοῦ παραθεμένου τὴν πίστιν διαφυλάξωσιν. οὐκ ὀλίγοι δ’ οὐδὲ τῶν ἄλλων Ἰουδαίων εἰς τὴν Αἴγυπτον παρεγίγνοντο τῆς τε ἀρετῆς τῶν τόπων αὐτοὺς καὶ τῆς τοῦ Πτολεμαίου φιλοτιμίας προκαλουμένης. στάσεις μέντοι γε τοῖς ἐκγόνοις αὐτῶν πρὸς τοὺς Σαμαρείτας τὴν πάτριον ἀγωγὴν τῶν ἐθῶν ἀποσώζειν προαιρουμένοις ἐγίγνοντο καὶ πρὸς ἀλλήλους ἐπολέμουν, τῶν μὲν Ἱεροσολυμιτῶν τὸ παρ’ αὐτοῖς ἱερὸν ἅγιον εἶναι λεγόντων καὶ τὰς θυσίας ἐκεῖ πέμπειν ἀξιούντων, τῶν δὲ Σικιμιτῶν εἰς τὸ Γαριζεὶν ὄρος κελευόντων.", "st": "12.1.1"}, {"sp": "N", "t": "Βασιλεύσαντος δὲ Ἀλεξάνδρου ἔτη δώδεκα καὶ μετ’ αὐτὸν Πτολεμαίου τοῦ Σωτῆρος τεσσαράκοντα καὶ ἕν, ἔπειτα τὴν βασιλείαν τῆς Αἰγύπτου παραλαβὼν ὁ Φιλάδελφος καὶ κατασχὼν αὐτὴν ἐπ’ ἔτη ἑνὸς δέοντα τεσσαράκοντα τόν τε νόμον ἡρμήνευσε καὶ τοὺς δουλεύοντας ἐν Αἰγύπτῳ τῶν Ἱεροσολυμιτῶν ἀπέλυσε τῆς δουλείας ὄντας περὶ δώδεκα μυριάδας ἐξ αἰτίας τοιαύτης· Δημήτριος ὁ Φαληρεύς, ὃς ἦν ἐπὶ τῶν βιβλιοθηκῶν τοῦ βασιλέως, σπουδάζων εἰ δυνατὸν εἴη πάντα τὰ κατὰ τὴν οἰκουμένην συναγαγεῖν βιβλία καὶ συνωνούμενος, εἴ τι που μόνον ἀκούσειε σπουδῆς ἄξιον ὄν, τῇ τοῦ βασιλέως προαιρέσει, μάλιστα γὰρ τὰ περὶ τὴν συλλογὴν τῶν βιβλίων εἶχεν φιλοκάλως, συνηγωνίζετο. ἐρομένου δ’ αὐτόν ποτε τοῦ Πτολεμαίου, πόσας ἤδη μυριάδας ἔχοι συνειλεγμένας βιβλίων, τῶν μὲν ὑπαρχόντων εἶπεν εἶναι περὶ εἴκοσι, ὀλίγου δὲ χρόνου εἰς πεντήκοντα συναθροίσειν. μεμηνῦσθαι δ’ ἔλεγεν αὐτῷ πολλὰ εἶναι καὶ παρὰ Ἰουδαίοις τῶν παρ’ αὐτοῖς νομίμων συγγράμματα σπουδῆς ἄξια καὶ τῆς βασιλέως βιβλιοθήκης, ἃ τοῖς ἐκείνων χαρακτῆρσιν καὶ τῇ διαλέκτῳ γεγραμμένα πόνον αὐτοῖς οὐκ ὀλίγον παρέξειν εἰς τὴν Ἑλληνικὴν μεταβαλλόμενα γλῶτταν. δοκεῖ μὲν γὰρ εἶναι τῇ ἰδιότητι τῶν Συρίων γραμμάτων ἐμφερὴς ὁ χαρακτὴρ αὐτῶν καὶ τὴν φωνὴν ὁμοίαν αὐτοῖς ἀπηχεῖν, ἰδιότροπον δὲ αὐτὴν εἶναι συμβέβηκεν. οὐδὲν οὖν ἔλεγεν κωλύειν καὶ ταῦτα μεταβαλόντα, δύνασθαι γὰρ τῆς εἰς αὐτὸ χορηγίας εὐποροῦντα, ἔχειν ἐν τῇ βιβλιοθήκῃ καὶ τὰ παρ’ ἐκείνοις. δόξας οὖν ὁ βασιλεὺς ἄριστα τὸν Δημήτριον φιλοτιμουμένῳ περὶ πλῆθος αὐτῷ βιβλίων ὑποτίθεσθαι γράφει τῷ τῶν Ἰουδαίων ἀρχιερεῖ ταῦτα γίγνεσθαι.", "st": "12.2.1"}, {"sp": "N", "t": "Ἀρισταῖος δέ τις φίλος ὢν ἐν τοῖς μάλιστα τῷ βασιλεῖ καὶ σπουδαζόμενος ὑπ’ αὐτοῦ διὰ μετριότητα, πολλάκις μὲν καὶ πρότερον ἔγνω παρακαλέσαι τὸν βασιλέα, ὅπως ἀπολύσῃ τοὺς αἰχμαλώτους Ἰουδαίους ὅσοι κατὰ τὴν βασιλείαν ἦσαν αὐτοῦ, καιρὸν δ’ ἐπιτήδειον τοῦτον εἶναι δοκιμάσας τῆς δεήσεως πρώτοις περὶ τούτου διαλέγεται τοῖς ἄρχουσι τῶν σωματοφυλάκων Σωσιβίῳ τῷ Ταραντίνῳ καὶ Ἀνδρέᾳ, συναγωνίσασθαι περὶ ὧν ἐντυγχάνειν μέλλει τῷ βασιλεῖ παρακαλῶν αὐτούς. προσλαβὼν δὲ καὶ τὴν τῶν προειρημένων γνώμην ὁ Ἀρισταῖος, προσελθὼν τῷ βασιλεῖ λόγους πρὸς αὐτὸν τοιούτους ἐποιήσατο· οὐ χρῆν ἀπατωμένους ἡμᾶς, ὦ βασιλεῦ, περιορᾶν, ἀλλὰ τἀληθὲς ἀπελέγχειν· τοὺς γὰρ τῶν Ἰουδαίων νόμους οὐ μεταγράψαι μόνον ἀλλὰ καὶ μεθερμηνεῦσαι διεγνωκότες εἰς τὸ σοὶ κεχαρισμένον, τίνι καὶ λόγῳ χρώμενοι τοῦτο πράξαιμεν ἂν πολλῶν Ἰουδαίων ἐν τῇ σῇ βασιλείᾳ δουλευόντων; οὓς τῇ σαυτοῦ μεγαλοψυχίᾳ καὶ χρηστότητι ποιῶν ἀκολούθως ἀπόλυσον τῆς ταλαιπωρίας, τὴν βασιλείαν σου διέποντος τοῦ θεμένου τοὺς νόμους αὐτοῖς θεοῦ, καθὼς ἐμοὶ πολυπραγμονήσαντι μαθεῖν ὑπῆρξεν. τὸν γὰρ ἅπαντα συστησάμενον θεὸν καὶ οὗτοι καὶ ἡμεῖς σεβόμεθα Ζῆνα καλοῦντες αὐτὸν ἐτύμως ἀπὸ τοῦ πᾶσιν ἐμφύειν τὸ ζῆν τὴν ἐπίκλησιν αὐτοῦ θέντες. ὅθεν εἰς τιμὴν τοῦ θεοῦ τοὺς ἐξαίρετον τὴν εἰς αὐτὸν θρησκείαν πεποιημένους ἀπόδος τοῖς τὴν πατρίδα καὶ τὸν ἐν αὐτῇ βίον ἀπολελοιπόσιν. ἴσθι μέντοι γε, ὦ βασιλεῦ, ὡς οὔτε γένει προσήκων αὐτοῖς οὔτε ὁμόφυλος ὢν ταῦτα περὶ αὐτῶν ἀξιῶ, πάντων δὲ ἀνθρώπων δημιούργημα ὄντων τοῦ θεοῦ· καὶ δὴ γιγνώσκων αὐτὸν ἡδόμενον τοῖς εὖ ποιοῦσιν ἐπὶ τοῦτο καὶ σὲ παρακαλῶ.", "st": "12.2.2"}, {"sp": "N", "t": "Ταῦτ’ εἰπόντος τοῦ Ἀρισταίου ἀναβλέψας εἰς αὐτὸν ὁ βασιλεὺς ἱλαρῷ καὶ γεγηθότι τῷ προσώπῳ πόσας, εἶπεν, ὑπολαμβάνεις τῶν ἀπολυθησομένων ἔσεσθαι μυριάδας; ὑποτυχόντος δὲ Ἀνδρέου, παρειστήκει γάρ, καὶ φήσαντος ὀλίγῳ πλείονας ἔσεσθαι τῶν ἕνδεκα μυριάδων ἦ μικρὰν ἄρα εἶπεν, ἡμᾶς, Ἀρισταῖε, δωρεὰν αἰτεῖς. Σωσιβίου δὲ καὶ τῶν παρόντων φησάντων, ὡς ἄξιον αὐτὸν δέοι τῆς αὐτοῦ μεγαλοψυχίας τῷ παρεσχηκότι τὴν βασιλείαν θεῷ ποιήσασθαι χαριστήριον, διαχυθεὶς ὑπ’ αὐτῶν ἐκέλευσεν, ὅταν τοῖς στρατιώταις ἀποδιδῶσιν τὸ μισθοφορικόν, καὶ ὑπὲρ ἑκάστου τῶν παρ’ αὐτοῖς αἰχμαλώτων καταβαλεῖν δραχμὰς ἑκατὸν εἴκοσι. καὶ περὶ ὧν ἠξίουν προθεῖναι γράμματα ὑπέσχετο μεγαλοπρεπῶς τε ἔχοντα καὶ τὴν Ἀρισταίου προαίρεσιν βεβαιοῦντα καὶ πρὸ ταύτης τὴν τοῦ θεοῦ βούλησιν, καθ’ ἣν οὐ μόνον τοὺς ὑπὸ τοῦ πατρὸς ἀχθέντας αὐτοῦ καὶ τῆς ἐκείνου στρατιᾶς ἀπολύσειν ἔλεγεν, ἀλλὰ καὶ τοὺς προϋπάρχοντας ἐν τῇ βασιλείᾳ καὶ εἴ τινες αὖθις ἐπεισήχθησαν. πλειόνων δ’ ἢ τετρακοσίων ταλάντων τῆς ἀπολυτρώσεως γενήσεσθαι φαμένων ταῦτά τε συνεχώρει καὶ τὸ ἀντίγραφον τοῦ προστάγματος εἰς δήλωσιν τῆς τοῦ βασιλέως μεγαλοφροσύνης ἔγνωσαν διαφυλάξαι. ἦν δὲ τοιοῦτον· ὅσοι τῶν συστρατευσαμένων ἡμῶν τῷ πατρὶ τήν τε Συρίαν καὶ Φοινίκην ἐπέδραμον καὶ τὴν Ἰουδαίαν καταστρεψάμενοι σώματα λαβόντες αἰχμάλωτα διεκόμισαν εἴς τε τὰς πόλεις ἡμῶν καὶ τὴν χώραν καὶ ταῦτα ἀπημπόλησαν, τούς τε πρὸ αὐτῶν ὄντας ἐν τῇ ἐμῇ βασιλείᾳ καὶ εἴ τινες νῦν εἰσήχθησαν, τούτους ἀπολυέτωσαν οἱ παρ’ αὐτοῖς ἔχοντες ὑπὲρ ἑκάστου σώματος λαμβάνοντες δραχμὰς ἑκατὸν εἴκοσι, οἱ μὲν στρατιῶται μετὰ καὶ τῶν ὀψωνίων, οἱ δὲ λοιποὶ ἀπὸ τῆς βασιλικῆς τραπέζης κομιζόμενοι τὰ λύτρα. νομίζω γὰρ αὐτοὺς καὶ παρὰ τὴν τοῦ πατρὸς προαίρεσιν καὶ παρὰ τὸ δέον ᾐχμαλωτίσθαι, τήν τε χώραν αὐτῶν διὰ τὴν στρατιωτικὴν αὐθάδειαν κεκακῶσθαι, καὶ διὰ τὴν εἰς Αἴγυπτον αὐτῶν μεταγωγὴν πολλὴν ὠφέλειαν ἐκ τούτου τοῖς στρατιώταις γεγονέναι. τὸ δίκαιον οὖν σκοπῶν καὶ τοὺς καταδεδυναστευμένους παρὰ τὸ προσῆκον ἐλεῶν ἀπολύειν κελεύω τοὺς ἐν ταῖς οἰκετείαις ὄντας Ἰουδαίους τὸ προγεγραμμένον κομιζομένους ὑπὲρ αὐτῶν κεφάλαιον τοὺς κεκτημένους, καὶ μηδένα περὶ τούτων κακουργεῖν, ἀλλ’ ὑπακούειν τοῖς προστεταγμένοις. βούλομαι δὲ τὰς ἀπογραφὰς ἀφ’ ἧς ἐξεπέμφθησαν ἐπὶ τρεῖς ἡμέρας ποιεῖσθαι πρὸς τοὺς ἐπ’ αὐτῶν ὑπάρχοντας, παραδεικνύντας εὐθὺς καὶ τὰ σώματα· τοῦτο γὰρ τοῖς ἐμαυτοῦ πράγμασιν ἡγοῦμαι συμφέρειν. προσαγγελλέτω δὲ τοὺς ἀπειθήσαντας ὁ βουλόμενος, ὧν τὰς οὐσίας εἰς τὴν βασιλικὴν κτῆσιν ἀνενεχθῆναι βούλομαι. τούτου δὲ τοῦ προστάγματος ἀναγνωσθέντος τῷ βασιλεῖ καὶ τὰ μὲν ἄλλα ἔχοντος, μόνου δὲ λείποντος τοῦ περὶ τῶν πρότερον καὶ τῶν αὖθις εἰσηγμένων Ἰουδαίων μὴ διεστάλθαι, προσέθηκεν αὐτὸς μεγαλοφρόνως καὶ τὸ περὶ τούτων φιλάνθρωπον, καὶ τὴν τῶν διαφόρων δόσιν οὖσαν ἀθρόαν ἐκέλευσεν τοῖς ὑπηρέταις τῶν πραγμάτων ἀπομερίσαι καὶ τοῖς βασιλικοῖς τραπεζίταις. γενομένου δὲ τούτου ταχέως ἐν ἑπτὰ ταῖς πάσαις ἡμέραις τέλος εἰλήφει τὰ δοχθέντα τῷ βασιλεῖ, τάλαντα δ’ ὑπὲρ ἑξήκοντα καὶ τετρακόσια τῶν λύτρων ἐγένετο· καὶ γὰρ ὑπὲρ τῶν νηπίων εἰσέπραττον οἱ δεσπόται τὰς εἴκοσι καὶ ἑκατὸν δραχμάς, ὡς τοῦ βασιλέως καὶ ὑπὲρ τούτων διδόναι κελεύσαντος ἐν τῷ προγράψαι ὑπὲρ ἑκάστου σώματος λαμβάνειν τὸ προειρημένον.", "st": "12.2.3"}, {"sp": "N", "t": "Ἐπειδὴ δὲ ταῦτ’ ἐγένετο κατὰ τὴν τοῦ βασιλέως βούλησιν μεγαλοπρεπῶς, ἐκέλευσε τὸν Δημήτριον εἰσδοῦναι καὶ τὸ περὶ τῆς τῶν Ἰουδαϊκῶν βιβλίων ἀναγραφῆς δόγμα· οὐδὲν γὰρ εἰκῆ τοῖς βασιλεῦσιν ᾠκονομεῖτο, πάντα δὲ μετὰ πολλῆς ἐπιμελείας ἐπράττετο. διὸ καὶ τὸ τῆς εἰσδόσεως ἀντίγραφον καὶ τὸ τῶν ἐπιστολῶν κατατέτακται καὶ τὸ πλῆθος τῶν ἀπεσταλμένων ἀναθημάτων καὶ τὸ ἐφ’ ἑκάστου κατασκευασθέν, ὡς ἀκριβεστάτην εἶναι τὴν τοῦ τεχνίτου τοῖς ὁρῶσι μεγαλουργίαν, καὶ διὰ τὴν τῶν κατασκευασμάτων ἐξοχὴν τὸν ἑκάστου δημιουργὸν εὐθέως ποιήσειν γνώριμον. τῆς μέντοι γε εἰσδόσεως τὸ ἀντίγραφον ὑπῆρχε τοιοῦτον· βασιλεῖ μεγάλῳ παρὰ Δημητρίου. προστάξαντός σου, ὦ βασιλεῦ, περί τε τῶν ἔτι λειπόντων εἰς ἀναπλήρωσιν τῆς βιβλιοθήκης συγγραμμάτων, ὅπως συναχθῇ, καὶ περὶ τῶν διαπεπτωκότων, ὅπως τῆς δεούσης ἐπιμελείας τύχῃ, πάσῃ κεχρημένος περὶ ταῦτα σπουδῇ δηλῶ σοι τὰ τῆς Ἰουδαίων νομοθεσίας βιβλία λείπειν ἡμῖν σὺν ἑτέροις· χαρακτῆρσιν γὰρ Ἑβραϊκοῖς γεγραμμένα καὶ φωνῇ τῇ ἐθνικῇ ἐστιν ἡμῖν ἀσαφῆ. συμβέβηκε δ’ αὐτὰ καὶ ἀμελέστερον ἢ ἔδει σεσημάνθαι διὰ τὸ βασιλικῆς οὐ τετυχηκέναι προνοίας. ἔστι δ’ ἀναγκαῖον εἶναι καὶ ταῦτα παρὰ σοὶ διηκριβωμένα· φιλοσοφωτέραν γὰρ καὶ ἀκέραιον τὴν νομοθεσίαν εἶναι συμβέβηκεν ὡς ἂν οὖσαν θεοῦ. διὸ καὶ τοὺς ποιητὰς αὐτῆς καὶ τοὺς συγγραφεῖς τῶν ἱστοριῶν οὐκ ἐπιμνησθῆναί φησιν Ἑκαταῖος ὁ Ἀβδηρίτης οὐδὲ τῶν κατ’ αὐτὴν πολιτευσαμένων ἀνδρῶν, ὡς ἁγνῆς οὔσης καὶ μὴ δέον αὐτὴν βεβήλοις στόμασιν διασαφεῖσθαι. ἐὰν οὖν σοι δοκῇ, βασιλεῦ, γράψεις τῷ τῶν Ἰουδαίων ἀρχιερεῖ, ὅπως ἀποστείλῃ τῶν πρεσβυτέρων ἓξ ἀφ’ ἑκάστης φυλῆς τοὺς ἐμπειροτάτους τῶν νόμων, παρ’ ὧν τὸ τῶν βιβλίων σαφὲς καὶ σύμφωνον ἐκμαθόντες καὶ τὸ κατὰ τὴν ἑρμηνείαν ἀκριβὲς λαβόντες τῶν πραγμάτων ἀξίως ταῦτα τῆς σῆς προαιρέσεως συναγάγωμεν.", "st": "12.2.4"}, {"sp": "N", "t": "Τοιαύτης οὖν τῆς εἰσδόσεως γενομένης ὁ βασιλεὺς ἐκέλευσεν τῷ ἀρχιερεῖ τῶν Ἰουδαίων Ἐλεαζάρῳ γραφῆναι περὶ τούτων ἅμα καὶ τὴν ἄφεσιν τῶν δουλευόντων παρ’ αὐτοῖς Ἰουδαίων δηλοῦντας αὐτῷ, καὶ πρὸς κατασκευὴν δὲ κρατήρων καὶ φιαλῶν καὶ σπονδείων ἔπεμψε χρυσίου μὲν ὁλκῆς τάλαντα πεντήκοντα, λίθων δὲ πολυτελῶν ἀσυλλόγιστόν τι πλῆθος. προσέταξε δὲ καὶ τοὺς φύλακας τῶν κιβωτῶν, ἐν αἷς ἐτύγχανον οἱ λίθοι, τὴν ἐκλογὴν τοῖς τεχνίταις αὐτοῖς οὗπερ ἂν θελήσωσιν εἴδους ἐπιτρέπειν. διετάξατο δὲ καὶ νομίσματος εἰς θυσίας καὶ τὰς λοιπὰς χρείας πρὸς ἑκατὸν τάλαντα τῷ ἱερεῖ δοθῆναι. διηγήσομαι δὲ τὰ κατασκευάσματα καὶ τὸν τρόπον τῆς δημιουργίας αὐτῶν μετὰ τὸ προεκθέσθαι τὸ ἀντίγραφον τῆς ἐπιστολῆς τῆς γραφείσης Ἐλεαζάρῳ τῷ ἀρχιερεῖ, ταύτην λαβόντι τὴν τιμὴν ἐξ αἰτίας τοιαύτης· τελευτήσαντος Ὀνίου τοῦ ἀρχιερέως ὁ παῖς αὐτοῦ Σίμων γίγνεται διάδοχος ὁ καὶ δίκαιος ἐπικληθεὶς διά τε τὸ πρὸς τὸν θεὸν εὐσεβὲς καὶ τὸ πρὸς τοὺς ὁμοφύλους εὔνουν. ἀποθανόντος δὲ τούτου καὶ νήπιον υἱὸν καταλιπόντος τὸν κληθέντα Ὀνίαν ὁ ἀδελφὸς αὐτοῦ Ἐλεάζαρος, περὶ οὗ τὸν λόγον ποιούμεθα, τὴν ἀρχιερωσύνην παρέλαβεν, ᾧ γράφει Πτολεμαῖος τοῦτον τὸν τρόπον· βασιλεὺς Πτολεμαῖος Ἐλεαζάρῳ τῷ ἀρχιερεῖ χαίρειν. πολλῶν ἐν τῇ βασιλείᾳ κατῳκισμένων Ἰουδαίων, οὓς αἰχμαλωτισθέντας ὑπὸ Περσῶν ὅτ’ ἐκράτουν ὁ ἐμὸς πατὴρ ἐτίμησεν, καὶ τοὺς μὲν εἰς τὸ στρατιωτικὸν κατέταξεν ἐπὶ μείζοσιν μισθοφοραῖς, τισὶν δὲ γενομένοις ἐν Αἰγύπτῳ σὺν αὐτῷ τὰ φρούρια καὶ τὴν τούτων φυλακὴν παρέθετο, ἵνα τοῖς Αἰγυπτίοις ὦσιν φοβεροί, τὴν ἀρχὴν ἐγὼ παραλαβὼν πᾶσι μὲν φιλανθρώπως ἐχρησάμην, μάλιστα δὲ τοῖς σοῖς πολίταις, ὧν ὑπὲρ δέκα μὲν μυριάδας αἰχμαλώτων δουλευόντων ἀπέλυσα τοῖς δεσπόταις αὐτῶν ἐκ τῶν ἐμῶν λύτρα καταβαλών. τοὺς δὲ ἀκμάζοντας ταῖς ἡλικίαις εἰς τὸν στρατιωτικὸν κατάλογον κατέταξα, τινὰς δὲ τῶν περὶ ἡμᾶς καὶ τὴν τῆς αὐλῆς πίστιν εἶναι δυναμένων ταύτης ἠξίωκα, νομίζων ἡδὺ τῷ θεῷ τῆς ὑπὲρ ἐμοῦ προνοίας ἀνάθημα τοῦτο καὶ μέγιστον ἀναθήσειν. βουλόμενος δὲ καὶ τούτοις χαρίζεσθαι καὶ πᾶσι τοῖς κατὰ τὴν οἰκουμένην Ἰουδαίοις τὸν νόμον ὑμῶν ἔγνων μεθερμηνεῦσαι, καὶ γράμμασιν Ἑλληνικοῖς ἐκ τῶν Ἑβραϊκῶν μεταγραφέντα κεῖσθαι ἐν τῇ ἐμῇ βιβλιοθήκῃ. καλῶς οὖν ποιήσεις ἐπιλεξάμενος ἄνδρας ἀγαθοὺς ἓξ ἀφ’ ἑκάστης φυλῆς ἤδη πρεσβυτέρους, οἳ καὶ διὰ τὸν χρόνον ἐμπείρως ἔχουσι τῶν νόμων καὶ δυνήσονται τὴν ἑρμηνείαν αὐτῶν ἀκριβῆ ποιήσασθαι· νομίζω γὰρ τούτων ἐπιτελεσθέντων μεγίστην δόξαν ἡμῖν περιγενήσεσθαι. ἀπέσταλκα δέ σοι περὶ τούτων διαλεξομένους Ἀνδρέαν τὸν ἀρχισωματοφύλακα καὶ Ἀρισταῖον ἐμοὶ τιμιωτάτους, δι’ ὧν καὶ ἀπαρχὰς ἀναθημάτων εἰς τὸ ἱερὸν καὶ θυσιῶν καὶ τῶν ἄλλων ἀπέσταλκα τάλαντα ἀργυρίου ἑκατόν. καὶ σὺ δ’ ἡμῖν ἐπιστέλλων περὶ ὧν ἂν θέλῃς ποιήσεις κεχαρισμένα.", "st": "12.2.5"}, {"sp": "N", "t": "Τῆς οὖν ἐπιστολῆς τοῦ βασιλέως κομισθείσης πρὸς τὸν Ἐλεάζαρον ἀντιγράφει πρὸς αὐτὴν ὡς ἐνῆν μάλιστα φιλοτίμως. ἀρχιερεὺς Ἐλεάζαρος βασιλεῖ Πτολεμαίῳ χαίρειν. ἐρρωμένων σοῦ τε καὶ τῆς βασιλίσσης Ἀρσινόης καὶ τῶν τέκνων καλῶς ἡμῖν ἔχει πάντα. τὴν δ’ ἐπιστολὴν λαβόντες μεγάλως ἥσθημεν ἐπὶ τῇ προαιρέσει σου, καὶ συναθροίσαντες τὸ πλῆθος ἀνέγνωμεν αὐτὴν ἐμφανίζοντες αὐτῷ ἣν ἔχεις πρὸς τὸν θεὸν εὐσέβειαν. ἐπεδείξαμεν δ’ αὐτῷ καὶ τὰς φιάλας ἃς ἔπεμψας χρυσᾶς εἴκοσι καὶ ἀργυρᾶς τριάκοντα καὶ κρατῆρας πέντε καὶ τράπεζαν εἰς ἀνάθεσιν, ἅ τε εἰς θυσίαν καὶ εἰς ἐπισκευὴν ὧν ἂν δέηται τὸ ἱερὸν τάλαντα ἑκατόν, ἅπερ ἐκόμισαν Ἀνδρέας καὶ Ἀρισταῖος οἱ τιμιώτατοί σου τῶν φίλων, ἄνδρες ἀγαθοὶ καὶ παιδείᾳ διαφέροντες καὶ τῆς σῆς ἀρετῆς ἄξιοι. ἴσθι δ’ ἡμᾶς τὸ σοὶ συμφέρον, κἂν ᾖ τι παρὰ φύσιν, ὑπομενοῦντας· ἀμείβεσθαι γὰρ ἡμᾶς δεῖ τὰς σὰς εὐεργεσίας πολυμερῶς εἰς τοὺς ἡμετέρους πολίτας κατατεθείσας. εὐθὺς οὖν ὑπὲρ σοῦ καὶ τῆς ἀδελφῆς σου καὶ τέκνων καὶ φίλων προσηγάγομεν θυσίας, καὶ τὸ πλῆθος εὐχὰς ἐποιήσατο γενέσθαι σοι τὰ κατὰ νοῦν καὶ φυλαχθῆναί σου τὴν βασιλείαν ἐν εἰρήνῃ, τήν τε τοῦ νόμου μεταγραφὴν ἐπὶ συμφέροντι τῷ σῷ λαβεῖν ὃ προαιρῇ τέλος. ἐπελεξάμην δὲ καὶ πρεσβυτέρους ἄνδρας ἓξ ἀπὸ φυλῆς ἑκάστης, οὓς πεπόμφαμεν ἔχοντας τὸν νόμον. ἔσται δὲ τῆς σῆς εὐσεβείας καὶ δικαιοσύνης τὸ μεταγραφέντα τὸν νόμον εἰς ἡμᾶς ἀποπέμψαι μετ’ ἀσφαλείας τῶν κομιζόντων. ἔρρωσο.", "st": "12.2.6"}, {"sp": "N", "t": "Ταῦτα μὲν ὁ ἀρχιερεὺς ἀντέγραψεν. ἐμοὶ δ’ οὐκ ἀναγκαῖον ἔδοξεν εἶναι τὰ ὀνόματα τῶν ἑβδομήκοντα πρεσβυτέρων, οἳ τὸν νόμον ἐκόμιζον ὑπὸ Ἐλεαζάρου πεμφθέντες, δηλοῦν· ἦν γὰρ ταῦτα ὑπογεγραμμένα ἐν τῇ ἐπιστολῇ. τὴν μέντοι γε τῶν ἀναθημάτων πολυτέλειαν καὶ κατασκευήν, ἣν ἀπέστειλεν ὁ βασιλεὺς τῷ θεῷ, οὐκ ἀνεπιτήδειον ἡγησάμην διελθεῖν, ὅπως ἅπασιν ἡ τοῦ βασιλέως περὶ τὸν θεὸν φιλοτιμία φανερὰ γένηται· ἄφθονον γὰρ τὴν εἰς ταῦτα δαπάνην χορηγῶν ὁ βασιλεὺς καὶ παρὼν ἀεὶ τοῖς τεχνίταις καὶ τὰ ἔργα ἐπιβλέπων οὐδὲν ἀμελῶς οὐδὲ ῥᾳθύμως εἴα γίγνεσθαι τῶν κατασκευασμάτων. ὧν ἕκαστον οἷον ἦν τὴν πολυτέλειαν διηγήσομαι, τῆς μὲν ἱστορίας ἴσως οὐκ ἀπαιτούσης τὴν ἀπαγγελίαν, τὸ δὲ τοῦ βασιλέως φιλόκαλον καὶ μεγαλόφρον οὕτω συστήσειν τοῖς ἐντευξομένοις ὑπολαμβάνων.", "st": "12.2.7"}, {"sp": "N", "t": "Πρῶτον δὲ τὰ περὶ τῆς τραπέζης ἐκθήσομαι. εἶχεν μὲν οὖν δι’ ἐννοίας ὁ βασιλεὺς ὑπερμεγεθέστατον τοῖς μέτροις ἀπεργάσασθαι τὸ κατασκεύασμα, προσέταξε δὲ μαθεῖν τὸ μέγεθος τῆς ἀνακειμένης ἐν τοῖς Ἱεροσολύμοις τραπέζης πόσον τέ ἐστιν καὶ εἰ δύναται τούτου μεῖζον κατασκευασθῆναι. μαθὼν δὲ καὶ τὴν οὖσαν ἡλίκη τις ἦν, καὶ ὅτι αὐτῆς οὐδὲν κωλύει μείζονα γενέσθαι, φήσας καὶ πενταπλασίονα τῆς ὑπαρχούσης τῷ μεγέθει βούλεσθαι κατασκευάσαι, φοβεῖσθαι δέ, μὴ πρὸς τὰς λειτουργίας ἄχρηστος διὰ τὴν ὑπερβολὴν τοῦ μεγέθους γένηται· βούλεσθαι γὰρ οὐκ ἀνακεῖσθαι μόνον εἰς θέαν τἀναθήματα, ἀλλὰ καὶ πρὸς τὰς λειτουργίας εὔχρηστα· καὶ διὰ τοῦτο λογισάμενος σύμμετρον κατεσκευάσθαι τὴν προτέραν τράπεζαν, ἀλλ’ οὐ διὰ σπάνιν χρυσοῦ, τῷ μεγέθει μὲν οὐκ ἔγνω τὴν προϋπάρχουσαν ὑπερβαλεῖν, τῇ δὲ ποικιλίᾳ καὶ τῷ κάλλει τῆς ὕλης ἀξιολογωτέραν κατασκευάσαι. δεινὸς δὲ ὢν συνιδεῖν πραγμάτων παντοδαπῶν φύσιν καὶ λαβεῖν ἐπίνοιαν ἔργων καινῶν καὶ παραδόξων καὶ ὅσα ἦν ἄγραφα τὴν εὕρεσιν αὐτὸς παρέχων διὰ τὴν σύνεσιν καὶ ὑποδεικνὺς τοῖς τεχνίταις, ἐκέλευσεν ταῦτα κατασκευάζεσθαι καὶ τὰ ἀναγεγραμμένα πρὸς τὴν ἀκρίβειαν αὐτῶν ἀποβλέποντας ὁμοίως ἐπιτελεῖν.", "st": "12.2.8"}, {"sp": "N", "t": "Ὑποστησάμενοι τοίνυν ποιήσασθαι τὴν τράπεζαν δύο μὲν καὶ ἡμίσους πηχῶν τὸ μῆκος, ἑνὸς δὲ τὸ εὖρος, τὸ δ’ ὕψος ἑνὸς καὶ ἡμίσους, κατεσκεύαζον ἐκ χρυσοῦ τὴν ὅλην τοῦ ἔργου καταβολὴν ποιούμενοι. τὴν μὲν οὖν στεφάνην παλαιστιαίαν εἰργάσαντο, τὰ δὲ κυμάτια στρεπτὰ τὴν ἀναγλυφὴν ἔχοντα σχοινοειδῆ τῇ τορείᾳ θαυμαστῶς ἐκ τῶν τριῶν μερῶν μεμιμημένην. τριγώνων γὰρ ὄντων αὐτῶν ἑκάστη γωνία τὴν αὐτὴν τῆς ἐκτυπώσεως εἶχεν διάθεσιν, ὡς στρεφομένων αὐτῶν μίαν καὶ μὴ διάφορον τὴν ἰδέαν αὐτοῖς συμπεριφέρεσθαι. τῆς δὲ στεφάνης τὸ μὲν ὑπὸ τὴν τράπεζαν ἐκκεκλιμένον ὡραίαν εἶχεν τὴν ἀποτύπωσιν, τὸ δ’ ἔξωθεν περιηγμένον ἔτι μᾶλλον τῷ κάλλει τῆς ἐργασίας ἦν ἐκπεπονημένον, ὡς ὑπ’ ὄψιν καὶ θεωρίαν ἐρχόμενον. διὸ καὶ τὴν μὲν ὑπεροχὴν ἀμφοτέρων τῶν μερῶν ὀξεῖαν συνέβαινε γίγνεσθαι, καὶ μηδεμίαν γωνίαν τριῶν οὐσῶν, ὡς προειρήκαμεν, περὶ τὴν μεταγωγὴν τῆς τραπέζης ἐλάσσονα βλέπεσθαι. ἐνδιέκειντο δὲ ταῖς σχοινίσιν τῆς τορείας λίθοι πολυτελεῖς παράλληλοι περόναις χρυσαῖς διὰ τρημάτων κατειλημμένοι. τὰ δ’ ἐκ πλαγίου τῆς στεφάνης καὶ πρὸς ὄψιν ἀνατείνοντα ὠῶν ἐκ λίθου καλλίστου πεποιημένων θέσει κατακεκόσμητο ῥάβδοις τὴν ἀναγλυφὴν ἐοικότων πυκναῖς, αἳ περὶ τὸν κύκλον τῆς τραπέζης εἴληντο. ὑπὸ δὲ τὴν τῶν ὠῶν διατύπωσιν στέφανον περιήγαγον οἱ τεχνῖται παντοίου καρποῦ φύσιν ἐντετορευμένον, ὡς ἀποκρέμασθαί τε βότρυς καὶ στάχυας ἀναστῆναι καὶ ῥόας ἀποκεκλεῖσθαι. τοὺς δὲ λίθους εἰς πᾶν γένος τῶν προειρημένων καρπῶν, ὡς ἑκάστου τὴν οἰκείαν ἐντετυπῶσθαι χρόαν, ἐξεργασάμενοι συνέδησαν τῷ χρυσῷ περὶ ὅλην τὴν τράπεζαν. ὑπὸ δὲ τὸν στέφανον ὁμοίως ἡ τῶν ὠῶν διάθεσις πεποίητο καὶ ἡ τῆς ῥαβδώσεως ἀναγλυφή, τῆς τραπέζης ἐπ’ ἀμφότερον μέρος ἔχειν τὴν αὐτὴν τῆς ποικιλίας τῶν ἔργων καὶ γλαφυρότητος θέαν κατεσκευασμένης, ὡς καὶ τὴν τῶν ἄλλων κυμάτων θέσιν καὶ τὴν τῆς στεφάνης μηδὲ τῆς τραπέζης ἐφ’ ἕτερον μέρος ἐναλλαττομένης γίγνεσθαι διάφορον, τὴν δ’ αὐτὴν ἄχρι καὶ τῶν ποδῶν ὄψιν τῆς ἐπιτεχνήσεως διατετάσθαι. ἔλασμα γὰρ χρυσοῦ τὸ πλάτος τεσσάρων δακτύλων ποιήσαντες καθ’ ὅλου τοῦ τῆς τραπέζης πλάτους εἰς τοῦτο τοὺς πόδας αὐτῆς ἐνέθεσαν, ἔπειτα περόναις καὶ κατακλεῖσιν αὐτοὺς ἐνέσφιγγον τῇ τραπέζῃ κατὰ τὴν στεφάνην, ἵνα τὴν θέαν τῆς καινουργίας καὶ πολυτελείας, ἐφ’ ᾧ τις ἂν στήσῃ τὴν τράπεζαν μέρει, παρέχωσι τὴν αὐτήν. ἐπὶ δὲ τῆς τραπέζης μαίανδρον ἐξέγλυψαν λίθους αὐτῷ κατὰ μέσον ἀξιολόγους ὥσπερ ἀστέρας ποικίλης ἰδέας ἐνθέντες, τόν τε ἄνθρακα καὶ τὸν σμάραγδον ἥδιστον προσαυγάζοντας αὐτῶν ἑκάτερον τοῖς ὁρῶσιν, τῶν τε ἄλλων γενῶν ὅσοι περισπούδαστοι καὶ ζηλωτοὶ πᾶσιν διὰ τὴν πολυτέλειαν τῆς φύσεως ὑπάρχουσιν. μετὰ δὲ τὸν μαίανδρον πλέγμα τι σχοινοειδὲς περιῆκτο ῥόμβῳ τὴν κατὰ μέσον ὄψιν ἐμφερές, ἐφ’ οὗ κρύσταλλός τε λίθος καὶ ἤλεκτρον ἐντετύπωτο τῇ παραλλήλῳ τῆς ἰδέας γειτνιάσει ψυχαγωγίαν θαυμαστὴν παρέχον τοῖς βλέπουσιν. τῶν δὲ ποδῶν ἦσαν αἱ κεφαλίδες εἰς κρίνα μεμιμημέναι τὰς ἐκφύσεις τῶν πετάλων ὑπὸ τὴν τράπεζαν ἀνακλωμένων, εἰς ὀρθὸν δὲ τὴν βλάστησιν ἔνδοθεν παρεχόντων ὁρᾶν. ἡ δὲ βάσις αὐτοῖς ἦν ἐξ ἄνθρακος λίθου παλαιστιαία πεποιημένη σχῆμα κρηπῖδος ἀποτελοῦσα, τὸ δὲ πλάτος ὀκτὼ δακτύλων ἔχουσα, καθ’ οὗ τὸ πᾶν ἔλασμα τῶν ποδῶν ἐρήρειστο. ἀνέγλυψαν δὲ λεπτομερεῖ καὶ φιλοπονωτάτῃ τορείᾳ τῶν ποδῶν ἕκαστον, κισσὸν αὐτοῖς καὶ κλήματα ἀμπέλων σὺν καὶ βότρυσιν ἐκφύσαντες, ὡς εἰκάσαι μηδὲν ἀποδεῖν τῆς ἀληθείας· καὶ γὰρ πρὸς τὸ πνεῦμα διὰ λεπτότητα καὶ τὴν ἐπ’ ἄκρον αὐτῶν ἔκτασιν κινούμενα φαντασίαν τῶν κατὰ φύσιν μᾶλλον ἢ τέχνης μιμημάτων παρεῖχεν. ἐκαινούργησαν δὲ ὥστε τρίπτυχον οἱονεὶ τὸ σχῆμα τῆς ὅλης κατασκευάσαι τραπέζης τῆς ἁρμονίας πρὸς ἄλληλα τῶν μερῶν οὕτω συνδεδεμένης, ὡς ἀόρατον εἶναι καὶ μηδ’ ἐπινοεῖσθαι τὰς συμβολάς. ἥμισυ δὲ πήχεως οὐκ ἔλασσον τῇ τραπέζῃ τὸ πάχος συνέβαινεν εἶναι. τὸ μὲν οὖν ἀνάθημα τοῦτο κατὰ πολλὴν τοῦ βασιλέως φιλοτιμίαν τοιοῦτο τῇ τε πολυτελείᾳ τῆς ὕλης καὶ τῇ ποικιλίᾳ τῆς καλλονῆς καὶ τῇ μιμήσει τῇ κατὰ τὴν τορείαν τῶν τεχνιτῶν συνετελέσθη, σπουδάσαντος εἰ καὶ μὴ τῷ μεγέθει τῆς προανακειμένης τῷ θεῷ τραπέζης ἔμελλεν ἔσεσθαι διάφορος, τῇ μέντοι γε τέχνῃ καὶ τῇ καινουργίᾳ καὶ τῇ λαμπρότητι τῆς κατασκευῆς πολὺ κρείττονα καὶ περίβλεπτον ἀπεργάσασθαι.", "st": "12.2.9"}, {"sp": "N", "t": "Τῶν δὲ κρατήρων χρύσεοι μὲν ἦσαν δύο, φολιδωτὴν δ’ εἶχον ἀπὸ τῆς βάσεως μέχρι τοῦ διαζώματος τὴν τορείαν λίθων ταῖς σπείραις ποικίλων ἐνδεδεμένων. εἶτα ἐπ’ αὐτῇ μαίανδρος πηχυαῖος τὸ ὕψος ἐξείργαστο κατὰ σύνθεσιν λίθων παντοίων τὴν ἰδέαν, κατ’ αὐτοῦ δὲ ῥάβδωσις ἀναγέγλυπτο, καθ’ ἧς πλέγμα ῥομβωτὸν δικτύοις ἐμφερὲς ἕως τοῦ χείλους ἀνείλκυστο· τὰ δὲ μέσα λίθων ἀσπίδια τετραδακτύλων ἀνεπλήρου τὸ κάλλος. περιεστέφετο δὲ τὰ χείλη τοῦ κρατῆρος κρίνων σμίλαξι καὶ ἀνθεμίσι καὶ βοτρύων σχοινίαις εἰς κύκλον περιηγμέναις. τοὺς μὲν οὖν χρυσέους κρατῆρας δύο χωροῦντας ἑκάτερον ἀμφορέας τοῦτον κατεσκεύασαν τὸν τρόπον, οἱ δ’ ἀργύρεοι τῶν ἐσόπτρων τὴν λαμπρότητα πολὺ διαυγέστεροι γεγόνεισαν, ὡς τρανοτέρας διὰ τούτων τὰς τῶν προσφερομένων ὄψεις ὁρᾶσθαι. προσκατεσκεύασε δὲ τούτοις ὁ βασιλεὺς καὶ φιάλας τριάκοντα, ὧν ὅσα χρυσὸς ἦν ἀλλὰ μὴ λίθῳ πολυτελεῖ διείληπτο, σμίλαξι κισσοῦ καὶ πετάλοις ἀμπέλων ἐσκίαστο φιλοτέχνως ἐντετορευμένων. ταῦτα δ’ ἐγίγνετο μὲν καὶ διὰ τὴν ἐμπειρίαν τῶν ἐργαζομένων θαυμασίων ὄντων περὶ τὴν τέχνην, πολὺ δὲ μᾶλλον ὑπὸ τῆς τοῦ βασιλέως σπουδῆς καὶ φιλοτιμίας διαφερόντως ἀπηρτίζετο· οὐ γὰρ τῆς χορηγίας τὸ ἄφθονον καὶ μεγαλόψυχον τοῖς τεχνίταις παρεῖχεν μόνον, ἀλλὰ καὶ τὸ χρηματίζειν τοῖς δημοσίοις πράγμασιν ἀπειρηκὼς αὐτὸς τοῖς κατασκευάζουσι παρῆν καὶ τὴν ὅλην ἐργασίαν ἐπέβλεπεν. αἴτιον δ’ ἦν τοῦτο τῆς τῶν τεχνιτῶν ἐπιμελείας, οἳ πρὸς τὸν βασιλέα καὶ τὴν τούτου σπουδὴν ἀποβλέποντες φιλοπονώτερον τοῖς ἔργοις προσελιπάρουν.", "st": "12.2.10"}, {"sp": "N", "t": "Ταῦτα μὲν τὰ πεμφθέντα εἰς Ἱεροσόλυμα ὑπὸ Πτολεμαίου ἀναθήματα. ὁ δ’ ἀρχιερεὺς Ἐλεάζαρος ἀναθεὶς αὐτὰ καὶ τιμήσας τοὺς κομίσαντας καὶ δῶρα τῷ βασιλεῖ δοὺς κομίζειν ἀπέλυσε πρὸς τὸν βασιλέα. παραγενομένων δ’ εἰς τὴν Ἀλεξάνδρειαν ἀκούσας Πτολεμαῖος τὴν παρουσίαν αὐτῶν καὶ τοὺς ἑβδομήκοντα τῶν πρεσβυτέρων ἐληλυθότας, εὐθὺς μεταπέμπεται τὸν Ἀνδρέαν καὶ τὸν Ἀρισταῖον τοὺς πρέσβεις. οἱ δ’ ἀφικόμενοι τάς τε ἐπιστολάς, ἃς ἐκόμιζον αὐτῷ παρὰ τοῦ ἀρχιερέως, ἀπέδοσαν καὶ ὅσα φράζειν ἀπὸ λόγων ὑπέθετο ταῦτα ἐδήλωσαν. σπεύδων δ’ ἐντυχεῖν τοῖς ἀπὸ τῶν Ἱεροσολύμων [πρεσβύταις] ἥκουσιν ἐπὶ τὴν ἑρμηνείαν τῶν νόμων, τοὺς μὲν ἄλλους οὓς χρειῶν ἕνεκα παρεῖναι συνέβαινεν ἐκέλευσεν ἀπολῦσαι, παράδοξον τοῦτο ποιῶν καὶ παρὰ τὸ ἔθος· οἱ μὲν γὰρ ὑπὸ τοιούτων αἰτιῶν ἀχθέντες διὰ πέμπτης ἡμέρας αὐτῷ προσῄεσαν, οἱ δὲ πρεσβεύοντες διὰ μηνός· τότε τοίνυν ἀπολύσας ἐκείνους τοὺς πεμφθέντας ὑπὸ Ἐλεαζάρου περιέμενεν. ὡς δὲ παρῆλθον μετὰ καὶ τῶν δώρων οἱ γέροντες, ἃ τῷ βασιλεῖ κομίσαι ὁ ἀρχιερεὺς αὐτοῖς ἔδωκεν, καὶ τῶν διφθερῶν, αἷς ἐγγεγραμμένους εἶχον τοὺς νόμους χρυσοῖς γράμμασιν, ἐπηρώτησεν αὐτοὺς περὶ τῶν βιβλίων. ὡς δ’ ἀποκαλύψαντες τῶν ἐνειλημάτων ἐπέδειξαν αὐτῷ, θαυμάσας ὁ βασιλεὺς τῆς ἰσχνότητος τοὺς ὑμένας καὶ τῆς συμβολῆς τὸ ἀνεπίγνωστον, οὕτως γὰρ ἥρμοστο, καὶ τοῦτο ποιήσας χρόνῳ πλείονι χάριν ἔχειν εἶπεν αὐτοῖς τε ἐλθοῦσιν καὶ μείζονα τῷ πέμψαντι, πρὸ δὲ πάντων τῷ θεῷ, οὗ τοὺς νόμους εἶναι συμβέβηκεν. ἐκβοησάντων δ’ ὑφ’ ἓν καὶ τῶν πρεσβυτέρων καὶ τῶν συμπαρόντων γίγνεσθαι τὰ ἀγαθὰ τῷ βασιλεῖ δι’ ὑπερβολὴν ἡδονῆς εἰς δάκρυα προύπεσεν, φύσει τῆς μεγάλης χαρᾶς πασχούσης καὶ τὰ τῶν λυπηρῶν σύμβολα. κελεύσας δὲ τὰ βιβλία δοῦναι τοῖς ἐπὶ τῆς τάξεως τότε τοὺς ἄνδρας ἠσπάσατο, δίκαιον εἰπὼν εἶναι πρῶτον περὶ ὧν αὐτοὺς μετεπέμψατο ποιησάμενον τοὺς λόγους ἔπειτα κἀκείνους προσειπεῖν. τὴν μέντοι γε ἡμέραν, καθ’ ἣν ἦλθον πρὸς αὐτόν, ἐπιφανῆ ποιήσειν καὶ κατὰ πᾶν ἔτος ἐπίσημον εἰς ὅλον τὸν τῆς ζωῆς χρόνον ἐπηγγέλλετο· ἔτυχεν γὰρ ἡ αὐτὴ εἶναι τῆς παρουσίας αὐτοῖς καὶ τῆς νίκης, ἣν Ἀντίγονον ναυμαχῶν ἐνίκησεν· συνεστιαθῆναί τε ἐκέλευσεν αὐτῷ καὶ καταλύσεις προσέταξεν αὐτοῖς δοθῆναι τὰς καλλίστας πρὸς τῇ ἄκρᾳ.", "st": "12.2.11"}, {"sp": "N", "t": "Ὁ δὲ ἐπὶ τῆς τῶν ξένων ἀποδοχῆς τεταγμένος Νικάνωρ Δωρόθεον καλέσας, ὃς εἶχεν τὴν περὶ τούτων πρόνοιαν, ἐκέλευεν ἑτοιμάζειν ἑκάστῳ τὰ δέοντα πρὸς τὴν δίαιταν. διετέτακτο δὲ τοῦτον ὑπὸ τοῦ βασιλέως τὸν τρόπον· κατὰ γὰρ πόλιν ἑκάστην, ὅσαι τοῖς αὐτοῖς χρῶνται περὶ τὴν δίαιταν, ἦν τούτων ἐπιμελόμενος καὶ κατὰ τὸ τῶν ἀφικνουμένων πρὸς αὐτὸν ἔθος πάντ’ αὐτοῖς παρεσκευάζετο, ἵνα τῷ συνήθει τρόπῳ τῆς διαίτης εὐωχούμενοι μᾶλλον ἥδωνται καὶ πρὸς μηδὲν ὡς ἀλλοτρίως ἔχοντες δυσχεραίνωσιν. ὃ δὴ καὶ περὶ τούτους ἐγένετο Δωροθέου διὰ τὴν περὶ τὸν βίον ἀκρίβειαν ἐπὶ τούτοις καθεστῶτος. συνέστρωσε δὲ πάντα δι’ αὐτοῦ τὰ πρὸς τὰς τοιαύτας ὑποδοχὰς καὶ διμερῆ τὴν κλισίαν ἐποίησεν οὑτωσὶ προστάξαντος τοῦ βασιλέως· τοὺς μὲν γὰρ ἡμίσεις ἐκέλευσεν ἀνὰ χεῖρα κατακλιθῆναι, τοὺς δὲ λοιποὺς μετὰ τὴν αὐτοῦ κλισίαν, οὐδὲν ἀπολιπὼν τῆς εἰς τοὺς ἄνδρας τιμῆς. ἐπεὶ δ’ οὕτως κατεκλίθησαν ἐκέλευσε τὸν Δωρόθεον, οἷς ἔθεσι χρώμενοι διατελοῦσιν πάντες οἱ ἀπὸ τῆς Ἰουδαίας πρὸς αὐτὸν ἀφιγμένοι κατὰ ταῦτα ὑπηρετεῖν. [διὸ] καὶ τοὺς ἱεροκήρυκας καὶ θύτας καὶ τοὺς ἄλλους, οἳ τὰς κατευχὰς ἐποιοῦντο, παρῃτήσατο, τῶν δὲ παραγενομένων ἕνα Ἐλισαῖον ὄνομα ὄντα ἱερέα παρεκάλεσεν ὁ βασιλεὺς ποιήσασθαι κατευχάς. ὁ δὲ στὰς εἰς μέσον ηὔχετο τῷ βασιλεῖ τὰ ἀγαθὰ καὶ τοῖς ἀρχομένοις ὑπ’ αὐτοῦ, εἶτα κρότος ἐξ ἁπάντων μετὰ χαρᾶς καὶ βοῆς ἤρθη καὶ παυσάμενοι πρὸς εὐωχίαν καὶ τὴν ἀπόλαυσιν τῶν παρεσκευασμένων ἐτράπησαν. διαλιπὼν δ’ ὁ βασιλεὺς ἐφ’ ὅσον ἔδοξεν ἀποχρῶντα καιρὸν εἶναι φιλοσοφεῖν ἤρξατο καὶ ἕκαστον αὐτῶν λόγους ἐπηρώτα φυσικούς, καὶ πρὸς τὴν τῶν ζητουμένων θεωρίαν ἀκριβῶς ἐκείνων περὶ παντὸς οὑτινοσοῦν λέγειν αὐτοῖς προβληθείη διασαφούντων, ἡδόμενος τούτοις ἐφ’ ἡμέρας δώδεκα τὸ συμπόσιον ἐποιήσατο, ὡς τῷ βουλομένῳ τὰ κατὰ μέρος γνῶναι τῶν ἐν τῷ συμποσίῳ ζητηθέντων εἶναι μαθεῖν ἀναγνόντι τὸ Ἀρισταίου βιβλίον, ὃ συνέγραψεν διὰ ταῦτα.", "st": "12.2.12"}, {"sp": "N", "t": "Θαυμάζοντος δ’ αὐτοὺς οὐ μόνον τοῦ βασιλέως, ἀλλὰ καὶ Μενεδήμου τοῦ φιλοσόφου προνοίᾳ διοικεῖσθαι πάντα φήσαντος καὶ διὰ τοῦτ’ εἰκὸς καὶ τοῦ λόγου δύναμιν καὶ κάλλος εὑρῆσθαι, παύονται μὲν περὶ τούτων ἐπιζητοῦντες. γεγενῆσθαι δ’ αὐτῷ τὰ μέγιστα τῶν ἀγαθῶν ὁ βασιλεὺς ἔλεγεν ἤδη παρόντων αὐτῶν· ὠφελῆσθαι γὰρ παρ’ αὐτῶν μεμαθηκότα, πῶς δεῖ βασιλεύειν· κελεύει τε αὐτοῖς ἀνὰ τρία δοθῆναι τάλαντα καὶ τοὺς ἀποκαταστήσοντας ἐπὶ τὴν κατάλυσιν. διελθουσῶν δὲ τριῶν ἡμερῶν παραλαβὼν αὐτοὺς ὁ Δημήτριος καὶ διελθὼν τὸ ἑπταστάδιον χῶμα τῆς θαλάσσης πρὸς τὴν νῆσον καὶ διαβὰς πρὸς τὴν γέφυραν, προελθὼν ἐπὶ τὰ βόρεια μέρη συνέδριον ἐποιήσατο ἐν τῷ παρὰ τὴν ᾐόνα κατεσκευασμένῳ οἴκῳ πρὸς διάσκεψιν πραγμάτων ἠρεμίας καλῶς ἔχοντι. ἀγαγὼν οὖν αὐτοὺς ἐκεῖ παρεκάλει πάντων, ὧν ἂν δεηθεῖεν εἰς τὴν ἑρμηνείαν τοῦ νόμου, παρόντων ἀκωλύτως ἐπιτελεῖν τὸ ἔργον. οἱ δ’ ὡς ἔνι μάλιστα φιλοτίμως καὶ φιλοπόνως ἀκριβῆ τὴν ἑρμηνείαν ποιούμενοι μέχρι μὲν ὥρας ἐνάτης πρὸς τούτῳ διετέλουν ὄντες, ἔπειτ’ ἐπὶ τὴν τοῦ σώματος ἀπηλλάττοντο θεραπείαν ἀφθόνως αὐτοῖς τῶν πρὸς τὴν δίαιταν χορηγουμένων καὶ προσέτι τοῦ Δωροθέου πολλὰ καὶ τῶν παρασκευαζομένων τῷ βασιλεῖ, προσέταξε γάρ, αὐτοῖς παρέχοντος. πρωῒ δὲ πρὸς τὴν αὐλὴν παραγινόμενοι καὶ τὸν Πτολεμαῖον ἀσπαζόμενοι πάλιν ἐπὶ τὸν αὐτὸν ἀπῄεσαν τόπον καὶ τῇ θαλάσσῃ τὰς χεῖρας ἀπονιπτόμενοι καὶ καθαίροντες αὑτοὺς οὕτως ἐπὶ τὴν τῶν νόμων ἑρμηνείαν ἐτρέποντο. Μεταγραφέντος δὲ τοῦ νόμου καὶ τοῦ κατὰ τὴν ἑρμηνείαν ἔργου τέλος ἐν ἡμέραις ἑβδομήκοντα καὶ δυσὶν λαβόντος, συναγαγὼν ὁ Δημήτριος τοὺς Ἰουδαίους ἅπαντας εἰς τὸν τόπον, ἔνθα καὶ μετεβλήθησαν οἱ νόμοι, παρόντων καὶ τῶν ἑρμηνέων ἀνέγνω τούτους. τὸ δὲ πλῆθος ἀπεδέξατο μὲν καὶ τοὺς διασαφήσαντας πρεσβυτέρους τὸν νόμον, ἐπῄνεσεν δὲ καὶ τὸν Δημήτριον τῆς ἐπινοίας ὡς μεγάλων ἀγαθῶν αὐτοῖς εὑρετὴν γεγενημένον, παρεκάλεσάν τε δοῦναι καὶ τοῖς ἡγουμένοις αὐτῶν ἀναγνῶναι τὸν νόμον, ἠξίωσάν τε [πάντες] ὅ τε ἱερεὺς καὶ τῶν ἑρμηνέων οἱ πρεσβύτεροι καὶ τοῦ πολιτεύματος οἱ προεστηκότες, ἐπεὶ καλῶς τὰ τῆς ἑρμηνείας ἀπήρτισται, καὶ διαμεῖναι ταῦθ’, ὡς ἔχοι, καὶ μὴ μετακινεῖν αὐτά. ἁπάντων δ’ ἐπαινεσάντων τὴν γνώμην ἐκέλευσαν, εἴ τις ἢ περισσόν τι προσγεγραμμένον ὁρᾷ τῷ νόμῳ ἢ λεῖπον, πάλιν ἐπισκοποῦντα τοῦτο καὶ ποιοῦντα φανερὸν διορθοῦν, σωφρόνως τοῦτο πράττοντες, ἵνα τὸ κριθὲν ἅπαξ ἔχειν καλῶς εἰς ἀεὶ διαμένῃ.", "st": "12.2.13"}, {"sp": "N", "t": "Ἐχάρη μὲν οὖν ὁ βασιλεὺς καὶ ἐπὶ τούτῳ τὴν αὐτοῦ προαίρεσιν εἴς τι χρήσιμον ὁρῶν τετελειωμένην, μάλιστα [ὡς] δὲ τῶν νόμων ἀναγνωσθέντων αὐτῷ καὶ τὴν διάνοιαν καὶ τὴν σοφίαν ἐξεπλάγη τοῦ νομοθέτου καὶ πρὸς τὸν Δημήτριον ἤρξατο ποιεῖσθαι λόγους, πῶς οὕτως θαυμαστῆς οὔσης τῆς νομοθεσίας οὐδεὶς οὔτε τῶν ἱστορικῶν αὐτῆς οὔτε τῶν ποιητῶν ἐπεμνήσθη. ὁ δὲ Δημήτριος μηδένα τολμῆσαι τῆς τῶν νόμων τούτων ἀναγραφῆς ἅψασθαι διὰ τὸ θείαν αὐτὴν εἶναι καὶ σεμνὴν ἔφασκεν, καὶ ὅτι βλαβεῖεν ἤδη τινὲς τούτοις ἐγχειρήσαντες ὑπὸ τοῦ θεοῦ, δηλῶν ὡς Θεόπομπός τε βουληθεὶς ἱστορῆσαί τι περὶ τούτων ἐταράχθη τὴν διάνοιαν πλείοσιν ἢ τριάκοντα ἡμέραις καὶ παρὰ τὰς ἀνέσεις ἐξιλάσκετο τὸν θεόν, ἐντεῦθεν αὐτῷ γενέσθαι τὴν παραφροσύνην ὑπονοῶν· οὐ μὴν ἀλλὰ καὶ ὄναρ εἶδεν ὅτι τοῦτ’ αὐτῷ συμβαίη περιεργαζομένῳ τὰ θεῖα καὶ ταῦτ’ ἐκφέρειν εἰς κοινοὺς ἀνθρώπους θελήσαντι· καὶ ἀποσχόμενος κατέστη τὴν διάνοιαν. ἐδήλου δὲ καὶ περὶ Θεοδέκτου τοῦ τῶν τραγῳδιῶν ποιητοῦ ἀναφέρεσθαι, ὅτι βουληθεὶς ἔν τινι δράματι τῶν ἐν τῇ ἱερᾷ βύβλῳ γεγραμμένων μνησθῆναι τὰς ὄψεις γλαυκωθείη καὶ συνιδὼν τὴν αἰτίαν ἀπαλλαγείη τοῦ πάθους ἐξευμενισάμενος τὸν θεόν.", "st": "12.2.14"}, {"sp": "N", "t": "Παραλαβὼν δ’ ὁ βασιλεὺς ταῦτα παρὰ τοῦ Δημητρίου, καθὼς προείρηται, προσκυνήσας αὐτοῖς ἐκέλευσε πολλὴν ποιεῖσθαι τῶν βιβλίων τὴν ἐπιμέλειαν, ἵνα διαμείνῃ ταῦτα καθαρῶς, τούς τε ἑρμηνεύσαντας παρεκάλεσεν συνεχῶς πρὸς αὐτὸν ἐκ τῆς Ἰουδαίας παραγίγνεσθαι· τοῦτο γὰρ αὐτοῖς καὶ πρὸς τιμὴν τὴν παρ’ αὐτοῦ καὶ πρὸς τὰς ἀπὸ τῶν δώρων ὠφελείας λυσιτελήσειν· νῦν μὲν γὰρ εἶναι δίκαιον αὐτοὺς ἐκπέμπειν ἔλεγεν, ἑκουσίως δὲ πρὸς αὐτὸν ἐλθόντας τεύξεσθαι πάντων, ὧν ἥ τε αὐτῶν ἐστιν σοφία δικαία τυχεῖν καὶ ἡ ἐκείνου μεγαλοφροσύνη παρασχεῖν ἱκανή. τότε μὲν οὖν ἐξέπεμψεν αὐτοὺς δοὺς ἑκάστῳ στολὰς ἀρίστας τρεῖς καὶ χρυσοῦ τάλαντα δύο καὶ κυλίκιον ταλάντου καὶ τὴν τοῦ συμποσίου στρωμνήν. καὶ ταῦτα μὲν ἐκείνοις ἔχειν ἐδωρήσατο. τῷ δ’ ἀρχιερεῖ Ἐλεαζάρῳ δι’ αὐτῶν ἔπεμψεν κλίνας ἀργυρόποδας δέκα καὶ τὴν ἀκόλουθον αὐτῶν ἐπισκευὴν καὶ κυλίκιον ταλάντων τριάκοντα, πρὸς τούτοις δὲ καὶ στολὰς δέκα καὶ πορφύραν καὶ στέφανον διαπρεπῆ καὶ βυσσίνης ὀθόνης ἱστοὺς ἑκατόν, ἔτι γε μὴν φιάλας καὶ τρύβλια καὶ σπονδεῖα καὶ κρατῆρας χρυσοῦς πρὸς ἀνάθεσιν δύο. παρεκάλεσεν δ’ αὐτὸν καὶ διὰ τῶν ἐπιστολῶν, ὅπως εἰ τῶν ἀνδρῶν τούτων θελήσειάν τινες πρὸς αὐτὸν ἐλθεῖν ἐπιτρέψῃ, περὶ πολλοῦ ποιούμενος τὴν μετὰ τῶν ἐν παιδείᾳ τυγχανόντων συνουσίαν καὶ τὸν πλοῦτον εἰς τοὺς τοιούτους ἡδέως ἔχων κατατίθεσθαι. καὶ τὰ μὲν εἰς δόξαν καὶ τιμὴν Ἰουδαίοις τοιαῦτα παρὰ Πτολεμαίου τοῦ Φιλαδέλφου συνέβη γενέσθαι. Ἔτυχον δὲ καὶ τῆς παρὰ τῶν βασιλέων τῆς Ἀσίας τιμῆς, ἐπειδὴ συνεστράτευσαν αὐτοῖς· καὶ γὰρ Σέλευκος ὁ Νικάτωρ ἐν αἷς ἔκτισεν πόλεσιν ἐν τῇ Ἀσίᾳ καὶ τῇ κάτω Συρίᾳ καὶ ἐν αὐτῇ τῇ μητροπόλει Ἀντιοχείᾳ πολιτείας αὐτοὺς ἠξίωσεν καὶ τοῖς ἐνοικισθεῖσιν ἰσοτίμους ἀπέφηνεν Μακεδόσιν καὶ Ἕλλησιν, ὡς τὴν πολιτείαν ταύτην ἔτι καὶ νῦν διαμένειν·", "st": "12.2.15"}, {"sp": "N", "t": "τεκμήριον δὲ τοῦτο· τοὺς Ἰουδαίους μὴ βουλομένους ἀλλοφύλῳ ἐλαίῳ χρῆσθαι λαμβάνειν ὡρισμένον τι παρὰ τῶν γυμνασιάρχων εἰς ἐλαίου τιμὴν ἀργύριον ἐκέλευσεν. ὃ τοῦ δήμου τῶν Ἀντιοχέων ἐν τῷ νῦν πολέμῳ λῦσαι προαιρουμένου Μουκιανὸς ἡγεμὼν ὢν τότε τῆς Συρίας ἐτήρησεν, καὶ μετὰ ταῦτα κρατήσαντος Οὐεσπασιανοῦ καὶ Τίτου τοῦ υἱοῦ αὐτοῦ τῆς οἰκουμένης δεηθέντες οἱ Ἀλεξανδρεῖς καὶ Ἀντιοχεῖς, ἵνα τὰ δίκαια τὰ τῆς πολιτείας μηκέτι μένῃ τοῖς Ἰουδαίοις, οὐκ ἐπέτυχον. ἐξ οὗ τις ἂν κατανοήσειεν τὴν Ῥωμαίων ἐπιείκειαν καὶ μεγαλοφροσύνην, μάλιστα δὲ τὴν Οὐεσπασιανοῦ καὶ Τίτου, ὅτι καίτοι πολλὰ πονήσαντες ἐν τῷ πρὸς Ἰουδαίους πολέμῳ καὶ πικρῶς πρὸς αὐτοὺς ἔχοντες, ὅτι μὴ παρέδοσαν αὐτοῖς τὰ ὅπλα μέχρις δ’ ἐσχάτου πολεμοῦντες ὑπέμειναν, οὐδενὸς αὐτοὺς τῶν ὑπαρχόντων κατὰ τὴν προειρημένην πολιτείαν ἀφείλοντο· ἅμα γὰρ καὶ τῆς πρότερον ὀργῆς καὶ τῆς τῶν Ἀλεξανδρέων καὶ Ἀντιοχέων δήμων μεγίστων παρακλήσεως ἐκράτησαν, ὥστε μηδὲν μήθ’ ὑπὸ τῆς πρὸς τούτους χάριτος μήθ’ ὑπὸ τῆς πρὸς τοὺς πολεμηθέντας μισοπονηρίας ἐνδοῦναι πρὸς τὸ λῦσαί τι τῶν ἀρχαίων τοῖς Ἰουδαίοις φιλανθρώπων, ἀλλὰ τοὺς ἀνταραμένους αὐτοῖς ὅπλα καὶ χωρήσαντας διὰ μάχης δεδωκέναι τιμωρίαν φήσαντες τοὺς οὐδὲν ἐξαμαρτόντας οὐκ ἐδικαίουν ἀποστερεῖν τῶν ὑπαρχόντων.", "st": "12.3.1"}, {"sp": "N", "t": "Ὅμοιον δέ τι τούτῳ καὶ Μᾶρκον Ἀγρίππαν φρονήσαντα περὶ τῶν Ἰουδαίων οἴδαμεν· τῶν γὰρ Ἰώνων κινηθέντων ἐπ’ αὐτοὺς καὶ δεομένων τοῦ Ἀγρίππου, ἵνα τῆς πολιτείας, ἣν αὐτοῖς ἔδωκεν Ἀντίοχος ὁ Σελεύκου υἱωνὸς ὁ παρὰ τοῖς Ἕλλησιν Θεὸς λεγόμενος, μόνοι μετέλθωσιν, ἀξιούντων δ’, εἰ συγγενεῖς εἰσιν αὐτοῖς Ἰουδαῖοι, σέβεσθαι τοὺς αὐτῶν θεούς, καὶ δίκης περὶ τούτων συστάσης ἐνίκησαν οἱ Ἰουδαῖοι τοῖς αὐτῶν ἔθεσι χρῆσθαι συνηγορήσαντος αὐτοῖς Νικολάου τοῦ Δαμασκηνοῦ· ὁ γὰρ Ἀγρίππας ἀπεφήνατο μηδὲν αὐτῷ καινίζειν ἐξεῖναι. τὸ δ’ ἀκριβὲς εἴ τις βούλεται καταμαθεῖν, ἀναγνώτω τοῦ Νικολάου τὴν ἑκατοστὴν καὶ εἰκοστὴν καὶ τρίτην καὶ τετάρτην. περὶ μὲν οὖν τῶν ὑπ’ Ἀγρίππου κριθέντων οὐκ ἔστιν ἴσως θαυμάζειν· οὐ γὰρ ἐπολέμει τότε Ῥωμαίοις τὸ ἡμέτερον ἔθνος· Οὐεσπασιανοῦ δ’ ἄν τις καὶ Τίτου τὴν μεγαλοφροσύνην εἰκότως ἐκπλαγείη μετὰ πολέμους καὶ τηλικούτους ἀγῶνας οὓς ἔσχον πρὸς ἡμᾶς μετριοπαθησάντων. ἐπανάξω δὲ τὸν λόγον ὅθεν ἐπὶ ταῦτ’ ἐξέβην.", "st": "12.3.2"}, {"sp": "N", "t": "Τοὺς γὰρ Ἰουδαίους ἐπ’ Ἀντιόχου τοῦ μεγάλου βασιλεύοντος τῆς Ἀσίας ἔτυχεν αὐτούς τε πολλὰ ταλαιπωρῆσαι τῆς γῆς αὐτῶν κακουμένης καὶ τοὺς τὴν κοίλην Συρίαν νεμομένους. πολεμοῦντος γὰρ αὐτοῦ πρὸς τὸν Φιλοπάτορα Πτολεμαῖον καὶ πρὸς τὸν υἱὸν αὐτοῦ Πτολεμαῖον ἐπικληθέντα δὲ Ἐπιφανῆ, κακοπαθεῖν συνέβαινεν αὐτοῖς καὶ νικῶντος καὶ πταίοντος ταὐτὰ πάσχειν, ὥστ’ οὐδὲν ἀπέλειπον χειμαζομένης νεὼς καὶ πονουμένης ὑπὸ τοῦ κλύδωνος ἑκατέρωθεν μεταξὺ τῆς εὐπραγίας τῆς Ἀντιόχου καὶ τῆς ἐπὶ θάτερον αὐτοῦ τροπῆς τῶν πραγμάτων κείμενοι. νικήσας μέντοι τὸν Πτολεμαῖον ὁ Ἀντίοχος τὴν Ἰουδαίαν προσάγεται. τελευτήσαντος δὲ τοῦ Φιλοπάτορος ὁ παῖς αὐτοῦ μεγάλην ἐξέπεμψε δύναμιν καὶ στρατηγὸν Σκόπαν ἐπὶ τοὺς ἐν τῇ κοίλῃ Συρίᾳ, ὃς πολλάς τε αὐτῶν πόλεις ἔλαβεν καὶ τὸ ἡμέτερον ἔθνος· πολεμούμενον γὰρ αὐτῷ προσέθετο. μετ’ οὐ πολὺ δὲ τὸν Σκόπαν Ἀντίοχος νικᾷ συμβαλὼν αὐτῷ πρὸς ταῖς πηγαῖς τοῦ Ἰορδάνου καὶ πολλὴν αὐτοῦ τῆς στρατιᾶς διέφθειρεν. ὕστερον δ’ Ἀντιόχου χειρωσαμένου τὰς ἐν τῇ κοίλῃ Συρίᾳ πόλεις, ἃς ὁ Σκόπας κατεσχήκει, καὶ τὴν Σαμάρειαν, ἑκουσίως αὐτῷ προσέθεντο οἱ Ἰουδαῖοι καὶ τῇ πόλει δεξάμενοι πᾶσαν αὐτοῦ τῇ τε στρατιᾷ καὶ τοῖς ἐλέφασιν ἀφθονίαν παρέσχον καὶ τοὺς ὑπὸ Σκόπα καταλειφθέντας ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων φρουροὺς πολιορκοῦντι προθύμως συνεμάχησαν. ὁ οὖν Ἀντίοχος δίκαιον ἡγησάμενος τὴν τῶν Ἰουδαίων πρὸς αὐτὸν σπουδὴν καὶ φιλοτιμίαν ἀμείψασθαι γράφει τοῖς τε στρατηγοῖς αὐτοῦ καὶ τοῖς φίλοις μαρτυρῶν τοῖς Ἰουδαίοις ὑπὲρ ὧν εὖ πάθοι πρὸς αὐτῶν καὶ τὰς δωρεὰς ἃς ὑπὲρ τούτων διέγνω παρασχεῖν αὐτοῖς ἐμφανίζων. παραθήσομαι δὲ τὰς ἐπιστολὰς τὰς τοῖς στρατηγοῖς περὶ αὐτῶν γραφείσας προδιελθών, ὡς μαρτυρεῖ τούτοις ἡμῶν τοῖς λόγοις Πολύβιος ὁ Μεγαλοπολίτης· ἐν γὰρ τῇ ἑξκαιδεκάτῃ τῶν ἱστοριῶν αὐτοῦ φησιν οὕτως· ὁ δὲ τοῦ Πτολεμαίου στρατηγὸς Σκόπας ὁρμήσας εἰς τοὺς ἄνω τόπους κατεστρέψατο ἐν τῷ χειμῶνι τὸ Ἰουδαίων ἔθνος. λέγει δὲ ἐν τῇ αὐτῇ βίβλῳ, ὡς τοῦ Σκόπα νικηθέντος ὑπ’ Ἀντιόχου τὴν μὲν Βατανέαν καὶ Σαμάρειαν καὶ Ἄβιλα καὶ Γάδαρα παρέλαβεν Ἀντίοχος, μετ’ ὀλίγον δὲ προσεχώρησαν αὐτῷ καὶ τῶν Ἰουδαίων οἱ περὶ τὸ ἱερὸν τὸ προσαγορευόμενον Ἱεροσόλυμα κατοικοῦντες, ὑπὲρ οὗ καὶ πλείω λέγειν ἔχοντες καὶ μάλιστα περὶ τῆς γενομένης περὶ τὸ ἱερὸν ἐπιφανείας, εἰς ἕτερον καιρὸν ὑπερθησόμεθα τὴν διήγησιν. καὶ Πολύβιος μὲν ταῦτα ἱστόρησεν. ἡμεῖς δ’ ἐπανάξομεν τὸν λόγον ἐπὶ τὴν διήγησιν παραθέμενοι πρῶτον τὰς ἐπιστολὰς τοῦ βασιλέως Ἀντιόχου. Βασιλεὺς Ἀντίοχος Πτολεμαίῳ χαίρειν. τῶν Ἰουδαίων καὶ παραυτίκα μέν, ἡνίκα τῆς χώρας ἐπέβημεν αὐτῶν, ἐπιδειξαμένων τὸ πρὸς ἡμᾶς φιλότιμον καὶ παραγενομένους δ’ εἰς τὴν πόλιν λαμπρῶς ἐκδεξαμένων καὶ μετὰ τῆς γερουσίας ἀπαντησάντων, ἄφθονον δὲ τὴν χορηγίαν τοῖς στρατιώταις καὶ τοῖς ἐλέφασι παρεσχημένων, συνεξελόντων δὲ καὶ τοὺς ἐν τῇ ἄκρᾳ φρουροὺς τῶν Αἰγυπτίων, ἠξιώσαμεν καὶ αὐτοὶ τούτων αὐτοὺς ἀμείψασθαι καὶ τὴν πόλιν αὐτῶν ἀναλαβεῖν κατεφθαρμένην ὑπὸ τῶν περὶ τοὺς πολέμους συμπεσόντων καὶ συνοικίσαι τῶν διεσπαρμένων εἰς αὐτὴν πάλιν συνελθόντων. πρῶτον δ’ αὐτοῖς ἐκρίναμεν διὰ τὴν εὐσέβειαν παρασχεῖν εἰς τὰς θυσίας σύνταξιν κτηνῶν τε θυσίμων καὶ οἴνου καὶ ἐλαίου καὶ λιβάνου ἀργυρίου μυριάδας δύο καὶ σεμιδάλεως ἀρτάβας ἱερᾶς κατὰ τὸν ἐπιχώριον νόμον πυρῶν μεδίμνους χιλίους τετρακοσίους ἑξήκοντα καὶ ἁλῶν μεδίμνους τριακοσίους ἑβδομηκονταπέντε. τελεῖσθαι δ’ αὐτοῖς ταῦτα βούλομαι, καθὼς ἐπέσταλκα, καὶ τὸ περὶ τὸ ἱερὸν ἀπαρτισθῆναι ἔργον τάς τε στοὰς κἂν εἴ τι ἕτερον οἰκοδομῆσαι δέοι· ἡ δὲ τῶν ξύλων ὕλη κατακομιζέσθω ἐξ αὐτῆς τε τῆς Ἰουδαίας καὶ ἐκ τῶν ἄλλων ἐθνῶν καὶ ἐκ τοῦ Λιβάνου μηδενὸς πρασσομένου τέλος. ὁμοίως δὲ καὶ τοῖς ἄλλοις, ἐν οἷς ἂν ἐπιφανεστέραν γίγνεσθαι τὴν τοῦ ἱεροῦ ἐπισκευὴν δέῃ. πολιτευέσθωσαν δὲ πάντες οἱ ἐκ τοῦ ἔθνους κατὰ τοὺς πατρίους νόμους, ἀπολυέσθω δ’ ἡ γερουσία καὶ οἱ ἱερεῖς καὶ γραμματεῖς τοῦ ἱεροῦ καὶ ἱεροψάλται ὧν ὑπὲρ τῆς κεφαλῆς τελοῦσιν καὶ τοῦ στεφανιτικοῦ φόρου καὶ τοῦ περὶ τῶν ἄλλων. ἵνα δὲ θᾶττον ἡ πόλις κατοικισθῇ, δίδωμι τοῖς τε νῦν κατοικοῦσιν καὶ κατελευσομένοις ἕως τοῦ Ὑπερβερεταίου μηνὸς ἀτελέσιν εἶναι μέχρι τριῶν ἐτῶν. ἀπολύομεν δὲ καὶ εἰς τὸ λοιπὸν αὐτοὺς τοῦ τρίτου μέρους τῶν φόρων, ὥστε αὐτῶν ἐπανορθωθῆναι τὴν βλάβην. καὶ ὅσοι ἐκ τῆς πόλεως ἁρπαγέντες δουλεύουσιν, αὐτούς τε τούτους καὶ τοὺς ὑπ’ αὐτῶν γεννηθέντας ἐλευθέρους ἀφίεμεν καὶ τὰς οὐσίας αὐτοῖς ἀποδίδοσθαι κελεύομεν.", "st": "12.3.3"}, {"sp": "N", "t": "Ἡ μὲν οὖν ἐπιστολὴ ταῦτα περιεῖχεν. σεμνύνων δὲ καὶ τὸ ἱερὸν πρόγραμμα κατὰ πᾶσαν τὴν βασιλείαν ἐξέθηκεν περιέχον τάδε· μηδενὶ ἐξεῖναι ἀλλοφύλῳ εἰς τὸν περίβολον εἰσιέναι τοῦ ἱεροῦ τὸν ἀπηγορευμένον τοῖς Ἰουδαίοις, εἰ μὴ οἷς ἁγνισθεῖσίν ἐστιν ἔθιμον κατὰ τὸν πάτριον νόμον. μηδ’ εἰς τὴν πόλιν εἰσφερέσθω ἵππεια κρέα μηδὲ ἡμιόνεια μηδὲ ἀγρίων ὄνων καὶ ἡμέρων παρδάλεών τε καὶ ἀλωπέκων καὶ λαγῶν καὶ καθόλου δὲ πάντων τῶν ἀπηγορευμένων ζῴων τοῖς Ἰουδαίοις· μηδὲ τὰς δορὰς εἰσφέρειν ἐξεῖναι, ἀλλὰ μηδὲ τρέφειν τι τούτων ἐν τῇ πόλει· μόνοις δὲ τοῖς προγονικοῖς θύμασιν, ἀφ’ ὧν καὶ τῷ θεῷ δεῖ καλλιερεῖν, ἐπιτετράφθαι χρῆσθαι. ὁ δέ τι τούτων παραβὰς ἀποτινύτω τοῖς ἱερεῦσιν ἀργυρίου δραχμὰς τρισχιλίας. Ἔγραψε δὲ μαρτυρῶν ἡμῖν εὐσέβειάν τε καὶ πίστιν, ἡνίκα νεωτερίζοντα τὰ κατὰ τὴν Φρυγίαν ἐπύθετο καὶ Λυδίαν καθ’ ὃν ἦν καιρὸν ἐν ταῖς ἄνω σατραπείαις, κελεύων Ζεῦξιν τὸν αὐτοῦ στρατηγὸν καὶ ἐν τοῖς μάλιστα φίλον πέμψαι τινὰς τῶν ἡμετέρων ἐκ Βαβυλῶνος εἰς Φρυγίαν. γράφει δ’ οὕτως· βασιλεὺς Ἀντίοχος Ζεύξιδι τῷ πατρὶ χαίρειν. εἰ ἔρρωσαι, εὖ ἂν ἔχοι, ὑγιαίνω δὲ καὶ αὐτός. πυνθανόμενος τοὺς ἐν Λυδίᾳ καὶ Φρυγίᾳ νεωτερίζοντας μεγάλης ἐπιστροφῆς ἡγησάμην τοῦτό μοι δεῖσθαι, καὶ βουλευσαμένῳ μοι μετὰ τῶν φίλων, τί δεῖ ποιεῖν, ἔδοξεν εἰς τὰ φρούρια καὶ τοὺς ἀναγκαιοτάτους τόπους τῶν ἀπὸ τῆς Μεσοποταμίας καὶ Βαβυλωνίας Ἰουδαίων οἴκους δισχιλίους σὺν ἐπισκευῇ μεταγαγεῖν. πέπεισμαι γὰρ εὔνους αὐτοὺς ἔσεσθαι τῶν ἡμετέρων φύλακας διὰ τὴν πρὸς τὸν θεὸν εὐσέβειαν, καὶ μαρτυρουμένους δ’ αὐτοὺς ὑπὸ τῶν προγόνων εἰς πίστιν οἶδα καὶ προθυμίαν εἰς ἃ παρακαλοῦνται· βούλομαι τοίνυν καίπερ ἐργώδους ὄντος τοῦ μεταγαγεῖν ὑποσχομένους νόμοις αὐτοὺς χρῆσθαι τοῖς ἰδίοις. ὅταν δ’ αὐτοὺς ἀγάγῃς εἰς τοὺς προειρημένους τόπους, εἴς τ’ οἰκοδομίας οἰκιῶν αὐτοῖς δώσεις τόπον ἑκάστῳ καὶ χώραν εἰς γεωργίαν καὶ φυτείαν ἀμπέλων, καὶ ἀτελεῖς τῶν ἐκ τῆς γῆς καρπῶν ἀνήσεις ἐπὶ ἔτη δέκα. μετρείσθωσαν δὲ καὶ ἄχρις ἂν τοὺς παρὰ τῆς γῆς καρποὺς λαμβάνωσιν σῖτον εἰς τὰς τῶν θεραπόντων διατροφάς· διδόσθω δὲ καὶ τοῖς εἰς τὰς χρείας ὑπηρετοῦσιν τὸ αὔταρκες, ἵνα τῆς παρ’ ἡμῶν τυγχάνοντες φιλανθρωπίας προθυμοτέρους παρέχωσιν αὑτοὺς περὶ τὰ ἡμέτερα. πρόνοιαν δὲ ποιοῦ καὶ τοῦ ἔθνους κατὰ τὸ δυνατόν, ὅπως ὑπὸ μηδενὸς ἐνοχλῆται. περὶ μὲν οὖν τῆς Ἀντιόχου φιλίας τοῦ μεγάλου πρὸς Ἰουδαίους ταῦτα ἡμῖν ἀποχρώντως εἰρήσθω μαρτύρια.", "st": "12.3.4"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα φιλίαν καὶ σπονδὰς πρὸς Πτολεμαῖον Ἀντίοχος ἐποιήσατο καὶ δίδωσιν αὐτῷ τὴν θυγατέρα Κλεοπάτραν πρὸς γάμον παραχωρήσας αὐτῷ τῆς κοίλης Συρίας καὶ Σαμαρείας καὶ Ἰουδαίας καὶ Φοινίκης φερνῆς ὀνόματι. καὶ διαιρεθέντων εἰς ἀμφοτέρους τοὺς βασιλέας τῶν φόρων τὰς ἰδίας ἕκαστοι τῶν ἐπισήμων ὠνοῦντο πατρίδας φορολογεῖν καὶ συναθροίζοντες τὸ προστεταγμένον κεφάλαιον τοῖς βασιλεῦσιν ἐτέλουν. ἐν τούτῳ τῷ χρόνῳ Σαμαρεῖς εὖ πράσσοντες πολλὰ τοὺς Ἰουδαίους ἐκάκωσαν τήν τε χώραν αὐτῶν τεμόντες καὶ σώματα διαρπάσαντες· ἐγένετο δὲ ταῦτα ἐπὶ ἀρχιερέως Ὀνίου. τελευτήσαντος γὰρ Ἐλεαζάρου τὴν ἀρχιερωσύνην ὁ θεῖος αὐτοῦ Μανασσῆς παρέλαβεν, μεθ’ ὃν καταστρέψαντα τὸν βίον Ὀνίας τὴν τιμὴν ἐξεδέξατο Σίμωνος υἱὸς ὢν τοῦ δικαίου κληθέντος· Σίμων δ’ ἦν ἀδελφὸς Ἐλεαζάρου, καθὼς προεῖπον. οὗτος ὁ Ὀνίας βραχὺς ἦν τὴν διάνοιαν καὶ χρημάτων ἥττων καὶ διὰ τοῦτο τὸν ὑπὲρ τοῦ λαοῦ φόρον, ὃν τοῖς βασιλεῦσιν οἱ πατέρες αὐτοῦ ἐτέλουν ἐκ τῶν ἰδίων, τάλαντα εἴκοσιν ἀργυρίου μὴ δούς, εἰς ὀργὴν ἐκίνησεν τὸν βασιλέα Πτολεμαῖον [τὸν Εὐεργέτην, ὃς ἦν πατὴρ τοῦ Φιλοπάτορος]. καὶ πέμψας εἰς Ἱεροσόλυμα πρεσβευτὴν ᾐτιᾶτο τὸν Ὀνίαν ὡς οὐκ ἀποδιδόντα τοὺς φόρους καὶ ἠπείλει κληρουχήσειν αὐτῶν τὴν γῆν οὐκ ἀπολαβὼν καὶ πέμψειν τοὺς ἐνοικήσοντας στρατιώτας. ἀκούσαντες δὲ τὰ παρὰ τοῦ βασιλέως οἱ Ἰουδαῖοι συνεχύθησαν, τὸν δὲ Ὀνίαν τούτων ἐδυσώπει διὰ τὴν φιλοχρηματίαν οὐδέν.", "st": "12.4.1"}, {"sp": "N", "t": "Ἰώσηπος δέ τις, νέος μὲν ἔτι τὴν ἡλικίαν, ἐπὶ σεμνότητι δὲ καὶ προνοίᾳ δικαιοσύνης δόξαν ἔχων παρὰ τοῖς Ἱεροσολυμίταις, Τωβίου μὲν πατρός, ἐκ δὲ τῆς Ὀνίου τοῦ ἀρχιερέως ἀδελφῆς γεγονώς, δηλωσάσης αὐτῷ τῆς μητρὸς τὴν τοῦ πρεσβευτοῦ παρουσίαν, ἔτυχεν γὰρ αὐτὸς ἀποδημῶν εἰς Φικόλαν κώμην ἐξ ἧς ὑπῆρχεν, ἐλθὼν εἰς τὴν πόλιν ἐπέπληττε τῷ Ὀνίᾳ μὴ προνοουμένῳ τῆς ἀσφαλείας τῶν πολιτῶν, ἀλλ’ εἰς κινδύνους τὸ ἔθνος βουλομένῳ περιστῆσαι διὰ τὴν τῶν χρημάτων ἀποστέρησιν, δι’ ἃ καὶ τοῦ λαοῦ τὴν προστασίαν λαβεῖν αὐτὸν ἔλεγεν καὶ τῆς ἀρχιερατικῆς τιμῆς ἐπιτυχεῖν. εἰ δ’ ἐρωτικῶς οὕτως ἔχοι τῶν χρημάτων, ὡς δι’ αὐτὰ καὶ τὴν πατρίδα κινδυνεύουσαν ἰδεῖν ὑπομεῖναι καὶ πᾶν ὁτιοῦν παθόντας αὐτοῦ τοὺς πολίτας, συνεβούλευσεν ἀπελθόντα πρὸς τὸν βασιλέα δεηθῆναι αὐτοῦ ἢ πάντων αὐτῷ παραχωρῆσαι τῶν χρημάτων ἢ μέρους. τοῦ δὲ Ὀνίου μήτε ἄρχειν θέλειν ἀποκριναμένου καὶ τὴν ἀρχιερωσύνην δ’ εἰ δυνατόν ἐστιν ἑτοίμως ἔχειν ἀποθέσθαι λέγοντος μήτε ἀναβήσεσθαι πρὸς τὸν βασιλέα, μέλειν γὰρ αὐτῷ περὶ τούτων οὐδέν, εἰ πρεσβεύειν αὐτῷ συγχωρεῖ πρὸς τὸν Πτολεμαῖον ὑπὲρ τοῦ ἔθνους ἐπηρώτησεν. φήσαντος δὲ ἐπιτρέπειν ἀναβὰς εἰς τὸ ἱερὸν ὁ Ἰώσηπος καὶ συγκαλέσας τὸ πλῆθος εἰς ἐκκλησίαν μηδὲν ταράσσεσθαι μηδὲ φοβεῖσθαι παρῄνει διὰ τὴν Ὀνίου τοῦ θείου περὶ αὐτῶν ἀμέλειαν, ἀλλ’ ἐν ἀδείᾳ τῶν ἀπὸ τῆς σκυθρωποτέρας ἐλπίδος τὴν διάνοιαν αὐτοὺς ἔχειν ἠξίου· πρεσβεύσειν γὰρ αὐτὸς ἐπηγγέλλετο πρὸς τὸν βασιλέα καὶ πείσειν αὐτόν, ὅτι μηδὲν ἀδικοῦσιν. καὶ τὸ μὲν πλῆθος τούτων ἀκοῦσαν εὐχαριστεῖ τῷ Ἰωσήπῳ, καταβὰς δ’ αὐτὸς ἐκ τοῦ ἱεροῦ ξενίᾳ τε ὑποδέχεται τὸν παρὰ τοῦ Πτολεμαίου πεπρεσβευκότα καὶ δωρησάμενος αὐτὸν πολυτελέσι δωρεαῖς καὶ ἐπὶ πολλὰς ἑστιάσας φιλοτίμως ἡμέρας προέπεμψε πρὸς τὸν βασιλέα, φράσας αὐτῷ καὶ αὐτὸς ἀκολουθήσειν· καὶ γὰρ ἔτι μᾶλλον γεγόνει πρόθυμος πρὸς τὴν ἄφιξιν τὴν παρὰ τὸν βασιλέα τοῦ πρεσβευτοῦ προτρεψαμένου καὶ παρορμήσαντος εἰς Αἴγυπτον ἐλθεῖν καὶ πάντων ὧν ἂν δέηται παρὰ Πτολεμαίου τυχεῖν αὐτὸν ποιήσειν ὑποσχομένου· τὸ γὰρ ἐλευθέριον αὐτοῦ καὶ τὸ σεμνὸν τοῦ ἤθους λίαν ἠγάπησεν.", "st": "12.4.2"}, {"sp": "N", "t": "Καὶ ὁ μὲν πρεσβευτὴς ἐλθὼν εἰς Αἴγυπτον ἀπήγγειλεν τῷ βασιλεῖ τὴν τοῦ Ὀνίου ἀγνωμοσύνην καὶ περὶ τῆς τοῦ Ἰωσήπου χρηστότητος ἐδήλου, καὶ ὅτι μέλλοι πρὸς αὐτὸν ἥξειν παραιτησόμενος τῶν ἁμαρτημάτων τὸ πλῆθος· εἶναι γὰρ αὐτοῦ προστάτην· ἀμέλει τοσαύτῃ [περὶ] τῶν ἐγκωμίων τῶν περὶ τοῦ νεανίσκου διετέλεσε χρώμενος περιουσίᾳ, ὥστε καὶ τὸν βασιλέα καὶ τὴν γυναῖκα αὐτοῦ Κλεοπάτραν προδιέθηκεν οἰκείως ἔχειν πρὸς τὸν Ἰώσηπον οὔπω παρόντα. ὁ δὲ Ἰώσηπος διαπέμψας πρὸς τοὺς φίλους εἰς Σαμάρειαν καὶ δανεισάμενος ἀργύριον καὶ τὰ πρὸς τὴν ἀποδημίαν ἑτοιμασάμενος ἐσθῆτάς τε καὶ ἐκπώματα καὶ ὑποζύγια, καὶ ταῦθ’ ὡς περὶ δισμυρίας δραχμὰς παρασκευασάμενος εἰς Ἀλεξάνδρειαν παρεγένετο. ἔτυχεν δὲ κατ’ ἐκεῖνον τὸν καιρὸν πάντας ἀναβαίνειν τοὺς ἀπὸ τῶν πόλεων τῶν τῆς Συρίας καὶ Φοινίκης πρώτους καὶ τοὺς ἄρχοντας ἐπὶ τὴν τῶν τελῶν ὠνήν· κατ’ ἔτος δὲ αὐτὰ τοῖς δυνατοῖς τῶν ἐν ἑκάστῃ πόλει ἐπίπρασκεν ὁ βασιλεύς. ὁρῶντες οὖν οὗτοι κατὰ τὴν ὁδὸν τὸν Ἰώσηπον ἐχλεύαζον ἐπὶ πενίᾳ καὶ λιτότητι. ὡς δ’ εἰς τὴν Ἀλεξάνδρειαν ἀφικόμενος ἐν Μέμφει τὸν Πτολεμαῖον ἤκουσεν ὄντα, ὑπαντησάμενος συνέβαλεν αὐτῷ. καθεζομένου δὲ τοῦ βασιλέως ἐπ’ ὀχήματος μετὰ τῆς γυναικὸς καὶ μετὰ Ἀθηνίωνος φίλου, οὗτος δ’ ἦν ὁ πρεσβεύσας εἰς Ἱεροσόλυμα καὶ παρὰ Ἰωσήπῳ ξενισθείς, θεασάμενος αὐτὸν ὁ Ἀθηνίων εὐθὺς ἐποίει τῷ βασιλεῖ γνώριμον, τοῦτον εἶναι λέγων, περὶ οὗ παραγενόμενος ἐξ Ἱεροσολύμων ἀπήγγειλεν, ὡς ἀγαθός τε εἴη καὶ φιλότιμος νεανίσκος. ὁ δὲ Πτολεμαῖος πρῶτός τε αὐτὸν ἠσπάσατο καὶ δὴ ἀναβῆναι ἐπὶ τὸ ὄχημα παρεκάλεσεν καὶ καθεσθέντος ἤρξατο περὶ τῶν Ὀνίᾳ πραττομένων ἐγκαλεῖν. ὁ δέ συγγίνωσκε, φησίν, αὐτῷ διὰ τὸ γῆρας· οὐ γὰρ λανθάνει σε πάντως, ὅτι καὶ τοὺς πρεσβύτας καὶ τὰ νήπια τὴν αὐτὴν διάνοιαν ἔχειν συμβέβηκεν. παρὰ δ’ ἡμῶν ἔσται σοι τῶν νέων ἅπαντα, ὥστε μηδὲν αἰτιᾶσθαι. ἡσθεὶς δ’ ἐπὶ τῇ χάριτι καὶ τῇ εὐτραπελίᾳ τοῦ νεανίσκου μᾶλλον αὐτὸν ὡς ἤδη καὶ πεπειραμένος ἀγαπᾶν ἤρξατο, ὡς ἔν τε τοῖς βασιλείοις αὐτὸν κελεῦσαι διαιτᾶσθαι καὶ καθ’ ἡμέραν ἐπὶ τῆς ἑστιάσεως τῆς ἰδίας ἔχειν. γενομένου δ’ ἐν Ἀλεξανδρείᾳ τοῦ βασιλέως ἰδόντες οἱ πρῶτοι τῆς Συρίας συγκαθεζόμενον αὐτῷ τὸν Ἰώσηπον ἀηδῶς ἔφερον.", "st": "12.4.3"}, {"sp": "N", "t": "Ἐνστάσης δὲ τῆς ἡμέρας, καθ’ ἣν ἔμελλεν τὰ τέλη πιπράσκεσθαι τῶν πόλεων, ἠγόραζον οἱ τοῖς ἀξιώμασιν ἐν ταῖς πατρίσιν διαφέροντες. εἰς ὀκτακισχίλια δὲ τάλαντα συναθροιζομένων τῶν τῆς κοίλης Συρίας τελῶν καὶ τῆς Φοινίκης καὶ Ἰουδαίας σὺν τῇ Σαμαρείᾳ, προσελθὼν Ἰώσηπος τοὺς μὲν ὠνουμένους διέβαλλεν ὡς συνθεμένους ὀλίγην αὐτῷ τιμὴν ὑφίστασθαι τῶν τελῶν, αὐτὸς δὲ διπλασίονα δώσειν ὑπισχνεῖτο καὶ τῶν ἁμαρτόντων εἰς τὸν οἶκον αὐτοῦ τὰς οὐσίας ἀναπέμψειν αὐτῷ· καὶ γὰρ τοῦτο τοῖς τέλεσι συνεπιπράσκετο. τοῦ δὲ βασιλέως ἡδέως ἀκούσαντος καὶ ὡς αὔξοντι τὴν πρόσοδον αὐτοῦ κατακυροῦν τὴν ὠνὴν τῶν τελῶν ἐκείνῳ φήσαντος, ἐρομένου δὲ εἰ καὶ τοὺς ἐγγυησομένους αὐτὸν ἔχει, σφόδρ’ ἀστείως ἀπεκρίνατο· δώσω γὰρ εἶπεν ἀνθρώπους ἀγαθοὺς καὶ καλούς, οἷς οὐκ ἀπιστήσετε. λέγειν δὲ τούτους οἵτινες εἶεν εἰπόντος, αὐτόν, εἶπεν, ὦ βασιλεῦ, σέ τε καὶ τὴν γυναῖκα τὴν σὴν ὑπὲρ ἑκατέρου μέρους ἐγγυησομένους δίδωμί σοι. γελάσας δ’ ὁ Πτολεμαῖος συνεχώρησεν αὐτῷ δίχα τῶν ὁμολογούντων ἔχειν τὰ τέλη. τοῦτο σφόδρα τοὺς ἀπὸ τῶν πόλεων εἰς τὴν Αἴγυπτον ἐλθόντας ἐλύπησεν ὡς παρευδοκιμηθέντας. καὶ οἱ μὲν ἐπανῆκον εἰς τὰς ἰδίας ἕκαστοι πατρίδας μετ’ αἰσχύνης.", "st": "12.4.4"}, {"sp": "N", "t": "Ὁ δὲ Ἰώσηπος λαβὼν παρὰ τοῦ βασιλέως πεζῶν μὲν στρατιώτας δισχιλίους, ἠξίωσε γὰρ βοήθειάν τινα λαβεῖν, ἵνα τοὺς ἐν ταῖς πόλεσι καταφρονοῦντας ἔχῃ βιάζεσθαι, καὶ δανεισάμενος ἐν Ἀλεξανδρείᾳ παρὰ τῶν τοῦ βασιλέως φίλων τάλαντα πεντακόσια εἰς Συρίαν ἐξώρμησεν. γενόμενος δὲ ἐν Ἀσκάλωνι τοὺς φόρους ἀπαιτῶν τοὺς Ἀσκαλωνίτας, ἐπεὶ μηδὲν ἐβούλοντο διδόναι, ἀλλὰ καὶ προσύβριζον αὐτόν, συλλαβὼν αὐτῶν τοὺς πρωτεύοντας ὡς εἴκοσιν ἀπέκτεινε καὶ τὰς οὐσίας αὐτῶν εἰς χίλια τάλαντα ἀθροισθείσας ἔπεμψε τῷ βασιλεῖ, δηλῶν αὐτῷ καὶ τὰ γεγενημένα. θαυμάσας δ’ αὐτὸν ὁ Πτολεμαῖος τοῦ φρονήματος καὶ τῶν πεπραγμένων ἐπαινέσας ἐφίησιν αὐτῷ ποιεῖν ὅ τι βούλεται. ταῦτ’ ἀκούσαντες οἱ Σύροι κατεπλάγησαν καὶ παράδειγμα τῆς ἀπειθείας χαλεπὸν ἔχοντες τοὺς τῶν Ἀσκαλωνιτῶν ἄνδρας ἀνῃρημένους ἀνοίγοντες τὰς πύλας ἐδέχοντο προθύμως τὸν Ἰώσηπον καὶ τοὺς φόρους ἐτέλουν. ἐπιχειρούντων δὲ καὶ Σκυθοπολιτῶν ὑβρίζειν αὐτὸν καὶ μὴ παρέχειν τοὺς φόρους αὐτῷ, οὓς μηδὲν ἀμφισβητοῦντες ἐτέλουν, καὶ τούτων ἀποκτείνας τοὺς πρώτους τὰς οὐσίας αὐτῶν ἀπέστειλε τῷ βασιλεῖ. συναγαγὼν δὲ πολλὰ χρήματα καὶ κέρδη μεγάλα ποιήσας ἐκ τῆς ὠνῆς τῶν τελῶν, εἰς τὸ διαμεῖναι τὴν ὑπάρχουσαν αὐτῷ δύναμιν τοῖς οὖσι κατεχρήσατο, τὴν ἀφορμὴν αὐτῷ καὶ τὴν ὑπόθεσιν τῆς τότε εὐτυχίας τηρεῖν φρόνιμον ἡγούμενος ἐξ αὐτῶν ὧν αὐτὸς ἐκέκτητο· πολλὰ γὰρ ὑπὸ χεῖρα τῷ βασιλεῖ καὶ τῇ Κλεοπάτρᾳ δῶρα ἔπεμπεν καὶ τοῖς φίλοις αὐτῶν καὶ πᾶσιν τοῖς περὶ τὴν αὐλὴν δυνατοῖς ὠνούμενος διὰ τούτων τὴν εὔνοιαν τὴν παρ’ αὐτῶν.", "st": "12.4.5"}, {"sp": "N", "t": "Ἀπέλαυσε δὲ ταύτης τῆς εὐτυχίας ἐπὶ ἔτη εἴκοσι καὶ δύο, πατὴρ μὲν γενόμενος ἐκ μιᾶς γυναικὸς παίδων ἑπτά, ποιησάμενος δὲ καὶ ἐκ τῆς τοῦ ἀδελφοῦ Σολυμίου θυγατρὸς ἕνα Ὑρκανὸν ὄνομα. γαμεῖ δὲ ταύτην ἐξ αἰτίας τοιαύτης· τἀδελφῷ ποτε συνελθὼν εἰς Ἀλεξάνδρειαν ἄγοντι καὶ τὴν θυγατέρα γάμων ὥραν ἔχουσαν, ὅπως αὐτὴν συνοικίσῃ τινὶ τῶν ἐπ’ ἀξιώματος Ἰουδαίων, καὶ δειπνῶν παρὰ τῷ βασιλεῖ, ὀρχηστρίδος εἰσελθούσης εἰς τὸ συμπόσιον εὐπρεποῦς ἐρασθεὶς τῷ ἀδελφῷ τοῦτο μηνύει παρακαλῶν αὐτόν, ἐπεὶ καὶ νόμῳ κεκώλυται παρὰ Ἰουδαίοις ἀλλοφύλῳ πλησιάζειν γυναικί, συγκρύψαντα τὸ ἁμάρτημα καὶ διάκονον ἀγαθὸν γενόμενον παρασχεῖν αὐτῷ ὥστ’ ἐκπλῆσαι τὴν ἐπιθυμίαν. ὁ δὲ ἀδελφὸς ἀσμένως δεξάμενος τὴν διακονίαν, κοσμήσας τὴν αὐτοῦ θυγατέρα νυκτὸς ἤγαγε πρὸς αὐτὸν καὶ συγκατεκοίμισεν. ὁ δ’ ὑπὸ μέθης ἀγνοήσας τἀληθὲς συνέρχεται τῇ τοῦ ἀδελφοῦ θυγατρί, καὶ τούτου γενομένου πολλάκις ἤρα σφοδρότερον. ἔφη δὲ καὶ πρὸς τὸν ἀδελφόν, ὡς κινδυνεύει τῷ ζῆν ἐρῶν ὀρχηστρίδος, ἧς ἴσως οὐκ ἂν αὐτῷ παραχωρήσειν τὸν βασιλέα. τοῦ δὲ ἀδελφοῦ μηδὲν ἀγωνιᾶν παρακαλοῦντος, ἀπολαύειν δ’ ἧς ἐρᾷ μετ’ ἀδείας καὶ γυναῖκα ἔχειν αὐτὴν φήσαντος καὶ τἀληθὲς αὐτῷ φανερὸν ποιήσαντος, ὡς ἕλοιτο μᾶλλον τὴν ἰδίαν ὑβρίσαι θυγατέρα ἢ περιιδεῖν ἐκεῖνον ἐν αἰσχύνῃ γενόμενον, ἐπαινέσας αὐτὸν Ἰώσηπος τῆς φιλαδελφίας συνῴκησεν αὐτοῦ τῇ θυγατρὶ καὶ παῖδα ἐξ αὐτῆς ἐγέννησεν Ὑρκανόν, ὡς προειρήκαμεν. ἔτι δὲ ὢν τρισκαίδεκα ἐτῶν οὗτος ὁ παῖς νεώτερος ἐπεδείκνυτο τὴν φυσικὴν ἀνδρείαν καὶ σύνεσιν, ὡς ζηλοτυπηθῆναι δεινῶς αὐτὸν ὑπὸ τῶν ἀδελφῶν ὄντα πολὺ κρείττονα καὶ φθονηθῆναι δυνάμενον. τοῦ δὲ Ἰωσήπου γνῶναι θελήσαντος, τίς αὐτῷ τῶν υἱῶν πρὸς ἀρετὴν εὖ πέφυκεν καὶ καθ’ ἕνα πέμψαντος πρὸς τοὺς παιδεύειν τότε δόξαν ἔχοντας, οἱ λοιποὶ μὲν ὑπὸ ῥᾳθυμίας καὶ τῆς πρὸς τὸ φιλεργεῖν μαλακίας ἀνόητοι καὶ ἀμαθεῖς ἐπανῆκον αὐτῷ, μετὰ δ’ ἐκείνους τὸν νεώτατον Ὑρκανόν, δοὺς αὐτῷ τριακόσια ζεύγη βοῶν, ἐξέπεμψεν ὁδὸν ἡμερῶν δύο εἰς τὴν ἐρημίαν σπεροῦντα τὴν γῆν ἀποκρύψας τοὺς ζευκτῆρας ἱμάντας. ὁ δὲ γενόμενος ἐν τῷ τόπῳ καὶ τοὺς ἱμάντας οὐκ ἔχων, τῆς μὲν τῶν βοηλατῶν γνώμης κατηλόγησεν συμβουλευόντων πέμπειν πρὸς τὸν πατέρα κομιοῦντάς τινας τοὺς ἱμάντας, τὸν δὲ καιρὸν ἡγησάμενος μὴ δεῖν ἀπολλύναι περιμένοντα τοὺς ἀποσταλησομένους ἐπενόησέν τι στρατηγικὸν καὶ τῆς ἡλικίας πρεσβύτερον. κατασφάξας γὰρ δέκα ζεύγη τὰ μὲν κρέα τοῖς ἐργάταις διένειμεν, τεμὼν δὲ τὰς δορὰς αὐτῶν καὶ ποιήσας ἱμάντας ἐνέδησεν τούτοις τὰ ζυγά, καὶ τοῦτον τὸν τρόπον σπείρας ἣν ὁ πατὴρ αὐτῷ προσέταξε γῆν ὑπέστρεψε πρὸς αὐτόν. ἐλθόντα δ’ ὁ πατὴρ ὑπερηγάπησεν τοῦ φρονήματος, καὶ τὴν ὀξύτητα τῆς διανοίας καὶ τὸ ἐπ’ αὐτῇ τολμηρὸν ἐπαινέσας ὡς μόνον ὄντα γνήσιον ἔτι μᾶλλον ἔστεργεν ἀχθομένων ἐπὶ τούτῳ τῶν ἀδελφῶν.", "st": "12.4.6"}, {"sp": "N", "t": "Ὡς δ’ ἀπήγγειλέ τις αὐτῷ κατὰ τοῦτον τὸν καιρὸν υἱὸν τῷ βασιλεῖ Πτολεμαίῳ γεγενῆσθαι, καὶ πάντες οἱ πρῶτοι τῆς Συρίας καὶ τῆς ὑπηκόου χώρας ἑορτάζοντες τὴν γενέσιον ἡμέραν τοῦ παιδίου μετὰ μεγάλης παρασκευῆς εἰς τὴν Ἀλεξάνδρειαν ἐξώρμων, αὐτὸς μὲν ὑπὸ γήρως κατείχετο, τῶν δὲ υἱῶν ἀπεπειρᾶτο εἴ τις αὐτῶν ἀπελθεῖν βούλεται πρὸς τὸν βασιλέα. τῶν δὲ πρεσβυτέρων παραιτησαμένων καὶ πρὸς τὰς τοιαύτας συνουσίας ἀγροικότερον ἔχειν φησάντων, τὸν δ’ ἀδελφὸν Ὑρκανὸν πέμπειν συμβουλευσάντων, ἡδέως ἀκούσας καλεῖ τὸν Ὑρκανὸν καὶ εἰ δύναται πρὸς τὸν βασιλέα βαδίσαι καὶ πρόθυμός ἐστιν ἀνέκρινεν. ἐπαγγειλαμένου δὲ πορεύσεσθαι καὶ δεῖσθαι χρημάτων οὐ πολλῶν φήσαντος εἰς τὴν ὁδόν, ζήσεσθαι γὰρ ἐπιεικῶς ὥστε ἀρκέσειν αὐτῷ δραχμὰς μυρίας, ἥσθη τοῦ παιδὸς τῇ σωφροσύνῃ. διαλιπὼν δὲ ὀλίγον ὁ παῖς συνεβούλευε τῷ πατρὶ δῶρα μὲν αὐτόθεν μὴ πέμπειν τῷ βασιλεῖ, δοῦναι δὲ ἐπιστολὴν πρὸς τὸν ἐν Ἀλεξανδρείᾳ οἰκονόμον, ὅπως αὐτῷ παρέχῃ πρὸς ὠνὴν ὧν ἂν εὕρῃ καλλίστων καὶ πολυτελῶν χρήματα. ὁ δὲ νομίζων δέκα ταλάντων ἔσεσθαι τὴν εἰς τὰς δωρεὰς τῷ βασιλεῖ δαπάνην καὶ τὸν υἱὸν ἐπαινέσας ὡς παραινοῦντα καλῶς, γράφει τῷ οἰκονόμῳ Ἀρίονι, ὃς ἅπαντα τὰ ἐν Ἀλεξανδρείᾳ χρήματα αὐτοῦ διῴκει οὐκ ὄντα ἐλάσσω τρισχιλίων ταλάντων· ὁ γὰρ Ἰώσηπος τὰ ἀπὸ τῆς Συρίας χρήματα ἔπεμπεν εἰς Ἀλεξάνδρειαν καὶ τῆς προθεσμίας ἐνισταμένης, καθ’ ἣν ἔδει τῷ βασιλεῖ τοὺς φόρους ἀπαριθμεῖν, ἔγραφεν τῷ Ἀρίονι τοῦτο ποιεῖν. πρὸς οὖν τοῦτον ἀπαιτήσας τὸν πατέρα ἐπιστολήν, λαβὼν εἰς τὴν Ἀλεξάνδρειαν ὥρμησεν. ἐξελθόντος δ’ αὐτοῦ γράφουσιν οἱ ἀδελφοὶ πᾶσι τοῖς τοῦ βασιλέως φίλοις, ἵν’ αὐτὸν διαφθείρωσιν.", "st": "12.4.7"}, {"sp": "N", "t": "Ὡς δὲ παραγενόμενος εἰς τὴν Ἀλεξάνδρειαν ἀπέδωκε τῷ Ἀρίονι τὴν ἐπιστολήν, ἐπερωτήσαντος αὐτοῦ, πόσα βούλεται τάλαντα λαβεῖν, ἤλπισε δ’ αὐτὸν αἰτήσειν δέκα ἢ βραχεῖ τούτων πλέον, εἰπόντος χιλίων χρῄζειν ὀργισθεὶς ἐπέπληττεν αὐτῷ ὡς ἀσώτως ζῆν διεγνωκότι, καὶ πῶς ὁ πατὴρ αὐτοῦ συναγάγοι τὴν οὐσίαν [ὡς] πονῶν καὶ ταῖς ἐπιθυμίαις ἀντέχων ἐδήλου καὶ μιμητὴν αὐτὸν ἠξίου γενέσθαι τοῦ γεγεννηκότος· δώσειν δ’ οὐδὲν πλέον ταλάντων δέκα καὶ ταῦτα εἰς δωρεὰς τῷ βασιλεῖ. παροξυνθεὶς δ’ ὁ παῖς εἰς δεσμὰ τὸν Ἀρίονα ἐνέβαλεν. τῆς δὲ τοῦ Ἀρίονος γυναικὸς τοῦτο δηλωσάσης τῇ Κλεοπάτρᾳ καὶ δεηθείσης, ὅπως ἐπιπλήξῃ τῷ παιδί, σφόδρα γὰρ ἦν ὁ Ἀρίων ἐν τιμῇ παρ’ αὐτῇ, φανερὸν τῷ βασιλεῖ τοῦτο ἐποίησεν ἡ Κλεοπάτρα. ὁ δὲ Πτολεμαῖος πέμψας πρὸς τὸν Ὑρκανὸν θαυμάζειν ἔλεγεν, πῶς ἀποσταλεὶς πρὸς αὐτὸν ὑπὸ τοῦ πατρὸς οὔτε ὀφθείη αὐτῷ καὶ προσέτι δήσειεν τὸν οἰκονόμον· ἐλθόντα οὖν τὴν αἰτίαν αὐτῷ μηνύειν ἐκέλευσεν. τὸν δέ φασιν ἀποκρίνασθαι τῷ παρὰ τοῦ βασιλέως λέγειν αὐτῷ, ὅτι νόμος ἐστὶ παρ’ αὐτῷ κωλύων τὸν γεννηθέντα γεύσασθαι θυσιῶν, πρὶν εἰς τὸ ἱερὸν ἔλθῃ καὶ θύσῃ τῷ θεῷ· κατὰ δὴ τοῦτον τὸν λογισμὸν οὐδ’ αὐτὸς ἐλθεῖν πρὸς αὐτὸν περιμένων τὰ δῶρα κομίσαι τοῦ πατρὸς εὐεργέτῃ γεγενημένῳ. τὸν δὲ δοῦλον κολάσαι παρακούσαντα ὧν προσέταξεν· διαφέρειν γὰρ οὐδὲν ἢ μικρὸν εἶναί τινα δεσπότην ἢ μέγαν· ἂν οὖν μὴ κολάζωμεν τοὺς τοιούτους, καὶ σὺ προσδόκα ὑπὸ τῶν ἀρχομένων καταφρονηθήσεσθαι. ταῦτ’ ἀκούσας ὁ Πτολεμαῖος εἰς γέλωτα ἐτράπη καὶ τὴν μεγαλοφροσύνην τοῦ παιδὸς ἐθαύμασεν.", "st": "12.4.8"}, {"sp": "N", "t": "Μαθὼν δὲ ὁ Ἀρίων, ὅτι τοῦτον ὁ βασιλεὺς διετέθη τὸν τρόπον καὶ μηδεμία βοήθειά ἐστιν αὐτῷ, δοὺς τὰ χίλια τάλαντα τῷ παιδὶ τῶν δεσμῶν ἀπελύθη. καὶ τρεῖς διαλιπὼν ἡμέρας ὁ Ὑρκανὸς ἠσπάσατο τοὺς βασιλέας. οἱ δὲ ἀσμένως αὐτὸν εἶδον καὶ φιλοφρόνως εἱστίασαν διὰ τὴν πρὸς τὸν πατέρα τιμήν. λάθρα δὲ πρὸς τοὺς ἐμπόρους ἀπελθὼν ὠνεῖται παρ’ αὐτῶν παῖδας μὲν ἑκατὸν γράμματα ἐπισταμένους καὶ ἀκμαιοτάτους, ἑνὸς ἕκαστον ταλάντου, ἑκατὸν δὲ παρθένους τῆς αὐτῆς τιμῆς ἑκάστην. κληθεὶς δ’ ἐφ’ ἑστίασιν πρὸς τὸν βασιλέα μετὰ τῶν πρώτων τῆς χώρας ὑποκατακλίνεται πάντων, καταφρονηθεὶς ὡς παῖς ἔτι τὴν ἡλικίαν ὑπὸ τῶν τοὺς τόπους κατὰ τὴν ἀξίαν διανεμόντων. τῶν δὲ συγκατακειμένων πάντων τῶν μερῶν τὰ ὀστᾶ, ἀφῄρουν γὰρ αὐτοὶ τὰς σάρκας, σωρευόντων ἔμπροσθεν τοῦ Ὑρκανοῦ, ὡς πληρῶσαι τὴν παρακειμένην αὐτῷ τράπεζαν, Τρύφων ὃς ἦν τοῦ βασιλέως ἄθυρμα καὶ πρὸς τὰ σκώμματα καὶ τοὺς ἐν τοῖς πότοις γέλωτας ἀπεδέδεικτο, παρακαλεσάντων αὐτὸν τῶν κατακειμένων τῇ τραπέζῃ παρεστὼς τῷ βασιλεῖ, ὁρᾷς, εἶπεν, ὦ δέσποτα, τὰ παρακείμενα Ὑρκανῷ ὀστᾶ; ἐκ τούτου στόχασαι, ὅτι καὶ ὁ πατὴρ αὐτοῦ τὴν Συρίαν ἅπασαν περιέδυσεν ὡς οὗτος ταῦτα τῶν σαρκῶν ἐγύμνωσεν. γελάσαντος δὲ πρὸς τὸν τοῦ Τρύφωνος λόγον τοῦ βασιλέως καὶ ἐρομένου τὸν Ὑρκανόν, ὅτι τοσαῦτ’ αὐτῷ παράκειται ὀστᾶ, εἰκότως, εἶπεν, ὦ δέσποτα· τοὺς μὲν γὰρ κύνας τὰ ὀστᾶ σὺν τοῖς κρέασιν κατεσθίειν, ὥσπερ οὗτοι πρὸς τοὺς κατακειμένους ἐπιβλέπων, ὅτι μηθὲν ἔμπροσθεν αὐτῶν ἔκειτο, οἱ δὲ ἄνθρωποι τὸ κρέας ἐσθίουσιν, τὰ δ’ ὀστᾶ ῥίπτουσιν, ὅπερ ἄνθρωπος ὢν κἀγὼ νῦν πεποίηκα. ὁ δὲ βασιλεὺς θαυμάζει τὴν ἀπόκρισιν αὐτοῦ σοφὴν οὕτως γενομένην καὶ πάντας ἐκέλευσεν ἀνακροτῆσαι τῆς εὐτραπελίας ἀποδεχόμενος αὐτόν. τῇ δ’ ἐπιούσῃ πρὸς ἕκαστον τῶν τοῦ βασιλέως φίλων πορευόμενος καὶ τῶν περὶ τὴν αὐλὴν δυνατῶν τοὺς μὲν ἠσπάζετο, παρὰ δὲ τῶν οἰκετῶν ἀπεπυνθάνετο, τί μέλλουσιν διδόναι τῷ βασιλεῖ δῶρον ἐν τῇ τοῦ παιδὸς αὐτοῦ γενεσίῳ. τῶν δὲ ἀνὰ δέκα τάλαντα μέλλειν διδόναι φησάντων τοὺς μέν, τοὺς δὲ ἐν ἀξίᾳ κατὰ τὸ μέγεθος τῆς οὐσίας ἕκαστον αὐτῶν, ὑπεκρίνετο λυπεῖσθαι διὰ τὸ μὴ δύνασθαι τοιαύτην προσενεγκεῖν δωρεάν· πλέον γὰρ πέντε ταλάντων οὐκ ἔχειν. οἱ δὲ θεράποντες ταῦτ’ ἀκούσαντες ἀπήγγελλον τοῖς δεσπόταις. χαιρόντων δ’ αὐτῶν ὡς καταγνωσθησομένου τοῦ Ἰωσήπου καὶ προσκρούσοντος τῷ βασιλεῖ διὰ τὴν βραχύτητα τῆς δωρεᾶς, ἐνστάσης τῆς ἡμέρας οἱ μὲν ἄλλοι προσέφερον τῷ βασιλεῖ ταλάντων οἱ λίαν μεγαλοδωρεῖσθαι νομίζοντες οὐ πλεῖον εἴκοσι, ὁ δ’ Ὑρκανὸς οὓς ὠνήσατο παῖδας ἑκατὸν καὶ παρθένους τοσαύτας ἀνὰ τάλαντον ἑκάστῳ φέρειν δοὺς προσήγαγεν τοὺς μὲν τῷ βασιλεῖ, τὰς δὲ τῇ Κλεοπάτρᾳ. πάντων δὲ θαυμασάντων τὴν παρ’ ἐλπίδα τῶν δώρων πολυτέλειαν καὶ τῶν βασιλέων αὐτῶν, καὶ τοῖς φίλοις ἔτι καὶ τοῖς περὶ τὴν θεραπείαν τοῦ βασιλέως οὖσιν πολλῶν ἄξια ταλάντων δῶρα ἔδωκεν, ὡς διαφυγεῖν τὸν ἐξ αὐτῶν κίνδυνον· τούτοις γὰρ ἐγεγράφεισαν αὐτοῦ οἱ ἀδελφοὶ διαχρήσασθαι τὸν Ὑρκανόν. Πτολεμαῖος δὲ τὴν μεγαλοψυχίαν ἀγασάμενος τοῦ μειρακίου προσέταξεν αὐτῷ δωρεὰν ἣν βούλεται λαμβάνειν. ὁ δ’ οὐδὲν πλέον ἠξίωσεν αὐτῷ γενέσθαι παρ’ αὐτοῦ ἢ γράψαι τῷ πατρὶ καὶ τοῖς ἀδελφοῖς περὶ αὐτοῦ. τιμήσας οὖν αὐτὸν φιλοτιμότατα καὶ δωρεὰς δοὺς λαμπρὰς καὶ τῷ τε πατρὶ γράψας καὶ τοῖς ἀδελφοῖς καὶ πᾶσι τοῖς ἡγεμόσιν αὐτοῦ καὶ ἐπιτρόποις ἐξέπεμψεν. ἀκούσαντες δὲ οἱ ἀδελφοὶ τούτων τετυχηκότα τὸν Ὑρκανὸν παρὰ τοῦ βασιλέως καὶ μετὰ μεγάλης ἐπανερχόμενον τιμῆς, ἐξῆλθον ὑπαντησόμενοι καὶ διαφθεροῦντες αὐτὸν καὶ τοῦ πατρὸς εἰδότος· ὀργιζόμενος γὰρ αὐτῷ ἕνεκεν τῶν εἰς τὰς δωρεὰς χρημάτων οὐκ ἐφρόντιζεν τῆς σωτηρίας αὐτοῦ. τὴν ὀργὴν μέντοι τὴν πρὸς τὸν υἱὸν ὁ Ἰώσηπος ἀπεκρύπτετο φοβούμενος τὸν βασιλέα. συμβαλόντων δ’ αὐτῷ τῶν ἀδελφῶν εἰς μάχην ἄλλους τε τῶν σὺν αὐτοῖς πολλοὺς ἀπέκτεινεν καὶ δύο τῶν ἀδελφῶν, οἱ δὲ λοιποὶ διεσώθησαν εἰς Ἱεροσόλυμα πρὸς τὸν πατέρα. παραγενόμενον δ’ αὐτὸν εἰς τὴν πόλιν ἐπεὶ μηδεὶς ἐδέχετο, δείσας ἀνεχώρησεν εἰς τὴν πέραν τοῦ Ἰορδάνου ποταμοῦ κἀκεῖ διέτριβεν φορολογῶν τοὺς βαρβάρους.", "st": "12.4.9"}, {"sp": "N", "t": "Ἐβασίλευσεν δὲ κατ’ ἐκεῖνον τὸν καιρὸν τῆς Ἀσίας Σέλευκος ὁ Σωτὴρ ἐπικαλούμενος υἱὸς ὢν Ἀντιόχου τοῦ μεγάλου. τελευτᾷ δὲ καὶ ὁ τοῦ Ὑρκανοῦ πατὴρ Ἰώσηπος ἀνὴρ ἀγαθὸς γενόμενος καὶ μεγαλόφρων, καὶ τὸν τῶν Ἰουδαίων λαὸν ἐκ πτωχείας καὶ πραγμάτων ἀσθενῶν εἰς λαμπροτέρας ἀφορμὰς τοῦ βίου καταστήσας, εἴκοσι ἔτη καὶ δύο τὰ τέλη τῆς Συρίας καὶ τῆς Φοινίκης καὶ Σαμαρείας κατασχών. ἀπέθανεν δὲ καὶ ὁ θεῖος αὐτοῦ Ὀνίας τὴν ἀρχιερωσύνην Σίμωνι τῷ παιδὶ καταλιπών. Τελευτήσαντος δὲ καὶ τούτου ὁ υἱὸς αὐτοῦ διάδοχος τῆς τιμῆς Ὀνίας γίνεται, πρὸς ὃν ὁ Λακεδαιμονίων βασιλεὺς Ἄρειος πρεσβείαν τε ἔπεμψεν καὶ ἐπιστολάς, ὧν τὸ ἀντίγραφόν ἐστι τοιοῦτο· βασιλεὺς Λακεδαιμονίων Ἄρειος Ὀνίᾳ χαίρειν. ἐντυχόντες γραφῇ τινι εὕρομεν, ὡς ἐξ ἑνὸς εἶεν γένους Ἰουδαῖοι καὶ Λακεδαιμόνιοι καὶ ἐκ τῆς πρὸς Ἄβραμον οἰκειότητος. δίκαιον οὖν ἐστιν ἀδελφοὺς ὑμᾶς ὄντας διαπέμπεσθαι πρὸς ἡμᾶς περὶ ὧν ἂν βούλησθε. ποιήσομεν δὲ καὶ ἡμεῖς τοῦτο, καὶ τά τε ὑμέτερα ἴδια νομιοῦμεν καὶ τὰ αὑτῶν κοινὰ πρὸς ὑμᾶς ἕξομεν. Δημοτέλης ὁ φέρων τὰ γράμματα διαπέμπει τὰς ἐπιστολάς. τὰ γεγραμμένα ἐστὶν τετράγωνα· ἡ σφραγίς ἐστιν ἀετὸς δράκοντος ἐπειλημμένος.", "st": "12.4.10"}, {"sp": "N", "t": "Ἡ μὲν οὖν ἐπιστολὴ ἡ πεμφθεῖσα ὑπὸ τοῦ Λακεδαιμονίων βασιλέως τοῦτον περιεῖχε τὸν τρόπον. ἀποθανόντος δὲ Ἰωσήπου τὸν λαὸν συνέβη στασιάσαι διὰ τοὺς παῖδας αὐτοῦ. τῶν γὰρ πρεσβυτέρων πόλεμον ἐξενεγκαμένων πρὸς Ὑρκανόν, ὃς ἦν νεώτατος τῶν Ἰωσήπου τέκνων, διέστη τὸ πλῆθος. καὶ οἱ μὲν πλείους τοῖς πρεσβυτέροις συνεμάχουν καὶ ὁ ἀρχιερεὺς Σίμων διὰ τὴν συγγένειαν· ὁ δὲ Ὑρκανὸς ἐπανελθεῖν μὲν οὐκέτι ἔγνω εἰς Ἱεροσόλυμα, προσκαθίσας δὲ τοῖς πέραν τοῦ Ἰορδάνου συνεχῶς ἐπολέμει τοὺς Ἄραβας, ὡς πολλοὺς αὐτῶν καὶ ἀποκτεῖναι καὶ λαβεῖν αἰχμαλώτους. ᾠκοδόμησεν δὲ βᾶριν ἰσχυρὰν ἐκ λίθου λευκοῦ κατασκευάσας πᾶσαν μέχρι καὶ τῆς στέγης ἐγγλύψας ζῷα παμμεγεθέστατα, περιήγαγεν δ’ αὐτῇ εὔριπον μέγαν καὶ βαθύν. ἐκ δὲ τῆς καταντικρὺ τοῦ ὄρους πέτρας διατεμὼν αὐτῆς τὸ προέχον σπήλαια πολλῶν σταδίων τὸ μῆκος κατεσκεύασεν. ἔπειτα οἴκους ἐν αὐτῇ τοὺς μὲν εἰς συμπόσια τοὺς δ’ εἰς ὕπνον καὶ δίαιταν ἐποίησεν, ὑδάτων δὲ διαθεόντων πλῆθος, ἃ καὶ τέρψις ἦν καὶ κόσμος τῆς αὐλῆς, εἰσήγαγεν. τὰ μέντοι στόμια τῶν σπηλαίων ὥστε ἕνα δι’ αὐτῶν εἰσδῦναι καὶ μὴ πλείους βραχύτερα ἤνοιξεν· καὶ ταῦτ’ ἐπίτηδες ἀσφαλείας ἕνεκα τοῦ μὴ πολιορκηθεὶς ὑπὸ τῶν ἀδελφῶν καὶ κινδυνεῦσαι ληφθεὶς κατεσκεύασεν. προσῳκοδόμησε δὲ καὶ αὐλὰς τῷ μεγέθει διαφερούσας καὶ παραδείσοις ἐκόσμησε παμμήκεσι. καὶ τοιοῦτον ἀπεργασάμενος τὸν τόπον Τύρον ὠνόμασεν. οὗτος ὁ τόπος ἐστὶ μεταξὺ τῆς Ἀραβίας καὶ τῆς Ἰουδαίας πέραν τοῦ Ἰορδάνου οὐ πόρρω τῆς Ἐσσεβωνίτιδος. ἦρξε δ’ ἐκείνων τῶν μερῶν ἐπὶ ἔτη ἑπτά, πάντα τὸν χρόνον ὃν Σέλευκος τῆς Συρίας ἐβασίλευσεν. ἀποθανόντος δὲ τούτου μετ’ αὐτὸν ὁ ἀδελφὸς Ἀντίοχος ὁ κληθεὶς Ἐπιφανὴς τὴν βασιλείαν κατέσχεν. τελευτᾷ δὲ καὶ Πτολεμαῖος ὁ τῆς Αἰγύπτου βασιλεὺς καὶ αὐτὸς ἐπικαλούμενος Ἐπιφανής, καταλιπὼν δύο παῖδας ἔτι βραχεῖς τὴν ἡλικίαν, ὧν ὁ μὲν πρεσβύτερος Φιλομήτωρ ἐκαλεῖτο, Φύσκων δὲ ὁ νεώτερος. Ὑρκανὸς δὲ ὁρῶν μεγάλην δύναμιν ἔχοντα τὸν Ἀντίοχον καὶ δείσας, μὴ συλληφθεὶς ὑπ’ αὐτοῦ κολασθῇ διὰ τὰ πρὸς τοὺς Ἄραβας αὐτῷ πεπραγμένα, τελευτᾷ τὸν βίον αὐτόχειρ αὐτοῦ γενόμενος. τὴν δ’ οὐσίαν αὐτοῦ πᾶσαν Ἀντίοχος λαμβάνει.", "st": "12.4.11"}, {"sp": "N", "t": "Ὑπὸ δὲ τὸν αὐτὸν καιρὸν ἀποθανόντος καὶ Ὀνίου τοῦ ἀρχιερέως τῷ ἀδελφῷ αὐτοῦ [Ἰησοῦ] τὴν ἀρχιερωσύνην Ἀντίοχος δίδωσιν· ὁ γὰρ παῖς, ὃν Ὀνίας καταλελοίπει, ἔτι νήπιος ἦν. δηλώσομεν δὲ τὰ περὶ τοῦ παιδὸς τούτου κατὰ χώραν ἕκαστα. Ἰησοῦς δέ, οὗτος γὰρ ἦν ὁ τοῦ Ὀνίου ἀδελφός, τὴν ἀρχιερωσύνην ἀφῃρέθη προσοργισθέντος αὐτῷ τοῦ βασιλέως καὶ δόντος αὐτὴν τῷ νεωτάτῳ αὐτοῦ ἀδελφῷ Ὀνίᾳ τοὔνομα. Σίμωνι γὰρ οὗτοι τρεῖς ἐγένοντο παῖδες, καὶ εἰς τοὺς τρεῖς ἧκεν ἡ ἀρχιερωσύνη, καθὼς δεδηλώκαμεν. ὁ μὲν οὖν Ἰησοῦς Ἰάσονα αὑτὸν μετωνόμασεν, ὁ δὲ Ὀνίας ἐκλήθη Μενέλαος. στασιάσαντος οὖν τοῦ προτέρου ἀρχιερέως Ἰησοῦ πρὸς τὸν μετὰ ταῦτα κατασταθέντα Μενέλαον καὶ τοῦ πλήθους διανεμηθέντος εἰς ἑκατέρους, ἐκ τῆς Μενελάου μοίρας οἱ Τωβίου παῖδες ἐγένοντο, τὸ δὲ πλέον τοῦ λαοῦ τῷ Ἰάσονι συνελάμβανεν, ὑφ’ οὗ καὶ πονούμενοι ὅ τε Μενέλαος καὶ οἱ παῖδες οἱ τοῦ Τωβίου πρὸς Ἀντίοχον ἀνεχώρησαν δηλοῦντες αὐτῷ, ὅτι βούλονται τοὺς πατρίους νόμους καταλιπόντες καὶ τὴν κατ’ αὐτοὺς πολιτείαν ἕπεσθαι τοῖς βασιλικοῖς καὶ τὴν Ἑλληνικὴν πολιτείαν ἔχειν. παρεκάλεσαν οὖν αὐτὸν ἐπιτρέψαι αὐτοῖς οἰκοδομῆσαι γυμνάσιον ἐν Ἱεροσολύμοις. συγχωρήσαντος δὲ καὶ τὴν τῶν αἰδοίων περιτομὴν ἐπεκάλυψαν, ὡς ἂν εἶεν καὶ τὰ περὶ τὴν ἀπόδυσιν Ἕλληνες, τά τε ἄλλα πάνθ’ ὅσα ἦν αὐτοῖς πάτρια παρέντες ἐμιμοῦντο τὰ τῶν ἄλλων ἐθνῶν ἔργα.", "st": "12.5.1"}, {"sp": "N", "t": "Ἀντίοχος δὲ τῆς βασιλείας αὐτῷ χωρούσης κατὰ τρόπον ἐπὶ τὴν Αἴγυπτον διέγνω στρατεύσασθαι, πόθον αὐτῆς λαβὼν καὶ διὰ τὸ τῶν Πτολεμαίου παίδων καταφρονεῖν ἀσθενῶν ἔτι τυγχανόντων καὶ μηδέπω πράγματα τηλικαῦτα διέπειν δυναμένων. γενόμενος οὖν μετὰ πολλῆς δυνάμεως κατὰ τὸ Πηλούσιον καὶ δόλῳ τὸν Φιλομήτορα Πτολεμαῖον ἐκπεριελθὼν καταλαμβάνει τὴν Αἴγυπτον, καὶ γενόμενος ἐν τοῖς περὶ Μέμφιν τόποις καὶ κατασχὼν ταύτην ὥρμησεν ἐπὶ τὴν Ἀλεξάνδρειαν, ὡς πολιορκίᾳ παραστησόμενος αὐτὴν καὶ τὸν ἐκεῖ βασιλεύοντα χειρωσόμενος Πτολεμαῖον. ἀπεκρούσθη δ’ οὐ τῆς Ἀλεξανδρείας μόνον, ἀλλὰ καὶ τῆς ὅλης Αἰγύπτου, Ῥωμαίων αὐτῷ παραγγειλάντων ἀπέχεσθαι τῆς χώρας, καθὼς ἤδη που καὶ πρότερον ἐν ἄλλοις δεδηλώκαμεν. διηγήσομαι δὲ κατὰ μέρος τὰ περὶ τοῦτον τὸν βασιλέα, ὡς τήν τε Ἰουδαίαν ἐχειρώσατο καὶ τὸν ναόν· ἐν γὰρ τῇ πρώτῃ μου πραγματείᾳ κεφαλαιωδῶς αὐτῶν ἐπιμνησθεὶς ἀναγκαῖον ἡγησάμην νῦν εἰς τὴν ἐπ’ ἀκριβὲς αὐτῶν ἐπανελθεῖν ὑφήγησιν.", "st": "12.5.2"}, {"sp": "N", "t": "Ὑποστρέψας ἀπὸ τῆς Αἰγύπτου διὰ τὸ παρὰ Ῥωμαίων δέος ὁ βασιλεὺς Ἀντίοχος ἐπὶ τὴν Ἱεροσολυμιτῶν πόλιν ἐξεστράτευσεν, καὶ γενόμενος ἐν αὐτῇ ἔτει ἑκατοστῷ καὶ τεσσαρακοστῷ καὶ τρίτῳ μετὰ τοὺς ἀπὸ Σελεύκου βασιλεῖς ἀμαχητὶ λαμβάνει τὴν πόλιν ἀνοιξάντων αὐτῷ τὰς πύλας ὅσοι τῆς ἐκείνου προαιρέσεως ἦσαν. ἐγκρατὴς δ’ οὕτως τῶν Ἱεροσολύμων γενόμενος πολλοὺς ἀπέκτεινεν τῶν τἀναντία φρονούντων καὶ χρήματα πολλὰ συλήσας ὑπέστρεψεν εἰς Ἀντιόχειαν.", "st": "12.5.3"}, {"sp": "N", "t": "Συνέβη δὲ μετὰ ἔτη δύο τῷ ἑκατοστῷ καὶ τεσσαρακοστῷ καὶ πέμπτῳ ἔτει μηνὸς πέμπτῃ καὶ εἰκάδι, ὃς καλεῖται κατὰ μὲν ἡμᾶς Ἐξελέους, κατὰ δὲ Μακεδόνας Ἀπελλαῖος, ὀλυμπιάδι ἑκατοστῇ καὶ πεντηκοστῇ καὶ τρίτῃ μετὰ πολλῆς δυνάμεως ἀναβῆναι τὸν βασιλέα εἰς Ἱεροσόλυμα καὶ προσποιησάμενον εἰρήνην ἀπάτῃ περιγενέσθαι τῆς πόλεως. ἐφείσατο δὲ τότε οὐδὲ τῶν εἰσδεξαμένων αὐτὸν διὰ τὸν ἐν τῷ ναῷ πλοῦτον, ἀλλ’ ὑπὸ πλεονεξίας, χρυσὸν γὰρ ἑώρα πολὺν ἐν τῷ ἱερῷ καὶ τὸν ἄλλον τῶν ἀναθημάτων κόσμον πολυτελέστατον, ἵνα συλήσῃ τοῦτον, ὑπέμεινε τὰς πρὸς ἐκείνους αὐτῷ σπονδὰς παραβῆναι. περιδύσας οὖν τὸν ναόν, ὡς καὶ τὰ σκεύη τοῦ θεοῦ βαστάσαι λυχνίας χρυσᾶς καὶ βωμὸν χρύσεον καὶ τράπεζαν καὶ τὰ θυσιαστήρια, καὶ μηδὲ τῶν καταπετασμάτων ἀποσχόμενος, ἅπερ ἦν ἐκ βύσσου καὶ κόκκου πεποιημένα, κενώσας δὲ καὶ τοὺς θησαυροὺς τοὺς ἀποκρύφους καὶ μηδὲν ὅλως ὑπολιπών, εἰς μέγα τοὺς Ἰουδαίους ἐπὶ τούτοις πένθος ἐνέβαλεν. καὶ γὰρ τὰς καθημερινὰς θυσίας, ἃς προσέφερον τῷ θεῷ κατὰ τὸν νόμον, ἐκώλυσεν αὐτοὺς προσφέρειν, καὶ διαρπάσας πᾶσαν τὴν πόλιν τοὺς μὲν ἀπέκτεινεν τοὺς δ’ αἰχμαλώτους γυναιξὶν ἅμα καὶ τέκνοις ἔλαβεν, ὡς τῶν ζωγρηθέντων περὶ μυρίους γενέσθαι τὸ πλῆθος. ἐνέπρησε δ’ αὐτῆς τὰ κάλλιστα καὶ καταβαλὼν τὰ τείχη τὴν ἐν τῇ κάτω πόλει ᾠκοδόμησεν ἄκραν· ἦν γὰρ ὑψηλὴ καὶ ὑπερκειμένη τὸ ἱερόν· καὶ διὰ τοῦτο αὐτὴν ὀχυρώσας τείχεσιν ὑψηλοῖς καὶ πύργοις φρουρὰν Μακεδονικὴν ἐγκατέστησεν. ἔμενον δ’ οὐδὲν ἧττον ἐν τῇ ἄκρᾳ καὶ τοῦ πλήθους οἱ ἀσεβεῖς καὶ πονηροὶ τὸν τρόπον, ὑφ’ ὧν πολλὰ καὶ δεινὰ τοὺς πολίτας συνέβη παθεῖν. ἐποικοδομήσας δὲ καὶ τῷ θυσιαστηρίῳ βωμὸν ὁ βασιλεὺς σύας ἐπ’ αὐτοῦ κατέσφαξε, θυσίαν οὐ νόμιμον οὐδὲ πάτριον τῇ Ἰουδαίων θρησκείᾳ ταύτην ἐπιτελῶν. ἠνάγκασε δ’ αὐτοὺς ἀφεμένους τὴν περὶ τὸν αὐτῶν θεὸν θρησκείαν τοὺς ὑπ’ αὐτοῦ νομιζομένους σέβεσθαι, οἰκοδομήσαντας δὲ ἐν ἑκάστῃ πόλει καὶ κώμῃ τεμένη αὐτῶν καὶ βωμοὺς καθιδρύσαντας θύειν ἐπ’ αὐτοῖς σῦς καθ’ ἡμέραν. ἐκέλευσε δὲ καὶ μὴ περιτέμνειν αὐτοὺς τὰ τέκνα, κολάσειν ἀπειλήσας εἴ τις παρὰ ταῦτα ποιῶν εὑρεθείη. κατέστησε δὲ καὶ ἐπισκόπους, οἳ προσαναγκάσουσιν αὐτοὺς τὰ ἐπεσταλμένα ποιεῖν. καὶ πολλοὶ μὲν τῶν Ἰουδαίων οἱ μὲν ἑκοντὶ οἱ δὲ καὶ δι’ εὐλάβειαν τῆς ἐπηγγελμένης τιμωρίας κατηκολούθουν οἷς ὁ βασιλεὺς διετέτακτο, οἱ δὲ δοκιμώτατοι καὶ τὰς ψυχὰς εὐγενεῖς οὐκ ἐφρόντισαν αὐτοῦ, τῶν δὲ πατρίων ἐθῶν πλείονα λόγον ἔσχον ἢ τῆς τιμωρίας, ἣν οὐ πειθομένοις ἠπείλησεν αὐτοῖς, καὶ διὰ τοῦτο κατὰ πᾶσαν ἡμέραν αἰκιζόμενοι καὶ πικρὰς βασάνους ὑπομένοντες ἀπέθνησκον. καὶ γὰρ μαστιγούμενοι καὶ τὰ σώματα λυμαινόμενοι ζῶντες ἔτι καὶ ἐμπνέοντες ἀνεσταυροῦντο, τὰς δὲ γυναῖκας καὶ τοὺς παῖδας αὐτῶν, οὓς περιέτεμνον παρὰ τὴν τοῦ βασιλέως προαίρεσιν, ἀπῆγχον ἐκ τῶν τραχήλων αὐτοὺς τῶν ἀνεσταυρωμένων γονέων ἀπαρτῶντες. ἠφανίζετο δ’ εἴ που βίβλος εὑρεθείη ἱερὰ καὶ νόμος, καὶ παρ’ οἷς εὑρέθη καὶ αὐτοὶ κακοὶ κακῶς ἀπώλλυντο.", "st": "12.5.4"}, {"sp": "N", "t": "Ταῦτα βλέποντες οἱ Σαμαρεῖται πάσχοντας τοὺς Ἰουδαίους οὐκέθ’ ὡμολόγουν αὑτοὺς εἶναι συγγενεῖς αὐτῶν οὐδὲ τὸν ἐν Γαριζεὶν ναὸν τοῦ μεγίστου θεοῦ, τῇ φύσει ποιοῦντες ἀκόλουθα, ἣν δεδηλώκαμεν, καὶ λέγοντες αὑτοὺς Μήδων ἀποίκους καὶ Περσῶν· καὶ γάρ εἰσιν τούτων ἄποικοι. πέμψαντες οὖν πρὸς τὸν Ἀντίοχον πρέσβεις καὶ ἐπιστολὴν ἐδήλουν τὰ ὑπογεγραμμένα· βασιλεῖ Ἀντιόχῳ θεῷ ἐπιφανεῖ ὑπόμνημα παρὰ τῶν ἐν Σικίμοις Σιδωνίων. οἱ ἡμέτεροι πρόγονοι διά τινας αὐχμοὺς τῆς χώρας παρακολουθήσαντες ἀρχαίᾳ τινὶ δεισιδαιμονίᾳ ἔθος ἐποίησαν σέβειν τὴν παρὰ τοῖς Ἰουδαίοις λεγομένην σαββάτων ἡμέραν, ἱδρυσάμενοι δὲ ἀνώνυμον ἐν τῷ Γαριζεὶν λεγομένῳ ὄρει ἱερὸν ἔθυον ἐπ’ αὐτοῦ τὰς καθηκούσας θυσίας. σοῦ δὲ τοῖς Ἰουδαίοις τῆς πονηρίας αὐτῶν ἀξίως χρησαμένου, οἱ τὰ βασιλικὰ διοικοῦντες οἰόμενοι κατὰ συγγένειαν ἡμᾶς ταὐτὰ ποιεῖν ἐκείνοις ταῖς ὁμοίαις αἰτίαις περιάπτουσιν, ὄντων ἡμῶν τὸ ἀνέκαθεν Σιδωνίων, καὶ τοῦτο φανερόν ἐστιν ἐκ τῶν πολιτικῶν ἀναγραφῶν. ἀξιοῦμεν οὖν σε τὸν εὐεργέτην καὶ σωτῆρα προστάξαι Ἀπολλωνίῳ τῷ μεριδάρχῃ καὶ Νικάνορι τῷ τὰ βασιλικὰ πράττοντι μηδὲν ἡμῖν ἐνοχλεῖν προσάπτουσι τὰς τῶν Ἰουδαίων αἰτίας, ἡμῶν καὶ τῷ γένει καὶ τοῖς ἔθεσιν ἀλλοτρίων ὑπαρχόντων, προσαγορευθῆναι δὲ τὸ ἀνώνυμον ἱερὸν Διὸς Ἑλληνίου· γενομένου γὰρ τούτου παυσόμεθα μὲν ἐνοχλούμενοι, τοῖς δ’ ἔργοις μετὰ ἀδείας προσανέχοντες μείζονάς σοι ποιήσομεν τὰς προσόδους. ταῦτα τῶν Σαμαρέων δεηθέντων ἀντέγραψεν αὐτοῖς ὁ βασιλεὺς τάδε· βασιλεὺς Ἀντίοχος Νικάνορι. οἱ ἐν Σικίμοις Σιδώνιοι ἐπέδωκαν τὸ κατακεχωρισμένον ὑπόμνημα. ἐπεὶ οὖν συμβουλευομένοις ἡμῖν μετὰ τῶν φίλων παρέστησαν οἱ πεμφθέντες ὑπ’ αὐτῶν, ὅτι μηδὲν τοῖς τῶν Ἰουδαίων ἐγκλήμασι προσήκουσιν, ἀλλὰ τοῖς Ἑλληνικοῖς ἔθεσιν αἱροῦνται χρώμενοι ζῆν, ἀπολύομέν τε αὐτοὺς τῶν αἰτιῶν, καὶ τὸ παρ’ αὐτοῖς ἱερόν, καθάπερ ἠξιώκασι, προσαγορευθήτω Διὸς Ἑλληνίου. ταῦτα δὲ καὶ Ἀπολλωνίῳ τῷ μεριδάρχῃ ἐπέστειλεν ἕκτῳ ἔτει καὶ τεσσαρακοστῷ μηνὸς Ἑκατομβαιῶνος Ὑρκανίου ὀκτωκαιδεκάτῃ.", "st": "12.5.5"}, {"sp": "N", "t": "Κατὰ δὲ τὸν αὐτὸν καιρὸν ἦν τις οἰκῶν ἐν Μωδαῒ κώμῃ τῆς Ἰουδαίας, ὄνομα Ματταθίας, υἱὸς Ἰωάννου τοῦ Συμεῶνος τοῦ Ἀσαμωναίου, ἱερεὺς ἐξ ἐφημερίδος Ἰώαβος, Ἱεροσολυμίτης. ἦσαν δ’ αὐτῷ υἱοὶ πέντε, Ἰωάννης ὁ καλούμενος Γάδδης καὶ Σίμων ὁ κληθεὶς Θάτις καὶ Ἰούδας ὁ καλούμενος Μακαβαῖος καὶ Ἐλεάζαρος ὁ κληθεὶς Αὐρὰν καὶ Ἰωνάθης ὁ κληθεὶς Ἀφφοῦς. οὗτος οὖν ὁ Ματταθίας ἀπωδύρετο τοῖς τέκνοις τὴν κατάστασιν τῶν πραγμάτων καὶ τήν τε τῆς πόλεως διαρπαγὴν καὶ τοῦ ναοῦ τὴν σύλησιν καὶ τοῦ πλήθους τὰς συμφοράς, ἔλεγέν τε κρεῖττον αὐτοῖς εἶναι ὑπὲρ τῶν πατρίων νόμων ἀποθανεῖν ἢ ζῆν οὕτως ἀσεβῶς.", "st": "12.6.1"}, {"sp": "N", "t": "Ἐλθόντων δὲ εἰς τὴν Μωδαῒν κώμην τῶν ὑπὸ τοῦ βασιλέως καθεσταμένων ἐπὶ τῷ ποιεῖν ἀναγκάζειν τοὺς Ἰουδαίους ἃ διετέτακτο καὶ θύειν τοὺς ἐκεῖ κελευόντων, ὡς ὁ βασιλεὺς κελεύσειεν, διά τε τὴν δόξαν τήν τε διὰ τὰ ἄλλα καὶ διὰ τὴν εὐπαιδίαν ἀξιούντων τὸν Ματταθίαν προκατάρχειν τῶν θυσιῶν, κατακολουθήσειν γὰρ αὐτῷ καὶ τοὺς πολίτας, καὶ διὰ τοῦτο τιμηθήσεσθαι πρὸς τοῦ βασιλέως, ὁ Ματταθίας οὐκ ἔφασκεν ποιήσειν, οὐδ’ εἰ τὰ πάντα ἔθνη τοῖς Ἀντιόχου προστάγμασιν ἢ διὰ φόβον ἢ δι’ εὐαρέστησιν ὑπακούει, πεισθήσεσθαί ποτ’ αὐτὸς μετὰ τῶν τέκνων τὴν πάτριον θρησκείαν ἐγκαταλιπεῖν. ὡς δὲ σιωπήσαντος αὐτοῦ προσελθών τις τῶν Ἰουδαίων ἔθυσεν εἰς μέσον καθ’ ἃ προσέταξεν Ἀντίοχος, θυμωθεὶς ὁ Ματταθίας ὥρμησεν ἐπ’ αὐτὸν μετὰ τῶν παίδων ἐχόντων κοπίδας καὶ αὐτόν τε ἐκεῖνον διέφθειρεν καὶ τὸν στρατηγὸν τοῦ βασιλέως Ἀπελλῆν, ὃς ἐπηνάγκαζεν, διεχρήσατο μετ’ ὀλίγων στρατιωτῶν, καὶ τὸν βωμὸν καθελὼν ἀνέκραγεν, εἴ τις ζηλωτής ἐστιν τῶν πατρίων ἐθῶν καὶ τῆς τοῦ θεοῦ θρησκείας, ἑπέσθω, φησίν, ἐμοί, καὶ ταῦτ’ εἰπὼν μετὰ τῶν τέκνων εἰς τὴν ἔρημον ἐξώρμησεν καταλιπὼν ἅπασαν τὴν αὐτοῦ κτῆσιν ἐν τῇ κώμῃ. τὸ δ’ αὐτὸ καὶ ἄλλοι ποιήσαντες μετὰ τέκνων καὶ γυναικῶν ἔφυγον εἰς τὴν ἔρημον καὶ ἐν τοῖς σπηλαίοις διῆγον. ἀκούσαντες δὲ ταῦθ’ οἱ τοῦ βασιλέως στρατηγοὶ καὶ τὴν δύναμιν ὅσην εἶναι συνέβαινεν ἐν τῇ ἀκροπόλει τῶν Ἱεροσολύμων ἀναλαβόντες ἐδίωξαν εἰς τὴν ἔρημον τοὺς Ἰουδαίους. καὶ καταλαβόντες τὸ μὲν πρῶτον αὐτοὺς ἐπεχείρουν πείθειν μετανοήσαντας αἱρεῖσθαι τὰ συμφέροντα καὶ μὴ προσάγειν αὐτοῖς ἀνάγκην, ὥστ’ αὐτοῖς χρήσασθαι πολέμου νόμῳ· μὴ προσδεχομένων δὲ τοὺς λόγους, ἀλλὰ τἀναντία φρονούντων, συμβάλλουσιν αὐτοῖς εἰς μάχην σαββάτων ἡμέρᾳ, καὶ ὡς εἶχον οὕτως ἐν τοῖς σπηλαίοις αὐτοὺς κατέφλεξαν οὐδὲ ἀμυνομένους ἀλλ’ οὐδὲ τὰς εἰσόδους ἐμφράξαντας· τοῦ δὲ ἀμύνασθαι διὰ τὴν ἡμέραν ἀπέσχοντο μηδ’ ἐν κακοῖς παραβῆναι τὴν τοῦ σαββάτου τιμὴν θελήσαντες· ἀργεῖν γὰρ ἡμῖν ἐν αὐτῇ νόμιμόν ἐστιν. ἀπέθανον μὲν οὖν σὺν γυναιξὶ καὶ τέκνοις ἐμπνιγέντες τοῖς σπηλαίοις ὡσεὶ χίλιοι, πολλοὶ δὲ καὶ διασωθέντες τῷ Ματταθίᾳ προσέθεντο κἀκεῖνον ἄρχοντα ἀπέδειξαν. ὁ δὲ καὶ σαββάτοις αὐτοὺς ἐδίδαξε μάχεσθαι λέγων, ὡς εἰ μὴ ποιήσουσι τοῦτο φυλαττόμενοι τὸ νόμιμον, αὐτοῖς ἔσονται πολέμιοι, τῶν μὲν ἐχθρῶν κατ’ ἐκείνην τὴν ἡμέραν αὐτοῖς προσβαλλόντων, αὐτῶν δ’ οὐκ ἀμυνομένων, κωλύσειν τε μηδὲν οὕτως ἀμαχητὶ πάντας ἀπολέσθαι. ταῦτ’ εἰπὼν ἔπεισεν αὐτούς, καὶ ἄχρι δεῦρο μένει παρ’ ἡμῖν τὸ καὶ σαββάτοις, εἴ ποτε δεήσειεν, μάχεσθαι. ποιήσας οὖν δύναμιν πολλὴν περὶ αὐτὸν Ματταθίας τούς τε βωμοὺς καθεῖλεν καὶ τοὺς ἐξαμαρτάνοντας ἀπέκτεινεν, ὅσους λαβεῖν ὑποχειρίους ἠδυνήθη· πολλοὶ γὰρ δι’ εὐλάβειαν διεσπάρησαν εἰς τὰ πέριξ ἔθνη· τῶν τε παίδων τοὺς οὐ περιτετμημένους ἐκέλευσε περιτέμνεσθαι τοὺς ἐπὶ τῷ κωλύειν καθεσταμένους ἐκβαλών.", "st": "12.6.2"}, {"sp": "N", "t": "Ἄρξας δ’ ἐνιαυτὸν καὶ καταπεσὼν εἰς νόσον προσκαλεῖται τοὺς παῖδας, καὶ περιστησάμενος αὐτοὺς ἐγὼ μέν, εἶπεν, ὦ παῖδες, ἄπειμι τὴν εἱμαρμένην πορείαν, παρατίθεμαι δ’ ὑμῖν τοὐμὸν φρόνημα καὶ παρακαλῶ μὴ γενέσθαι κακοὺς αὐτοῦ φύλακας, ἀλλὰ μεμνημένους τῆς τοῦ φύσαντος ὑμᾶς καὶ θρεψαμένου προαιρέσεως ἔθη τε σώζειν τὰ πάτρια καὶ κινδυνεύουσαν οἴχεσθαι τὴν ἀρχαίαν πολιτείαν ἀνακτᾶσθαι μὴ συμφερομένους τοῖς ἢ διὰ βούλησιν ἢ δι’ ἀνάγκην προδιδοῦσιν αὐτήν, ἀλλ’ ἀξιῶ παῖδας ὄντας ἐμοὺς ἐμμεῖναι καὶ βίας ἁπάσης καὶ ἀνάγκης ἐπάνω γενέσθαι, τὰς ψυχὰς οὕτω παρασκευασαμένους, ὥστ’ ἀποθανεῖν ὑπὲρ τῶν νόμων, ἂν δέῃ, λογιζομένους τοῦθ’, ὅτι τὸ θεῖον τοιούτους ὑμᾶς ὁρῶν οὐχ ὑπερόψεται, τῆς δ’ ἀρετῆς ἀγασάμενον ἀποδώσει πάλιν ὑμῖν αὐτοὺς καὶ τὴν ἐλευθερίαν, ἐν ᾗ ζήσεσθε μετ’ ἀδείας τῶν ἰδίων ἀπολαύοντες ἐθῶν, ἀποκαταστήσει· θνητὰ μὲν γὰρ τὰ σώματα ἡμῶν καὶ ἐπίκηρα, τῇ δὲ τῶν ἔργων μνήμῃ τάξιν ἀθανασίας λαμβάνομεν, ἧς ἐρασθέντας ὑμᾶς βούλομαι διώκειν τὴν εὔκλειαν καὶ τὰ μέγιστα ὑφισταμένους μὴ ὀκνεῖν ὑπὲρ αὐτῶν ἀπολιπεῖν τὸν βίον. μάλιστα δ’ ὑμῖν ὁμονοεῖν παραινῶ καὶ πρὸς ὅ τις ὑμῶν πέφυκεν ἀμείνων θατέρου πρὸς τοῦτ’ εἴκοντας ἀλλήλοις οἰκείαις χρῆσθαι ταῖς ἀρεταῖς. καὶ Σίμωνα μὲν τὸν ἀδελφὸν συνέσει προύχοντα πατέρα ἡγεῖσθε καὶ οἷς ἂν οὗτος συμβουλεύσῃ πείθεσθε, Μακαβαῖον δὲ τῆς στρατιᾶς δι’ ἀνδρείαν καὶ ἰσχὺν στρατηγὸν ἕξετε· τὸ γὰρ ἔθνος οὗτος ἐκδικήσει καὶ ἀμυνεῖται τοὺς πολεμίους. προσίεσθε δὲ καὶ τοὺς δικαίους καὶ θεοσεβεῖς καὶ τὴν δύναμιν αὐτῶν αὔξετε.", "st": "12.6.3"}, {"sp": "N", "t": "Ταῦτα διαλεχθεὶς τοῖς παισὶν καὶ τὸν θεὸν εὐξάμενος σύμμαχον αὐτοῖς γενέσθαι καὶ τῷ λαῷ τὴν ἰδίαν ἀνασῶσαι πάλιν τοῦ βίου συνήθειαν, μετ’ οὐ πολὺ τελευτᾷ, καὶ θάπτεται μὲν ἐν Μωδαῒ πένθος ἐπ’ αὐτῷ μέγα παντὸς τοῦ λαοῦ ποιησαμένου, διεδέξατο δὲ τὴν προστασίαν τῶν πραγμάτων ὁ παῖς αὐτοῦ Ἰούδας ὁ καὶ Μακκαβαῖος ἑκατοστῷ ἔτει καὶ τεσσαρακοστῷ καὶ ἕκτῳ. συναραμένων δ’ αὐτῷ προθύμως τῶν ἀδελφῶν καὶ τῶν ἄλλων τούς τε πολεμίους ἐξέβαλεν ἐκ τῆς χώρας καὶ τοὺς παρανομήσαντας τῶν ὁμοφύλων εἰς τὰ πάτρια διεχρήσατο καὶ ἐκαθάρισεν ἀπὸ παντὸς μιάσματος τὴν γῆν.", "st": "12.6.4"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας Ἀπολλώνιος ὁ τῆς Σαμαρείας στρατηγὸς ἀναλαβὼν τὴν δύναμιν ὥρμησεν ἐπὶ τὸν Ἰούδαν. ὁ δὲ ἀπήντησεν αὐτῷ καὶ συμβαλὼν κρατεῖ τῇ μάχῃ καὶ πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, ἐν οἷς καὶ τὸν στρατηγὸν Ἀπολλώνιον, οὗ καὶ τὴν μάχαιραν, ᾗ χρῆσθαι συνέβαινεν ἐκεῖνον, σκυλεύσας αὐτὸς εἶχεν, πλείους δὲ τραυματίας ἐποίησεν καὶ πολλὴν λείαν ἐκ τοῦ στρατοπέδου λαβὼν τῶν πολεμίων ἀνεχώρησεν. Σήρων δ’ ὁ τῆς κοίλης Συρίας στρατηγός, ἀκούσας ὅτι πολλοὶ προσκεχωρήκασιν τῷ Ἰούδᾳ καὶ δύναμιν ἤδη περιβέβληται πρὸς ἀγῶνας καὶ πολέμους ἀξιόλογον, ἐπ’ αὐτὸν ἔγνω στρατεύσασθαι προσήκειν ὑπολαμβάνων τοὺς εἰς τὰ τοῦ βασιλέως προστάγματα παρανομοῦντας πειρᾶσθαι κολάζειν. συναγαγὼν οὖν δύναμιν ὅση παρῆν αὐτῷ, προσκαταλέξας δὲ καὶ τῶν Ἰουδαίων τοὺς φυγάδας καὶ ἀσεβεῖς ἐπὶ τὸν Ἰούδαν παρεγίγνετο· προελθὼν δὲ ἄχρι Βαιθώρων κώμης τῆς Ἰουδαίας αὐτόθι στρατοπεδεύεται. ὁ δὲ Ἰούδας ἀπαντήσας αὐτῷ καὶ συμβαλεῖν προαιρούμενος, ἐπεὶ τοὺς στρατιώτας ἑώρα πρὸς τὴν μάχην διά τε τὴν ὀλιγότητα καὶ δι’ ἀσιτίαν, νενηστεύκεσαν γάρ, ὀκνοῦντας, παρεθάρσυνεν λέγων οὐκ ἐν τῷ πλήθει τὸ νικᾶν εἶναι καὶ κρατεῖν τῶν πολεμίων, ἀλλ’ ἐν τῷ πρὸς τὸ θεῖον εὐσεβεῖν. καὶ τούτου σαφέστατον ἔχειν παράδειγμα τοὺς προγόνους, οἳ διὰ δικαιοσύνην καὶ τὸ περὶ τῶν ἰδίων νόμων καὶ τέκνων ἀγωνίζεσθαι πολλὰς πολλάκις ἥττησαν μυριάδας· τὸ γὰρ μηδὲν ἀδικεῖν ἰσχυρὰ δύναμις. ταῦτ’ εἰπὼν πείθει τοὺς σὺν αὐτῷ καταφρονήσαντας τοῦ πλήθους τῶν ἐναντίων ὁμόσε χωρῆσαι τῷ Σήρωνι, καὶ συμβαλὼν τρέπει τοὺς Σύρους· πεσόντος γὰρ τοῦ στρατηγοῦ πάντες φεύγειν ὥρμησαν, ὡς ἐν τούτῳ τῆς σωτηρίας αὐτοῖς ἀποκειμένης. ἐπιδιώκων δ’ ἄχρι τοῦ πεδίου κτείνει τῶν πολεμίων ὡσεὶ ὀκτακοσίους· οἱ δὲ λοιποὶ διεσώθησαν εἰς τὴν παραλίαν.", "st": "12.7.1"}, {"sp": "N", "t": "Ταῦτα ἀκούσας ὁ βασιλεὺς Ἀντίοχος μεγάλως ὠργίσθη τοῖς γεγενημένοις, καὶ πᾶσαν τὴν οἰκείαν δύναμιν ἀθροίσας καὶ πολλοὺς ἐκ τῶν νήσων μισθοφόρους παραλαβὼν ἡτοιμάζετο περὶ τὴν ἀρχὴν τοῦ ἔαρος εἰς τὴν Ἰουδαίαν ἐμβαλεῖν. ἐπεὶ δὲ τὸ στρατιωτικὸν διανείμας ἑώρα τοὺς θησαυροὺς ἐπιλείποντας καὶ χρημάτων ἔνδειαν οὖσαν, οὔτε γὰρ οἱ φόροι πάντες ἐτελοῦντο διὰ τὰς τῶν ἐθνῶν στάσεις μεγαλόψυχός τε ὢν καὶ φιλόδωρος οὐκ ἠρκεῖτο τοῖς οὖσιν, ἔγνω πρῶτον εἰς τὴν Περσίδα πορευθεὶς τοὺς φόρους τῆς χώρας συναγαγεῖν. καταλιπὼν οὖν ἐπὶ τῶν πραγμάτων Λυσίαν τινὰ δόξαν ἔχοντα παρ’ αὐτῷ, καὶ τὰ μέχρι τῶν Αἰγύπτου ὅρων καὶ τῆς κάτωθεν Ἀσίας ἀπ’ Εὐφράτου διήκοντα ποταμοῦ καὶ μέρος τι τῆς δυνάμεως καὶ τῶν ἐλεφάντων, τρέφειν μὲν Ἀντίοχον τὸν υἱὸν αὐτοῦ μετὰ πάσης φροντίδος ἐνετείλατο ἕως ἂν οὗ παραγένηται, καταστρεψάμενον δὲ τὴν Ἰουδαίαν καὶ τοὺς οἰκοῦντας αὐτὴν ἐξανδραποδισάμενον ἀφανίσαι τὰ Ἱεροσόλυμα καὶ τὸ γένος αὐτῶν ἀπολέσαι. καὶ ταῦτα μὲν ἐπιστείλας τῷ Λυσίᾳ ὁ βασιλεὺς Ἀντίοχος ἐξήλασεν εἰς τὴν Περσίδα τῷ ἑκατοστῷ καὶ τεσσαρακοστῷ καὶ ἑβδόμῳ ἔτει, καὶ περαιωσάμενος τὸν Εὐφράτην ἀνέβαινεν πρὸς τοὺς ἄνω σατράπας.", "st": "12.7.2"}, {"sp": "N", "t": "Ὁ δὲ Λυσίας ἐπιλεξάμενος Πτολεμαῖον τὸν Δορυμένους καὶ Νικάνορα καὶ Γοργίαν, ἄνδρας δυνατοὺς τῶν φίλων τῶν τοῦ βασιλέως, καὶ παραδοὺς αὐτοῖς πεζῆς μὲν δυνάμεως μυριάδας τέσσαρας, ἱππεῖς δὲ ἑπτακισχιλίους, ἐξέπεμψεν ἐπὶ τὴν Ἰουδαίαν. οἱ δὲ ἄχρις Ἐμμαοῦ πόλεως ἐλθόντες ἐπὶ τῇ πεδινῇ καταστρατοπεδεύονται. προσγίγνονται δ’ αὐτοῖς σύμμαχοι ἀπό τε τῆς Συρίας καὶ τῆς πέριξ χώρας καὶ πολλοὶ τῶν πεφευγότων Ἰουδαίων, ἔτι γε μὴν καὶ τῶν ἐμπόρων τινὲς ὡς ὠνησόμενοι τοὺς αἰχμαλωτισθησομένους, πέδας μὲν κομίζοντες αἷς δήσουσιν τοὺς ληφθησομένους, ἄργυρον δὲ καὶ χρυσὸν τιμὴν αὐτῶν καταθησόμενοι. τὸ δὲ στρατόπεδον καὶ τὸ πλῆθος τῶν ἐναντίων Ἰούδας κατανοήσας ἔπειθε τοὺς οἰκείους στρατιώτας θαρρεῖν καὶ παρεκελεύετο τὰς ἐλπίδας τῆς νίκης ἔχοντας ἐν τῷ θεῷ τοῦτον ἱκετεύειν τῷ πατρίῳ νόμῳ σάκκους περιθεμένους, καὶ τὸ σύνηθες αὐτῷ σχῆμα τῆς ἱκεσίας παρὰ τοὺς μεγάλους κινδύνους ἐπιδείξαντας τούτῳ δυσωπῆσαι παρασχεῖν αὐτοῖς τὸ κατὰ τῶν ἐχθρῶν κράτος. διατάξας δὲ τὸν ἀρχαῖον αὐτοὺς τρόπον καὶ πάτριον κατὰ χιλιάρχους καὶ ταξιάρχους καὶ τοὺς νεογάμους ἀπολύσας καὶ τοὺς τὰς κτήσεις νεωστὶ πεποιημένους, ὅπως μὴ διὰ τὴν τούτων ἀπόλαυσιν φιλοζωοῦντες ἀτολμότερον μάχωνται, καταστὰς τοιούτοις παρώρμα λόγοις πρὸς τὸν ἀγῶνα τοὺς αὐτοῦ στρατιώτας· καιρὸς μὲν [οὖν] ὑμῖν οὐκ ἄλλος ἀναγκαιότερος τοῦ παρόντος, ὦ ἑταῖροι, εἰς εὐψυχίαν καὶ κινδύνων καταφρόνησιν καταλείπεται· νῦν γὰρ ἔστιν ἀνδρείως ἀγωνισαμένοις τὴν ἐλευθερίαν ἀπολαβεῖν, ἣν καὶ δι’ αὐτὴν ἅπασιν ἀγαπητὴν οὖσαν ὑμῖν ὑπὲρ ἐξουσίας τοῦ θρησκεύειν τὸ θεῖον ποθεινοτέραν εἶναι συμβέβηκεν. ὡς οὖν ἐν τῷ παρόντι κειμένων ὑμῖν ταύτην τε ἀπολαβεῖν καὶ τὸν εὐδαίμονα καὶ μακάριον βίον ἀνακτήσασθαι, οὗτος δ’ ἦν ὁ κατὰ τοὺς νόμους καὶ τὴν πάτριον συνήθειαν, ἢ τὰ αἴσχιστα παθεῖν καὶ μηδὲ σπέρμα τοῦ γένους ὑμῶν ὑπολειφθῆναι κακῶν ἐν τῇ μάχῃ γενομένων, οὕτως ἀγωνίζεσθε, τὸ μὲν ἀποθανεῖν καὶ μὴ πολεμοῦσιν ὑπάρξον ἡγούμενοι, τὸ δ’ ὑπὲρ τηλικούτων ἐπάθλων, ἐλευθερίας πατρίδος νόμων εὐσεβείας, αἰώνιον τὴν εὔκλειαν κατασκευάσειν πεπιστευκότες· ἑτοιμάζεσθε τοιγαροῦν οὕτως τὰς ψυχὰς ὡς αὔριον ἅμ’ ἡμέρᾳ συμβαλοῦντες τοῖς πολεμίοις.", "st": "12.7.3"}, {"sp": "N", "t": "Καὶ ὁ μὲν Ἰούδας ταῦτα παραθαρσύνων τὴν στρατιὰν ἔλεξεν. τῶν δὲ πολεμίων πεμψάντων Γοργίαν μετὰ πεντακισχιλίων πεζῶν καὶ χιλίων ἱππέων, ὅπως διὰ τῆς νυκτὸς ἐπιπέσῃ τῷ Ἰούδᾳ, καὶ πρὸς τοῦτο ὁδηγοὺς ἔχοντος αὐτοῦ τινας τῶν πεφευγότων Ἰουδαίων, αἰσθόμενος ὁ τοῦ Ματταθίου παῖς ἔγνω καὶ αὐτὸς τοῖς ἐν τῇ παρεμβολῇ τῶν πολεμίων ἐπιπεσεῖν καὶ ταῦτα διῃρημένης αὐτῶν τῆς δυνάμεως. καθ’ ὥραν οὖν δειπνοποιησάμενος καὶ πολλὰ πυρὰ καταλιπὼν ἐπὶ τοῦ στρατοπέδου δι’ ὅλης ὥδευε τῆς νυκτὸς ἐπὶ τοὺς ἐν Ἐμμαοῖ τῶν πολεμίων. οὐχ εὑρὼν δ’ ἐν τῷ στρατοπέδῳ τοὺς ἐχθροὺς ὁ Γοργίας, ἀλλ’ ὑπονοήσας ἀναχωρήσαντας αὐτοὺς ἐν τοῖς ὄρεσι κεκρύφθαι, πορευθεὶς ἔγνω ζητεῖν, ὅπου ποτ’ εἶεν. περὶ δὲ τὸν ὄρθρον ἐπιφαίνεται τοῖς ἐν Ἐμμαοῖ πολεμίοις ὁ Ἰούδας μετὰ τρισχιλίων φαύλως ὡπλισμένων διὰ πενίαν, καὶ θεασάμενος τοὺς ἐχθροὺς ἄριστα πεφραγμένους καὶ μετ’ ἐμπειρίας πολλῆς ἐστρατοπεδευμένους, προτρεψάμενος τοὺς ἰδίους, ὡς καὶ γυμνοῖς τοῖς σώμασιν μάχεσθαι δεῖ καὶ τὸ θεῖον ἤδη που καὶ τοῖς οὕτως ἔχουσιν τὸ κατὰ τῶν πλειόνων καὶ ὡπλισμένων κράτος ἔδωκεν ἀγασάμενον αὐτοὺς τῆς εὐψυχίας, ἐκέλευσε σημῆναι τοὺς σαλπιγκτάς. ἔπειτ’ ἐμπεσὼν ἀπροσδοκήτοις τοῖς πολεμίοις καὶ ἐκπλήξας αὐτῶν τὴν διάνοιαν καὶ ταράξας πολλοὺς μὲν ἀπέκτεινεν ἀνθισταμένους, τοὺς δὲ λοιποὺς διώκων ἦλθεν ἄχρι Γαζάρων καὶ τῶν πεδίων τῆς Ἰδουμαίας καὶ Ἀζώτου καὶ Ἰαμνείας· ἔπεσόν τε αὐτῶν ὡς περὶ τρισχιλίους. Ἰούδας δὲ τῶν μὲν σκύλων παρεκελεύετο μὴ ἐπιθυμεῖν τοὺς αὐτοῦ στρατιώτας· ἔτι γὰρ αὐτοῖς ἀγῶνά τινα καὶ μάχην [εἶναι] πρὸς Γοργίαν καὶ τὴν σὺν αὐτῷ δύναμιν· κρατήσαντας δὲ καὶ τούτων τότε σκυλεύσειν ἐπ’ ἀδείας ἔλεγεν τοῦτο μόνον ἔχοντας καὶ μηδὲν ἕτερον ἐκδεχομένους. ἔτι δὲ αὐτοῦ διαλεγομένου ταῦτα πρὸς τοὺς στρατιώτας ὑπερκύψαντες οἱ τοῦ Γοργίου τὴν μὲν στρατιὰν ἣν ἐν τῇ παρεμβολῇ κατέλιπον ὁρῶσιν τετραμμένην, τὸ δὲ στρατόπεδον ἐμπεπρησμένον· ὁ γὰρ καπνὸς αὐτοῖς πόρρωθεν οὖσιν τοῦ συμβεβηκότος δήλωσιν ἔφερεν. ὡς οὖν ταῦθ’ οὕτως ἔχοντα ἔμαθον οἱ σὺν Γοργίᾳ καὶ τοὺς μετὰ Ἰούδου πρὸς παράταξιν ἑτοίμους κατενόησαν, καὶ αὐτοὶ δείσαντες εἰς φυγὴν ἐτράπησαν. ὁ δὲ Ἰούδας ὡς ἀμαχητὶ τῶν μετὰ Γοργίου στρατιωτῶν ἡττημένων ὑποστρέψας ἀνῃρεῖτο τὰ σκῦλα, πολὺν δὲ χρυσὸν καὶ ἄργυρον καὶ πορφύραν καὶ ὑάκινθον λαβὼν εἰς τὴν οἰκείαν ὑπέστρεψε χαίρων καὶ ὑμνῶν τὸν θεὸν ἐπὶ τοῖς κατωρθωμένοις· οὐ μικρὰ γὰρ αὐτοῖς ἡ νίκη πρὸς τὴν ἐλευθερίαν συνεβάλλετο.", "st": "12.7.4"}, {"sp": "N", "t": "Λυσίας δὲ συγχυθεὶς ἐπὶ τῇ τῶν ἐκπεμφθέντων ἥττῃ τῷ ἐχομένῳ ἔτει μυριάδας ἀνδρῶν ἐπιλέκτων ἀθροίσας ἓξ καὶ πεντακισχιλίους λαβὼν ἱππεῖς ἐνέβαλεν εἰς τὴν Ἰουδαίαν, καὶ ἀναβὰς εἰς τὴν ὀρεινὴν ἐν Βεθσούροις κώμῃ τῆς Ἰουδαίας ἐστρατοπεδεύσατο. ἀπήντησε δὲ μετὰ μυρίων Ἰούδας, καὶ τὸ πλῆθος ἰδὼν τῶν πολεμίων σύμμαχον ἐπ’ αὐτῷ γενέσθαι τὸν θεὸν εὐξάμενος, συμβαλὼν τοῖς προδρόμοις τῶν πολεμίων νικᾷ τούτους καὶ φονεύσας αὐτῶν ὡς πεντακισχιλίους τοῖς λοιποῖς ἦν ἐπίφοβος. ἀμέλει κατανοήσας ὁ Λυσίας τὸ φρόνημα τῶν Ἰουδαίων, ὡς ἕτοιμοι τελευτᾶν εἰσιν, εἰ μὴ ζήσουσιν ἐλεύθεροι, καὶ δείσας αὐτῶν τὴν ἀπόγνωσιν ὡς ἰσχύν, ἀναλαβὼν τὴν λοιπὴν δύναμιν ὑπέστρεψεν εἰς Ἀντιόχειαν καὶ διέτριβεν ἐκεῖ ξενολογῶν καὶ παρασκευαζόμενος μετὰ μείζονος στρατιᾶς εἰς τὴν Ἰουδαίαν ἐμβαλεῖν.", "st": "12.7.5"}, {"sp": "N", "t": "Τοσαυτάκις οὖν ἡττημένων ἤδη τῶν Ἀντιόχου τοῦ βασιλέως στρατηγῶν ὁ Ἰούδας ἐκκλησιάσας ἔλεγεν μετὰ πολλὰς νίκας, ἃς ὁ θεὸς αὐτοῖς ἔδωκεν, ἀναβῆναι δεῖν εἰς Ἱεροσόλυμα καὶ τὸν ναὸν καθαρίσαι καὶ τὰς νενομισμένας θυσίας προσφέρειν. ὡς δὲ παραγενόμενος μετὰ παντὸς τοῦ πλήθους εἰς Ἱεροσόλυμα τὸν ναὸν ἔρημον εὗρεν καὶ καταπεπρησμένας τὰς πύλας καὶ φυτὰ διὰ τὴν ἐρημίαν αὐτόματα ἐν τῷ ἱερῷ ἀναβεβλαστηκότα, θρηνεῖν ἤρξατο μετὰ τῶν ἰδίων ἐπὶ τῇ ὄψει τοῦ ναοῦ συγχυθείς. ἐπιλεξάμενος δέ τινας τῶν αὐτοῦ στρατιωτῶν προσέταξε τούτοις ἐκπολεμῆσαι τοὺς τὴν ἄκραν φυλάττοντας, ἄχρι τὸν ναὸν αὐτὸς ἁγνίσειεν. καὶ καθάρας ἐπιμελῶς αὐτὸν εἰσεκόμισε καινὰ σκεύη, λυχνίαν τράπεζαν βωμόν, ἐκ χρυσοῦ πεποιημένα, ἀπήρτησεν δὲ καὶ τὰ ἐμπετάσματα τῶν θυρῶν καὶ τὰς θύρας αὐτὰς ἐπέθηκεν, καθελὼν δὲ καὶ τὸ θυσιαστήριον καινὸν ἐκ λίθων συμμίκτων ᾠκοδόμησεν οὐ λελαξευμένων ὑπὸ σιδήρου. πέμπτῃ δὲ καὶ εἰκάδι τοῦ Ἐξελέου μηνός, ὃν οἱ Μακεδόνες Ἀπελλαῖον καλοῦσιν, ἧψάν τε φῶτα ἐπὶ τῆς λυχνίας καὶ ἐθυμίασαν ἐπὶ τοῦ βωμοῦ καὶ ἄρτους ἐπὶ τὴν τράπεζαν ἐπέθεσαν καὶ ὡλοκαύτησαν ἐπὶ τοῦ καινοῦ θυσιαστηρίου. ἔτυχεν δὲ ταῦτα κατὰ τὴν αὐτὴν ἡμέραν γίνεσθαι, καθ’ ἣν καὶ μετέπεσεν αὐτῶν ἡ ἅγιος θρησκεία εἰς βέβηλον καὶ κοινὴν συνήθειαν μετὰ ἔτη τρία· τὸν γὰρ ναὸν ἐρημωθέντα ὑπὸ Ἀντιόχου διαμεῖναι τοιοῦτον ἔτεσι συνέβη τρισίν· ἔτει γὰρ πέμπτῳ καὶ τεσσαρακοστῷ καὶ ἑκατοστῷ ταῦτα περὶ τὸν ναὸν ἐγένετο, πέμπτῃ δὲ καὶ εἰκάδι τοῦ Ἀπελλαίου μηνὸς ὀλυμπιάδι ἑκατοστῇ καὶ πεντηκοστῇ καὶ τρίτῃ, ἀνενεώθη δὲ κατὰ τὴν αὐτὴν ἡμέραν πέμπτῃ καὶ εἰκοστῇ τοῦ Ἀπελλαίου μηνὸς ὀγδόῳ καὶ τεσσαρακοστῷ καὶ ἑκατοστῷ ἔτει ὀλυμπιάδι ἑκατοστῇ καὶ πεντηκοστῇ καὶ τετάρτῃ. τὴν δ’ ἐρήμωσιν τοῦ ναοῦ συνέβη γενέσθαι κατὰ τὴν Δανιήλου προφητείαν πρὸ τετρακοσίων καὶ ὀκτὼ γενομένην ἐτῶν· ἐδήλωσεν γάρ, ὅτι Μακεδόνες καταλύσουσιν αὐτόν.", "st": "12.7.6"}, {"sp": "N", "t": "Ἑώρταζε δὲ ὁ Ἰούδας μετὰ τῶν πολιτῶν τὴν ἀνάκτησιν τῆς περὶ τὸν ναὸν θυσίας ἐφ’ ἡμέρας ὀκτὼ μηδὲν ἀπολιπὼν ἡδονῆς εἶδος, ἀλλὰ πολυτελέσι μὲν καὶ λαμπραῖς ταῖς θυσίαις κατευωχῶν αὐτούς, ὕμνοις δὲ καὶ ψαλμοῖς τὸν μὲν θεὸν τιμῶν αὐτοὺς δὲ τέρπων. τοσαύτῃ δ’ ἐχρήσαντο τῇ περὶ τὴν ἀνανέωσιν τῶν ἐθῶν ἡδονῇ μετὰ χρόνον πολὺν ἀπροσδοκήτως ἐν ἐξουσίᾳ γενόμενοι τῆς θρησκείας, ὡς νόμον θεῖναι τοῖς μετ’ αὐτοὺς ἑορτάζειν τὴν ἀνάκτησιν τῶν περὶ τὸν ναὸν ἐφ’ ἡμέρας ὀκτώ. καὶ ἐξ ἐκείνου μέχρι τοῦ δεῦρο τὴν ἑορτὴν ἄγομεν καλοῦντες αὐτὴν φῶτα ἐκ τοῦ παρ’ ἐλπίδας οἶμαι ταύτην ἡμῖν φανῆναι τὴν ἐξουσίαν τὴν προσηγορίαν θέμενοι τῇ ἑορτῇ. τειχίσας δ’ ἐν κύκλῳ τὴν πόλιν καὶ πρὸς τὰς ἐπιδρομὰς τῶν πολεμίων πύργους οἰκοδομησάμενος ὑψηλοὺς φύλακας ἐν αὐτοῖς ἐγκατέστησεν, καὶ τὴν Βεθσούραν δὲ πόλιν ὠχύρωσεν, ὅπως ἀντὶ φρουρίου αὐτῇ πρὸς τὰς ἀπὸ τῶν πολεμίων ἀνάγκας ἔχῃ χρῆσθαι.", "st": "12.7.7"}, {"sp": "N", "t": "Τούτων οὕτως γενομένων τὰ πέριξ ἔθνη πρὸς τὴν ἀναζωπύρησιν καὶ τὴν ἰσχὺν τῶν Ἰουδαίων χαλεπῶς διακείμενα πολλοὺς ἐπισυνιστάμενα διέφθειρεν ἐνέδραις καὶ ἐπιβουλαῖς αὐτῶν ἐγκρατῆ γιγνόμενα. πρὸς τούτους πολέμους συνεχεῖς ἐκφέρων ὁ Ἰούδας ἐπέχειν αὐτοὺς τῆς καταδρομῆς καὶ ὧν ἐποίουν κακῶς τοὺς Ἰουδαίους ἐπειρᾶτο. καὶ τοῖς Ἠσαῦ υἱοῖς Ἰδουμαίοις ἐπιπεσὼν κατὰ τὴν Ἀκραβατηνὴν πολλοὺς αὐτῶν ἀπέκτεινεν καὶ ἐσκύλευσεν. συγκλείσας δὲ καὶ τοὺς υἱοὺς τοῦ Βαάνου λοχῶντας τοὺς Ἰουδαίους περικαθίσας ἐπολιόρκει καὶ τούς τε πύργους αὐτῶν ἐνεπίμπρα καὶ τοὺς ἄνδρας διέφθειρεν. ἔπειτ’ ἐκεῖθεν ἐπὶ τοὺς Ἀμμανίτας ἐξώρμησεν δύναμιν μεγάλην καὶ πολυάνθρωπον ἔχοντας, ὧν ἡγεῖτο Τιμόθεος. χειρωσάμενος δὲ καὶ τούτους τὴν Ἰαζωρῶν ἐξαιρεῖ πόλιν, καὶ τάς τε γυναῖκας αὐτῶν καὶ τὰ τέκνα λαβὼν αἰχμαλώτους καὶ τὴν πόλιν ἐμπρήσας εἰς τὴν Ἰουδαίαν ὑπέστρεψεν. μαθόντα δ’ αὐτὸν τὰ γειτονεύοντα τῶν ἐθνῶν ἀνεστροφότα συναθροίζεται εἰς τὴν Γαλαδηνὴν ἐπὶ τοὺς ἐν τοῖς ὅροις αὐτῶν Ἰουδαίους. οἱ δὲ καταφυγόντες εἰς Διάθημα τὸ φρούριον πέμψαντες πρὸς Ἰούδαν ἐδήλουν αὐτῷ, ὅτι λαβεῖν ἐσπούδακεν Τιμόθεος τὸ χωρίον, εἰς ὃ συνεπεφεύγεσαν. ἀναγινωσκομένων δὲ τῶν ἐπιστολῶν τούτων κἀκ τῆς Γαλιλαίας ἄγγελοι παραγίγνονται σημαίνοντες ἐπισυνῆχθαι τοὺς ἐκ Πτολεμαΐδος καὶ Τύρου καὶ Σιδῶνος καὶ τῶν ἄλλων ἐθνῶν τῆς Γαλιλαίας.", "st": "12.8.1"}, {"sp": "N", "t": "Πρὸς οὖν ἀμφοτέρας τὰς τῶν ἠγγελμένων χρείας σκεψάμενος Ἰούδας ὅ τι χρὴ ποιεῖν, Σίμωνα μὲν τὸν ἀδελφὸν προσέταξεν ὡς τρισχιλίους τῶν ἐπιλέκτων λαβόντα τοῖς ἐν Γαλιλαίᾳ βοηθὸν ἐξελθεῖν Ἰουδαίοις. αὐτὸς δὲ καὶ Ἰωνάθης ὁ ἕτερος ἀδελφὸς μετ’ ὀκτακισχιλίων στρατιωτῶν ὥρμησαν εἰς τὴν Γαλαδῖτιν· κατέλιπεν δ’ ἐπὶ τῶν ὑπολοίπων τῆς δυνάμεως Ἰώσηπόν τε τὸν Ζαχαρία καὶ Ἀζαρίαν προστάξας αὐτοῖς φυλάττειν ἐπιμελῶς τὴν Ἰουδαίαν καὶ συνάπτειν πόλεμον πρὸς μηδένα, ἕως ἂν αὐτὸς ἐπανέλθῃ. ὁ μὲν οὖν Σίμων παραγενόμενος εἰς τὴν Γαλιλαίαν καὶ συμβαλὼν τοῖς ἐχθροῖς εἰς φυγὴν αὐτοὺς ἔτρεψεν καὶ μέχρι τῶν πυλῶν τῆς Πτολεμαΐδος διώξας ἀπέκτεινεν αὐτῶν ὡς περὶ τρισχιλίους, καὶ τά τε σκῦλα λαβὼν τῶν ἀνῃρημένων καὶ τοὺς αἰχμαλώτους Ἰουδαίους καὶ τὴν ἀποσκευὴν αὐτῶν ἐπαγόμενος εἰς τὴν οἰκείαν πάλιν ἀνέστρεψεν.", "st": "12.8.2"}, {"sp": "N", "t": "Ἰούδας δὲ ὁ Μακαβαῖος καὶ ὁ ἀδελφὸς αὐτοῦ Ἰωνάθης διαβάντες τὸν Ἰορδάνην ποταμὸν καὶ ὁδὸν ἀπ’ αὐτοῦ τριῶν ἀνύσαντες ἡμερῶν τοῖς Ναβαταίοις εἰρηνικῶς ὑπαντῶσιν περιτυγχάνουσιν. ὧν διηγησαμένων τὰ περὶ τοὺς ἐν τῇ Γαλάτιδι, ὡς πολλοὶ κακοπαθοῦσιν αὐτῶν ἐν τοῖς φρουρίοις ἀπειλημμένοι καὶ ταῖς πόλεσιν τῆς Γαλάτιδος, καὶ παραινεσάντων αὐτῷ σπεύδειν ἐπὶ τοὺς ἀλλοφύλους καὶ ζητεῖν ἀπ’ αὐτῶν σώζειν τοὺς ὁμοεθνεῖς, πεισθεὶς ὑπέστρεψεν εἰς τὴν ἔρημον, καὶ προσπεσὼν πρώτοις τοῖς τὴν Βοσόραν κατοικοῦσιν καὶ λαβὼν αὐτὴν καταβαλὼν πᾶν τὸ ἄρρεν καὶ μάχεσθαι δυνάμενον διέφθειρεν καὶ τὴν πόλιν ὑφῆψεν. ἐπιγενομένης δὲ νυκτὸς οὐδ’ οὕτως ἐπέσχεν, ἀλλ’ ὁδεύσας δι’ αὐτῆς ἐπὶ τὸ φρούριον, ἔνθα τοὺς Ἰουδαίους ἐγκεκλεῖσθαι συνέβαινεν περικαθεζομένου τὸ χωρίον Τιμοθέου μετὰ τῆς δυνάμεως, ἕωθεν ἐπ’ αὐτὸ παραγίνεται. καὶ καταλαβὼν ἤδη τοῖς τείχεσι προσβεβληκότας τοὺς πολεμίους καὶ τοὺς μὲν κλίμακας, ὥστε ἀναβαίνειν ἐπ’ αὐτά, τοὺς δὲ μηχανήματα προσφέροντας, κελεύσας τὸν σαλπικτὴν σημῆναι καὶ παρορμήσας τοὺς στρατιώτας ὑπὲρ ἀδελφῶν καὶ συγγενῶν διακινδυνεῦσαι προθύμως, εἰς τρία διελὼν τὸν στρατὸν ἐπιπίπτει κατὰ νώτου τοῖς πολεμίοις. οἱ δὲ περὶ τὸν Τιμόθεον αἰσθόμενοι, ὅτι Μακαβαῖος εἴη, πεῖραν ἤδη καὶ πρότερον αὐτοῦ τῆς ἀνδρείας καὶ τῆς ἐν τοῖς πολέμοις εὐτυχίας εἰληφότες φυγῇ χρῶνται· ἐφεπόμενος δὲ μετὰ τοῦ στρατεύματος ὁ Ἰούδας ἀναιρεῖ μὲν αὐτῶν ὡς ὀκτακισχιλίους, ἀπονεύσας δ’ εἰς Μελλὰ πόλιν οὕτως λεγομένην τῶν ἀλλοφύλων λαμβάνει καὶ ταύτην καὶ τοὺς μὲν ἄρρενας ἅπαντας ἀποκτείνει, τὴν δὲ πόλιν αὐτὴν ἐμπίπρησιν. ἄρας δ’ ἐκεῖθεν τήν τε Χασφομάκη καὶ Βοσὸρ καὶ πολλὰς ἄλλας πόλεις τῆς Γαλάτιδος καταστρέφεται.", "st": "12.8.3"}, {"sp": "N", "t": "Χρόνῳ δ’ ὕστερον οὐ πολλῷ Τιμόθεος δύναμιν μεγάλην παρασκευασάμενος καὶ συμμάχους ἄλλους τε παραλαβὼν καὶ Ἀράβων τινὰς μισθῷ πείσας αὐτῷ συστρατεύειν ἧκεν ἄγων τὴν στρατιὰν πέραν τοῦ χειμάρρου Ῥομφῶν ἄντικρυς· πόλις δ’ ἦν αὕτη· καὶ παρεκελεύετο τοὺς στρατιώτας, εἰ συμβάλοιεν εἰς μάχην τοῖς Ἰουδαίοις, προθύμως ἀγωνίζεσθαι καὶ κωλύειν αὐτοὺς διαβαίνειν τὸν χείμαρρον· διαβάντων γὰρ ἧτταν αὐτοῖς προύλεγεν. Ἰούδας δ’ ἀκούσας παρεσκευάσθαι τὸν Τιμόθεον πρὸς μάχην ἀναλαβὼν ἅπασαν τὴν οἰκείαν δύναμιν ἔσπευδεν ἐπὶ τὸν πολέμιον, καὶ περαιωσάμενος τὸν χείμαρρον ἐπιπίπτει τοῖς ἐχθροῖς καὶ τοὺς μὲν αὐτῶν ὑπαντιάζοντας ἀνῄρει, τοὺς δ’ εἰς δέος ἐμβαλὼν ῥίψαντας τὰ ὅπλα φεύγειν ἠνάγκασεν. καὶ τινὲς μὲν αὐτῶν διέδρασαν, οἱ δ’ εἰς τὸ καλούμενον ἐγκρανὰς τέμενος συμφυγόντες ἤλπισαν τεύξεσθαι σωτηρίας. Ἰούδας δὲ τὴν πόλιν καταλαβόμενος αὐτούς τε ἀπέκτεινεν καὶ τὸ τέμενος ἐνέπρησεν ποικίλῃ χρησάμενος ἰδέᾳ τῆς ἀπωλείας τῶν πολεμίων.", "st": "12.8.4"}, {"sp": "N", "t": "Ταῦτα διαπραξάμενος καὶ συναγαγὼν τοὺς ἐν τῇ Γαλάτιδι Ἰουδαίους μετὰ τέκνων καὶ γυναικῶν καὶ τῆς ὑπαρχούσης αὐτοῖς ἀποσκευῆς οἷός τε ἦν εἰς τὴν Ἰουδαίαν ἐπαναγαγεῖν. ὡς δ’ ἧκεν ἐπί τινα πόλιν Ἐμφρὼν ὄνομα ἐπὶ τῆς ὁδοῦ κειμένην καὶ οὔτε ἄλλην αὐτῷ τραπομένῳ βαδίζειν δυνατὸν ἦν οὔτε ἀναστρέφειν ἤθελεν, πέμψας πρὸς τοὺς ἐν αὐτῇ παρεκάλει τὰς πύλας ἀνοίξαντας ἐπιτρέπειν αὐτῷ διὰ τῆς πόλεως ἀπελθεῖν· τάς τε γὰρ πύλας λίθοις ἐμπεφράκεσαν καὶ τὴν διέξοδον ἀπετέμοντο. μὴ πειθομένων δὲ τῶν Ἐμφραίων παρορμήσας τοὺς μεθ’ ἑαυτοῦ κυκλωσάμενος ἐπολιόρκει, καὶ δι’ ἡμέρας καὶ νυκτὸς προσκαθίσας ἐξαιρεῖ τὴν πόλιν καὶ πᾶν ὅσον ἄρρεν ἦν ἐν αὐτῇ κτείνας καὶ καταπρήσας ἅπασαν αὐτὴν ὁδὸν ἔσχεν· τοσοῦτον δ’ ἦν τὸ τῶν πεφονευμένων πλῆθος, ὡς ἐπ’ αὐτῶν βαδίζειν τῶν νεκρῶν. διαβάντες δὲ τὸν Ἰορδάνην ἧκον εἰς τὸ μέγα πεδίον, οὗ κεῖται κατὰ πρόσωπον πόλις Βεθσάνη καλουμένη πρὸς Ἑλλήνων Σκυθόπολις. κἀκεῖθεν ὁρμηθέντες εἰς τὴν Ἰουδαίαν παρεγένοντο ψάλλοντές τε καὶ ὑμνοῦντες καὶ τὰς συνήθεις ἐν τοῖς ἐπινικίοις παιδιὰς ἄγοντες, ἔθυσάν τε χαριστηρίους ὑπέρ τε τῶν κατωρθωμένων θυσίας καὶ ὑπὲρ τῆς τοῦ στρατεύματος σωτηρίας· οὐδεὶς γὰρ ἐν τούτοις τοῖς πολέμοις τῶν Ἰουδαίων ἀπέθανεν.", "st": "12.8.5"}, {"sp": "N", "t": "Ἰώσηπος δὲ ὁ Ζαχαρίου καὶ Ἀζαρίας, οὓς κατέλιπεν στρατηγοὺς ὁ Ἰούδας καθ’ ὃν καιρὸν Σίμων μὲν ὑπῆρχεν ἐν τῇ Γαλιλαίᾳ πολεμῶν τοὺς ἐν τῇ Πτολεμαΐδι, αὐτὸς δὲ ὁ Ἰούδας καὶ ὁ ἀδελφὸς αὐτοῦ Ἰωνάθης ἐν τῇ Γαλάτιδι, βουληθέντες καὶ αὐτοὶ δόξαν περιποιήσασθαι στρατηγῶν τὰ πολεμικὰ γενναίων τὴν ὑπ’ αὐτοῖς δύναμιν ἀναλαβόντες ἦλθον εἰς Ἰάμνειαν. Γοργίου δὲ τοῦ τῆς Ἰαμνείας στρατηγοῦ ὑπαντήσαντος συμβολῆς γενομένης δισχιλίους ἀποβάλλουσι τῆς στρατιᾶς καὶ φεύγοντες ἄχρι τῶν τῆς Ἰουδαίας ὅρων [διώκονται]. συνέβη δ’ αὐτοῖς τὸ πταῖσμα τοῦτο παρακούσασιν ὧν αὐτοῖς Ἰούδας ἐπέστειλεν, μὴ συμβαλεῖν εἰς μάχην μηδενὶ πρὸ τῆς ἐκείνου παρουσίας· πρὸς γὰρ τοῖς ἄλλοις αὐτοῦ στρατηγήμασιν καὶ τὸ κατὰ τοὺς περὶ τὸν Ἰώσηπον καὶ τὸν Ἀζαρίαν πταῖσμα θαυμάσειεν ἄν τις, ὃ συνῆκεν εἰ παρακινήσουσίν τι τῶν ἐπεσταλμένων αὐτοῖς ἐσόμενον. ὁ δὲ Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ πολεμοῦντες τοὺς Ἰδουμαίους οὐκ ἀνίεσαν, ἀλλ’ ἐνέκειντο πανταχόθεν αὐτοῖς, τήν τε Χεβρῶνα πόλιν καταλαβόμενοι ὅσον ὀχυρὸν αὐτῆς καθεῖλον καὶ τοὺς πύργους ἐμπρήσαντες ἐδῄουν τὴν ἀλλόφυλον χώραν καὶ Μάρισαν πόλιν, εἴς τε Ἄζωτον ἐλθόντες καὶ λαβόντες αὐτὴν διήρπασαν. πολλὰ δὲ σκῦλα καὶ λείαν κομίζοντες εἰς τὴν Ἰουδαίαν ὑπέστρεψαν.", "st": "12.8.6"}, {"sp": "N", "t": "Ὑπὸ δὲ τὸν αὐτὸν καιρὸν καὶ ὁ βασιλεὺς Ἀντίοχος τὴν ἄνω χώραν ἐπερχόμενος ἀκούει πόλιν ἐν τῇ Περσίδι πλούτῳ διαφέρουσαν Ἐλυμαΐδα τοὔνομα καὶ πολυτελὲς ἱερὸν Ἀρτέμιδος ἐν αὐτῇ καὶ παντοδαπῶν ἀναθημάτων πλῆρες εἶναι ἔτι γε μὴν ὅπλα καὶ θώρακας, ἃ καταλιπεῖν ἐπυνθάνετο τὸν υἱὸν τὸν Φιλίππου βασιλέα δὲ Μακεδόνων Ἀλέξανδρον. κινηθεὶς οὖν ὑπὸ τούτων ὥρμησεν ἐπὶ τὴν Ἐλυμαΐδα καὶ προσβαλὼν αὐτὴν ἐπολιόρκει. τῶν δ’ ἐν αὐτῇ μὴ καταπλαγέντων τὴν ἔφοδον αὐτοῦ μηδὲ τὴν πολιορκίαν, ἀλλὰ καρτερῶς ἀντισχόντων ἀποκρούεται τῆς ἐλπίδος· ἀπωσάμενοι γὰρ ἀπὸ τῆς πόλεως καὶ ἐπεξελθόντες ἐδίωξαν, ὥστ’ αὐτὸν ἐλθεῖν εἰς Βαβυλῶνα φεύγοντα καὶ πολλοὺς ἀποβαλόντα τῆς στρατιᾶς. λυπουμένῳ δ’ ἐπὶ τῇ διαμαρτίᾳ ταύτῃ προσαγγέλλουσίν τινες καὶ τὴν τῶν στρατηγῶν ἧτταν, οὓς πολεμήσοντας τοῖς Ἰουδαίοις καταλελοίπει, καὶ τὴν ἰσχὺν ἤδη τὴν τῶν Ἰουδαίων. προσγενομένης οὖν καὶ τῆς περὶ τούτων φροντίδος τῇ προτέρᾳ συγχυθεὶς ὑπὸ ἀθυμίας εἰς νόσον κατέπεσεν, ἧς μηκυνομένης καὶ αὐξανόντων τῶν παθῶν συνείς, ὅτι μέλλοι τελευτᾶν, συγκαλεῖ τοὺς φίλους καὶ τήν τε νόσον αὐτοῖς χαλεπὴν οὖσαν ἐμήνυε καὶ ὅτι ταῦτα πάσχει κακώσας τὸ τῶν Ἰουδαίων ἔθνος παρεδήλου συλήσας τὸν ναὸν καὶ τοῦ θεοῦ καταφρονήσας, καὶ ταῦτα λέγων ἐξέπνευσεν. ὥστε θαυμάζειν Πολύβιον τὸν Μεγαλοπολίτην, ὃς ἀγαθὸς ὢν ἀνὴρ ἀποθανεῖν λέγει τὸν Ἀντίοχον βουληθέντα τὸ τῆς ἐν Πέρσαις Ἀρτέμιδος ἱερὸν συλῆσαι· τὸ γὰρ μηκέτι ποιῆσαι τὸ ἔργον βουλευσάμενον οὐκ ἔστιν τιμωρίας ἄξιον. εἰ δὲ διὰ τοῦτο Πολυβίῳ δοκεῖ καταστρέψαι τὸν βίον Ἀντίοχον οὕτως, πολὺ πιθανώτερον διὰ τὴν ἱεροσυλίαν τοῦ ἐν Ἱεροσολύμοις ναοῦ τελευτῆσαι τὸν βασιλέα. ἀλλὰ περὶ μὲν τούτου οὐ διαφέρομαι τὴν ὑπὸ τοῦ Μεγαλοπολίτου λεγομένην αἰτίαν ταύτην ὑφ’ ἡμῶν ἀληθῆ νομιζόντων.", "st": "12.9.1"}, {"sp": "N", "t": "Ὁ δ’ Ἀντίοχος πρὶν ἢ τελευτᾶν καλέσας Φίλιππον ἕνα τῶν ἑταίρων τῆς βασιλείας αὐτὸν ἐπίτροπον καθίστησιν, καὶ δοὺς αὐτῷ τὸ διάδημα καὶ τὴν στολὴν καὶ τὸν δακτύλιον Ἀντιόχῳ τῷ παιδὶ αὐτοῦ ταῦτα ἐκέλευσε κομίσαντα δοῦναι, δεηθεὶς προνοῆσαι τῆς ἀνατροφῆς αὐτοῦ καὶ τηρῆσαι τὴν βασιλείαν ἐκείνῳ. ἀπέθανεν δὲ Ἀντίοχος ἐνάτῳ καὶ τεσσαρακοστῷ καὶ ἑκατοστῷ ἔτει. Λυσίας δὲ τὸν θάνατον αὐτοῦ δηλώσας τῷ πλήθει τὸν υἱὸν αὐτοῦ Ἀντίοχον, αὐτὸς γὰρ εἶχεν τὴν ἐπιμέλειαν, ἀποδείκνυσι βασιλέα καλέσας αὐτὸν Εὐπάτορα.", "st": "12.9.2"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ τῷ καιρῷ οἱ ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων φρουροὶ καὶ φυγάδες τῶν Ἰουδαίων πολλὰ τοὺς Ἰουδαίους εἰργάσαντο· τοὺς γὰρ ἀναβαίνοντας εἰς τὸ ἱερὸν καὶ θῦσαι βουλομένους ἐξαίφνης ἐκτρέχοντες οἱ φρουροὶ διέφθειραν· ἐπέκειτο γὰρ τῷ ἱερῷ ἡ ἄκρα. τούτων οὖν συμβαινόντων αὐτοῖς Ἰούδας ἐξελεῖν διέγνω τὴν φρουράν, καὶ συναγαγὼν τὸν λαὸν ἅπαντα τοὺς ἐν τῇ ἄκρᾳ καρτερῶς ἐπολιόρκει. ἔτος ἦν τοῦτο τῆς ἀρχῆς τοῖς ἀπὸ Σελεύκου ἑκατοστὸν καὶ πεντηκοστόν. κατασκευάσας οὖν μηχανήματα καὶ χώματα ἐγείρας φιλοπόνως προσέκειτο τῇ τῆς ἄκρας αἱρέσει. πολλοὶ δὲ τῶν ἐν αὐτῇ φυγάδων νύκτωρ ἐξελθόντες εἰς τὴν χώραν καί τινας τῶν ὁμοίων καὶ ἀσεβῶν συναγαγόντες ἧκον πρὸς Ἀντίοχον τὸν βασιλέα, οὐκ ἀξιοῦντες ἑαυτοὺς ὑπερορᾶσθαι δεινὰ πάσχοντας ὑπὸ τῶν ὁμοφύλων καὶ ταῦθ’ ὑπομένοντας διὰ τὸν πατέρα αὐτοῦ, τὴν μὲν πάτριον αὐτῶν καταλύσαντας θρησκείαν, ἣν δὲ προσέταξεν ταύτης ἀντιποιουμένους· κινδυνεύειν οὖν ὑπὸ Ἰούδου καὶ τῶν σὺν αὐτῷ τὴν ἀκρόπολιν αἱρεθῆναι καὶ τοὺς φρουροὺς τοὺς ὑπὸ τοῦ βασιλέως κατασταθέντας, εἰ μή τις παρ’ αὐτοῦ βοήθεια πεμφθείη. ταῦτ’ ἀκούσας ὁ παῖς Ἀντίοχος ὠργίσθη καὶ τοὺς ἡγεμόνας καὶ φίλους μεταπεμψάμενος ἐκέλευσε μισθοφόρους συναγαγεῖν καὶ ἐκ τῆς βασιλείας τοὺς στρατεύσιμον ἡλικίαν ἔχοντας. καὶ συνήχθη στρατὸς πεζῶν μὲν ὡσεὶ δέκα μυριάδες, ἱππεῖς δὲ δισμύριοι, ἐλέφαντες δὲ δύο καὶ τριάκοντα.", "st": "12.9.3"}, {"sp": "N", "t": "Ταύτην οὖν ἀναλαβὼν τὴν δύναμιν ἐξώρμησεν ἐκ τῆς Ἀντιοχείας μετὰ Λυσίου πάσης τῆς στρατιᾶς ἔχοντος τὴν ἡγεμονίαν. καὶ παραγενόμενος εἰς τὴν Ἰδουμαίαν ἐκεῖθεν εἰς Βηθσοῦραν ἀναβαίνει πόλιν σφόδρα ἐχυρὰν καὶ δυσάλωτον καὶ περικαθίσας ἐπολιόρκει τὴν πόλιν. ἰσχυρῶς δὲ ἀντεχόντων τῶν Βηθσουραίων καὶ τὴν παρασκευὴν αὐτοῦ τῶν μηχανημάτων ἐμπρησάντων, ἐπεξῆλθον γὰρ αὐτῷ, χρόνος ἐτρίβετο πολὺς περὶ τὴν πολιορκίαν. Ἰούδας δὲ τὴν ἔφοδον τοῦ βασιλέως ἀκούσας ἀφίσταται μὲν τοῦ τὴν ἄκραν πολιορκεῖν, ἀπαντήσας δὲ τῷ βασιλεῖ βάλλεται στρατόπεδον ἐπὶ τῶν στενῶν ἔν τινι τόπῳ Βεθζαχαρίᾳ λεγομένῳ σταδίους ἀπέχοντι τῶν πολεμίων ἑβδομήκοντα. ὁ δὲ βασιλεὺς ὁρμήσας ἀπὸ τῆς Βεθσούρας ἤγαγε τὴν δύναμιν ἐπὶ τὰ στενὰ καὶ τὸ τοῦ Ἰούδα στρατόπεδον, ἅμ’ ἡμέρᾳ δὲ πρὸς μάχην διέτασσε τὴν στρατιάν. τοὺς μὲν οὖν ἐλέφαντας ἐποίησεν ἀλλήλοις ἕπεσθαι διὰ τὴν στενοχωρίαν οὐ δυναμένων αὐτῶν ἐπὶ πλάτος τετάχθαι, εἰς δὲ κύκλον ἐλέφαντος ἑκάστου συμπροῇσαν πεζοὶ μὲν χίλιοι, ἱππεῖς δὲ πεντακόσιοι· ἔφερον δὲ οἱ ἐλέφαντες πύργους τε ὑψηλοὺς καὶ τοξότας· τὴν δὲ λοιπὴν δύναμιν ἑκατέρωθεν ἐποίησεν ἀναβαίνειν ἐπὶ τὰ ὄρη φίλους αὐτῆς προτάξας. κελεύσας δὲ ἀλαλάξαι τὴν στρατιὰν προσβάλλει τοῖς πολεμίοις, γυμνώσας τάς τε χρυσᾶς καὶ χαλκᾶς ἀσπίδας, ὥστε αὐγὴν ἀπ’ αὐτῶν ἀφίεσθαι λαμπράν· συνεπήχει δὲ τὰ ὄρη κεκραγότων αὐτῶν. ταῦτα ὁρῶν ὁ Ἰούδας οὐ κατεπλάγη, δεξάμενος δὲ γενναίως τοὺς πολεμίους τῶν προδρόμων περὶ ἑξακοσίους ἀναιρεῖ. Ἐλεάζαρος δ’ ὁ ἀδελφὸς αὐτοῦ, ὃν Αὐρὸν ἐκάλουν, ἰδὼν τὸν ὑψηλότατον τῶν ἐλεφάντων ὡπλισμένον θώραξι βασιλικοῖς καὶ νομίζων ἐπ’ αὐτοῦ τὸν βασιλέα εἶναι παρεβάλετο σφόδρα εὐκαρδίως ἐπ’ αὐτὸν ὁρμήσας, καὶ πολλοὺς μὲν τῶν περὶ τὸν ἐλέφαντα κτείνας τοὺς ἄλλους διεσκέδασεν, ὑποδὺς δὲ ὑπὸ τὴν γαστέρα καὶ πλήξας ἀπέκτεινε τὸν ἐλέφαντα. ὁ δ’ ἐπικατενεχθεὶς τῷ Ἐλεαζάρῳ διαφθείρει τὸν ἄνδρα ὑπὸ τοῦ βάρους. καὶ οὗτος μὲν εὐψύχως πολλοὺς τῶν ἐχθρῶν ἀπολέσας τῷ τρόπῳ τούτῳ τὸν βίον κατέστρεψεν.", "st": "12.9.4"}, {"sp": "N", "t": "Ὁ δὲ Ἰούδας ὁρῶν τὴν τῶν πολεμίων ἰσχὺν ἀνεχώρησεν εἰς Ἱεροσόλυμα καὶ πρὸς πολιορκίαν παρεσκευάζετο· Ἀντίοχος δὲ τὸ μέν τι τῆς στρατιᾶς εἰς Βεθσοῦραν ἔπεμψεν πολεμήσων αὐτήν, τῷ δὲ λοιπῷ τῆς δυνάμεως αὐτὸς ἧκεν εἰς Ἱεροσόλυμα. οἱ μὲν οὖν Βεθσουρῖται τὴν ἰσχὺν καταπλαγέντες καὶ σπανίζοντα βλέποντες τὰ ἐπιτήδεια παραδιδόασιν ἑαυτοὺς ὅρκους λαβόντες ὑπὲρ τοῦ μηδὲν πείσεσθαι κακὸν ὑπὸ τοῦ βασιλέως. Ἀντίοχος δὲ λαβὼν τὴν πόλιν ἄλλο μὲν αὐτοὺς οὐδὲν διέθηκεν, μόνον δὲ γυμνοὺς ἐξέβαλεν, φρουρὰν δὲ κατέστησεν ἰδίαν ἐν τῇ πόλει. πολλῷ δὲ χρόνῳ τὸ ἱερὸν πολιορκῶν τὸ ἐν Ἱεροσολύμοις προσεκαθέζετο καρτερῶς τῶν ἔνδοθεν ἀμυνομένων· πρὸς ἕκαστον γὰρ ὧν ὁ βασιλεὺς ἐπ’ αὐτοὺς ἔστησε μηχάνημα κἀκεῖνοι πάλιν ἀντεμηχανῶντο. τροφὴ δ’ αὐτοὺς ἐπιλελοίπει, τοῦ μὲν ὄντος ἀπανηλωμένου καρποῦ, τῆς δὲ γῆς ἐκείνῳ τῷ ἔτει μὴ γεωργημένης, ἀλλὰ διὰ τὸ εἶναι τὸ ἕβδομον ἔτος, καθ’ ὃ νόμος ἡμῖν ἀργὴν ἐᾶν τὴν χώραν, ἀσπόρου μεμενηκυίας. πολλοὶ τοιγαροῦν τῶν πολιορκουμένων ἀπεδίδρασκον διὰ τὴν τῶν ἀναγκαίων ἀπορίαν, ὡς ὀλίγους ἐν τῷ ἱερῷ καταλειφθῆναι.", "st": "12.9.5"}, {"sp": "N", "t": "Καὶ τοῖς μὲν πολιορκουμένοις ἐν τῷ ἱερῷ τοιαῦτα συνέβαινεν εἶναι τὰ πράγματα. Λυσίας δὲ ὁ στρατηγὸς καὶ ὁ βασιλεύς, ἐπεὶ Φίλιππος αὐτοῖς ἀπὸ τῆς Περσίδος ἥκων ἐδηλώθη [καὶ] τὰ πράγματα εἰς αὐτὸν κατασκευάζειν, εἶχον μὲν ὥστε τὴν πολιορκίαν ἀφέντες ὁρμᾶν ἐπὶ τὸν Φίλιππον, οὐ μὴν τοῦτο ποιῆσαι φανερὸν τοῖς στρατιώταις καὶ τοῖς ἡγεμόσιν ἔγνωσαν, ἀλλ’ ἐκέλευσεν τὸν Λυσίαν ὁ βασιλεὺς αὐτῷ τε καὶ τοῖς ἡγεμόσιν ἐν κοινῷ διαλεχθῆναι μηδὲν μὲν τῶν περὶ Φίλιππον ἐμφανίζοντα, τὴν δὲ πολιορκίαν ὅτι χρονιωτάτη γένοιτ’ ἂν δηλοῦντα, καὶ τὴν ὀχυρότητα τοῦ χωρίου, καὶ ὅτι τὰ τῆς τροφῆς αὐτοῖς ἤδη ἐπιλείποι, καὶ ὡς πολλὰ δεῖ καταστῆσαι τῶν ἐν τῇ βασιλείᾳ πραγμάτων, καὶ ὡς δοκεῖ πολὺ κρεῖττον εἶναι σπονδὰς ποιησαμένους πρὸς τοὺς πολιορκουμένους καὶ φιλίαν πρὸς ὅλον αὐτῶν τὸ ἔθνος ἐπιτρέψαντας αὐτοῖς χρῆσθαι τοῖς πατρίοις νόμοις, ὧν ἀφαιρεθέντες νῦν ἐξεπολεμώθησαν, χωρεῖν ἐπὶ τὰ οἰκεῖα. ταῦτα τοῦ Λυσίου φήσαντος ἠρέσθη τό τε στράτευμα καὶ οἱ ἡγεμόνες τῇ γνώμῃ.", "st": "12.9.6"}, {"sp": "N", "t": "Καὶ πέμψας ὁ βασιλεὺς πρὸς τὸν Ἰούδαν καὶ τοὺς σὺν αὐτῷ πολιορκουμένους εἰρήνην τε ἐπηγγείλατο καὶ συγχωρεῖν τοῖς πατρίοις νόμοις χρωμένους ζῆν. οἱ δὲ ἀσμένως δεξάμενοι τοὺς λόγους λαβόντες ὅρκους τε καὶ πίστεις ἐξῆλθον ἐκ τοῦ ἱεροῦ. εἰσελθὼν δὲ Ἀντίοχος εἰς αὐτὸ καὶ θεασάμενος ὀχυρὸν οὕτως τὸ χωρίον παρέβη τοὺς ὅρκους καὶ κελεύει τὴν δύναμιν παραστᾶσαν καθελεῖν τὸ τεῖχος εἰς ἔδαφος. καὶ ταῦτα ποιήσας ἀνέστρεψεν εἰς Ἀντιόχειαν ἐπαγόμενος Ὀνίαν τὸν ἀρχιερέα, ὃς καὶ Μενέλαος ἐκαλεῖτο. Λυσίας γὰρ συνεβούλευσεν τῷ βασιλεῖ τὸν Μενέλαον ἀνελεῖν, εἰ βούλεται τοὺς Ἰουδαίους ἠρεμεῖν καὶ μηδὲν ἐνοχλεῖν αὐτῷ· τοῦτον γὰρ ἄρξαι τῶν κακῶν πείσαντ’ αὐτοῦ τὸν πατέρα τοὺς Ἰουδαίους ἀναγκάσαι τὴν πάτριον θρησκείαν καταλιπεῖν. πέμψας οὖν τὸν Μενέλαον ὁ βασιλεὺς εἰς Βέροιαν τῆς Συρίας διέφθειρεν ἀρχιερατεύσαντα μὲν ἔτη δέκα, πονηρὸν δὲ γενόμενον καὶ ἀσεβῆ καὶ ἵνα αὐτὸς ἄρχῃ τὸ ἔθνος ἀναγκάσαντα τοὺς ἰδίους παραβῆναι νόμους. ἀρχιερεὺς δὲ ἐγένετο μετὰ τὸν Μενελάου θάνατον Ἄλκιμος ὁ καὶ Ἰάκιμος κληθείς. ὁ δὲ βασιλεὺς Ἀντίοχος ὁρῶν ἤδη τὸν Φίλιππον κρατοῦντα τῶν πραγμάτων ἐπολέμει πρὸς αὐτὸν καὶ λαβὼν αὐτὸν ὑποχείριον ἀπέκτεινεν. ὁ δὲ τοῦ ἀρχιερέως υἱὸς Ὀνίας, ὃν προείπομεν ἔτι παῖδα τελευτήσαντος ἀφίεσθαι τοῦ πατρός, ἰδὼν ὅτι τὸν θεῖον αὐτοῦ Μενέλαον ὁ βασιλεὺς ἀνελὼν τὴν ἀρχιερωσύνην Ἀλκίμῳ δέδωκεν οὐκ ὄντι τῆς τῶν ἀρχιερέων γενεᾶς, ἀλλ’ ὑπὸ Λυσίου πεισθεὶς μεταθεῖναι τὴν τιμὴν ἀπὸ ταύτης τῆς οἰκίας εἰς ἕτερον οἶκον, φεύγει πρὸς Πτολεμαῖον τὸν Αἰγύπτου βασιλέα. καὶ τιμῆς ἀξιωθεὶς ὑπό τε αὐτοῦ καὶ τῆς γυναικὸς Κλεοπάτρας λαμβάνει τόπον ἀξιώσας ἐν τῷ νομῷ τῷ Ἡλιοπολίτῃ, ἐν ᾧ καὶ ὅμοιον τῷ ἐν Ἱεροσολύμοις ᾠκοδόμησεν ἱερόν. περὶ τούτου μὲν οὖν εὐκαιρότερον ἡμῖν ἔσται διελθεῖν.", "st": "12.9.7"}, {"sp": "N", "t": "Ὑπὸ δὲ τὸν αὐτὸν καιρὸν φυγὼν Δημήτριος ἀπὸ Ῥώμης ὁ Σελεύκου υἱὸς καὶ καταλαβόμενος τῆς Συρίας Τρίπολιν περιτίθησιν μὲν ἑαυτῷ διάδημα, συναγαγὼν δέ τινας περὶ αὐτὸν μισθοφόρους εἰς τὴν βασιλείαν εἰσῆλθεν, πάντων αὐτὸν ἡδέως προσδεχομένων καὶ παραδιδόντων αὑτούς. συλλαβόντες δὲ καὶ Ἀντίοχον τὸν βασιλέα καὶ Λυσίαν ζῶντας ἀνάγουσιν αὐτῷ. καὶ οὗτοι μὲν κελεύσαντος Δημητρίου παραχρῆμα διεφθάρησαν βασιλεύσαντος Ἀντιόχου ἔτη δύο, καθὼς ἤδη που καὶ ἐν ἄλλῳ δεδήλωται. συστραφέντες δὲ πρὸς αὐτὸν πολλοὶ τῶν Ἰουδαίων πονηροὶ καὶ φυγάδες καὶ μετ’ αὐτῶν Ἄλκιμος ὁ ἀρχιερεύς, κατηγόρουν τοῦ ἔθνους παντὸς καὶ Ἰούδα καὶ τῶν ἀδελφῶν αὐτοῦ, λέγοντες ὡς τοὺς φίλους αὐτοῦ πάντας ἀπεκτόνασιν καὶ ὅσοι τὰ ἐκείνου φρονοῦντες καὶ περιμένοντες αὐτὸν ὑπῆρχον ἐν τῇ βασιλείᾳ τούτους ἀπολωλέκασιν αὐτούς τε τῆς οἰκείας γῆς ἐκβαλόντες ἀλλοτρίας ἐπήλυδας πεποιήκασιν, ἠξίουν τε πέμψαντα τῶν ἰδίων τινὰ φίλων γνῶναι δι’ αὐτοῦ τὰ ὑπὸ τῶν περὶ Ἰούδαν τετολμημένα.", "st": "12.10.1"}, {"sp": "N", "t": "Ὁ δὲ Δημήτριος παροξυνθεὶς ἐκπέμπει Βακχίδην φίλον Ἀντιόχου τοῦ Ἐπιφανοῦς βασιλέως, ἄνδρα χρηστὸν καὶ τὴν Μεσοποταμίαν ἅπασαν πεπιστευμένον, δοὺς αὐτῷ δύναμιν καὶ τὸν ἀρχιερέα παραθέμενος αὐτῷ Ἄλκιμον ἐντειλάμενος ἀποκτεῖναι Ἰούδαν καὶ τοὺς σὺν αὐτῷ. ἐξορμήσας δὲ ἀπὸ τῆς Ἀντιοχείας ὁ Βακχίδης μετὰ τῆς δυνάμεως καὶ παραγενόμενος εἰς τὴν Ἰουδαίαν ἔπεμψε πρὸς τὸν Ἰούδαν καὶ τοὺς ἀδελφοὺς αὐτοῦ περὶ φιλίας καὶ εἰρήνης διαλεγόμενος· δόλῳ γὰρ αὐτὸν ἐβούλετο λαβεῖν. ὁ δ’ οὐκ ἐπίστευσεν· ἑώρα γάρ, ὅτι μετὰ στρατιᾶς πάρεστιν τοσαύτης, μεθ’ ὅσης ἐπὶ πόλεμόν τις, ἀλλ’ οὐκ ἐπ’ εἰρήνην ἔρχεται. τινὲς μέντοι γε τῶν ἐκ τοῦ δήμου προσέχοντες οἷς ὁ Βακχίδης ἐπεκηρυκεύσατο καὶ νομίσαντες οὐδὲν αὐτοὺς ὑπὸ Ἀλκίμου πείσεσθαι δεινὸν ὄντος ὁμοφύλου πρὸς αὐτοὺς ἀνεχώρησαν, καὶ λαβόντες ὅρκους παρ’ ἀμφοτέρων μήτε αὐτούς τι παθεῖν μήτε τοὺς ἐκ τῆς αὐτῆς ὄντας προαιρέσεως ἐπίστευσαν αὑτοὺς ἐκείνοις. ὁ δὲ Βακχίδης ὀλιγωρήσας τῶν ὅρκων ἑξήκοντα μὲν αὐτῶν ἀπέκτεινεν, τοὺς δὲ ἄλλους, ὅσοι διενοοῦντο πρὸς αὐτὸν ἀναχωρεῖν, ἐπέστρεψεν τοῖς πρώτοις τὴν πίστιν μὴ φυλάξας. ἐπεὶ δ’ ἐκ τῶν Ἱεροσολύμων ἀπελθὼν κατὰ κώμην Βηρζηθὼ λεγομένην ἐγένετο, πέμψας συλλαμβάνει πολλοὺς τῶν αὐτομολούντων καί τινας τοῦ λαοῦ καὶ πάντας ἀποκτείνας προσέταξεν τοῖς ἐν τῇ χώρᾳ πᾶσιν ὑπακούειν Ἀλκίμῳ, καὶ μετὰ στρατιᾶς τινος, ἵν’ ἔχῃ τηρεῖν τὴν χώραν αὐτοῦ, καταλιπὼν αὐτὸν εἰς Ἀντιόχειαν πρὸς τὸν βασιλέα Δημήτριον ὑπέστρεψεν.", "st": "12.10.2"}, {"sp": "N", "t": "Ἄλκιμος δὲ τὴν ἀρχὴν αὐτοῦ βουλόμενος βεβαιώσασθαι καὶ συνείς, ὅτι κατασκευάσας εὔνουν τὸ πλῆθος ἀσφαλέστερον ἄρξει, χρηστοῖς ἅπαντας ὑπήγετο λόγοις καὶ πρὸς ἡδονὴν ἑκάστῳ καὶ χάριν ὁμιλῶν ταχὺ δὴ μάλα χεῖρα πολλὴν καὶ δύναμιν περιεβάλετο· τούτων δ’ ἦσαν οἱ πλείους ἐκ τῶν ἀσεβῶν καὶ πεφυγαδευμένων, οἷς ὑπηρέταις καὶ στρατιώταις χρώμενος ἐπήρχετο τὴν χώραν καὶ ὅσους ἐν αὐτῇ τὰ Ἰούδα φρονοῦντας ηὕρισκεν ἐφόνευεν. ὁρῶν δὲ τὸν Ἄλκιμον ἤδη μέγαν ὁ Ἰούδας γινόμενον καὶ πολλοὺς διεφθαρκότα τῶν ἀγαθῶν καὶ ὁσίων τοῦ ἔθνους, καὶ αὐτὸς ἐπιπορευόμενος τὴν χώραν διέφθειρεν τοὺς ταὐτὰ ἐκείνῳ φρονοῦντας. βλέπων δὲ ἑαυτὸν Ἄλκιμος ἀντέχειν τῷ Ἰούδᾳ μὴ δυνάμενον, ἀλλ’ ἡττώμενον αὐτοῦ τῆς ἰσχύος, ἐπὶ τὴν παρὰ Δημητρίου τοῦ βασιλέως συμμαχίαν ἔγνω τραπέσθαι. παραγενόμενος οὖν εἰς Ἀντιόχειαν παρώξυνεν αὐτὸν ἐπὶ τὸν Ἰούδαν, κατηγορῶν ὡς πολλὰ μὲν ὑπ’ αὐτοῦ πεπόνθοι κακά, πλείω δὲ γένοιτ’ ἄν, εἰ μὴ προκαταληφθείη καὶ δοίη δίκην δυνάμεως ἐπ’ αὐτὸν ἰσχυρᾶς ἀποσταλείσης.", "st": "12.10.3"}, {"sp": "N", "t": "Ὁ δὲ Δημήτριος τοῦτ’ ἤδη καὶ τοῖς ἰδίοις αὐτοῦ πράγμασιν ἐπισφαλὲς ἡγησάμενος εἶναι τὸ περιιδεῖν Ἰούδαν ἐν ἰσχύι τοσαύτῃ γενόμενον, ἐκπέμπει Νικάνορα τὸν εὐνούστατον αὐτῷ καὶ πιστότατον τῶν φίλων, οὗτος γάρ ἐστιν ὁ καὶ ἀπὸ τῆς Ῥωμαίων πόλεως αὐτῷ συμφυγών, καὶ δοὺς δύναμιν ὅσην ὑπέλαβεν ἀρκέσειν αὐτῷ πρὸς τὸν Ἰούδαν ἐκέλευσεν μηδεμίαν φειδὼ ποιεῖσθαι τοῦ ἔθνους. ὁ δὲ Νικάνωρ παραγενόμενος εἰς Ἱεροσόλυμα πολεμεῖν μὲν εὐθὺς οὐ διέγνω τῷ Ἰούδᾳ, δόλῳ δ’ ὑποχείριον λαβεῖν κρίνας προσπέμπει λόγους εἰρηνικοὺς αὐτῷ, μηδεμίαν μὲν ἀνάγκην εἶναι φάσκων πολεμεῖν καὶ κινδυνεύειν, ὅρκους δ’ αὐτῷ διδόναι περὶ τοῦ μηδὲν πείσεσθαι δεινόν· ἥκειν γὰρ μετὰ φίλων ἐπὶ τῷ ποιῆσαι φανερὰν αὐτοῖς τὴν Δημητρίου τοῦ βασιλέως διάνοιαν, ὡς περὶ τοῦ γένους αὐτῶν φρονεῖ. ταῦτα διαπρεσβευσαμένου τοῦ Νικάνορος ὁ Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ πεισθέντες καὶ μηδεμίαν ἀπάτην ὑποπτεύσαντες διδόασιν πίστεις αὐτῷ καὶ δέχονται τὸν Νικάνορα μετὰ τῆς δυνάμεως. ὁ δὲ ἀσπασάμενος τὸν Ἰούδαν [καὶ] μεταξὺ προσομιλῶν δίδωσι τοῖς οἰκείοις τι σημεῖον, ὅπως συλλάβωσι τὸν Ἰούδαν. ὁ δὲ συνεὶς τὴν ἐπιβουλὴν ἐκπηδήσας πρὸς τοὺς ἰδίους συνέφυγεν. φανερᾶς δὲ τῆς προαιρέσεως αὐτοῦ καὶ τῆς ἐνέδρας ὁ Νικάνωρ γενομένης πολεμεῖν ἔκρινεν τῷ Ἰούδᾳ, καὶ συγκροτήσας καὶ παρασκευασάμενος τὰ πρὸς τὴν μάχην συμβάλλει κατά τινα κώμην Καφαρσαλαμὰ καὶ νικήσας ἀναγκάζει τὸν Ἰούδαν ἐπὶ τὴν ἐν τοῖς Ἱεροσολύμοις ἄκραν φεύγειν.", "st": "12.10.4"}, {"sp": "N", "t": "Ἔτι δ’ αὐτῷ κατιόντι ἀπὸ τῆς ἄκρας εἰς τὸ ἱερὸν ἀπαντήσαντες τῶν ἱερέων τινὲς καὶ πρεσβυτέρων ἠσπάζοντο καὶ τὰς θυσίας ἐπεδείκνυον, ἃς ὑπὲρ τοῦ βασιλέως ἔλεγον ἐπιφέρειν τῷ θεῷ. ὁ δὲ βλασφημήσας αὐτοὺς ἠπείλησεν, εἰ μὴ παραδοίη τὸν Ἰούδαν ὁ λαὸς αὐτῷ, καθαιρήσειν ὅταν ἐπανέλθῃ τὸν ναόν. καὶ ὁ μὲν ταῦτ’ ἀπειλήσας ἐξῆλθεν ἀπὸ τῶν Ἱεροσολύμων, οἱ δ’ ἱερεῖς εἰς δάκρυα διὰ τὴν ἐπὶ τοῖς εἰρημένοις λύπην προέπεσον καὶ τὸν θεὸν ἱκέτευον ῥύσασθαι ἐκ τῶν πολεμίων αὐτούς. ὁ δὲ Νικάνωρ, ὡς ἐκ τῶν Ἱεροσολύμων ἐξελθὼν ἐγένετο κατά τινα κώμην Βηθωρου λεγομένην, αὐτόθι στρατοπεδεύεται προσγενομένης αὐτῷ καὶ ἄλλης ἀπὸ Συρίας δυνάμεως· Ἰούδας δὲ ἐν Ἀδασοῖς ἑτέρᾳ κώμῃ σταδίους ἀπεχούσῃ τριάκοντα τῆς Βηθωροῦ στρατοπεδεύεται δισχιλίους στρατιώτας ἔχων. τούτους παρορμήσας μὴ καταπλαγῆναι τὸ τῶν ἐναντίων πλῆθος, μηδὲ λογίζεσθαι πρὸς πόσους ἀγωνίζεσθαι μέλλουσιν, ἀλλὰ τίνες ὄντες καὶ περὶ οἵων ἐπάθλων κινδυνεύουσιν ἐνθυμουμένους εὐψύχως ὁμόσε χωρῆσαι τοῖς πολεμίοις, ἐπὶ τὴν μάχην ἐξάγει, καὶ συμβαλὼν τῷ Νικάνορι καὶ καρτερᾶς τῆς μάχης γενομένης κρατεῖ τῶν ἐναντίων καὶ πολλούς τε αὐτῶν ἀπέκτεινεν καὶ τελευταῖον αὐτὸς ὁ Νικάνωρ λαμπρῶς ἀγωνιζόμενος ἔπεσεν. οὗ πεσόντος οὐδὲ τὸ στράτευμα ἔμεινεν, ἀλλὰ τὸν στρατηγὸν ἀπολέσαντες εἰς φυγὴν ἐτράπησαν ῥίψαντες τὰς πανοπλίας. ἐπιδιώκων δὲ ὁ Ἰούδας ἐφόνευσεν καὶ ταῖς σάλπιγξι ταῖς πέριξ κώμαις ἐσήμαινεν, ὅτι νικῴη τοὺς πολεμίους. οἱ δ’ ἐν αὐταῖς ἀκούσαντες ἐξεπήδων ὡπλισμένοι καὶ τοῖς φεύγουσιν ὑπαντῶντες ἔκτεινον αὐτοὺς γενόμενοι κατὰ πρόσωπον, ὥστ’ ἐκ τῆς μάχης ταύτης οὐδεὶς διέφυγεν ὄντων αὐτῶν ἐννακισχιλίων. τὴν δὲ νίκην συνέβη γενέσθαι ταύτην τῇ τρισκαιδεκάτῃ τοῦ μηνὸς τοῦ λεγομένου παρὰ μὲν Ἰουδαίοις Ἄδαρ κατὰ δὲ Μακεδόνας Δύστρου. ἄγουσιν δ’ ἐν τούτῳ τὰ νικητήρια κατὰ πᾶν ἔτος καὶ ἑορτὴν νομίζουσι τὴν ἡμέραν. ἐξ ἐκείνου μέντοι τοῦ χρόνου πρὸς ὀλίγον τὸ τῶν Ἰουδαίων ἔθνος τῶν πολέμων ἀναπαυσάμενον καὶ εἰρήνης ἀπολαῦον ἔπειτα εἰς ἀγῶνας πάλιν καὶ κινδύνους κατέστη.", "st": "12.10.5"}, {"sp": "N", "t": "Τῷ δ’ ἀρχιερεῖ τῷ Ἀλκίμῳ βουληθέντι καθελεῖν τὸ τεῖχος τοῦ ἁγίου παλαιὸν ὂν καὶ κατεσκευασμένον ὑπὸ τῶν ἀρχαίων προφητῶν, πληγή τις αἰφνίδιος ἐκ τοῦ θεοῦ προσέπεσεν, ὑφ’ ἧς ἄφωνός τε ἐπὶ τὴν γῆν κατηνέχθη καὶ βασανισθεὶς ἐπὶ συχνὰς ἡμέρας ἀπέθανεν ἀρχιερατεύσας ἔτη τέσσαρα. τελευτήσαντος δὲ τούτου τὴν ἀρχιερωσύνην ὁ λαὸς τῷ Ἰούδᾳ δίδωσιν, ὃς ἀκούσας περὶ τῆς Ῥωμαίων δυνάμεως καὶ ὅτι καταπεπολεμήκασιν τήν τε Γαλατίαν καὶ τὴν Ἰβηρίαν καὶ Καρχηδόνα τῆς Λιβύης καὶ πρὸς τούτοις τὴν Ἑλλάδα κεχείρωνται καὶ τοὺς βασιλεῖς Περσέα καὶ Φίλιππον καὶ τὸν μέγαν Ἀντίοχον, ἔγνω φιλίαν ποιήσασθαι πρὸς αὐτούς. πέμψας οὖν εἰς τὴν Ῥώμην τῶν αὐτοῦ φίλων Εὐπόλεμον τὸν Ἰωάννου υἱὸν καὶ Ἰάσονα τὸν Ἐλεαζάρου παρεκάλει δι’ αὐτῶν συμμάχους εἶναι καὶ φίλους, καὶ Δημητρίῳ γράψαι, ὅπως μὴ πολεμῇ τοὺς Ἰουδαίους. ἐλθόντας δὲ εἰς τὴν Ῥώμην τοὺς παρὰ τοῦ Ἰούδα πρεσβευτὰς ἡ σύγκλητος δέχεται καὶ διαλεχθεῖσα περὶ ὧν ἐπέμφθησαν τὴν συμμαχίαν ἐπινεύει. ποιήσασα δὲ περὶ τούτου δόγμα τὸ μὲν ἀντίγραφον εἰς τὴν Ἰουδαίαν ἀπέστειλεν, αὐτὸ δ’ εἰς τὸ Καπετώλιον εἰς χαλκᾶς ἐγγράψαντες δέλτους ἀνέθεσαν. ἦν δὲ τοιοῦτον· δόγμα συγκλήτου περὶ συμμαχίας καὶ εὐνοίας τῆς πρὸς τὸ ἔθνος τὸ Ἰουδαίων. μηδένα τῶν ὑποτεταγμένων Ῥωμαίοις πολεμεῖν τῷ Ἰουδαίων ἔθνει μηδὲ τοῖς πολεμοῦσι χορηγεῖν ἢ σῖτον ἢ πλοῖα ἢ χρήματα. ἐὰν δὲ ἐπίωσί τινες Ἰουδαίοις, βοηθεῖν Ῥωμαίους αὐτοῖς κατὰ τὸ δυνατόν, καὶ πάλιν, ἂν τῇ Ῥωμαίων ἐπίωσίν τινες, Ἰουδαίους αὐτοῖς συμμαχεῖν. ἂν δέ τι πρὸς ταύτην τὴν συμμαχίαν θελήσῃ τὸ τῶν Ἰουδαίων ἔθνος ἢ προσθεῖναι ἢ ἀφελεῖν, τοῦτο κοινῇ γινέσθω γνώμῃ τοῦ δήμου τοῦ Ῥωμαίων, ὃ δ’ ἂν προστεθῇ τοῦτ’ εἶναι κύριον. ἐγράφη τὸ δόγμα ὑπὸ Εὐπολέμου τοῦ Ἰωάννου παιδὸς καὶ ὑπὸ Ἰάσονος τοῦ Ἐλεαζάρου ἐπ’ ἀρχιερέως μὲν τοῦ ἔθνους Ἰούδα, στρατηγοῦ δὲ Σίμωνος τοῦ ἀδελφοῦ αὐτοῦ. καὶ τὴν μὲν πρώτην Ῥωμαίοις πρὸς Ἰουδαίους φιλίαν καὶ συμμαχίαν οὕτως συνέβη γενέσθαι.", "st": "12.10.6"}, {"sp": "N", "t": "Δημήτριος δ’ ἀπαγγελθείσης αὐτῷ τῆς Νικάνορος τελευτῆς καὶ τῆς ἀπωλείας τοῦ σὺν αὐτῷ. στρατεύματος πάλιν τὸν Βακχίδην μετὰ δυνάμεως εἰς τὴν Ἰουδαίαν ἐξέπεμψεν. ὃς ἐκ τῆς Ἀντιοχείας ἐξορμήσας καὶ παραγενόμενος εἰς τὴν Ἰουδαίαν ἐν Ἀρβήλοις πόλει τῆς Γαλιλαίας στρατοπεδεύεται, καὶ τοὺς ἐν τοῖς ἐκεῖ σπηλαίοις ὄντας, πολλοὶ γὰρ εἰς αὐτὰ συμπεφεύγεσαν, ἐκπολιορκήσας καὶ λαβὼν ἄρας ἐκεῖθεν ἐπὶ τὰ Ἱεροσόλυμα σπουδὴν ἐποιεῖτο. μαθὼν δὲ τὸν Ἰούδαν ἔν τινι κώμῃ Ζηθῶ τοὔνομα κατεστρατοπεδευμένον ἐπ’ αὐτὸν ἠπείγετο μετὰ πεζῶν μὲν δισμυρίων, ἱππέων δὲ δισχιλίων· τῷ Ἰούδᾳ δ’ ἦσαν οἱ πάντες χίλιοι. οὗτοι τὸ Βακχίδου πλῆθος θεωρήσαντες ἔδεισαν καὶ τὴν παρεμβολὴν καταλιπόντες ἔφυγον πάντες πλὴν ὀκτακοσίων. Ἰούδας δὲ καταλειφθεὶς ὑπὸ τῶν οἰκείων στρατιωτῶν [καὶ] τῶν πολεμίων ἐπικειμένων καὶ μηδένα καιρὸν αὐτῷ πρὸς συλλογὴν τῆς δυνάμεως ἐπιτρεπόντων οἷός τ’ ἦν μετὰ τῶν ὀκτακοσίων συμβαλεῖν τοῖς τοῦ Βακχίδου, [καὶ] προτρεπόμενός τε τούτους εὐψύχως ὑφίστασθαι τὸν κίνδυνον παρεκάλει χωρεῖν ἐπὶ τὴν μάχην. τῶν δὲ λεγόντων, ὡς οὐκ εἰσὶ πρὸς τοσοῦτο μέγεθος στρατιᾶς ἀξιόμαχοι, συμβουλευόντων δὲ νῦν μὲν ἀναχωρεῖν καὶ σώζειν αὐτούς, αὖθις δὲ συναγαγόντας τοὺς ἰδίους τοῖς ἐχθροῖς συμβαλεῖν, μὴ τοῦτ’, εἶπεν, ἥλιος ἐπίδοι γενόμενον, ἵν’ ἐγὼ τὰ νῶτά μου δείξω τοῖς πολεμίοις. ἀλλ’ εἰ καὶ τελευτὴν ὁ παρών μοι καιρὸς φέρει καὶ δεῖ πάντως ἀπολέσθαι μαχόμενον, στήσομαι γενναίως πᾶν ὑπομένων τὸ μέλλον ἢ τοῖς ἤδη κατωρθωμένοις καὶ τῇ περὶ αὐτῶν δόξῃ προσβαλῶ τὴν ἐκ τῆς νῦν φυγῆς ὕβριν. καὶ ὁ μὲν ταῦτα πρὸς τοὺς ὑπολειφθέντας παρακαλῶν τοῦ κινδύνου καταφρονήσαντας ὁμόσε χωρῆσαι τοῖς πολεμίοις ἔλεγεν.", "st": "12.11.1"}, {"sp": "N", "t": "Ὁ δὲ Βακχίδης ἐξαγαγὼν ἐκ τοῦ στρατοπέδου τὴν δύναμιν πρὸς μάχην παρετάσσετο, καὶ τοὺς μὲν ἱππεῖς ἐξ ἑκατέρων τῶν κεράτων ἔταξε, τοὺς δὲ ψιλοὺς καὶ τοξότας προέστησεν πάσης τῆς φάλαγγος, αὐτὸς δ’ ἦν ἐπὶ τοῦ δεξιοῦ. οὕτως δὲ συντάξας τὴν στρατιὰν ἐπεὶ προσέμιξεν τῷ τῶν πολεμίων στρατοπέδῳ, σημῆναι τὸν σαλπικτὴν ἐκέλευσεν καὶ τὴν στρατιὰν ἀλαλάξασαν προσιέναι. τὸ δ’ αὐτὸ ποιήσας ὁ Ἰούδας συμβάλλει τοῖς πολεμίοις, καὶ καρτερῶς ἀμφοτέρων ἀγωνιζομένων καὶ τῆς μάχης μέχρι δυσμῶν παρατεινομένης, ἰδὼν ὁ Ἰούδας τὸν Βακχίδην καὶ τὸ κρατερὸν τῆς στρατιᾶς ἐν τῷ δεξιῷ κέρατι τυγχάνον, παραλαβὼν τοὺς εὐψυχοτάτους ὥρμησεν ἐπ’ ἐκεῖνο τὸ μέρος τῆς τάξεως, καὶ προσβαλὼν τοῖς ἐκεῖ διέσπα αὐτῶν τὴν φάλαγγα. ὠσάμενος δ’ εἰς μέσους εἰς φυγὴν ἐβιάσατο αὐτούς, καὶ διώκει μέχρι Ἐζᾶ ὄρους οὕτω λεγομένου. θεασάμενοι δὲ τὴν τροπὴν τῶν ἐν τῷ δεξιῷ κέρατι οἱ τὸ εὐώνυμον ἔχοντες ἐκυκλώσαντο τὸν Ἰούδαν διώκοντα καὶ λαμβάνουσι μέσον αὐτὸν κατόπιν γενόμενοι. ὁ δὲ φυγεῖν οὐ δυνάμενος, ἀλλὰ περιεσχημένος ὑπὸ τῶν πολεμίων, στὰς ἐμάχετο μετὰ τῶν σὺν αὐτῷ. πολλοὺς δὲ κτείνας τῶν ἀντιπάλων καὶ κατάκοπος γενόμενος καὶ αὐτὸς ἔπεσεν, ἐπὶ καλοῖς μὲν πρότερον γεγενημένοις, ἐφ’ ὁμοίοις δὲ ὅτε ἀπέθνησκεν τὴν ψυχὴν ἀφείς. πεσόντος δὲ Ἰούδα πρὸς μηδένα τὸ λοιπὸν ἀφορᾶν ἔχοντες οἱ σὺν αὐτῷ στρατηγοῦ δὲ τοιούτου στερηθέντες ἔφυγον. λαβόντες δὲ τὸ σῶμα παρὰ τῶν πολεμίων ὑπόσπονδον Σίμων καὶ Ἰωνάθης ἀδελφοὶ τοῦ Ἰούδα, κομίσαντες εἰς τὴν Μωδεεῖν κώμην, ὅπου καὶ ὁ πατὴρ αὐτῶν τέθαπτο, κηδεύουσιν πενθήσαντος ἐπὶ συχνὰς αὐτὸν τοῦ πλήθους ἡμέρας καὶ τιμήσαντος κοινῇ τοῖς νενομισμένοις. καὶ τέλος μὲν τοιοῦτον κατέσχεν Ἰούδαν, ἄνδρα γενναῖον καὶ μεγαλοπόλεμον γενόμενον καὶ τῶν τοῦ πατρὸς ἐντολῶν Ματταθίου μνήμονα καὶ πάνθ’ ὑπὲρ τῆς τῶν πολιτῶν ἐλευθερίας καὶ δρᾶσαι καὶ παθεῖν ὑποστάντα. τοιοῦτος οὖν τὴν ἀρετὴν ὑπάρξας μέγιστον αὐτοῦ κλέος καὶ μνημεῖον κατέλιπεν, ἐλευθερώσας τὸ ἔθνος καὶ τῆς ὑπὸ Μακεδόσιν ἐξαρπάσας αὐτὸ δουλείας. τὴν δ’ ἀρχιερωσύνην ἔτος τρίτον κατασχὼν ἀπέθανεν.", "st": "12.11.2"}, {"sp": "HDR", "t": "Βιβλίον ΙΓʹ", "st": "13"}, {"sp": "N", "t": "Τίνα μὲν οὖν τρόπον τὸ τῶν Ἰουδαίων ἔθνος καταδουλωσαμένων αὐτὸ τῶν Μακεδόνων ἀνεκτήσατο τὴν ἐλευθερίαν καὶ δι’ ὅσων καὶ πηλίκων ἀγώνων ὁ στρατηγὸς αὐτῶν ἐλθὼν Ἰούδας ἀπέθανεν ὑπὲρ αὐτῶν μαχόμενος, ἐν τῇ πρὸ ταύτης βίβλῳ δεδηλώκαμεν. μετὰ δὲ τὴν τελευτὴν τὴν Ἰούδου πᾶν ὅσον ἦν ἔτι τῶν ἀσεβῶν καὶ παραβεβηκότων τὴν πάτριον πολιτείαν ἐπεφύη τοῖς Ἰουδαίοις καὶ πανταχόθεν αὐτοὺς ἀκμάζον ἐκάκου. συνελάμβανε δὲ τῇ τούτων πονηρίᾳ καὶ λιμὸς τὴν χώραν καταλαβών, ὡς πολλοὺς διὰ τὴν σπάνιν τῶν ἀναγκαίων καὶ τὸ μὴ δύνασθαι τοῖς παρ’ ἀμφοτέρων ἀπό τε τοῦ λιμοῦ καὶ τῶν ἐχθρῶν δεινοῖς ἀντέχειν αὐτομολῆσαι πρὸς τοὺς Μακεδόνας. Βακχίδης δὲ τῶν Ἰουδαίων τοὺς ἀποστάντας τῆς πατρίου συνηθείας καὶ τὸν κοινὸν βίον προῃρημένους συναθροίσας τούτοις ἐνεχείρισεν τὴν τῆς χώρας ἐπιμέλειαν, οἳ καὶ συλλαμβάνοντες τοὺς Ἰούδου φίλους καὶ τὰ ἐκείνου φρονοῦντας τῷ Βακχίδῃ παρέδοσαν· ὁ δὲ βασανίζων πρῶτον αὐτοὺς καὶ πρὸς ἡδονὴν αἰκιζόμενος ἔπειθ’ οὕτως διέφθειρεν. ταύτης δὲ τῆς συμφορᾶς τοῖς Ἰουδαίοις τηλικαύτης γενομένης, ἡλίκης οὐκ ἦσαν πεπειραμένοι μετὰ τὴν ἐκ Βαβυλῶνος ἐπάνοδον, οἱ περιλειφθέντες τῶν ἑταίρων τῶν Ἰούδου βλέποντες ἀπολλύμενον οἰκτρῶς τὸ ἔθνος προσελθόντες αὐτοῦ τῷ ἀδελφῷ Ἰωνάθῃ μιμεῖσθαι τὸν ἀδελφὸν αὐτοῦ καὶ τὴν ἐκείνου περὶ τῶν ὁμοφύλων πρόνοιαν ἠξίουν ἀποθανόντος ὑπὲρ τῆς ἐκείνων ἐλευθερίας, καὶ μὴ περιορᾶν ἀπροστάτητον τὸ ἔθνος μηδ’ ἐν οἷς φθείρεται. ὁ δ’ Ἰωνάθης φήσας ἑτοίμως ἔχειν ἀποθνήσκειν ὑπὲρ αὐτῶν καὶ νομισθεὶς κατὰ μηδὲν εἶναι χείρων τἀδελφοῦ στρατηγὸς ἀποδείκνυται τῶν Ἰουδαίων.", "st": "13.1.1"}, {"sp": "N", "t": "Ὁ δὲ Βακχίδης ἀκούσας καὶ φοβηθείς, μὴ παράσχῃ πράγματα τῷ βασιλεῖ καὶ τοῖς Μακεδόσιν ὁ Ἰωνάθης, ὡς καὶ πρότερον Ἰούδας, ἀποκτεῖναι δόλῳ τοῦτον ἐζήτει. ταύτην δὲ ἔχων τὴν προαίρεσιν οὐκ ἔλαθεν τὸν Ἰωνάθην οὐδὲ τὸν ἀδελφὸν αὐτοῦ Σίμωνα, ἀλλὰ γὰρ μαθόντες οὗτοι καὶ παραλαβόντες τοὺς ἑταίρους ἅπαντας εἰς τὴν ἐρημίαν τὴν ἔγγιστα τῆς πόλεως τὸ τάχος ἔφυγον, καὶ παραγενόμενοι ἐπὶ τὸ ὕδωρ τὸ καλούμενον λάκκου Ἀσφὰρ αὐτόθι διῆγον. ὁ δὲ Βακχίδης αἰσθόμενος αὐτοὺς ἀπηρκότας καὶ ἐν ἐκείνῳ τῷ τόπῳ τυγχάνοντας ὥρμησεν ἐπ’ αὐτοὺς μετὰ πάσης τῆς δυνάμεως, καὶ πέραν τοῦ Ἰορδάνου στρατοπεδευσάμενος ἀνελάμβανε τὴν δύναμιν. Ἰωνάθης δὲ γνοὺς τὸν Βακχίδην ἐπ’ αὐτὸν ἥκοντα πέμπει τὸν ἀδελφὸν Ἰωάννην τὸν καὶ Γάδδειν λεγόμενον πρὸς τοὺς Ναβαταίους Ἄραβας, ἵνα παρ’ αὐτοῖς ἀποθῆται τὴν ἀποσκευὴν ἕως οὗ πολεμήσουσι πρὸς Βακχίδην· ἦσαν γὰρ φίλοι. τὸν δὲ Ἰωάννην ἀπιόντα πρὸς τοὺς Ναβαταίους ἐνεδρεύσαντες ἐκ Μηδάβας πόλεως οἱ Ἀμαραίου παῖδες αὐτόν τε συλλαμβάνουσι καὶ τοὺς σὺν αὐτῷ, καὶ διαρπάσαντες ὅσα ἐπεκομίζετο κτείνουσι τὸν Ἰωάννην καὶ τοὺς ἑταίρους αὐτοῦ πάντας. δίκην μέντοι γε τούτων ὑπέσχον τοῖς ἀδελφοῖς αὐτοῦ τὴν ἀξίαν, ἣν μετ’ οὐ πολὺ δηλώσομεν.", "st": "13.1.2"}, {"sp": "N", "t": "Ὁ δὲ Βακχίδης γνοὺς τὸν Ἰωνάθην ἐν τοῖς ἕλεσι τοῦ Ἰορδάνου κατεστρατοπεδευμένον παραφυλάξας τὴν τῶν σαββάτων ἡμέραν ἐπ’ αὐτὸν ἧκεν ὡς οὐ μαχούμενον ἐκείνῃ διὰ τὸν νόμον. ὁ δὲ παρορμήσας τοὺς ἑταίρους καὶ περὶ τῶν ψυχῶν αὐτοῖς εἶναι τὸν κίνδυνον εἰπὼν μέσοις ἀπειλημμένοις τοῦ τε ποταμοῦ καὶ τῶν πολεμίων ὡς φυγὴν οὐκ ἔχουσιν, οἱ μὲν γὰρ ἔμπροσθεν ἐπῄεσαν ὁ ποταμὸς δ’ ἦν κατόπιν αὐτῶν, εὐξάμενος δὲ καὶ τῷ θεῷ νίκην αὐτοῖς παρασχεῖν συνάπτει τοῖς πολεμίοις. ὧν πολλοὺς καταβαλὼν ἐπεὶ τολμηρῶς εἶδεν ἐπερχόμενον αὐτῷ τὸν Βακχίδην, ἐξέτεινε τὴν δεξιὰν ὡς πλήξων αὐτόν. τοῦ δὲ προϊδομένου καὶ τὴν πληγὴν ἐκκλίναντος ἀποπηδήσας μετὰ τῶν ἑταίρων εἰς τὸν ποταμὸν διενήξατο, καὶ τοῦτον διασώζονται τὸν τρόπον εἰς τὸ πέραν τοῦ Ἰορδάνου, τῶν πολεμίων οὐκέτι τὸν ποταμὸν ἀντιδιαβάντων ὑποστρέψαντος εὐθὺς τοῦ Βακχίδου εἰς τὴν ἐν Ἱεροσολύμοις ἄκραν. ἀπέβαλεν δὲ τῆς στρατιᾶς ὡς περὶ δισχιλίους. πολλὰς δὲ τῆς Ἰουδαίας καταλαβόμενος πόλεις ὁ Βακχίδης ὠχύρωσεν, καὶ τὴν Ἱεριχοῦντα καὶ Ἀμμαοῦν καὶ Βαιθωροῦν καὶ Βέθηλα καὶ Θαμναθὰ καὶ Φαραθὼ καὶ Τοχόαν καὶ Γάζαρα, καὶ πύργους ἐν ἑκάστῃ τῶν πόλεων οἰκοδομήσας καὶ τείχη περιβαλὼν αὐταῖς καρτερὰ καὶ τῷ μεγέθει διαφέροντα δύναμιν εἰς αὐτὰς κατέστησεν, ὅπως κακοῦν ἐκεῖθεν ὁρμώμενοι τοὺς Ἰουδαίους ἔχωσιν. μάλιστα δὲ τὴν ἐν Ἱεροσολύμοις ἄκραν ὠχύρωσεν. λαβὼν δὲ καὶ τοὺς τῶν πρώτων τῆς Ἰουδαίας παῖδας ὁμήρους εἰς τὴν ἄκραν αὐτοὺς ἐνέκλεισεν καὶ τοῦτον ἐφύλαττεν τὸν τρόπον.", "st": "13.1.3"}, {"sp": "N", "t": "Ὑπὸ τὸν αὐτὸν δὲ καιρὸν παραγενόμενός τις πρὸς Ἰωνάθην καὶ τὸν ἀδελφὸν αὐτοῦ Σίμωνα τοὺς Ἀμαραίου παῖδας ἀπήγγειλεν αὐτοῖς γάμον ἐπιτελοῦντας καὶ τὴν νύμφην ἄγοντας ἀπὸ Ναβαθὰ πόλεως θυγατέρα τινὸς οὖσαν τῶν ἐπιφανῶν παρὰ τοῖς Ἄραψιν, μέλλειν δὲ γίνεσθαι παραπομπὴν τῆς κόρης λαμπρὰν καὶ πολυτελῆ. οἱ δὲ περὶ τὸν Ἰωνάθην καὶ Σίμωνα καιρὸν ἐπιτηδειότατον εἰς τὴν ἐκδικίαν τἀδελφοῦ νομίσαντες αὐτοῖς παραφανῆναι, καὶ λήψεσθαι τὴν ὑπὲρ Ἰωάννου δίκην παρ’ αὐτῶν ἐπὶ πολλῆς ἐξουσίας ὑπολαβόντες ἐξώρμησαν εἰς τὰ Μήδαβα καὶ τοὺς ἐχθροὺς ἐν τῷ ὄρει λοχῶντες ἔμενον. ὡς δ’ εἶδον αὐτοὺς ἄγοντας τὴν παρθένον καὶ τὸν νυμφίον καὶ φίλων σὺν αὐτοῖς οἷον εἰκὸς ἐν γάμοις ὄχλον, ἀναπηδήσαντες ἐκ τῆς ἐνέδρας ἀπέκτειναν ἅπαντας καὶ τὸν κόσμον καὶ τὴν ἄλλην ὅση τότε εἵπετο λεία τοῖς ἀνθρώποις λαβόντες ὑπέστρεψαν. καὶ τιμωρίαν μὲν ὑπὲρ Ἰωάννου τἀδελφοῦ παρὰ τῶν υἱῶν Ἀμαραίου τοιαύτην ἀπέλαβον· αὐτοί τε γὰρ οὗτοι καὶ οἱ συνεπόμενοι τούτοις φίλοι καὶ γυναῖκες αὐτῶν καὶ τέκνα διεφθάρησαν ὄντες τετρακόσιοι.", "st": "13.1.4"}, {"sp": "N", "t": "Σίμων μὲν οὖν καὶ Ἰωνάθης εἰς τὰ ἕλη τοῦ ποταμοῦ ὑποστρέψαντες αὐτόθι κατέμενον. Βακχίδης δὲ τὴν Ἰουδαίαν ἅπασαν φρουραῖς ἀσφαλισάμενος ὑπέστρεψεν πρὸς τὸν βασιλέα. καὶ τότε μὲν ἐπ’ ἔτη δύο τὰ τῶν Ἰουδαίων ἠρέμησεν πράγματα. οἱ δὲ φυγάδες καὶ οἱ ἀσεβεῖς ὁρῶντες τὸν Ἰωνάθην καὶ τοὺς σὺν αὐτῷ μετὰ πολλῆς ἀδείας ἐνδιατρίβοντας τῇ χώρᾳ διὰ τὴν εἰρήνην πέμπουσιν πρὸς Δημήτριον τὸν βασιλέα, παρακαλοῦντες ἀποστεῖλαι Βακχίδην ἐπὶ τὴν Ἰωνάθου σύλληψιν· ἐδήλουν γὰρ αὐτὴν ἀπόνως ἐσομένην, καὶ νυκτὶ μιᾷ μὴ προσδοκῶσιν αὐτοῖς ἐπιπεσόντες ἀποκτενεῖν ἅπαντας. τοῦ δὲ βασιλέως ἐκπέμψαντος τὸν Βακχίδην, γενόμενος οὗτος ἐν τῇ Ἰουδαίᾳ πᾶσιν ἔγραψεν τοῖς φίλοις καὶ Ἰουδαίοις καὶ συμμάχοις συλλαβεῖν αὐτῷ τὸν Ἰωνάθην. σπουδαζόντων δὲ πάντων καὶ μὴ δυναμένων κρατῆσαι τοῦ Ἰωνάθου, ἐφυλάσσετο γὰρ σφόδρα τὴν ἐπιβουλὴν ᾐσθημένος, ὁ Βακχίδης ὀργισθεὶς τοῖς φυγάσιν ὡς ψευσαμένοις αὐτόν τε καὶ τὸν βασιλέα πεντήκοντα αὐτῶν τοὺς ἡγουμένους συλλαβὼν ἀπέκτεινεν. ὁ δὲ Ἰωνάθης σὺν τἀδελφῷ καὶ τοῖς ἑταίροις εἰς Βηθαλαγὰν ἀναχωρεῖ κώμην οὖσαν ἐν τῇ ἐρήμῳ φοβηθεὶς τὸν Βακχίδην, καὶ οἰκοδομήσας πύργους καὶ τείχη περιβαλόμενος αὑτὸν ἔσχεν ἀσφαλῶς πεφρουρημένον. Βακχίδης δὲ ταῦτ’ ἀκούσας τήν τε μεθ’ ἑαυτοῦ στρατιὰν ἄγων καὶ τῶν Ἰουδαίων τοὺς συμμάχους παραλαβὼν ἐπὶ τὸν Ἰωνάθην ἧκεν, καὶ προσβαλὼν αὐτοῦ τοῖς ὀχυρώμασιν ἐπὶ πολλὰς αὐτὸν ἡμέρας ἐπολιόρκει. ὁ δὲ πρὸς τὴν σπουδὴν τῆς πολιορκίας οὐκ ἐνδίδωσιν, ἀλλὰ καρτερῶς ἀντιστὰς Σίμωνα μὲν τὸν ἀδελφὸν ἐν τῇ πόλει καταλείπει τῷ Βακχίδῃ πολεμήσοντα, λάθρα δ’ αὐτὸς εἰς τὴν χώραν ἐξελθὼν καὶ συναγαγὼν χεῖρα πολλὴν παρὰ τῶν τὰ αὐτοῦ φρονούντων νυκτὸς ἐπιπίπτει τῷ τοῦ Βακχίδου στρατοπέδῳ καὶ συχνοὺς αὐτῶν διαφθείρας φανερὸς καὶ τἀδελφῷ Σίμωνι γίνεται τοῖς ἐχθροῖς ἐπιπεσών. καὶ γὰρ οὗτος αἰσθόμενος ὑπ’ αὐτοῦ κτεινομένους τοὺς πολεμίους ἐπέξεισιν αὐτοῖς, καὶ τά τε μηχανήματα τὰ πρὸς τὴν πολιορκίαν ἐνέπρησε τῶν Μακεδόνων καὶ φόνον αὐτῶν ἱκανὸν εἰργάσατο. θεασάμενος δ’ αὑτὸν ὁ Βακχίδης ὑπὸ τῶν ἐχθρῶν ἀπειλημμένον καὶ τοὺς μὲν ἔμπροσθεν αὐτῶν τοὺς δ’ ὄπισθεν προσκειμένους, εἰς ἀθυμίαν ἅμα καὶ ταραχὴν τῆς διανοίας ἐνέπεσεν τῷ παρ’ ἐλπίδας ἀποβάντι τῆς πολιορκίας συγχυθείς. τὸν μέντοι γε ὑπὲρ τούτων θυμὸν εἰς τοὺς φυγάδας, οἳ μετεπέμψαντο παρὰ τοῦ βασιλέως αὐτόν, ἀπέσκηψεν ὡς ἐξηπατηκότας, ἐβούλετο δὲ τελευτήσας τὴν πολιορκίαν, εἰ δυνατόν, εὐπρεπῶς εἰς τὴν οἰκείαν ὑποστρέψαι.", "st": "13.1.5"}, {"sp": "N", "t": "Μαθὼν δ’ αὐτοῦ τὴν διάνοιαν Ἰωνάθης πρεσβεύεται πρὸς αὐτὸν περὶ φιλίας καὶ συμμαχίας, ὅπως ἀποδῶσιν ἀλλήλοις οὓς εἰλήφασιν αἰχμαλώτους ἑκάτεροι. νομίσας δὲ ταύτην εὐπρεπεστάτην ὁ Βακχίδης τὴν ἀναχώρησιν σπένδεται πρὸς τὸν Ἰωνάθην φιλίαν, καὶ ὤμοσαν μὴ στρατεύσειν ἔτι κατ’ ἀλλήλων, καὶ τούς τε αἰχμαλώτους ἀποδοὺς καὶ τοὺς οἰκείους κομισάμενος ὑπέστρεψεν εἰς Ἀντιόχειαν πρὸς τὸν βασιλέα καὶ μετὰ ταύτην τὴν ἀναχώρησιν οὐκέτι εἰς τὴν Ἰουδαίαν ἐνέβαλεν. ὁ δὲ Ἰωνάθης ταύτης τῆς ἀδείας λαβόμενος καὶ ποιούμενος ἐν Μαχμᾶ πόλει τὴν δίαιταν αὐτόθι τοῖς ὄχλοις διεῖπε τὰ πράγματα καὶ τοὺς πονηροὺς καὶ ἀσεβεῖς κολάζων ἐκάθηρεν οὕτως ἀπὸ τούτων τὸ ἔθνος.", "st": "13.1.6"}, {"sp": "N", "t": "Ἔτει δ’ ἑξηκοστῷ καὶ ἑκατοστῷ τὸν Ἀντιόχου τοῦ Ἐπιφανοῦς υἱὸν Ἀλέξανδρον ἀναβάντα εἰς Συρίαν συνέβη καταλαβέσθαι Πτολεμαΐδα ἐκ προδοσίας τῶν ἔνδον στρατιωτῶν· ἀπεχθῶς γὰρ εἶχον πρὸς τὸν Δημήτριον διὰ τὴν ὑπερηφανίαν αὐτοῦ καὶ τὸ δυσέντευκτον. ἀποκλείσας γὰρ αὑτὸν εἰς τετραπύργιόν τι βασίλειον, ὃ κατεσκεύασεν αὐτὸς οὐκ ἄπωθεν τῆς Ἀντιοχείας, οὐδένα προσίετο, ἀλλὰ περὶ τὰ πράγματα ῥάθυμος ἦν καὶ ὀλίγωρος, ὅθεν αὐτῷ καὶ μᾶλλον τὸ παρὰ τῶν ὑποτεταγμένων μῖσος ἐξήφθη, καθὼς ἤδη καὶ ἐν ἄλλοις δεδηλώκαμεν. γενόμενον οὖν ἐν Πτολεμαΐδι τὸν Ἀλέξανδρον ἀκούσας ὁ Δημήτριος ἦγεν ἅπασαν ἀναλαβὼν ἐπ’ αὐτὸν τὴν δύναμιν. ἔπεμψεν δὲ καὶ πρὸς Ἰωνάθην πρέσβεις περὶ συμμαχίας καὶ εὐνοίας· φθάσαι γὰρ τὸν Ἀλέξανδρον διέγνω, μὴ προδιαλεχθεὶς ἐκεῖνος αὐτῷ σχῇ τὴν παρ’ αὐτοῦ βοήθειαν. τοῦτο δ’ ἐποίει φοβηθείς, μὴ μνησικακήσας ὁ Ἰωνάθης αὐτῷ τῆς ἔχθρας συνεπιθῆται. προσέταξεν οὖν αὐτῷ συναθροίζειν δύναμιν καὶ κατασκευάζειν ὅπλα καὶ τοὺς ὁμήρους, οὓς τῶν Ἰουδαίων ἐνέκλεισε Βακχίδης ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων, ἀπολαβεῖν. τοιούτων οὖν αὐτῷ τῶν παρὰ Δημητρίου προσπεσόντων ὁ Ἰωνάθης παραγενόμενος εἰς τὰ Ἱεροσόλυμα τὴν ἐπιστολὴν ἀνέγνω τοῦ βασιλέως ἀκουόντων τοῦ τε λαοῦ καὶ τῶν φρουρούντων τὴν ἀκρόπολιν. ἀναγνωσθέντων δὲ τούτων οἱ ἀσεβεῖς καὶ φυγάδες οἱ ἐκ τῆς ἀκροπόλεως λίαν ἔδεισαν ἐπιτετροφότος Ἰωνάθῃ τοῦ βασιλέως στρατιὰν συλλέγειν καὶ τοὺς ὁμήρους ἀπολαβεῖν. ὁ δὲ τοῖς γονεῦσιν ἑκάστῳ τὸν ἴδιον ἀπέδωκεν. καὶ οὕτως μὲν Ἰωνάθης ἐν Ἱεροσολύμοις τὴν μονὴν ἐποιεῖτο καινίζων τὰ κατὰ τὴν πόλιν καὶ πρὸς τὴν αὐτοῦ βούλησιν κατασκευάζων ἕκαστον. ἐκέλευσε γὰρ οἰκοδομηθῆναι καὶ τὰ τείχη τῆς πόλεως ἐκ λίθων τετραγώνων, ὡς ἂν ᾖ καὶ πρὸς τοὺς πολέμους ἀσφαλέστερα. ταῦτα δ’ ὁρῶντες οἱ τῶν φρουρίων τῶν ἐν τῇ Ἰουδαίᾳ φύλακες ἐκλιπόντες αὐτὰ πάντες ἔφυγον εἰς Ἀντιόχειαν πάρεξ τῶν ἐν Βαιθσούρᾳ πόλει καὶ τῶν ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων· οὗτοι γὰρ ἡ πλείων μοῖρα τῶν ἀσεβῶν καὶ πεφευγότων Ἰουδαίων ἦσαν καὶ διὰ τοῦτο τὰς φρουρὰς οὐκ ἐγκατέλιπον.", "st": "13.2.1"}, {"sp": "N", "t": "Γνοὺς δὲ ὁ Ἀλέξανδρος τάς τε ὑποσχέσεις, ἃς ἐποιήσατο Δημήτριος πρὸς Ἰωνάθην, καὶ τὴν ἀνδρείαν αὐτοῦ καὶ ὁπόσα διέθηκεν πολεμῶν τοὺς Μακεδόνας καὶ πάλιν οἷα πεπονθὼς αὐτὸς εἴη ὑπὸ Δημητρίου καὶ Βακχίδου τοῦ Δημητρίου στρατηγοῦ, σύμμαχον οὐκ ἂν εὑρεῖν Ἰωνάθου ἀμείνω πρὸς τοὺς φίλους ἔλεγεν ἐν τῷ παρόντι καιρῷ, ὃς καὶ πρὸς τοὺς πολέμους ἐστὶν ἀνδρεῖος, καὶ μῖσος οἰκεῖον ἔχει πρὸς Δημήτριον πολλὰ πεπονθὼς ὑπ’ αὐτοῦ κακὰ καὶ πεποιηκώς. εἰ τοιγαροῦν δοκεῖ φίλον ποιεῖσθαι αὐτὸν κατὰ Δημητρίου, νῦν ἐστιν οὐκ ἄλλοτε χρησιμώτερον παρακαλεῖν αὐτὸν ἐπὶ τὴν συμμαχίαν. δόξαν οὖν αὐτῷ καὶ τοῖς φίλοις πέμπειν πρὸς τὸν Ἰωνάθην γράφει τοιαύτην ἐπιστολήν· βασιλεὺς Ἀλέξανδρος Ἰωνάθῃ τῷ ἀδελφῷ χαίρειν. τὴν μὲν ἀνδρείαν σου καὶ πίστιν ἀκηκόαμεν πάλαι καὶ διὰ τοῦτο πεπόμφαμεν πρὸς σὲ περὶ φιλίας καὶ συμμαχίας. χειροτονοῦμεν δέ σε σήμερον ἀρχιερέα τῶν Ἰουδαίων καὶ φίλον ἐμὸν καλεῖσθαι. ἀπέσταλκά σοι καὶ δωρεὰς στολὴν πορφυρᾶν καὶ στέφανον χρύσεον καὶ παρακαλῶ τιμηθέντα ὑφ’ ἡμῶν ὅμοιον γίνεσθαι περὶ ἡμᾶς.", "st": "13.2.2"}, {"sp": "N", "t": "Δεξάμενος δὲ ὁ Ἰωνάθης τὴν ἐπιστολὴν ἐνδύεται μὲν τὴν ἱερατικὴν στολὴν τῆς σκηνοπηγίας ἐνστάσης μετὰ ἔτη τέσσαρα ἢ τὸν ἀδελφὸν αὐτοῦ Ἰούδαν ἀποθανεῖν· καὶ γὰρ οὐδὲ κατὰ τοῦτον τὸν χρόνον ἀρχιερεύς τις ἐγεγόνει· συνάγει δὲ δύναμιν πολλὴν καὶ πλῆθος ὅπλων ἐχάλκευεν. Δημήτριον δὲ σφόδρα ταῦτ’ ἐλύπησεν μαθόντα καὶ τῆς βραδυτῆτος ἑαυτὸν ἐποίησεν αἰτιᾶσθαι, ὅτι μὴ προλαβὼν Ἀλέξανδρον αὐτὸς ἐφιλανθρωπεύσατο τὸν Ἰωνάθην, ἀλλ’ ἐκείνῳ καταλίποι καιρὸν εἰς τοῦτο. γράφει τοίνυν καὶ αὐτὸς ἐπιστολὴν τῷ Ἰωνάθῃ καὶ τῷ δήμῳ δηλοῦσαν τάδε· βασιλεὺς Δημήτριος Ἰωνάθῃ καὶ τῷ ἔθνει τῶν Ἰουδαίων χαίρειν. ἐπειδὴ διετηρήσατε τὴν πρὸς ἡμᾶς φιλίαν καὶ πειράσασιν ὑμᾶς τοῖς ἐμοῖς ἐχθροῖς οὐ προσέθεσθε, καὶ ταύτην μὲν ὑμῶν ἐπαινῶ τὴν πίστιν καὶ παρακαλῶ δὲ τοῖς αὐτοῖς ἐμμένειν ἀποληψομένους ἀμοιβὰς παρ’ ἡμῶν καὶ χάριτας. τοὺς γὰρ πλείστους ὑμῶν ἀνήσω τῶν φόρων καὶ τῶν συντάξεων, ἃς ἐτελεῖτε τοῖς πρὸ ἐμοῦ βασιλεῦσιν καὶ ἐμοί, νῦν τε ὑμῖν ἀφίημι τοὺς φόρους, οὓς ἀεὶ παρέχετε. πρὸς τούτοις καὶ τὴν τιμὴν ὑμῖν χαρίζομαι τῶν ἁλῶν καὶ τῶν στεφάνων, οὓς προσεφέρετε ἡμῖν, καὶ ἀντὶ τῶν τρίτων τοῦ καρποῦ καὶ τοῦ ἡμίσους τοῦ ξυλίνου καρποῦ τὸ γινόμενον ἐμοὶ μέρος ὑμῖν ἀφίημι ἀπὸ τῆς σήμερον ἡμέρας. καὶ ὑπὲρ κεφαλῆς ἑκάστης ὃ ἔδει μοι δίδοσθαι τῶν ἐν τῇ Ἰουδαίᾳ κατοικούντων καὶ τῶν τριῶν τοπαρχιῶν τῶν τῇ Ἰουδαίᾳ προσκειμένων Σαμαρείας καὶ Γαλιλαίας καὶ Περαίας, τούτους παραχωρῶ ὑμῖν ἀπὸ τοῦ νῦν εἰς τὸν ἅπαντα χρόνον. καὶ τὴν Ἱεροσολυμιτῶν πόλιν ἱερὰν καὶ ἄσυλον εἶναι βούλομαι καὶ ἐλευθέραν ἕως τῶν ὅρων αὐτῆς ἀπὸ τῆς δεκάτης καὶ τῶν τελῶν. τὴν δὲ ἄκραν ἐπιτρέπω τῷ ἀρχιερεῖ ὑμῶν Ἰωνάθῃ, οὓς δ’ ἂν αὐτὸς δοκιμάσῃ πιστοὺς καὶ φίλους τούτους ἐν αὐτῇ φρουροὺς καταστῆσαι, ἵνα φυλάσσωσιν ἡμῖν αὐτήν. καὶ Ἰουδαίων δὲ τοὺς αἰχμαλωτισθέντας καὶ δουλεύοντας ἐν τῇ ἡμετέρᾳ ἀφίημι ἐλευθέρους. κελεύω δὲ μηδὲ ἀγγαρεύεσθαι τὰ Ἰουδαίων ὑποζύγια· τὰ δὲ σάββατα καὶ ἑορτὴν ἅπασαν καὶ τρεῖς καὶ πρὸ τῆς ἑορτῆς ἡμέρας ἔστωσαν ἀτελεῖς. τὸν αὐτὸν τρόπον καὶ τοὺς ἐν τῇ ἐμῇ κατοικοῦντας Ἰουδαίους ἐλευθέρους καὶ ἀνεπηρεάστους ἀφίημι, καὶ τοῖς στρατεύεσθαι μετ’ ἐμοῦ βουλομένοις ἐπιτρέπω καὶ μέχρις τρισμυρίων ἐξέστω τοῦτο· τῶν δ’ αὐτῶν, ὅποι ἂν ἀπίωσι, τεύξονται ὧν καὶ τὸ ἐμὸν στράτευμα μεταλαμβάνει. καταστήσω δ’ αὐτῶν οὓς μὲν εἰς τὰ φρούρια, τινὰς δὲ περὶ τὴν φυλακὴν τοὐμοῦ σώματος, καὶ ἡγεμόνας δὲ ποιήσω τῶν περὶ τὴν ἐμὴν αὐλήν. ἐπιτρέπω δὲ καὶ τοῖς πατρῴοις χρῆσθαι νόμοις καὶ τούτους φυλάττειν, καὶ τοῖς τρισὶν τοῖς προσκειμένοις τῇ Ἰουδαίᾳ νομοῖς ὑποτάσσεσθαι βούλομαι, καὶ τῷ ἀρχιερεῖ δὲ ἐπιμελὲς εἶναι, ἵνα μηδὲ εἷς Ἰουδαῖος ἄλλο ἔχῃ ἱερὸν προσκυνεῖν ἢ μόνον τὸ ἐν Ἱεροσολύμοις. δίδωμι δ’ ἐκ τῶν ἐμῶν καὶ εἰς τὴν δαπάνην τῶν θυσιῶν κατ’ ἔτος μυριάδας πεντεκαίδεκα, τὰ δὲ περισσεύοντα τῶν χρημάτων ὑμέτερα εἶναι βούλομαι· τὰς δὲ μυρίας δραχμάς, ἃς ἐλάμβανον ἐκ τοῦ ἱεροῦ οἱ βασιλεῖς, ὑμῖν ἀφίημι διὰ τὸ προσήκειν αὐτὰς τοῖς ἱερεῦσιν τοῖς λειτουργοῦσιν τῷ ἱερῷ. καὶ ὅσοι δ’ ἂν φύγωσιν εἰς τὸ ἱερὸν τὸ ἐν Ἱεροσολύμοις καὶ εἰς τὰ ἀπ’ αὐτοῦ χρηματίζοντα ἢ βασιλικὰ ὀφείλοντες χρήματα ἢ δι’ ἄλλην αἰτίαν, ἀπολελύσθωσαν οὗτοι καὶ τὰ ὑπάρχοντα αὐτοῖς σῶα ἔστω. ἐπιτρέπω δὲ καὶ ἀνακαινίζειν τὸ ἱερὸν καὶ οἰκοδομεῖν τῆς εἰς ταῦτα δαπάνης ἐκ τῶν ἐμῶν γινομένης, καὶ τὰ τείχη δὲ συγχωρῶ τὰ τῆς πόλεως οἰκοδομεῖσθαι καὶ πύργους ὑψηλοὺς ἐγείρειν καὶ ταῦτα ἐκ τῶν ἐμῶν ἀνιστᾶν πάντα. εἰ δέ τι καὶ φρούριόν ἐστιν, ὃ συμφέρει τῇ χώρᾳ τῇ Ἰουδαίων ὀχυρὸν εἶναι, καὶ τοῦτ’ ἐκ τῶν ἐμῶν κατασκευασθήτω.", "st": "13.2.3"}, {"sp": "N", "t": "Ταῦτα μὲν ὑπισχνούμενος καὶ χαριζόμενος ἔγραψεν τοῖς Ἰουδαίοις Δημήτριος. Ἀλέξανδρος δὲ ὁ βασιλεὺς δύναμιν μεγάλην συναγαγὼν μισθοφόρων καὶ τῶν προσθεμένων ἐκ τῆς Συρίας αὐτῷ στρατιωτῶν ἐπὶ τὸν Δημήτριον ἐστράτευσεν. καὶ μάχης γενομένης τὸ μὲν εὐώνυμον κέρας τοῦ Δημητρίου τρέπεται τοὺς ἐναντίους εἰς φυγὴν καὶ ἐδίωξεν ἄχρι πολλοῦ κτείνει τε συχνοὺς αὐτῶν καὶ διαρπάζει τὸ στρατόπεδον, τὸ δὲ δεξιόν, οὗ συνέβαινεν εἶναι τὸν Δημήτριον, ἡττᾶται. καὶ οἱ μὲν ἄλλοι πάντες ἔφυγον, Δημήτριος δὲ γενναίως μαχόμενος οὐκ ὀλίγους μὲν ἀναιρεῖ τῶν πολεμίων, διώκων δὲ τοὺς ἄλλους ἐλαύνει τὸν ἵππον εἰς τέλμα βαθὺ καὶ δυσεκπόρευτον, ἔνθα συνέβη πεσόντος αὐτῷ τοῦ ἵππου μὴ δυνάμενον διαφυγεῖν ἀναιρεθῆναι. τὸ γὰρ συμβεβηκὸς περὶ αὐτὸν ἰδόντες οἱ πολέμιοι ἀνέστρεψαν καὶ κυκλωσάμενοι τὸν Δημήτριον πάντες ἐπ’ αὐτὸν ἠκόντιζον. ὁ δὲ πεζὸς ὢν γενναίως ἀπεμάχετο, καὶ τελευταῖον τραύματα λαβὼν πολλὰ καὶ μηκέτ’ ἀντέχειν δυνάμενος κατέπεσεν. καὶ τέλος μὲν τοιοῦτον τὸν Δημήτριον κατέλαβεν ἔτη βασιλεύσαντα ἕνδεκα, ὡς καὶ ἐν ἄλλοις δεδηλώκαμεν.", "st": "13.2.4"}, {"sp": "N", "t": "Ὁ δὲ Ὀνίου τοῦ ἀρχιερέως υἱὸς ὁμώνυμος δὲ ὢν τῷ πατρί, ὃς ἐν Ἀλεξανδρείᾳ φυγὼν πρὸς τὸν βασιλέα Πτολεμαῖον τὸν ἐπικαλούμενον Φιλομήτορα διῆγεν, ὡς καὶ πρότερον εἰρήκαμεν, ἰδὼν τὴν Ἰουδαίαν κακουμένην ὑπὸ τῶν Μακεδόνων καὶ τῶν βασιλέων αὐτῶν, βουλόμενος αὑτῷ δόξαν καὶ μνήμην αἰώνιον κατασκευάσαι, διέγνω πέμψας πρὸς Πτολεμαῖον τὸν βασιλέα καὶ τὴν βασίλισσαν Κλεοπάτραν αἰτήσασθαι παρ’ αὐτῶν ἐξουσίαν, ὅπως οἰκοδομήσειεν ναὸν ἐν Αἰγύπτῳ παραπλήσιον τῷ ἐν Ἱεροσολύμοις καὶ Λευίτας καὶ ἱερεῖς ἐκ τοῦ ἰδίου γένους καταστήσῃ. τοῦτο δ’ ἐβούλετο θαρρῶν μάλιστα τῷ προφήτῃ Ἡσαΐᾳ, ὃς ἔμπροσθεν ἔτεσιν ἑξακοσίοις πλέον γεγονὼς προεῖπεν, ὡς δεῖ πάντως ἐν Αἰγύπτῳ οἰκοδομηθῆναι ναὸν τῷ μεγίστῳ θεῷ ὑπ’ ἀνδρὸς Ἰουδαίου. διὰ ταῦτα οὖν ἐπηρμένος Ὀνίας γράφει Πτολεμαίῳ καὶ Κλεοπάτρᾳ τοιαύτην ἐπιστολήν· πολλὰς καὶ μεγάλας ὑμῖν χρείας τετελεκὼς ἐν τοῖς κατὰ πόλεμον ἔργοις μετὰ τῆς τοῦ θεοῦ βοηθείας, καὶ γενόμενος ἔν τε τῇ κοίλῃ Συρίᾳ καὶ Φοινίκῃ, καὶ εἰς Λεόντων δὲ πόλιν τοῦ Ἡλιοπολίτου σὺν τοῖς Ἰουδαίοις καὶ εἰς ἄλλους τόπους ἀφικόμενος τοῦ ἔθνους, καὶ πλείστους εὑρὼν παρὰ τὸ καθῆκον ἔχοντας ἱερὰ καὶ διὰ τοῦτο δύσνους ἀλλήλοις, ὃ καὶ Αἰγυπτίοις συμβέβηκεν διὰ τὸ πλῆθος τῶν ἱερῶν καὶ τὸ περὶ τὰς θρησκείας οὐχ ὁμόδοξον, ἐπιτηδειότατον εὑρὼν τόπον ἐν τῷ προσαγορευομένῳ τῆς ἀγρίας Βουβάστεως ὀχυρώματι βρύοντα ποικίλης ὕλης καὶ τῶν ἱερῶν ζῴων μεστόν, δέομαι συγχωρῆσαί μοι τὸ ἀδέσποτον ἀνακαθάραντι ἱερὸν καὶ συμπεπτωκὸς οἰκοδομῆσαι ναὸν τῷ μεγίστῳ θεῷ καθ’ ὁμοίωσιν τοῦ ἐν Ἱεροσολύμοις αὐτοῖς μέτροις ὑπὲρ σοῦ καὶ τῆς σῆς γυναικὸς καὶ τῶν τέκνων, ἵν’ ἔχωσιν οἱ τὴν Αἴγυπτον κατοικοῦντες Ἰουδαῖοι εἰς αὐτὸ συνιόντες κατὰ τὴν πρὸς ἀλλήλους ὁμόνοιαν ταῖς σαῖς ἐξυπηρετεῖν χρείαις· καὶ γὰρ Ἡσαΐας ὁ προφήτης τοῦτο προεῖπεν· ἔσται θυσιαστήριον ἐν Αἰγύπτῳ κυρίῳ τῷ θεῷ· καὶ πολλὰ δὲ προεφήτευσεν ἄλλα τοιαῦτα διὰ τὸν τόπον.", "st": "13.3.1"}, {"sp": "N", "t": "Καὶ ταῦτα μὲν ὁ Ὀνίας τῷ βασιλεῖ Πτολεμαίῳ γράφει. κατανοήσειε δ’ ἄν τις αὐτοῦ τὴν εὐσέβειαν καὶ Κλεοπάτρας τῆς ἀδελφῆς αὐτοῦ καὶ γυναικὸς ἐξ ἧς ἀντέγραψαν ἐπιστολῆς· τὴν γὰρ ἁμαρτίαν καὶ τὴν τοῦ νόμου παράβασιν εἰς τὴν Ὀνίου κεφαλὴν ἀνέθεσαν· ἀντέγραψαν γὰρ οὕτως· βασιλεὺς Πτολεμαῖος καὶ βασίλισσα Κλεοπάτρα Ὀνίᾳ χαίρειν. ἀνέγνωμέν σου τὴν ἐπιστολὴν ἀξιοῦντος ἐπιτραπῆναί σοι τὸ ἐν Λεόντων πόλει τοῦ Ἡλιοπολίτου ἱερὸν συμπεπτωκὸς ἀνακαθᾶραι, προσαγορευόμενον δὲ τῆς ἀγρίας Βουβάστεως. διὸ καὶ θαυμάζομεν, εἰ ἔσται τῷ θεῷ κεχαρισμένον τὸ καθιδρυσόμενον ἱερὸν ἐν ἀσελγεῖ τόπῳ καὶ πλήρει ζῴων ἱερῶν. ἐπεὶ δὲ σὺ φῂς Ἡσαΐαν τὸν προφήτην ἐκ πολλοῦ χρόνου τοῦτο προειρηκέναι, συγχωροῦμέν σοι, εἰ μέλλει τοῦτ’ ἔσεσθαι κατὰ τὸν νόμον· ὥστε μηδὲν ἡμᾶς δοκεῖν εἰς τὸν θεὸν ἐξημαρτηκέναι.", "st": "13.3.2"}, {"sp": "N", "t": "Λαβὼν οὖν τὸν τόπον ὁ Ὀνίας κατεσκεύασεν ἱερὸν καὶ βωμὸν τῷ θεῷ ὅμοιον τῷ ἐν Ἱεροσολύμοις, μικρότερον δὲ καὶ πενιχρότερον. τὰ δὲ μέτρα αὐτοῦ καὶ τὰ σκεύη νῦν οὐκ ἔδοξέ μοι δηλοῦν· ἐν γὰρ τῇ ἑβδόμῃ μου βίβλῳ τῶν Ἰουδαϊκῶν ἀναγέγραπται. εὗρεν δὲ Ὀνίας καὶ Ἰουδαίους τινὰς ὁμοίους αὐτῷ ἱερεῖς καὶ Λευίτας τοὺς ἐκεῖ θρησκεύσοντας. ἀλλὰ περὶ μὲν τοῦ ἱεροῦ τούτου ἀρκούντως ἡμῖν δεδήλωται.", "st": "13.3.3"}, {"sp": "N", "t": "Τοὺς δ’ ἐν Ἀλεξανδρείᾳ Ἰουδαίους καὶ Σαμαρεῖς, οἳ τὸ ἐν Γαριζεὶν προσεκύνουν ἱερόν, κατὰ τοὺς Ἀλεξάνδρου χρόνους συνέβη στασιάσαι πρὸς ἀλλήλους, καὶ περὶ τῶν ἱερῶν ἐπ’ αὐτοῦ Πτολεμαίου διεκρίνοντο, τῶν μὲν Ἰουδαίων λεγόντων κατὰ τοὺς Μωυσέος νόμους ᾠκοδομῆσθαι τὸ ἐν Ἱεροσολύμοις, τῶν δὲ Σαμαρέων τὸ ἐν Γαριζείν. παρεκάλεσάν τε σὺν τοῖς φίλοις καθίσαντα τὸν βασιλέα τοὺς περὶ τούτων ἀκοῦσαι λόγους καὶ τοὺς ἡττηθέντας θανάτῳ ζημιῶσαι. τὸν μὲν οὖν ὑπὲρ τῶν Σαμαρέων λόγον Σαββαῖος ἐποιήσατο καὶ Θεοδόσιος, τοὺς δ’ ὑπὲρ τῶν Ἱεροσολυμιτῶν καὶ Ἰουδαίων Ἀνδρόνικος ὁ Μεσαλάμου. ὤμοσαν δὲ τὸν θεὸν καὶ τὸν βασιλέα ἦ μὴν ποιήσεσθαι τὰς ἀποδείξεις κατὰ τὸν νόμον, παρεκάλεσάν τε τὸν Πτολεμαῖον, ὅπως ὃν ἂν λάβῃ παραβαίνοντα τοὺς ὅρκους ἀποκτείνῃ. ὁ μὲν οὖν βασιλεὺς πολλοὺς τῶν φίλων εἰς συμβουλίαν παραλαβὼν ἐκάθισεν ἀκουσόμενος τῶν λεγόντων. οἱ δ’ ἐν τῇ Ἀλεξανδρείᾳ τυγχάνοντες Ἰουδαῖοι σφόδρα ἠγωνίων περὶ τῶν ἀνδρῶν, οἷς ἀγανακτεῖν περὶ τοῦ ἐν τοῖς Ἱεροσολύμοις συνέβαινεν ἱεροῦ· χαλεπῶς γὰρ ἔφερον, εἰ τοῦτό τινες καταλύσουσιν οὕτως ἀρχαῖον καὶ διασημότατον τῶν κατὰ τὴν οἰκουμένην ὑπάρχον. τοῦ δὲ Σαββαίου καὶ Θεοδοσίου συγχωρησάντων τῷ Ἀνδρονίκῳ πρώτῳ ποιήσασθαι τοὺς λόγους, ἤρξατο τῶν ἀποδείξεων ἐκ τοῦ νόμου καὶ τῶν διαδοχῶν τῶν ἀρχιερέων, ὡς ἕκαστος παρὰ πατρὸς τὴν τιμὴν ἐκδεξάμενος ἦρξε τοῦ ναοῦ, καὶ ὅτι πάντες οἱ τῆς Ἀσίας βασιλεῖς τὸ ἱερὸν ἐτίμησαν ἀναθήμασιν καὶ λαμπροτάταις δωρεαῖς, τοῦ δ’ ἐν Γαριζεὶν ὡς οὐδὲ ὄντος οὐδεὶς λόγον οὐδ’ ἐπιστροφὴν ἐποιήσατο. ταῦτα λέγων Ἀνδρόνικος καὶ πολλὰ τούτοις ὅμοια πείθει τὸν βασιλέα κρῖναι μὲν κατὰ τοὺς Μωυσέος νόμους οἰκοδομηθῆναι τὸ ἐν Ἱεροσολύμοις ἱερόν, ἀποκτεῖναι δὲ τοὺς περὶ τὸν Σαββαῖον καὶ Θεοδόσιον. καὶ τὰ μὲν γενόμενα τοῖς ἐν Ἀλεξανδρείᾳ Ἰουδαίοις κατὰ Πτολεμαῖον τὸν Φιλομήτορα ταῦτα ἦν.", "st": "13.3.4"}, {"sp": "N", "t": "Δημητρίου δ’ ἀποθανόντος ἐν τῇ μάχῃ, καθὼς ἐπάνω δεδηλώκαμεν, Ἀλέξανδρος τὴν τῆς Συρίας παραλαβὼν βασιλείαν γράφει τῷ Φιλομήτορι Πτολεμαίῳ μνηστευόμενος αὐτοῦ πρὸς γάμον τὴν θυγατέρα, δίκαιον εἶναι λέγων τῷ τὴν πατρῴαν ἀρχὴν κομισαμένῳ καὶ διὰ τὴν τοῦ θεοῦ πρόνοιαν εἰς αὐτὴν προαχθέντι καὶ κρατήσαντι Δημητρίου καὶ μηδὲ τἆλλα ἐσομένῳ τῆς πρὸς αὐτὸν οἰκειότητος ἀναξίῳ συνάψαι συγγένειαν. Πτολεμαῖος δὲ προσδεξάμενος ἡδέως τὴν μνηστείαν ἀντιγράφει χαίρειν τε λέγων ἐπὶ τῷ τὴν ἀρχὴν αὐτῷ πατρῴαν οὖσαν ἀπειληφέναι, καὶ τὴν θυγατέρα δώσειν ὑπισχνεῖται, ἀπαντᾶν δ’ αὐτὸν εἰς Πτολεμαΐδα τὴν θυγατέρα μέλλοντι ἄγειν ἐκέλευσεν· αὐτὸς γὰρ αὐτὴν μέχρι ταύτης παραπέμψειν ἀπ’ Αἰγύπτου κἀκεῖ συνοικίσειν αὐτῷ τὴν παῖδα. καὶ Πτολεμαῖος μὲν ταῦτα γράψας παραγίνεται μετὰ σπουδῆς εἰς Πτολεμαΐδα καὶ Κλεοπάτραν ἄγων τὴν θυγατέρα. εὑρὼν δ’ ἐκεῖ τὸν Ἀλέξανδρον καθὼς ἐπέστειλεν προαπηντηκότα δίδωσιν αὐτῷ τὴν παῖδα καὶ φερνὴν ἄργυρόν τε καὶ χρυσὸν ὅσον εἰκὸς ἦν δοῦναι βασιλέα.", "st": "13.4.1"}, {"sp": "N", "t": "Τῶν δὲ γάμων ἐπιτελουμένων Ἀλέξανδρος Ἰωνάθῃ τῷ ἀρχιερεῖ γράψας ἐκέλευσεν αὐτὸν ἥκειν εἰς Πτολεμαΐδα. παραγενόμενος δὲ πρὸς τοὺς βασιλέας καὶ δωρησάμενος αὐτοὺς λαμπρᾶς τῆς παρ’ ἀμφοτέρων ἀπέλαυσε τιμῆς. Ἀλέξανδρος δ’ αὐτὸν ἠνάγκασεν καὶ ἀποδυσάμενον τὴν οἰκείαν ἐσθῆτα λαβεῖν πορφύραν, καὶ συγκαθεσθῆναι ποιήσας αὐτὸν ἐπὶ τοῦ βήματος προσέταξεν τοὺς ἡγεμόνας εἰς μέσην μετ’ αὐτοῦ προελθόντας τὴν πόλιν κηρῦξαι, μηδενὶ κατ’ αὐτοῦ λέγειν ἐφεῖσθαι μηδὲ παρέχειν αὐτῷ πράγματα. τοῦτο δὲ ποιησάντων τῶν ἡγεμόνων ὁρῶντες τὴν παρὰ τοῦ βασιλέως κεκηρυγμένην Ἰωνάθῃ τιμὴν οἱ κατηγορεῖν παρεσκευασμένοι καὶ πρὸς αὐτὸν ἀπεχθῶς ἔχοντες ἀπέδρασαν, μὴ καὶ προσλάβωσίν τι κακὸν δεδιότες. τοσαύτῃ δὲ σπουδῇ περὶ τὸν Ἰωνάθην ὁ βασιλεὺς Ἀλέξανδρος ἐχρῆτο, ὥστ’ αὐτὸν καὶ πρῶτον ἀναγράψαι τῶν φίλων.", "st": "13.4.2"}, {"sp": "N", "t": "Ἔτει δὲ πέμπτῳ καὶ ἑξηκοστῷ πρὸς τοῖς ἑκατὸν Δημήτριος ὁ Δημητρίου μετὰ πολλῶν μισθοφόρων, οὓς παρέσχεν αὐτῷ Λασθένης ὁ Κρής, ἄρας ἀπὸ τῆς Κρήτης κατέπλευσεν εἰς Κιλικίαν. τοῦτο δὲ Ἀλέξανδρον ἀκούσαντα εἰς ἀγωνίαν καὶ ταραχὴν ἐνέβαλεν καὶ παραχρῆμα ἐκ τῆς Φοινίκης εἰς Ἀντιόχειαν ἔσπευσεν, ἵνα τὰ ἐκεῖ πρὶν ἢ Δημήτριον ἐλθεῖν ἀσφαλῶς θῆται. κατέλιπεν δὲ τῆς κοίλης Συρίας Ἀπολλώνιον τὸν Τάον ἡγεμόνα, ὃς μετὰ πολλῆς δυνάμεως εἰς Ἰάμνειαν ἐλθὼν ἔπεμψε πρὸς Ἰωνάθην τὸν ἀρχιερέα, λέγων ἄδικον εἶναι μόνον αὐτὸν ἐπ’ ἀδείας ζῆν καὶ μετὰ ἐξουσίας οὐχ ὑποτασσόμενον τῷ βασιλεῖ· τοῦτο δ’ αὐτῷ παρὰ πάντων ὄνειδος φέρειν, ὅτι μὴ ὑποτάξειεν αὐτὸν τῷ βασιλεῖ. μὴ τοίνυν σαυτὸν ἐν τοῖς ὄρεσιν καθήμενος ἐξαπάτα νομίζων ἰσχὺν ἔχειν, ἀλλ’ εἰ θαρρεῖς τῇ σαυτοῦ δυνάμει καταβὰς εἰς τὸ πεδίον τῇ ἡμετέρᾳ στρατιᾷ συγκρίθητι, καὶ τὸ τέλος τῆς νίκης ἐπιδείξει τὸν ἀνδρειότατον. ἴσθι μέντοι γε τοὺς ἀρίστους ἐξ ἑκάστης πόλεως ἐμοὶ συστρατεύεσθαι· καὶ γὰρ δὴ τοὺς σοὺς προγόνους οἱ ἀεὶ νικῶντές εἰσιν οὗτοι. ποιήσῃ δὲ τὸν πρὸς ἡμᾶς ἀγῶνα ἐν τοιαύτῃ γῇ, ἐν ᾗ λίθοις οὐκ ἔστιν ἀλλ’ ὅπλοις ἀμύνασθαι οὐδὲ τόπος εἰς ὃν ἡττώμενος φεύξῃ.", "st": "13.4.3"}, {"sp": "N", "t": "Παροξυνθεὶς δ’ ἐπὶ τούτοις ὁ Ἰωνάθης μυρίους ἐπιλεξάμενος στρατιώτας ὥρμησεν ἐξ Ἱεροσολύμων μετὰ καὶ Σίμωνος τἀδελφοῦ, καὶ γενόμενος ἐν Ἰόππῃ στρατοπεδεύεται τῆς πόλεως ἔξω τῶν Ἰοππηνῶν ἀποκλεισάντων αὐτῷ τὰς πύλας· φρουρὰν γὰρ ἔνδον εἶχον ὑπὸ Ἀπολλωνίου κατασταθεῖσαν. τοῦ δὲ Ἰωνάθου πρὸς πολιορκίαν αὐτῶν παρασκευαζομένου, φοβηθέντες μὴ τὴν πόλιν αὐτῶν ἐξέλῃ κατὰ κράτος ἀνοίγουσιν αὐτῷ τὰς πύλας. ὁ δὲ Ἀπολλώνιος ἀκούσας τὴν Ἰόππην κατειλημμένην ὑπὸ τοῦ Ἰωνάθου τρισχιλίους ἱππεῖς παραλαβὼν καὶ πεζοὺς ὀκτακισχιλίους εἰς Ἄζωτον ἦλθεν κἀκεῖθεν ἄρας ἠρέμα καὶ βάδην ἐποιεῖτο τὴν πορείαν, ἐλθὼν δ’ εἰς τὴν Ἰόππην ἀναχωρῶν ἕλκει τὸν Ἰωνάθην εἰς τὸ πεδίον τῇ ἵππῳ καταφρονῶν καὶ τὰς τῆς νίκης ἐλπίδας ἔχων ἐν αὐτῇ. προελθὼν δ’ Ἰωνάθης ἐδίωκεν εἰς Ἄζωτον τὸν Ἀπολλώνιον. ὁ δ’, ὡς ἐν τῷ πεδίῳ συνέβη γενέσθαι τὸν πολέμιον, ὑποστρέψας εἰς μάχην αὐτῷ συνέβαλεν. τοῦ δ’ Ἀπολλωνίου χιλίους ἱππεῖς καθίσαντος εἰς ἐνέδραν ἔν τινι χειμάρρῳ, ὡς ἂν κατόπιν ἐπιφανεῖεν τοῖς πολεμίοις, αἰσθόμενος ὁ Ἰωνάθης οὐ κατεπλάγη· τάξας δὲ τὴν στρατιὰν ἐν πλινθίῳ κατ’ ἀμφότερα τοὺς πολεμίους ἀμύνασθαι παρεσκευάσατο, καὶ κατὰ πρόσωπον καὶ τοῖς ὄπισθεν ἐπελευσομένοις αὑτὸν ἀντιτάξας. τῆς δὲ μάχης ἕως ἑσπέρας προβαινούσης, δοὺς Σίμωνι τἀδελφῷ μέρος τῆς δυνάμεως τοῦτον μὲν ἐκέλευσε συμβαλεῖν τῇ φάλαγγι τῶν ἐχθρῶν, αὐτὸς δὲ τοὺς σὺν αὐτῷ προσέταξεν φραξαμένους τοῖς ὅπλοις ἀποδέχεσθαι τὰ βέλη τὰ παρὰ τῶν ἱππέων. καὶ οἱ μὲν ἐποίησαν τὸ κελευσθέν, οἱ δὲ τῶν πολεμίων ἱππεῖς ἐπ’ αὐτοὺς ἀφέντες τὰ βέλη μέχρι καὶ ἐξεκενώθησαν οὐδὲν αὐτοὺς ἔβλαπτον· οὐ γὰρ διικνεῖτο τῶν σωμάτων τὰ βαλλόμενα, συμπεφραγμένοις δὲ ταῖς ἀσπίσιν συνηνωμέναις ὑπὸ πυκνότητος ἐπαφιέμενα ῥᾳδίως ἐκρατεῖτο καὶ ἄπρακτα ἐφέρετο. ὡς δὲ παρείθησαν ἀπὸ πρωῒ μέχρι δείλης ὀψίας ἀκοντίζοντες εἰς αὐτοὺς οἱ πολέμιοι, νοήσας Σίμων κεκμηκότας αὐτοὺς συμβάλλει τῇ φάλαγγι, καὶ προθυμίᾳ χρησαμένων πολλῇ τῶν στρατιωτῶν αὐτοῦ τρέπει τοὺς ἐχθροὺς εἰς φυγήν. θεασάμενοι δὲ τοὺς πεζοὺς φεύγοντας οἱ ἱππεῖς οὐδ’ αὐτοὶ μένουσιν, ἀλλὰ πάρετοι μὲν ὄντες αὐτοὶ διὰ τὸ μέχρι δείλης μάχεσθαι, τῆς δὲ παρὰ τῶν πεζῶν ἐλπίδος αὐτοῖς ἀπολωλυίας, ἀκόσμως καὶ συγκεχυμένως ἔφευγον, ὡς διασχισθέντας αὐτοὺς διὰ παντὸς σκορπισθῆναι τοῦ πεδίου. διώκων δ’ αὐτοὺς Ἰωνάθης μέχρι τῆς Ἀζώτου καὶ πολλοὺς ἀναιρῶν ἀπογνόντας τῆς σωτηρίας ἠνάγκασεν ἐπὶ τὸν τοῦ Δαγῶνος ναὸν καταφυγεῖν, ὃς ἦν ἐν Ἀζώτῳ. λαβὼν δ’ ἐξ ἐπιδρομῆς Ἰωνάθης τὴν πόλιν αὐτήν τε ἐνέπρησεν καὶ τὰς περὶ αὐτὴν κώμας. ἀπέσχετο δ’ οὐδὲ τοῦ Δαγῶνος ἱεροῦ, ἀλλὰ καὶ τοῦτ’ ἐνέπρησεν καὶ τοὺς εἰς αὐτὸ συμφυγόντας διέφθειρεν. τὸ δὲ πᾶν πλῆθος τῶν ἐν τῇ μάχῃ πεσόντων καὶ καταφλεγέντων ἐν τῷ ἱερῷ τῶν πολεμίων ἦσαν ὀκτακισχίλιοι. κρατήσας οὖν τοσαύτης δυνάμεως ἄρας ἀπὸ τῆς Ἀζώτου εἰς Ἀσκάλωνα παραγίνεται, καὶ καταστρατοπεδεύσαντος ἔξω τῆς πόλεως αὐτοῦ προῆλθον εἰς ἀπάντησιν αὐτῷ οἱ Ἀσκαλωνῖται ξένια προσφέροντες αὐτῷ καὶ τιμῶντες. ὁ δὲ ἀποδεξάμενος αὐτοὺς τῆς προαιρέσεως ἀνέστρεψεν ἐκεῖθεν εἰς Ἱεροσόλυμα πολλὴν ἐπαγόμενος λείαν, ἣν ἔλαβεν νικήσας τοὺς πολεμίους. Ἀλέξανδρος δ’ ἀκούσας ἡττημένον τὸν αὐτοῦ στρατηγὸν Ἀπολλώνιον προσεποιεῖτο χαίρειν, ὅτι παρὰ τὴν αὐτοῦ γνώμην Ἰωνάθῃ συνέβαλεν φίλῳ ὄντι καὶ συμμάχῳ, καὶ πέμπει πρὸς Ἰωνάθην μαρτυρῶν αὐτῷ καὶ γέρα καὶ τιμὰς διδοὺς πόρπην χρυσέαν, ὡς ἔστιν ἔθος δίδοσθαι τοῖς τῶν βασιλέων συγγενέσιν, καὶ τὴν Ἀκκάρωνα καὶ τὴν τοπαρχίαν αὐτῆς εἰς κληρουχίαν ἐπιτρέπει.", "st": "13.4.4"}, {"sp": "N", "t": "Ὑπὸ δὲ τοῦτον τὸν καιρὸν καὶ βασιλεὺς Πτολεμαῖος ὁ Φιλομήτωρ ἐπικληθεὶς ναυτικὴν ἄγων δύναμιν καὶ πεζὴν εἰς Συρίαν ἧκεν συμμαχήσων Ἀλεξάνδρῳ· γαμβρὸς γὰρ ἦν αὐτοῦ. καὶ πᾶσαι προθύμως αὐτὸν αἱ πόλεις Ἀλεξάνδρου κελεύσαντος ἐκδεχόμεναι παρέπεμπον ἕως Ἀζώτου πόλεως, ἔνθα πάντες κατεβόων αὐτοῦ περὶ τοῦ ἐμπεπρησμένου ἱεροῦ αὐτῶν Δαγῶνος κατηγοροῦντες Ἰωνάθου τοῦτο ἀφανίσαντος καὶ τὴν χώραν πυρπολήσαντος καὶ πολλοὺς αὐτῶν ἀποκτείναντος. καὶ Πτολεμαῖος μὲν ταῦτ’ ἀκούσας ἡσύχασεν, Ἰωνάθης δὲ εἰς Ἰόππην ἀπαντήσας Πτολεμαίῳ ξενίων τε λαμπρῶν παρ’ αὐτοῦ τυγχάνει καὶ τιμῆς ἁπάσης, ἔπειτα προπέμψας αὐτὸν ἕως τοῦ Ἐλευθέρου καλουμένου ποταμοῦ πάλιν ὑπέστρεψεν εἰς Ἱεροσόλυμα.", "st": "13.4.5"}, {"sp": "N", "t": "Γενόμενος δ’ ἐν Πτολεμαΐδι παρὰ πᾶσαν προσδοκίαν μικροῦ διεφθάρη Πτολεμαῖος ἐπιβουλευθεὶς ὑπὸ Ἀλεξάνδρου δι’ Ἀμμωνίου, ὃς ἐτύγχανεν αὐτῷ φίλος ὤν. φανερᾶς δὲ τῆς ἐπιβουλῆς γενομένης Πτολεμαῖος γράφει τῷ Ἀλεξάνδρῳ πρὸς κόλασιν ἐξαιτῶν τὸν Ἀμμώνιον, ἐπιβουλευθῆναι λέγων ὑπ’ αὐτοῦ καὶ δίκην διὰ τοῦτ’ αὐτὸν ὑποσχεῖν ἀξιῶν. οὐκ ἐκδιδόντος δὲ τοῦ Ἀλεξάνδρου συνεὶς αὐτὸν ἐκεῖνον εἶναι τὸν ἐπιβουλεύσαντα χαλεπῶς διετέθη πρὸς αὐτόν. τοῖς δὲ Ἀντιοχεῦσιν καὶ πρότερον ἦν προσκεκρουκὼς Ἀλέξανδρος διὰ τὸν Ἀμμώνιον· πολλὰ γὰρ ὑπ’ αὐτοῦ πεπόνθεισαν κακά. τιμωρίαν μέντοι τῶν τετολμημένων Ἀμμώνιος ὑπέσχεν κατασφαγεὶς αἰσχρῶς ὡς γυνή, κρύπτειν ἑαυτὸν σπουδάσας στολῇ γυναικείῳ, καθὼς ἐν ἄλλοις δεδηλώκαμεν.", "st": "13.4.6"}, {"sp": "N", "t": "Πτολεμαῖος δὲ μεμψάμενος αὑτὸν τοῦ τε συνοικίσαι τὴν θυγατέρα Ἀλεξάνδρῳ τῆς τε συμμαχίας τῆς κατὰ Δημητρίου διαλύεται τὴν πρὸς αὐτὸν συγγένειαν· ἀποσπάσας γὰρ τὴν θυγατέρα πέμπει πρὸς Δημήτριον εὐθὺς περὶ συμμαχίας καὶ φιλίας συντιθέμενος, τήν τε θυγατέρα δώσειν αὐτῷ ὑπισχνούμενος γυναῖκα καὶ καταστήσειν αὐτὸν εἰς τὴν πατρῴαν ἀρχήν. ὁ δὲ Δημήτριος ἡσθεὶς τοῖς πεπρεσβευμένοις δέχεται τὴν συμμαχίαν καὶ τὸν γάμον. ἓν δ’ ἔτι Πτολεμαίῳ τὸ λοιπὸν ἀγώνισμα ὑπελείπετο πεῖσαι τοὺς Ἀντιοχεῖς δέξασθαι Δημήτριον ἀπεχθῶς πρὸς αὐτὸν διακειμένους ὑπὲρ ὧν ὁ πατὴρ αὐτοῦ Δημήτριος εἰς αὐτοὺς παρηνόμησεν. κατεπράξατο δὲ καὶ τοῦτο· μισοῦντες γὰρ τὸν Ἀλέξανδρον οἱ Ἀντιοχεῖς διὰ τὸν Ἀμμώνιον, ὡς δεδηλώκαμεν, ῥᾳδίως αὐτὸν ἐκ τῆς Ἀντιοχείας ἐξέβαλον. καὶ ὁ μὲν ἐκπεσὼν τῆς Ἀντιοχείας ἦλθεν εἰς Κιλικίαν. ἐλθὼν δὲ πρὸς τοὺς Ἀντιοχεῖς Πτολεμαῖος βασιλεὺς ὑπ’ αὐτῶν καὶ τῶν στρατευμάτων ἀναδείκνυται καὶ ἀναγκασθεὶς δύο περιτίθεται διαδήματα, ἓν μὲν τὸ τῆς Ἀσίας, ἕτερον δὲ τὸ τῆς Αἰγύπτου. χρηστὸς δὲ ὢν φύσει καὶ δίκαιος καὶ τῶν λαμπρῶν οὐκ ἐφιέμενος πρὸς δὲ τούτοις καὶ λογίσασθαι τὰ μέλλοντα συνετός, φείσασθαι τοῦ μὴ δόξαι εἶναι Ῥωμαίοις ἐπίφθονος ἔκρινεν, καὶ συναγαγὼν τοὺς Ἀντιοχεῖς εἰς ἐκκλησίαν πείθει δέξασθαι τὸν Δημήτριον αὐτούς, λέγων οὐδενὸς μνησικακήσειν αὐτοῖς περὶ τοῦ πατρὸς αὐτὸν εὐεργετηθέντα, διδάσκαλός τε ἀγαθῶν καὶ ἡγεμὼν ἔσεσθαι αὐτῷ διωμολογήσατο καὶ φαύλοις ἐγχειροῦντι πράγμασιν οὐκ ἐπιτρέψειν ὑπέσχετο. αὐτῷ δ’ ἔφασκεν ἀρκεῖν τὴν τῆς Αἰγύπτου βασιλείαν. ταῦτ’ εἰπὼν πείθει τοὺς Ἀντιοχεῖς δέξασθαι τὸν Δημήτριον.", "st": "13.4.7"}, {"sp": "N", "t": "Τοῦ δ’ Ἀλεξάνδρου σὺν στρατεύματι πολλῷ καὶ μεγάλῃ παρασκευῇ ὁρμήσαντος ἐκ τῆς Κιλικίας εἰς τὴν Συρίαν καὶ τὴν Ἀντιοχέων γῆν ἐμπρήσαντος καὶ διαρπάσαντος Πτολεμαῖος ἐπ’ αὐτὸν ἐξεστράτευσεν μετὰ τοῦ γαμβροῦ Δημητρίου· ἤδη γὰρ αὐτῷ πρὸς γάμον ἐδεδώκει τὴν θυγατέρα· καὶ νικήσαντες εἰς φυγὴν ἐτρέψαντο τὸν Ἀλέξανδρον. οὗτος μὲν οὖν εἰς Ἀραβίαν φεύγει. συνέβη δὲ ἐν τῇ μάχῃ τὸν ἵππον τὸν Πτολεμαίου φωνῆς ἀκούσαντα ἐλέφαντος ταραχθῆναι καὶ τὸν Πτολεμαῖον ἀποσεισάμενον καταβαλεῖν, τοὺς δὲ πολεμίους ἰδόντας ἐπ’ αὐτὸν ὁρμῆσαι καὶ τραύματα πολλὰ δόντας αὐτῷ κατὰ τῆς κεφαλῆς εἰς κίνδυνον τὸν περὶ θανάτου καταστῆσαι· τῶν γὰρ σωματοφυλάκων αὐτὸν ἐξαρπασάντων χαλεπῶς οὕτως εἶχεν, ὡς ἐφ’ ἡμέρας τέσσαρας μήτε συνεῖναί τι μήτε φθέγξασθαι δυνηθῆναι. τοῦ δὲ Ἀλεξάνδρου τὴν κεφαλὴν ὁ τῶν Ἀράβων δυνάστης ἀποτεμὼν Ζάβειλος ἀπέστειλεν Πτολεμαίῳ, ὃς τῇ πέμπτῃ τῶν ἡμερῶν ἀνενεγκὼν ἐκ τῶν τραυμάτων καὶ φρονήσας ἥδιστον ἄκουσμα καὶ θέαμα τὴν Ἀλεξάνδρου τελευτὴν ἅμα καὶ τὴν κεφαλὴν ἀκούει καὶ θεᾶται. καὶ μετ’ οὐ πολὺ πλησθεὶς τῆς ἐπ’ Ἀλεξάνδρῳ τεθνηκότι χαρᾶς καὶ αὐτὸς κατέστρεψε τὸν βίον. ἐβασίλευσεν δὲ τῆς Ἀσίας Ἀλέξανδρος ὁ Βάλας ἐπιλεγόμενος ἔτη πέντε, καθὼς καὶ ἐν ἄλλοις δεδηλώκαμεν.", "st": "13.4.8"}, {"sp": "N", "t": "Παραλαβὼν δὲ τὴν βασιλείαν Δημήτριος ὁ Νικάτωρ ἐπιλεγόμενος ὑπὸ πονηρίας ἤρξατο διαφθείρειν τὰ τοῦ Πτολεμαίου στρατεύματα, τῆς τε πρὸς αὐτὸν συμμαχίας ἐκλαθόμενος καὶ ὅτι πενθερὸς ἦν αὐτοῦ καὶ διὰ τὸν τῆς Κλεοπάτρας γάμον συγγενής. οἱ μὲν οὖν στρατιῶται φεύγουσιν αὐτοῦ τὴν πεῖραν εἰς Ἀλεξάνδρειαν, τῶν δ’ ἐλεφάντων Δημήτριος ἐγκρατὴς γίνεται. Ἰωνάθης δ’ ὁ ἀρχιερεὺς ἐξ ἁπάσης τῆς Ἰουδαίας στρατιὰν συναγαγὼν προσβαλὼν ἐπολιόρκει τὴν ἐν τοῖς Ἱεροσολύμοις ἄκραν ἔχουσαν Μακεδονικὴν φρουρὰν καὶ τῶν ἀσεβῶν τινας καὶ πεφευγότων τὴν πάτριον συνήθειαν. οὗτοι δὲ τὸ μὲν πρῶτον κατεφρόνουν ὧν Ἰωνάθης ἐμηχανᾶτο περὶ τὴν αἵρεσιν πεπιστευκότες τῇ ὀχυρότητι τοῦ χωρίου, νυκτὸς δέ τινες τῶν ἐν αὐτῷ πονηρῶν ἐξελθόντες ἧκον πρὸς Δημήτριον καὶ τὴν πολιορκίαν αὐτῷ τῆς ἄκρας ἐμήνυσαν. ὁ δὲ τοῖς ἠγγελμένοις παροξυνθείς, ἀναλαβὼν τὴν δύναμιν ἧκεν ἐκ τῆς Ἀντιοχείας ἐπὶ τὸν Ἰωνάθην. γενόμενος δὲ ἐν Πτολεμαΐδι γράφει κελεύων αὐτὸν σπεῦσαι πρὸς αὐτὸν εἰς Πτολεμαΐδα. ὁ δὲ τὴν μὲν πολιορκίαν οὐκ ἔπαυσεν, τοὺς δὲ πρεσβυτέρους τοῦ λαοῦ παραλαβὼν καὶ τοὺς ἱερεῖς καὶ χρυσὸν καὶ ἄργυρον καὶ ἐσθῆτα καὶ πλῆθος ξενίων κομίζων ἧκεν πρὸς τὸν Δημήτριον, καὶ τούτοις δωρησάμενος αὐτὸν θεραπεύει τὴν ὀργὴν τοῦ βασιλέως, καὶ τιμηθεὶς ὑπ’ αὐτοῦ λαμβάνει βεβαίαν ἔχειν τὴν ἀρχιερωσύνην, καθὼς καὶ παρὰ τῶν πρὸ αὐτοῦ βασιλέων ἐκέκτητο. κατηγορούντων δὲ αὐτοῦ τῶν φυγάδων ὁ Δημήτριος οὐκ ἐπίστευσεν, ἀλλὰ καὶ παρακαλέσαντος αὐτόν, ὅπως ὑπὲρ τῆς Ἰουδαίας ἁπάσης καὶ τῶν τριῶν τοπαρχιῶν Σαμαρείας καὶ Ἰόππης καὶ Γαλιλαίας τριακόσια τελῇ τάλαντα, δίδωσιν καὶ περὶ πάντων ἐπιστολάς, αἳ περιεῖχον τοῦτον τὸν τρόπον· βασιλεὺς Δημήτριος Ἰωνάθῃ τῷ ἀδελφῷ καὶ τῷ ἔθνει τῶν Ἰουδαίων χαίρειν. τὸ ἀντίγραφον τῆς ἐπιστολῆς ἧς ἔγραψα Λασθένει τῷ συγγενεῖ ἡμῶν ἀπεστάλκαμεν ὑμῖν, ἵνα εἰδῆτε. βασιλεὺς Δημήτριος Λασθένει τῷ πατρὶ χαίρειν. τῷ Ἰουδαίων ἔθνει ὄντι φίλῳ καὶ τὰ δίκαια τὰ πρὸς ἡμᾶς φυλάττοντι τῆς εὐνοίας ἔκρινα χάριν παρασχεῖν. καὶ τοὺς τρεῖς νομοὺς Ἀφαίρεμα καὶ Λύδδα καὶ Ῥαμαθαιν, οἳ τῇ Ἰουδαίᾳ προσετέθησαν ἀπὸ τῆς Σαμαρείτιδος, καὶ τὰ προσκυροῦντα τούτοις, ἔτι τε ὅσα παρὰ τῶν θυόντων ἐν Ἱεροσολύμοις ἐλάμβανον οἱ πρὸ ἐμοῦ βασιλεῖς, καὶ ὅσα ἀπὸ τῶν καρπῶν τῆς γῆς καὶ τῶν φυτῶν, καὶ τἆλλα τὰ προσήκοντα ἡμῖν, καὶ τὰς λίμνας τῶν ἁλῶν καὶ τοὺς κομιζομένους ἡμῖν στεφάνους ἀφίημι αὐτοῖς, καὶ οὐδὲν παραβιβασθήσεται τούτων ἀπὸ τοῦ νῦν οὐδὲ εἰς τὸν ἅπαντα χρόνον. φρόντισον οὖν, ἵνα τούτων ἀντίγραφον γένηται καὶ δοθῇ Ἰωνάθῃ καὶ ἐν ἐπισήμῳ τόπῳ τοῦ ἁγίου ἱεροῦ τεθῇ. τὰ μὲν δὴ γραφέντα ταῦτα ἦν. ὁρῶν δὲ ὁ Δημήτριος εἰρήνην οὖσαν καὶ μηδένα κίνδυνον μηδὲ πολέμου φόβον ὑπάρχοντα διέλυσε τὴν στρατιὰν καὶ τὸν μισθὸν αὐτῶν ἐμείωσεν, καὶ μόνοις τοῦτον ἐχορήγει τοῖς ξενολογηθεῖσιν, οἳ συνανέβησαν ἐκ Κρήτης αὐτῷ καὶ ἐκ τῶν ἄλλων νήσων. ἔχθρα τοιγαροῦν αὐτῷ καὶ μῖσος ἐκ τούτου γίνεται παρὰ τῶν στρατιωτῶν, οἷς αὐτὸς μὲν οὐδὲν οὐκέτι παρεῖχεν, οἱ δὲ πρὸ αὐτοῦ βασιλεῖς καὶ ἐπ’ εἰρήνης χορηγοῦντες αὐτοῖς ὁμοίως διετέλουν, ἵν’ εὐνοοῦντας ἔχωσιν καὶ ἐν τοῖς ὑπὲρ αὐτῶν ἀγῶσιν εἰ δεήσειέν ποτε προθύμους.", "st": "13.4.9"}, {"sp": "N", "t": "Ἀμέλει ταύτην νοήσας τὴν δύσνοιαν τῶν στρατιωτῶν πρὸς Δημήτριον Ἀλεξάνδρου τις στρατηγὸς Ἀπαμεὺς τὸ γένος Διόδοτος ὁ καὶ Τρύφων ἐπικληθείς, παραγίνεται πρὸς Μάλχον τὸν Ἄραβα, ὃς ἔτρεφε τὸν Ἀλεξάνδρου υἱὸν Ἀντίοχον, καὶ δηλώσας αὐτῷ τὴν δυσμένειαν τὴν τῶν στρατευμάτων πρὸς Δημήτριον ἔπειθεν αὐτῷ δοῦναι τὸν Ἀντίοχον· βασιλέα γὰρ αὐτὸν ποιήσειν καὶ τὴν ἀρχὴν αὐτῷ τὴν τοῦ πατρὸς ἀποκαταστήσειν. ὁ δὲ τὸ μὲν πρῶτον ἀντεῖχεν ὑπ’ ἀπιστίας, ὕστερον δὲ πολλῷ χρόνῳ προσλιπαρήσαντος τοῦ Τρύφωνος νικᾶται τὴν προαίρεσιν εἰς ἃ Τρύφων παρεκάλει. καὶ τὰ μὲν περὶ τούτου τἀνδρὸς ἐν τούτοις ὑπῆρχεν.", "st": "13.5.1"}, {"sp": "N", "t": "Ὁ δ’ ἀρχιερεὺς Ἰωνάθης ἐξελθεῖν βουλόμενος τοὺς ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων καὶ τοὺς Ἰουδαίων φυγάδας καὶ ἀσεβεῖς καὶ τοὺς ἐν ἁπάσῃ τῇ χώρᾳ φρουρούς, πέμψας πρὸς Δημήτριον δῶρα καὶ πρεσβευτὰς παρεκάλει τοὺς ἐν τοῖς ὀχυρώμασι τῆς Ἰουδαίας ἐκβαλεῖν. ὁ δ’ οὐ ταῦτα μόνον αὐτῷ παρέξειν, ἀλλὰ καὶ μείζω τούτων ὑπισχνεῖται μετὰ τὸν ἐν χερσὶ πόλεμον· τούτῳ γὰρ νῦν εὐσχολεῖν. ἠξίου δ’ αὐτὸν καὶ συμμαχίαν πέμψαι δηλῶν ἀποστῆναι τὴν δύναμιν αὐτοῦ. καὶ Ἰωνάθης μὲν τρισχιλίους ἐπιλεξάμενος στρατιώτας ἔπεμψεν.", "st": "13.5.2"}, {"sp": "N", "t": "Ἀντιοχεῖς δὲ μισοῦντες τὸν Δημήτριον ὑπὲρ ὧν πεπόνθεισαν ὑπ’ αὐτοῦ κακῶς, ἀπεχθανόμενοι δ’ αὐτῷ καὶ διὰ τὸν πατέρα Δημήτριον πολλὰ εἰς αὐτοὺς ἐξαμαρτόντα, καιρὸν ἐπετήρουν λαβεῖν καθ’ ὃν ἐπιθοῖντο αὐτῷ. νοήσαντες δὲ συμμαχίαν παροῦσαν παρὰ Ἰωνάθου τῷ Δημητρίῳ καὶ συμφρονήσαντες, ὅτι πολλὴν ἀθροίσει δύναμιν, εἰ μὴ φθάσαντες προκαταλάβοιεν αὐτόν, ἁρπάσαντες τὰ ὅπλα καὶ περιστάντες τοῖς βασιλείοις αὐτοῦ τρόπῳ πολιορκίας καὶ τὰς ἐξόδους διαλαβόντες ἐζήτουν χειρώσασθαι τὸν βασιλέα. ὁ δὲ τὸν δῆμον ὁρῶν τὸν τῶν Ἀντιοχέων ἐκπεπολεμωμένον πρὸς αὐτὸν καὶ ἐν ὅπλοις ὄντα, παραλαβὼν τοὺς μισθοφόρους καὶ τοὺς πεμφθέντας ὑπὸ Ἰωνάθου Ἰουδαίους συμβάλλει τοῖς Ἀντιοχεῦσιν καὶ βιασθεὶς ὑπ’ αὐτῶν, πολλαὶ γὰρ ἦσαν μυριάδες, ἡττᾶται. βλέποντες δὲ τοὺς Ἀντιοχεῖς κρατοῦντας οἱ Ἰουδαῖοι ἐπὶ τὰς στέγας τῶν βασιλείων ἀναβάντες ἐκεῖθεν ἔβαλλον τοὺς Ἀντιοχεῖς, καὶ τοῦ μὲν αὐτοί τι πάσχειν ὑπ’ αὐτῶν ὄντες πορρωτάτω διὰ τὸ ὕψος, ποιοῦντες δ’ αὐτοὺς κακῶς διὰ τὸ ἄνωθεν μάχεσθαι τῶν σύνεγγυς αὐτοὺς οἰκιῶν ἀπώσαντο. καὶ ταύταις μὲν εὐθὺς πῦρ ἐνῆκαν, ἡ δὲ φλὸξ ἐφ’ ὅλην διατείνουσα τὴν πόλιν πυκνῶν τῶν οἰκιῶν οὐσῶν καὶ τὰ πλεῖστα ἐκ ξύλων ᾠκοδομημένων πᾶσαν αὐτὴν ἐνέμετο. οἱ δ’ Ἀντιοχεῖς μὴ δυνάμενοι βοηθῆσαι μηδὲ κρατῆσαι τοῦ πυρὸς εἰς φυγὴν ἐτράπησαν. τῶν δὲ Ἰουδαίων ἀπὸ δώματος ἐπὶ δῶμα διαπηδώντων καὶ τοῦτον αὐτοὺς διωκόντων τὸν τρόπον παράδοξον συνέβη γενέσθαι τὴν δίωξιν. ὁ δὲ βασιλεὺς ὁρῶν τοὺς Ἀντιοχεῖς σῶσαι τὰ τέκνα καὶ τὰς γυναῖκας ἐσπουδακότας καὶ διὰ τοῦτο μηκέτι μαχομένους δι’ ἄλλων αὐτοῖς ἐπιτίθεται στενωπῶν, καὶ συμβαλὼν πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, ὡς ἀναγκασθῆναι ῥῖψαι τὰς πανοπλίας καὶ παραδοῦναι αὑτοὺς τῷ Δημητρίῳ. συγγνοὺς δ’ αὐτοῖς τῶν τετολμημένων καταπαύει τὴν στάσιν. δωρησάμενος δὲ τοῖς Ἰουδαίοις τὰς ἐκ τῶν σκύλων ὠφελείας καὶ ὡς αἰτιωτάτοις τῆς νίκης αὐτῷ γεγενημένοις εὐχαριστήσας ἀπέπεμψεν εἰς Ἱεροσόλυμα πρὸς Ἰωνάθην μαρτυρῶν αὐτῷ τῆς συμμαχίας. ὕστερον δὲ πονηρὸς εἰς αὐτὸν ἐγένετο καὶ τὰς ὑποσχέσεις διεψεύσατο καὶ πόλεμον ἠπείλησεν, εἰ μὴ τοὺς φόρους αὐτῷ πάντας ἀποδώσει, οὓς ὤφειλεν τὸ τῶν Ἰουδαίων ἔθνος ἀπὸ τῶν πρώτων βασιλέων. καὶ ταῦτ’ ἐποίησεν ἄν, εἰ μὴ Τρύφων αὐτὸν ἐπέσχεν καὶ τὴν ἐπὶ τὸν Ἰωνάθην αὐτοῦ παρασκευὴν ἀντιμετέσπασεν εἰς τὰς περὶ αὐτοῦ φροντίδας. ὑποστρέψας γὰρ ἐκ τῆς Ἀραβίας εἰς τὴν Συρίαν μετὰ τοῦ παιδὸς Ἀντιόχου, μειράκιον δ’ ἦν οὗτος τὴν ἡλικίαν, περιτίθησιν αὐτῷ τὸ διάδημα. καὶ προσχωρήσαντος τοῦ στρατιωτικοῦ παντός, ὃ καταλελοίπει τὸν Δημήτριον διὰ τὸ μὴ τυγχάνειν μισθῶν, πόλεμον ἐκφέρει πρὸς τὸν Δημήτριον, καὶ συμβαλὼν αὐτῷ κρατεῖ τῇ μάχῃ καὶ τούς τε ἐλέφαντας καὶ τὴν τῶν Ἀντιοχέων πόλιν λαμβάνει.", "st": "13.5.3"}, {"sp": "N", "t": "Δημήτριος μὲν οὖν ἡττηθεὶς ἀνεχώρησεν εἰς Κιλικίαν, ὁ δὲ παῖς Ἀντίοχος πέμψας πρὸς Ἰωνάθην πρεσβευτὰς καὶ γράμματα φίλον τε καὶ σύμμαχον αὐτὸν ἐποιεῖτο καὶ τὴν ἀρχιερωσύνην ἐβεβαίου καὶ τῶν τεσσάρων παρεχώρει νομῶν, οἳ τῇ χώρᾳ τῶν Ἰουδαίων προσετέθησαν. ἔτι γε μὴν σκεύη χρυσᾶ καὶ ἐκπώματα καὶ πορφυρᾶν ἐσθῆτα χρῆσθαι τούτοις ἐπιτρέπων ἀπέστειλεν καὶ πόρπῃ δ’ αὐτὸν δωρεῖται χρυσέᾳ καὶ τῶν πρώτων αὐτοῦ καλεῖσθαι φίλων. τὸν ἀδελφὸν δ’ αὐτοῦ Σίμωνα στρατηγὸν τῆς στρατιᾶς ἀπὸ κλίμακος τῆς Τυρίων ἕως Αἰγύπτου καθίστησιν. Ἰωνάθης δ’ ἐπὶ τοῖς παρ’ Ἀντιόχου γεγενημένοις εἰς αὐτὸν ἡσθεὶς πέμψας πρὸς αὐτόν τε καὶ Τρύφωνα πρεσβευτὰς εἶναί τε φίλος ὡμολόγει καὶ σύμμαχος καὶ πολεμήσειν σὺν αὐτῷ πρὸς Δημήτριον, διδάσκων ὡς οὐδ’ αὐτῷ χάριτας ἀποδοίη πολλῶν παρ’ αὐτοῦ χρηστῶν ἐν οἷς ἐδεῖτο τυχών, ἀλλὰ προσαδικήσειεν ἀνθ’ ὧν εὖ πάθοι.", "st": "13.5.4"}, {"sp": "N", "t": "Συγχωρήσαντος οὖν Ἀντιόχου δύναμιν αὐτῷ συναγαγόντι πολλὴν ἔκ τε Συρίας καὶ Φοινίκης τοῖς Δημητρίου πολεμῆσαι στρατηγοῖς εὐθὺς ὥρμησεν εἰς τὰς πόλεις. αἱ δὲ λαμπρῶς μὲν ἐξεδέξαντο, στρατιὰν δ’ οὐκ ἔδοσαν. παραγενόμενος δ’ ἐκεῖθεν πρὸς Ἀσκάλωνα πόλιν καὶ τῶν Ἀσκαλωνιτῶν φιλοτίμως αὐτῷ μετὰ δώρων ἀπαντησάντων, αὐτούς τε τούτους παρεκάλει καὶ τῶν ἐν τῇ κοίλῃ Συρίᾳ πόλεων ἑκάστην ἀποστᾶσαν Δημητρίου προσθέσθαι μὲν Ἀντιόχῳ, σὺν αὐτῷ δὲ πολεμούσας πειρᾶσθαι παρὰ Δημητρίου δίκην λαμβάνειν ὧν ἁμάρτοι ποτ’ εἰς αὐτάς· εἶναι δ’ αὐταῖς βουλομέναις ταῦτα φρονεῖν πολλὰς αἰτίας. πείσας δ’ ὁμολογῆσαι πρὸς τὸν Ἀντίοχον συμμαχεῖν τὰς πόλεις εἰς Γάζαν παρεγένετο προσαξόμενος καὶ τὴν παρὰ τούτων εὔνοιαν Ἀντιόχῳ. πολὺ δ’ εὗρεν τῆς προσδοκίας τοὺς Γαζαίους ἀλλοτριώτερον ἔχοντας· ἀπέκλεισαν γὰρ αὐτῷ τὰς πύλας καὶ τὸν Δημήτριον ἐγκαταλιπόντες οὐκ ἔγνωσαν Ἀντιόχῳ προσχωρῆσαι. τοῦτο παρώξυνεν εἰς πολιορκίαν τὸν Ἰωνάθην καὶ τῆς χώρας τὴν κάκωσιν· μέρος γὰρ τῆς στρατιᾶς περικαθίσας τῇ Γάζῃ τῷ λοιπῷ τὴν γῆν αὐτὸς ἐπιὼν διέφθειρεν καὶ ἐνεπίμπρα. ταῦτα δὲ πάσχοντας ἑαυτοὺς ὁρῶντες οἱ Γαζῖται καὶ μηδεμίαν ἀπὸ Δημητρίου βοήθειαν αὐτοῖς γινομένην, ἀλλὰ τὸ μὲν λυποῦν ἤδη παρόν, τὸ δ’ ὠφελῆσον μακρὰν ἔτι καὶ ἄδηλον εἰ παραγένοιτο, σῶφρον ἔκριναν εἶναι τοῦτ’ ἀφέντες παραμένειν ἐκεῖνο θεραπεύειν. πέμψαντες οὖν πρὸς τὸν Ἰωνάθην φιλίαν τε ὡμολόγουν καὶ συμμαχίαν· οἱ μὲν γὰρ ἄνθρωποι πρὸ πείρας τῶν δεινῶν οὐ συνιᾶσιν τὸ συμφέρον, ἀλλ’ ὅταν ἔν τινι κακῷ γενόμενοι τύχωσιν, τότε γνωσιμαχήσαντες ἃ μηδ’ ὅλως βλαβέντας ἄμεινον ἦν ποιεῖν ταῦθ’ ὕστερον ζημιωθέντες αἱροῦνται. ὁ δὲ συνθέμενος πρὸς αὐτοὺς φιλίαν καὶ λαβὼν ὁμήρους τούτους μὲν ἀπέστειλεν εἰς Ἱεροσόλυμα, αὐτὸς δὲ τὴν χώραν ἅπασαν ἐπῆλθεν ἄχρι Δαμασκοῦ.", "st": "13.5.5"}, {"sp": "N", "t": "Τῶν δὲ Δημητρίου στρατηγῶν ἀκουσθέντων αὐτῷ προελθεῖν εἰς Κέδασαν σὺν πολλῇ στρατιᾷ, μεταξὺ δ’ ἐστὶν αὕτη τῆς τε Τυρίων γῆς καὶ τῆς Γαλιλαίας· ἀπάξειν γὰρ αὐτὸν ἐκ τῆς Συρίας ὑπέλαβον ἐπὶ τὴν τῶν Γαλιλαίων συμμαχίαν· τῆς γὰρ Γαλιλαίας ὄντας αὐτοὺς οὐ περιόψεσθαι πολεμουμένους· ὑπήντησεν αὐτοῖς τὸν ἀδελφὸν Σίμωνα καταλιπὼν ἐν τῇ Ἰουδαίᾳ, ὃς στρατὸν ἐκ τῆς χώρας συναγαγὼν ὡς ἐνῆν ἱκανώτατον τὴν Βεθσούραν πολιορκῶν προσεκάθητο χωρίον τῆς Ἰουδαίας ὀχυρώτατον· κατεῖχεν γὰρ αὐτὸ φρουρὰ Δημητρίου. δεδήλωται δ’ ἡμῖν τοῦτο καὶ πρότερον. ὡς δὲ χώματα μὲν ἐγείραντος τοῦ Σίμωνος, μηχανήματα δ’ ἱστάντος καὶ πολλῇ σπουδῇ χρωμένου περὶ τὴν τῆς Βεθσούρου πολιορκίαν ἔδεισαν οἱ φρουροί, μὴ κατὰ κράτος ἐξαιρεθέντος τοῦ χωρίου διαφθαρῶσιν, πέμψαντες πρὸς τὸν Σίμωνα ἠξίουν ὅρκους λαβόντες, ὥστε μηδὲν ὑπ’ αὐτοῦ παθεῖν, καταλιπεῖν τὸ χωρίον καὶ πρὸς Δημήτριον ἀπελθεῖν. ὁ δὲ δοὺς ταύτας αὐτοῖς τὰς πίστεις ἐκβάλλει μὲν ἐκείνους ἐκ τῆς πόλεως, αὐτὸς δὲ φρουρὰν καθίστησιν ἰδίαν.", "st": "13.5.6"}, {"sp": "N", "t": "Ἰωνάθης δὲ ἄρας ἐκ τῆς Γαλιλαίας ἀπὸ τῶν ὑδάτων τῶν Γενησάρων λεγομένων, ἐκεῖ γὰρ ἐτύγχανεν ἐστρατοπεδευκώς, εἰς τὸ καλούμενον Ἀσὼρ πεδίον προῆλθεν οὐκ εἰδὼς ὄντας ἐν αὐτῇ τοὺς πολεμίους. μαθόντες δὲ πρὸ μιᾶς ἡμέρας οἱ τοῦ Δημητρίου μέλλειν Ἰωνάθην ἐπ’ αὐτοὺς βαδίζειν ἐνέδραν αὐτῷ καὶ τοὺς λοχήσοντας ἐν τῷ ὄρει καθίσαντες αὐτοὶ μετὰ τῆς στρατιᾶς ἀπήντων εἰς τὸ πεδίον· οὓς ἰδὼν ὁ Ἰωνάθης ἑτοίμους πρὸς μάχην παρεσκευάζετο καὶ αὐτὸς τοὺς ἰδίους στρατιώτας πρὸς τὸν ἀγῶνα, ὡς ἠδύνατο. τῶν δὲ εἰς τὴν ἐνέδραν ὑπὸ τῶν Δημητρίου στρατηγῶν κατασταθέντων κατὰ νώτου τοῖς Ἰουδαίοις γενομένων, δείσαντες μὴ μέσοι ληφθέντες ἀπόλωνται, φεύγειν ὥρμησαν. καὶ οἱ μὲν ἄλλοι πάντες τὸν Ἰωνάθην κατέλιπον, ὀλίγοι δέ τινες ὡς περὶ πεντήκοντα τὸν ἀριθμὸν ὑπέμειναν, καὶ Ματθίας ὁ Ἀψαλώμου καὶ Ἰούδας ὁ Χαψέου τῆς ἁπάσης δυνάμεως ἡγεμόνες ὄντες· τολμηρῶς δὲ καὶ μετὰ ἀπογνώσεως εἰς τοὺς πολεμίους ὠσάμενοι τῷ τε θάρσει κατέπληξαν αὐτοὺς καὶ ταῖς χερσὶν ἀπέστρεψαν εἰς φυγήν. οἱ δ’ ἀναχωρήσαντες τῶν Ἰωνάθου στρατιωτῶν ὡς εἶδον τοὺς πολεμίους τραπέντας, ἐπισυλλεγέντες ἐκ τῆς φυγῆς ὥρμησαν αὐτοὺς διώκειν καὶ τοῦτ’ ἐποίησαν μέχρι Κεδάσων, οὗ τὸ στρατόπεδον ἦν τοῖς πολεμίοις.", "st": "13.5.7"}, {"sp": "N", "t": "Κρατήσας οὖν Ἰωνάθης τῇ μάχῃ λαμπρῶς καὶ δισχιλίους τῶν ἐχθρῶν ἀποκτείνας ὑπέστρεψεν εἰς Ἱεροσόλυμα. ὁρῶν οὖν, ὅτι πάντ’ αὐτῷ κατὰ νοῦν προνοίᾳ θεοῦ χωρεῖ, πρὸς Ῥωμαίους πρεσβευτὰς ἀπέστειλεν, ἀνανεώσασθαι βουλόμενος τὴν γενομένην τῷ ἔθνει πρὸς αὐτοὺς ἔμπροσθεν φιλίαν. τοῖς δ’ αὐτοῖς πρεσβευταῖς ἐπέστειλεν ἀπὸ τῆς Ῥώμης ἀναστρέφουσιν πρὸς τοὺς Σπαρτιάτας ἀφικέσθαι καὶ τὴν πρὸς αὐτοὺς ὑπομνῆσαι φιλίαν καὶ συγγένειαν. οἱ δ’ ὡς ἦλθον εἰς τὴν Ῥώμην παρελθόντες εἰς τὴν βουλὴν αὐτῶν καὶ τὰ παρὰ Ἰωνάθου τοῦ ἀρχιερέως εἰπόντες, ὡς πέμψειεν αὐτοὺς ἐπὶ τῇ τῆς συμμαχίας βεβαιώσει, τῆς βουλῆς ἐπικυρωσάσης τὰ πρότερον αὐτῇ περὶ τῆς Ἰουδαίων φιλίας ἐγνωσμένα καὶ δούσης ἐπιστολὰς πρὸς ἅπαντας τοὺς βασιλεῖς τῆς Ἀσίας καὶ Εὐρώπης καὶ τῶν πόλεων ἄρχοντας αὐτοῖς κομίζειν, ὅπως ἀσφαλοῦς τῆς εἰς τὴν οἰκείαν κομιδῆς δι’ αὐτῶν τύχωσιν, ἀναστρέφοντες εἰς τὴν Σπάρτην παρεγένοντο καὶ τὰς ἐπιστολάς, ἃς ἔλαβον παρὰ Ἰωνάθου, αὐτοῖς ἀπέδοσαν. τὸ δ’ ἀντίγραφον ἦν τόδε· ἀρχιερεὺς Ἰωνάθης τοῦ ἔθνους τῶν Ἰουδαίων καὶ ἡ γερουσία καὶ τὸ κοινὸν τῶν ἱερέων Λακεδαιμονίων ἐφόροις καὶ γερουσίᾳ καὶ δήμῳ τοῖς ἀδελφοῖς χαίρειν. εἰ ἐρρωμένοις ὑμῖν καὶ τὰ κοινὰ καὶ τὰ ἴδια χωρεῖ κατὰ νοῦν, οὕτως ἂν ἔχοι ὡς βουλόμεθα, ἐρρώμεθα δὲ καὶ ἡμεῖς. ἐπειδὴ τοῖς ἔμπροσθεν χρόνοις κομισθείσης Ὀνίᾳ τῷ γενομένῳ ἀρχιερεῖ παρ’ ἡμῖν παρὰ Ἀρέως τοῦ βασιλεύσαντος ὑμῶν ἐπιστολῆς διὰ Δημοτέλους περὶ τῆς ὑπαρχούσης ὑμῖν πρὸς ἡμᾶς συγγενείας, ἧς ὑποτέτακται τὸ ἀντίγραφον, τήν τε ἐπιστολὴν ἐδεξάμεθα προθύμως καὶ τῷ Δημοτέλει καὶ τῷ Ἀρεῖ εὐνοϊκῶς διετέθημεν, οὐ δεόμενοι τῆς τοιαύτης ἀποδείξεως διὰ τὸ ἐκ τῶν ἱερῶν ἡμῶν πεπιστεῦσθαι γραμμάτων, τὸ μὲν προκατάρχειν τῆς ἀναγνωρίσεως οὐδὲ δοκιμάζομεν μὴ καὶ προαρπάζειν δοκῶμεν τὴν παρ’ ὑμῶν διδομένην δόξαν, πολλῶν δὲ χρόνων διαγενομένων ἀπὸ τῆς ἐξ ἀρχῆς ἀναποληθείσης ἡμῖν οἰκειότητος ἐν ταῖς ἱεραῖς καὶ ἐπωνύμοις ἡμέραις θυσίας τῷ θεῷ προσφέροντες καὶ ὑπὲρ τῆς ὑμετέρας σωτηρίας τε καὶ νίκης αὐτὸν παρακαλοῦμεν. πολλῶν δ’ ἡμᾶς πολέμων περιστάντων διὰ τὴν τῶν γειτνιώντων πλεονεξίαν οὔθ’ ὑμῖν οὔτ’ ἄλλῳ τῶν προσηκόντων ἡμῖν ἐνοχλεῖν ἐκρίναμεν. καταγωνισάμενοι δὲ τοὺς πολεμίους πέμποντες πρὸς Ῥωμαίους Νουμήνιον τὸν Ἀντιόχου καὶ Ἀντίπατρον τὸν Ἰάσονος τῶν ἀπὸ τῆς γερουσίας ὄντων παρ’ ἡμῖν ἐν τιμῇ, ἐδώκαμεν αὐτοῖς καὶ πρὸς ὑμᾶς ἐπιστολάς, ὅπως ἀνανεώσωνται τὴν πρὸς ὑμᾶς ἡμῖν συγγένειαν. καλῶς οὖν ποιήσετε καὶ αὐτοὶ γράφοντες ἡμῖν καὶ περὶ ὧν ἂν δέησθε ἐπιστέλλοντες, ὡς εἰς ἅπαντα προθυμησομένοις ὑπὲρ τῆς ὑμετέρας προαιρέσεως. οἱ μὲν οὖν Λακεδαιμόνιοι τούς τε πρεσβευτὰς φιλοφρόνως ὑπεδέξαντο καὶ ψήφισμα ποιησάμενοι περὶ συμμαχίας καὶ φιλίας πρὸς αὐτοὺς ἀπέστειλαν.", "st": "13.5.8"}, {"sp": "N", "t": "Κατὰ δὲ τὸν χρόνον τοῦτον τρεῖς αἱρέσεις τῶν Ἰουδαίων ἦσαν, αἳ περὶ τῶν ἀνθρωπίνων πραγμάτων διαφόρως ὑπελάμβανον, ὧν ἡ μὲν Φαρισαίων ἐλέγετο, ἡ δὲ Σαδδουκαίων, ἡ τρίτη δὲ Ἐσσηνῶν. οἱ μὲν οὖν Φαρισαῖοι τινὰ καὶ οὐ πάντα τῆς εἱμαρμένης ἔργον εἶναι λέγουσιν, τινὰ δ’ ἐφ’ ἑαυτοῖς ὑπάρχειν συμβαίνειν τε καὶ μὴ γίνεσθαι. τὸ δὲ τῶν Ἐσσηνῶν γένος πάντων τὴν εἱμαρμένην κυρίαν ἀποφαίνεται καὶ μηδὲν ὃ μὴ κατ’ ἐκείνης ψῆφον ἀνθρώποις ἀπαντᾶν. Σαδδουκαῖοι δὲ τὴν μὲν εἱμαρμένην ἀναιροῦσιν οὐδὲν εἶναι ταύτην ἀξιοῦντες οὐδὲ κατ’ αὐτὴν τὰ ἀνθρώπινα τέλος λαμβάνειν, ἅπαντα δὲ ἐφ’ ἡμῖν αὐτοῖς κεῖσθαι, ὡς καὶ τῶν ἀγαθῶν αἰτίους ἡμᾶς γινομένους καὶ τὰ χείρω παρὰ τὴν ἡμετέραν ἀβουλίαν λαμβάνοντας. ἀλλὰ περὶ μὲν τούτων ἀκριβεστέραν πεποίημαι δήλωσιν ἐν τῇ δευτέρᾳ βίβλῳ τῆς Ἰουδαϊκῆς πραγματείας.", "st": "13.5.9"}, {"sp": "N", "t": "Οἱ δὲ τοῦ Δημητρίου στρατηγοὶ τὴν γεγενημένην ἧτταν ἀναμαχέσασθαι βουλόμενοι, πλείω τῆς προτέρας δύναμιν συναγαγόντες ἦλθον ἐπὶ τὸν Ἰωνάθην. ὁ δὲ ἐπιόντας πυθόμενος ὀξέως ἀπήντησεν αὐτοῖς εἰς τὴν Ἀμαθῖτιν· οὐ γὰρ ἔγνω σχολὴν αὐτοῖς παρασχεῖν, ὥστ’ εἰς τὴν Ἰουδαίαν ἐμβαλεῖν. στρατοπεδευσάμενος δὲ τῶν πολεμίων ἄπωθεν σταδίοις πεντήκοντα πέμπει τοὺς κατοψομένους αὐτῶν τὴν παρεμβολὴν καὶ πῶς εἶεν ἐστρατοπεδευκότες. τῶν δὲ κατασκόπων πάντ’ αὐτῷ φρασάντων καί τινας συλλαβόντων νυκτός, οἳ αὐτοῖς μέλλειν ἐπιτίθεσθαι τοὺς πολεμίους ἐμήνυον, προγνοὺς ἠσφαλίσατο, προφυλακάς τε ποιησάμενος ἔξω τοῦ στρατοπέδου καὶ τὴν δύναμιν δι’ ὅλης τῆς νυκτὸς ἐν τοῖς ὅπλοις ἔχων ἅπασαν καὶ παρηγγελκὼς αὐτοῖς τὰς ψυχὰς ἐρρωμένους εἶναι καὶ ταῖς διανοίαις οὕτως ἔχειν, ὡς καὶ διὰ τῆς νυκτὸς εἰ δεήσειε μαχεσομένους, ὥστε μὴ λαθεῖν αὐτῶν τὴν προαίρεσιν. οἱ δὲ τοῦ Δημητρίου στρατηγοὶ πυθόμενοι τὸν Ἰωνάθην ἐγνωκότα οὐκέτι τὴν γνώμην ἦσαν ὑγιεῖς, ἀλλ’ ἐτάραττεν αὐτοὺς τὸ καταφώρους τοῖς ἐχθροῖς γεγονέναι καὶ μηδενὶ προσδοκᾶν αὐτῶν ἐπικρατήσειν ἑτέρῳ τῆς ἐπιβουλῆς διημαρτημένης· ἐκ γὰρ τοῦ φανεροῦ διακινδυνεύοντες οὐκ ἐνόμιζον εἶναι τοῖς Ἰωνάθου ἀξιόμαχοι. φυγὴν οὖν ἐβουλεύσαντο, καὶ πυρὰ καύσαντες πολλά, ὡς ὁρῶντες οἱ πολέμιοι μένειν αὐτοὺς ὑπολάβοιεν, ἀνεχώρησαν. ὁ δὲ Ἰωνάθης ἕωθεν προσμίξας αὐτῶν τῷ στρατοπέδῳ καὶ καταλαβὼν ἔρημον αὐτό, συνεὶς ὅτι πεφεύγασιν ἐδίωκεν. οὐ μέντοι φθάνει καταλαβεῖν· ἤδη γὰρ τὸν Ἐλεύθερον ποταμὸν διαβεβηκότες ἦσαν ἐν ἀσφαλεῖ. ποιησάμενος οὖν ἐκεῖθεν τὴν ὑποστροφὴν εἰς τὴν Ἀραβίαν καὶ πολεμήσας τοὺς Ναβατηνοὺς καὶ πολλὴν αὐτῶν λείαν ἀπελάσας καὶ λαβὼν αἰχμαλώτους ἐλθὼν εἰς Δαμασκὸν ἐκεῖ πάντα ἀπέδοτο. ὑπὸ δὲ τὸν αὐτὸν καιρὸν καὶ Σίμων ὁ ἀδελφὸς αὐτοῦ τὴν Ἰουδαίαν ἅπασαν ἐπελθὼν καὶ τὴν Παλαιστίνην ἕως Ἀσκάλωνος ἠσφαλίσατο φρουρίοις, καὶ ποιήσας ταῦτα καὶ τοῖς οἰκοδομήμασιν ὀχυρώτατα καὶ ταῖς φυλακαῖς ἦλθεν εἰς Ἰόππην καὶ καταλαβόμενος αὐτὴν εἰσήγαγεν μεγάλην φρουράν· ἤκουσε γὰρ τοὺς Ἰοππηνοὺς βουλομένους τοῖς Δημητρίου στρατηγοῖς παραδοῦναι τὴν πόλιν.", "st": "13.5.10"}, {"sp": "N", "t": "Ταῦτ’ οὖν διοικησάμενοι ὅ τε Σίμων καὶ Ἰωνάθης ἦλθον εἰς Ἱεροσόλυμα. συναγαγὼν δὲ τὸν λαὸν ἅπαντα εἰς τὸ ἱερὸν Ἰωνάθης συνεβουλεύετο τά τε τείχη τῶν Ἱεροσολυμιτῶν ἐπισκευάσαι καὶ τὸ καθῃρημένον τοῦ περὶ τὸ ἱερὸν περιβόλου πάλιν ἀναστῆσαι καὶ πύργοις ὑψηλοῖς ἐξοχυρῶσαι τὰ περὶ αὐτό, πρὸς τούτοις δὲ καὶ μέσον τῆς πόλεως ἄλλο τεῖχος ἀνοικοδομησαμένους ἀποφράξαι τοῖς ἐν τῇ ἄκρᾳ φρουροῖς τὴν πόλιν καὶ τῆς εὐπορίας αὐτοὺς τῶν σιτίων τοῦτον ἀποκλεῖσαι τὸν τρόπον, ἔτι γε μὴν καὶ τὰ ἐν τῇ χώρᾳ φρούρια ποιῆσαι πολὺ τῆς ὑπαρχούσης αὐτοῖς ἀσφαλείας ὀχυρώτερα. τῆς δὲ γνώμης καὶ τῷ πλήθει δοκιμασθείσης καλῶς ἔχειν αὐτὸς μὲν τὰ κατὰ τὴν πόλιν ᾠκοδόμει, Σίμωνα δὲ τὰ κατὰ τὴν χώραν ἐξέπεμψεν ἀσφαλισόμενον. ὁ δὲ Δημήτριος διαβὰς εἰς τὴν Μεσοποταμίαν ἧκεν ταύτην τε βουλόμενος καὶ τὴν Βαβυλῶνα κατασχεῖν, καὶ τῶν ἄνω σατραπειῶν ἐγκρατὴς γενόμενος ἐντεῦθεν ποιεῖσθαι τὰς ὅλης τῆς βασιλείας ἀφορμάς· καὶ γὰρ οἱ ταύτῃ κατοικοῦντες Ἕλληνες καὶ Μακεδόνες συνεχῶς ἐπρεσβεύοντο πρὸς αὐτόν, εἰ πρὸς αὐτοὺς ἀφίκοιτο, παραδώσειν μὲν αὑτοὺς ὑπισχνούμενοι, συγκαταπολεμήσειν δὲ Ἀρσάκην τὸν Πάρθων βασιλέα. ταύταις ἐπαρθεὶς ταῖς ἐλπίσιν ὥρμησεν πρὸς αὐτούς, εἰ καταστρέψαιτο τοὺς Πάρθους καὶ γένοιτ’ αὐτῷ δύναμις, τὸν Τρύφωνα πολεμῆσαι διεγνωκὼς καὶ τῆς Συρίας ἐκβαλεῖν. δεξαμένων δὲ αὐτὸν προθύμως τῶν ἐν τῇ χώρᾳ, συναγαγὼν δύναμιν ἐπολέμησεν πρὸς τὸν Ἀρσάκην, καὶ τὴν στρατιὰν πᾶσαν ἀποβαλὼν αὐτὸς ζῶν ἐλήφθη, καθὼς καὶ ἐν ἄλλοις δεδήλωται.", "st": "13.5.11"}, {"sp": "N", "t": "Τρύφων δ’ ἐπειδὴ τὰ περὶ τὸν Δημήτριον ἔγνω τοιοῦτο λαβόντα τέλος οὐκέτ’ ἦν Ἀντιόχῳ βέβαιος, ἀλλ’ ἐπεβούλευεν ὥστ’ αὐτὸν ἀποκτείνας τὴν βασιλείαν αὐτὸς κατασχεῖν. ἐνεπόδιζέ γε μὴν αὐτοῦ τὴν προαίρεσιν ταύτην ὁ παρὰ Ἰωνάθου φόβος φίλου τυγχάνοντος Ἀντιόχῳ, καὶ διὰ τοῦτ’ ἐκποδὼν ποιήσασθαι τὸν Ἰωνάθην πρῶτον ἔγνω καὶ τότε τοῖς περὶ τὸν Ἀντίοχον ἐγχειρεῖν. ἀπάτῃ δ’ αὐτὸν καὶ δόλῳ κρίνας ἀνελεῖν εἰς Βαιθσὰν ἐκ τῆς Ἀντιοχείας παραγίνεται τὴν καλουμένην ὑφ’ Ἑλλήνων Σκυθόπολιν, εἰς ἣν μετὰ τεσσάρων αὐτῷ μυριάδων Ἰωνάθης ἀπήντησεν ἐπιλέκτου στρατοῦ· πολεμήσοντα γὰρ αὐτὸν ἥκειν ὑπελάμβανεν. ὁ δ’ ἕτοιμον εἰς μάχην γνοὺς τὸν Ἰωνάθην ὑπέρχεται δώροις αὐτὸν καὶ φιλοφρονήσει, καὶ τοῖς ἡγεμόσιν αὐτοῦ πειθαρχεῖν Ἰωνάθῃ προσέταξεν, τούτοις πιστώσασθαι βουλόμενος εὔνοιαν καὶ πᾶσαν ὑπόνοιαν ἐξελεῖν εἰς τὸ καταφρονήσαντα λαβεῖν ἀφύλακτον οὐδὲν προορώμενον. τήν τε στρατιὰν συνεβούλευεν ἀπολῦσαι· καὶ γὰρ νῦν οὐ δεόντως αὐτὴν ἐπάγεσθαι, πολέμου μὲν οὐκ ὄντος, εἰρήνης δὲ ἐχούσης τὰ πράγματα· κατασχόντα μέντοι γε περὶ αὐτὸν ὀλίγους εἰς Πτολεμαΐδα συνελθεῖν παρεκάλει· παραδώσειν γὰρ αὐτῷ τὴν πόλιν τά τε ἄλλα πάνθ’ ὅσα κατὰ τὴν χώραν ἐστὶν ὀχυρώματα ποιήσειν ἐπ’ αὐτῷ· καὶ γὰρ τούτων ἕνεκα παρεῖναι.", "st": "13.6.1"}, {"sp": "N", "t": "Ὁ μὲν οὖν Ἰωνάθης οὐδὲν τούτων ὑπονοήσας, ἀλλ’ ὑπ’ εὐνοίας καὶ γνώμης ἀληθοῦς τὸν Τρύφωνα συμβουλεῦσαι ταῦτα πιστεύσας τὴν μὲν στρατιὰν ἀπέλυσεν, τρισχιλίους δὲ κατασχὼν μόνους τοὺς μὲν δισχιλίους ἐν τῇ Γαλιλαίᾳ κατέλιπεν, αὐτὸς δὲ μετὰ τῶν χιλίων ἧκεν εἰς Πτολεμαΐδα σὺν Τρύφωνι. τῶν δ’ ἐν τῇ Πτολεμαΐδι κλεισάντων τὰς πύλας, τοῦτο γὰρ ἦν αὐτοῖς ὑπὸ τοῦ Τρύφωνος προστεταγμένον, Ἰωνάθην ἐζώγρησεν, τοὺς δὲ σὺν αὐτῷ πάντας ἀπέκτεινεν. ἔπεμψεν δὲ καὶ ἐπὶ τοὺς ἐν τῇ Γαλιλαίᾳ καταλειφθέντας δισχιλίους, ὅπως ἂν καὶ τούτους ἀπολέσωσιν· ἀλλ’ οὗτοι μὲν ὑπὸ φήμης τῶν περὶ τὸν Ἰωνάθην συμβεβηκότων ἔφθησαν πρὶν ἢ τοὺς ὑπὸ Τρύφωνος ἀπεσταλμένους ἀφικέσθαι φραξάμενοι τοῖς ὅπλοις ἐκ τῆς χώρας ἀπελθεῖν. οἱ δ’ ἐπ’ αὐτοὺς πεμφθέντες ἰδόντες ἑτοίμους ὑπὲρ τῶν ψυχῶν ἀγωνίζεσθαι μηδὲν αὐτοῖς ἐνοχλήσαντες πρὸς τὸν Τρύφωνα ὑπέστρεψαν.", "st": "13.6.2"}, {"sp": "N", "t": "Οἱ δ’ ἐν τοῖς Ἱεροσολύμοις ἀκούσαντες τὴν Ἰωνάθου σύλληψιν καὶ τὴν τῶν σὺν αὐτῷ στρατιωτῶν ἀπώλειαν αὐτόν τε ἐκεῖνον ἐπὶ τοῖς συμβεβηκόσιν ὠλοφύροντο καὶ δεινὴ τἀνδρὸς ἐπιζήτησις παρὰ πᾶσιν ἦν, δέος τε μέγα καὶ κατὰ λόγον αὐτοῖς ἐμπεσὸν ἐλύπει, μὴ τῆς Ἰωνάθου ἀνδρείας ἅμα καὶ προνοίας ἀφῃρημένων τὰ πέριξ ἔθνη χαλεπῶς ἔχοντα πρὸς αὐτοὺς καὶ διὰ Ἰωνάθην ἠρεμοῦντα νῦν αὐτοῖς ἐπισυστῇ καὶ πολεμοῦντες εἰς τοὺς περὶ τῶν ἐσχάτων κινδύνους ἀναγκάζωνται καθίστασθαι. καὶ δὴ τοῦτ’ αὐτοῖς ὡς ὑπενόουν συνέπεσεν· τὸν γὰρ Ἰωνάθου ἀκούσαντες θάνατον οἱ ἐκ τῶν ἐθνῶν πολεμεῖν ἤρξαντο τοὺς Ἰουδαίους ὡς ἀποροῦντας ἡγεμόνος. αὐτὸς δ’ ὁ Τρύφων δύναμιν συναγαγὼν γνώμην εἶχεν ἀναβὰς εἰς τὴν Ἰουδαίαν πολεμεῖν τοὺς ἐν αὐτῇ. Σίμων δ’ ὁρῶν πρὸς ταῦτα τοὺς Ἱεροσολυμίτας καταπεπληγότας, βουλόμενος αὐτοὺς εἰς τὸ ὑποστῆναι προθύμως ἐπιόντα τὸν Τρύφωνα θαρραλεωτέρους ποιῆσαι τῷ λόγῳ, συγκαλέσας τὸν δῆμον εἰς τὸν ἱερὸν ἐντεῦθεν αὐτοὺς παρακαλεῖν ἤρξατο· τὸ μὲν ὑπὲρ τῆς ὑμετέρας ἐλευθερίας, ὁμόφυλοι, μετὰ τοῦ πατρὸς ἐγώ τε καὶ οἱ ἀδελφοί μου ὡς ἐτολμήσαμεν ἀσμένως ἀποθανεῖν οὐκέτ’ ἀγνοεῖτε. παραδειγμάτων δὲ τοιούτων εὐποροῦντός μου κἀκ τοῦ θνήσκειν ὑπὲρ τῶν νόμων καὶ τῆς θρησκείας τοὺς ἐκ τῆς ἡμετέρας οἰκίας γενομένους ἡγησαμένου φόβος οὐδὲ εἷς ἔσται τηλικοῦτος, ὃς ταύτην ἡμῶν τὴν διάνοιαν ἐκβαλεῖ τῆς ψυχῆς, ἀντεισάξει δ’ εἰς αὐτὴν φιλοζωΐαν καὶ δόξης καταφρόνησιν. ὅθεν ὡς οὐκ ἀποροῦντες ἡγεμόνος οἵου τε καὶ πάσχειν ὑπὲρ ὑμῶν τὰ μέγιστα καὶ δρᾶν ἕπεσθέ μοι προθύμως ἐφ’ οὓς ἂν ἡγῶμαι· οὔτε γὰρ κρείττων ἐγὼ τῶν ἀδελφῶν τῶν ἐμῶν, ἵνα φείδωμαι τῆς ἐμαυτοῦ ψυχῆς, οὔτε χείρων, ἵν’ ὃ κάλλιστον ἐκείνοις ἔδοξεν τὸ τελευτᾶν ὑπὲρ τῶν νόμων καὶ τῆς τοῦ θεοῦ θρησκείας ὑμῶν τοῦτ’ ἐγὼ φύγω καὶ καταλίπω. οἷς δέ με δεῖ γνήσιον ἐκείνων ἀδελφὸν φανῆναι τούτοις ἀδελφὸν ἐμαυτὸν ἐπιδείξω· θαρρῶ γὰρ ὡς καὶ δίκην ληψόμενος παρὰ τῶν πολεμίων καὶ πάντας ὑμᾶς μετὰ γυναικῶν καὶ τέκνων τῆς ἐξ αὐτῶν ὕβρεως ῥυσόμενος καὶ τὸ ἱερὸν ἀπόρθητον μετὰ τοῦ θεοῦ διαφυλάξων· τὰ γὰρ ἔθνη βλέπω καταφρονήσαντα ὑμῶν ὡς οὐκ ἐχόντων ἡγεμόνα πρὸς τὸ πολεμεῖν ὡρμημένα.", "st": "13.6.3"}, {"sp": "N", "t": "Τούτους ποιησαμένου τοῦ Σίμωνος τοὺς λόγους ἀνεθάρσησεν τὸ πλῆθος, καὶ ταῖς ψυχαῖς ἐνδεδωκὸς ὑπὸ δειλίας ἀνηγέρθη πρὸς τὴν ἀμείνω καὶ ἀγαθὴν ἐλπίδα, ὡς ἀθρόως πάντα τὸν λαὸν ἐκβοῆσαι τὸν Σίμωνα αὐτῶν ἡγεῖσθαι καὶ ἀντὶ Ἰούδου καὶ Ἰωνάθου τῶν ἀδελφῶν αὐτοῦ τὴν προστασίαν ἔχειν· ἔσεσθαι γὰρ πρὸς ὅ τι κελεύσαι πειθηνίους. συναθροίσας δ’ εὐθὺς πᾶν ὅσον ἦν τὸ πολεμικὸν τῆς οἰκείας ἰσχύος ἔσπευδε τὰ τείχη τῆς πόλεως ἀνοικοδομῆσαι, καὶ πύργοις αὐτὴν ὑψηλοτάτοις καὶ καρτεροῖς ἀσφαλισάμενος ἀπέστειλεν μὲν Ἰωνάθην τινὰ φίλον Ἀψαλώμου παῖδα μετὰ στρατιᾶς εἰς Ἰόππην προστάξας αὐτῷ τοὺς οἰκήτορας ἐκβαλεῖν· ἐδεδίει γάρ, μὴ παραδῶσιν οὗτοι τὴν πόλιν τῷ Τρύφωνι. αὐτὸς δ’ ὑπομείνας ἐφύλαττε τὰ Ἱεροσόλυμα.", "st": "13.6.4"}, {"sp": "N", "t": "Ὁ δὲ Τρύφων ἄρας ἐκ Πτολεμαΐδος μετὰ στρατιᾶς πολλῆς εἰς τὴν Ἰουδαίαν παραγίνεται καὶ τὸν Ἰωνάθην δέσμιον ἄγων. ἀπήντησε δ’ αὐτῷ καὶ Σίμων μετὰ τῆς αὐτοῦ δυνάμεως εἰς Ἄδδιδα πόλιν, ἥτις ἐπ’ ὄρους κειμένη τυγχάνει, ὑφ’ ἧς ὑπόκειται τὰ τῆς Ἰουδαίας πεδία. γνοὺς δὲ Τρύφων ἡγεμόνα τὸν Σίμωνα ὑπὸ τῶν Ἰουδαίων καθεσταμένον ἔπεμψεν πρὸς αὐτὸν καὶ τοῦτον ἀπάτῃ καὶ δόλῳ περιελθεῖν βουλόμενος, κελεύων αὐτόν, εἰ θέλει λυθῆναι τὸν ἀδελφὸν Ἰωνάθην, πέμψαι τάλαντα ἑκατὸν ἀργυρίου καὶ δύο τῶν παίδων τῶν Ἰωνάθου ὁμήρους, ὅπως μὴ ἀφεθεὶς ἀποστήσῃ τὴν Ἰουδαίαν βασιλέως· ἄρτι γὰρ αὐτὸν διὰ τὸ ἀργύριον, ὃ τῷ βασιλεῖ χρησάμενος ὤφειλε, φυλάττεσθαι δεδεμένον. ὁ δὲ Σίμων τὴν τέχνην τὴν τοῦ Τρύφωνος οὐκ ἠγνόησεν, ἀλλὰ συνεὶς ὅτι καὶ τὸ ἀργύριον ἀπολέσει δοὺς καὶ τὸν ἀδελφὸν οὐ λύσει, μετ’ αὐτοῦ δὲ καὶ τοὺς παῖδας ἐκδώσει τῷ πολεμίῳ, φοβούμενος δέ, μὴ διαβληθῇ πρὸς τὸ πλῆθος ὡς αἴτιος αὐτὸς τἀδελφῷ θανάτου γενόμενος, ὅτι μήτε τὰ χρήματα μήτε τοὺς υἱοὺς ἔδωκεν ὑπὲρ αὐτοῦ, συναγαγὼν τὴν στρατιὰν ἐδήλωσεν αὐτῇ τὰ παρὰ τοῦ Τρύφωνος, εἰπὼν ὅτι ταῦτα καὶ ἐνέδραν καὶ ἐπιβουλὴν ἔχει· ὅμως αἱρετώτερον εἶναι πέμψαι τὰ χρήματ’ αὐτῷ καὶ τοὺς υἱοὺς ἢ τοῖς ὑπὸ Τρύφωνος προβαλλομένοις μὴ ὑπακούσαντα λαβεῖν αἰτίαν ὡς τὸν ἀδελφὸν σῶσαι μὴ θελήσας. καὶ Σίμων μὲν τούς τε Ἰωνάθου παῖδας ἐξέπεμψεν καὶ τὰ χρήματα. λαβὼν δὲ ὁ Τρύφων οὐκ ἐτήρησεν τὴν πίστιν οὐδὲ ἀπέλυσε τὸν Ἰωνάθην, ἀλλὰ τὴν στρατιὰν ἀναλαβὼν ἐκπεριῆλθε τὴν χώραν καὶ διὰ τῆς Ἰδουμαίας ἀναβαίνειν διεγνώκει τὸ λοιπὸν εἰς Ἱεροσόλυμα, καὶ παραγενόμενος ἧκεν εἰς Ἄδωρα πόλιν τῆς Ἰδουμαίας. ἀντιπαρῆγεν δ’ ὁ Σίμων μετὰ τῆς στρατιᾶς ἀεὶ καταστρατοπεδευόμενος ἐξ ἐναντίας αὐτοῦ.", "st": "13.6.5"}, {"sp": "N", "t": "Τῶν δ’ ἐν τῇ ἄκρᾳ πεμψάντων πρὸς Τρύφωνα καὶ παρακαλούντων σπεῦσαι πρὸς αὐτοὺς καὶ τροφὰς αὐτοῖς πέμψαι, παρεσκεύασε τὴν ἵππον ὡς διὰ τῆς νυκτὸς ἐκείνης ἐν Ἱεροσολύμοις ἐσόμενος. ἀλλὰ χιὼν διὰ νυκτὸς πολλὴ πεσοῦσα καὶ τάς τε ὁδοὺς καλύψασα καὶ ἄπορον ἵπποις μάλιστα πεζεύειν ὑπὸ βάθους τὴν πορείαν παρασχοῦσα διεκώλυσεν αὐτὸν ἐλθεῖν εἰς τὰ Ἱεροσόλυμα. διόπερ ἐκεῖθεν ἄρας ὁ Τρύφων εἰς τὴν κοίλην ἀφικνεῖται Συρίαν, σπουδῇ τε εἰς τὴν Γαλαδῖτιν ἐμβαλὼν τόν τε Ἰωνάθην ἀποκτείνας αὐτόθι καὶ ταφῆναι κελεύσας αὐτὸς εἰς τὴν Ἀντιόχειαν ὑπέστρεψεν. ὁ δὲ Σίμων πέμψας εἰς Βασκὰ πόλιν μετακομίζει τὰ τοῦ ἀδελφοῦ ὀστᾶ, καὶ κηδεύει μὲν ταῦτα ἐν Μωδεεῖ τῇ πατρίδι, πένθος δ’ ἐπ’ αὐτῷ μέγα πᾶς ὁ λαὸς ἐποιήσατο. Σίμων δὲ καὶ μνημεῖον μέγιστον ᾠκοδόμησεν τῷ τε πατρὶ καὶ τοῖς ἀδελφοῖς ἐκ λίθου λευκοῦ καὶ ἀνεξεσμένου. εἰς πολὺ δ’ αὐτὸ καὶ περίοπτον ἀναγαγὼν ὕψος στοὰς περὶ αὐτὸ βάλλεται καὶ στύλους μονολίθους θαυμαστὸν ἰδεῖν χρῆμα ἀνίστησιν, πρὸς τούτοις δὲ καὶ πυραμίδας ἑπτὰ τοῖς τε γονεῦσιν καὶ τοῖς ἀδελφοῖς ἑκάστῳ μίαν ᾠκοδόμησεν εἰς ἔκπληξιν μεγέθους τε ἕνεκα καὶ κάλλους πεποιημένας, αἳ καὶ μέχρι δεῦρο σώζονται. καὶ περὶ μὲν τῆς Ἰωνάθου ταφῆς καὶ τῆς τῶν μνημείων οἰκοδομίας τοῖς οἰκείοις Σίμωνος τοσαύτην σπουδὴν οἴδαμεν γενομένην. ἀπέθανεν δὲ Ἰωνάθης ἀρχιερατεύων ἔτη τέσσαρα προστὰς τοῦ γένους. καὶ τὰ μὲν περὶ τῆς τούτου τελευτῆς ἐν τούτοις ἦν.", "st": "13.6.6"}, {"sp": "N", "t": "Σίμων δὲ κατασταθεὶς ἀρχιερεὺς ὑπὸ τοῦ πλήθους τῷ πρώτῳ τῆς ἀρχιερωσύνης ἔτει τῆς ἐπὶ τοῖς Μακεδόσι δουλείας τὸν λαὸν ἠλευθέρωσεν ὡς μηκέτι φόρους αὐτοῖς τελεῖν· ἡ δὲ ἐλευθερία καὶ τὸ ἀνείσφορον τοῖς Ἰουδαίοις μετὰ ἑβδομήκοντα καὶ ἑκατὸν ἔτη τῶν Συρίας βασιλέων ἐξ οὗ χρόνου Σέλευκος ὁ Νικάτωρ ἐπικληθεὶς κατέσχεν Συρίαν ὑπῆρξεν. τοσαύτη δ’ ἦν ἡ τοῦ πλήθους περὶ τὸν Σίμωνα φιλοτιμία, ὥστ’ ἐν τοῖς πρὸς ἀλλήλους συμβολαίοις καὶ τοῖς δημοσίοις γράμμασιν ἐπὶ πρώτου ἔτους γράφειν Σίμωνος καὶ εὐεργέτου Ἰουδαίων καὶ ἐθνάρχου· εὐτύχησαν γὰρ ἐπ’ αὐτοῦ σφόδρα καὶ τῶν ἐχθρῶν τῶν περιοίκων ἐκράτησαν. κατεστρέψατο γὰρ Σίμων Γάζαρά τε πόλιν καὶ Ἰόππην καὶ Ἰάμνειαν, ἐκπολιορκήσας δὲ καὶ τὴν ἐν τοῖς Ἱεροσολύμοις ἄκραν εἰς ἔδαφος αὐτὴν καθεῖλεν, ὡς ἂν μὴ τοῖς ἐχθροῖς ὁρμητήριον ᾖ καταλαμβανομένοις αὐτὴν τοῦ κακῶς ποιεῖν, ὡς καὶ τότε. καὶ τοῦτο ποιήσας ἄριστον ἐδόκει καὶ συμφέρον καὶ τὸ ὄρος ἐφ’ οὗ τὴν ἄκραν εἶναι συνέβαινεν καθελεῖν, ὅπως ὑψηλότερον ᾖ τὸ ἱερόν. καὶ δὴ τοῦτ’ ἔπειθεν εἰς ἐκκλησίαν καλέσας τὸ πλῆθος ὑπ’ αὐτοῦ γίνεσθαι, ὧν τε ἔπαθον ὑπὸ τῶν φρουρῶν καὶ τῶν φυγάδων Ἰουδαίων ὑπομιμνήσκων, ἅ τε πάθοιεν ἄν, εἰ πάλιν κατάσχοι τὴν βασιλείαν ἀλλόφυλος φρουρᾶς ἐν αὐτῇ κατασταθείσης. ταῦτα λέγων πείθει τὸ πλῆθος παραινῶν αὐτῷ τὰ συμφέροντα. καὶ πάντες προσβαλόντες καθῄρουν τὸ ὄρος καὶ μήτε νυκτὸς μήθ’ ἡμέρας ἀπολυόμενοι τοῦ ἔργου τρισὶν αὐτὸ τοῖς πᾶσιν ἔτεσιν κατήγαγον εἰς ἔδαφος καὶ πεδινὴν λειότητα. καὶ τὸ λοιπὸν ἐξεῖχεν ἁπάντων τὸ ἱερὸν τῆς ἄκρας καὶ τοῦ ὄρους ἐφ’ ᾧ ἦν καθῃρημένων. καὶ τὰ μὲν ἐπὶ Σίμωνος πραχθέντα τοῦτον εἶχεν τὸν τρόπον.", "st": "13.6.7"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ τῆς αἰχμαλωσίας τῆς Δημητρίου τὸν Ἀλεξάνδρου υἱὸν Ἀντίοχον, ὃς καὶ Θεὸς ἐπεκλήθη, Τρύφων διέφθειρεν ἐπιτροπεύων αὐτοῦ τέσσαρα βασιλεύσαντα ἔτη. καὶ τὸν μέν, ὡς χειριζόμενος ἀποθάνοι, διήγγειλεν· τοὺς δὲ φίλους καὶ τοὺς οἰκειοτάτους διέπεμπε πρὸς τοὺς στρατιώτας, ἐπαγγελλόμενος αὐτοῖς χρήματα πολλὰ δώσειν, εἰ βασιλέα χειροτονήσουσιν αὐτόν, Δημήτριον μὲν ὑπὸ Πάρθων αἰχμάλωτον γεγονέναι μηνύων, τὸν δ’ ἀδελφὸν αὐτοῦ Ἀντίοχον παρελθόντα εἰς τὴν ἀρχὴν πολλὰ ποιήσειν αὐτοῖς κακὰ τῆς ἀποστάσεως ἀμυνόμενον. οἱ δ’ ἐλπίσαντες εὐπορίαν ἐκ τῆς Τρύφωνι δοθείσης βασιλείας ἀποδεικνύουσιν αὐτὸν ἄρχοντα. γενόμενος δὲ τῶν πραγμάτων ἐγκρατὴς ὁ Τρύφων διέδειξεν τὴν αὐτοῦ φύσιν οὖσαν πονηράν· ἰδιώτης μὲν γὰρ ὢν ἐθεράπευεν τὸ πλῆθος καὶ μετριότητα ὑπεκρίνατο δελεάζων αὐτὸ τούτοις εἰς ἅπερ ἐβούλετο, τὴν δὲ βασιλείαν λαβὼν ἀπεδύσατο τὴν ὑπόκρισιν καὶ ὁ ἀληθὴς Τρύφων ἦν. τοὺς οὖν ἐχθροὺς διὰ ταῦτ’ ἐποίει κρείττονας· τὸ μὲν γὰρ στρατιωτικὸν αὐτὸν μισοῦν ἀφίστατο πρὸς Κλεοπάτραν τὴν Δημητρίου γυναῖκα τότε ἐν Σελευκείᾳ μετὰ τῶν τέκνων ἐγκεκλεισμένην. ἀλωμένου δὲ καὶ Ἀντιόχου τοῦ Δημητρίου ἀδελφοῦ, ὃς ἐπεκαλεῖτο Σωτήρ, καὶ μηδεμιᾶς αὐτὸν πόλεως δεχομένης διὰ Τρύφωνα, πέμπει πρὸς αὐτὸν Κλεοπάτρα καλοῦσα πρὸς αὐτὴν ἐπί τε γάμῳ καὶ βασιλείᾳ. ἐκάλει δὲ τὸν Ἀντίοχον ἐπὶ τούτοις ἅμα μὲν τῶν φίλων αὐτὴν ἀναπεισάντων, ἅμα δὲ καὶ τὴν πόλιν ἐνδιδόντων τινῶν ἐκ τῆς Σελευκείας τῷ Τρύφωνι δείσασα.", "st": "13.7.1"}, {"sp": "N", "t": "Γενόμενος δ’ ἐν τῇ Σελευκείᾳ ὁ Ἀντίοχος καὶ τῆς ἰσχύος αὐτῷ καθ’ ἡμέραν αὐξανομένης ὥρμησε πολεμήσων τὸν Τρύφωνα, καὶ κρατήσας αὐτοῦ τῇ μάχῃ τῆς ἄνω Συρίας ἐξέβαλεν εἰς τὴν Φοινίκην διώξας ἄχρι ταύτης εἴς τε Δῶρα φρούριόν τι δυσάλωτον ἐπολιόρκει συμφυγόντα. πέμπει δὲ καὶ πρὸς Σίμωνα τὸν τῶν Ἰουδαίων ἀρχιερέα περὶ φιλίας καὶ συμμαχίας πρέσβεις. ὁ δὲ προσδέχεται προθύμως αὐτοῦ τὴν ἀξίωσιν, καὶ χρήματά τε πολλὰ καὶ τροφὴν τοῖς τὰ Δῶρα [στρατιώταις] πολιορκοῦσι πέμψας τὸν Ἀντίοχον ἀφθόνως ἐχορήγησεν, ὡς τῶν ἀναγκαιοτάτων αὐτῷ πρὸς ὀλίγον καιρὸν κριθῆναι φίλων. ὁ μὲν γὰρ Τρύφων ἐκ τῆς Δώρας φυγὼν εἰς Ἀπάμειαν καὶ ληφθεὶς ἐν αὐτῇ πολιορκίᾳ διεφθάρη βασιλεύσας ἔτη τρία.", "st": "13.7.2"}, {"sp": "N", "t": "Ὁ δ’ Ἀντίοχος ὑπὸ πλεονεξίας καὶ φαυλότητος λήθην τῶν ἐκ Σίμωνος αὐτῷ πρὸς τὰς χρείας ὑπηρετηθέντων ἐποιήσατο, καὶ δύναμιν στρατιωτικὴν Κενδεβαίῳ παραδοὺς τῶν φίλων ἐπὶ τὴν τῆς Ἰουδαίας πόρθησιν καὶ τὴν Σίμωνος ἅλωσιν ἐξαπέστειλεν. Σίμων δ’ ἀκούσας τὴν Ἀντιόχου παρανομίαν καὶ πρεσβύτερος ὢν ἤδη ὅμως ὑπὸ τοῦ μὴ δικαίων τῶν παρ’ Ἀντιόχου γινομένων τυγχάνειν παρορμηθεὶς καὶ τῆς ἡλικίας φρόνημα κρεῖττον λαβὼν νεανικῶς ἐστρατήγει τοῦ πολέμου. καὶ τοὺς μὲν υἱεῖς μετὰ τῶν μαχιμωτέρων προεκπέμπει στρατιωτῶν, αὐτὸς δὲ κατ’ ἄλλο μέρος προῄει μετὰ τῆς δυνάμεως, καὶ πολλοὺς ἐν τοῖς φαραγγώδεσι τῶν ὀρῶν τούτους εἰς ἐνέδραν καταστήσας διαμαρτάνει μὲν οὐδεμιᾶς τῶν ἐπιχειρήσεων, κρατήσας δὲ διὰ πάσης τῶν πολεμίων ἐν εἰρήνῃ τὸν λοιπὸν διήγαγεν χρόνον, ποιησάμενος καὶ αὐτὸς πρὸς Ῥωμαίους συμμαχίαν.", "st": "13.7.3"}, {"sp": "N", "t": "Ἦρξε μὲν οὖν ὀκτὼ τὰ πάντα τῶν Ἰουδαίων ἔτη, τελευτᾷ δὲ ἐξ ἐπιβουλῆς ἐν συμποσίῳ Πτολεμαίου τοῦ γαμβροῦ ταύτην ἐπ’ αὐτὸν συστησαμένου, ὃς καὶ τὴν γυναῖκα αὐτοῦ καὶ τοὺς δύο παῖδας συλλαβὼν καὶ δεδεμένους ἔχων ἔπεμψεν καὶ ἐπὶ Ἰωάννην τὸν τρίτον, τούτῳ δὲ καὶ Ὑρκανὸς ἦν ὄνομα, τοὺς διαφθεροῦντας. αἰσθόμενος δὲ τοὺς ἐλθόντας ὁ νεανίσκος διαφυγὼν τὸν ἐξ αὐτῶν κίνδυνον εἰς τὴν πόλιν ἠπείγετο, θαρρῶν τῷ πλήθει διὰ τὰς τοῦ πατρὸς εὐεργεσίας καὶ διὰ τὸ Πτολεμαίου τοῖς ὄχλοις μῖσος. σπουδάσαντα δὲ καὶ Πτολεμαῖον εἰσελθεῖν δι’ ἄλλης πύλης ὁ δῆμος ἀπεώσατο τὸν Ὑρκανὸν ἤδη προσδεδεγμένος.", "st": "13.7.4"}, {"sp": "N", "t": "Καὶ ὁ μὲν εἰς ἕν τι τῶν ὑπὲρ Ἱεριχοῦντος ἐρυμάτων ἀνεχώρησεν Δαγὼν λεγόμενον. ἀπολαβὼν δὲ τὴν πάτριον ἀρχιερωσύνην Ὑρκανὸς καὶ τὸν θεὸν πρώταις θυσίαις παραστησάμενος ἐπὶ τὸν Πτολεμαῖον ἐξεστράτευσεν, καὶ προσβαλὼν τῷ χωρίῳ τοῖς μὲν ἄλλοις περιῆν αὐτοῦ, ἡττᾶτο δὲ μόνῳ τῷ πρὸς τὴν μητέρα καὶ τοὺς ἀδελφοὺς οἴκτῳ. τούτους γὰρ Πτολεμαῖος ἀναγαγὼν ἐπὶ τὸ τεῖχος ἐξ ἀπόπτου ᾐκίζετο καὶ κατακρημνίσειν οὐκ ἀφισταμένου τῆς πολιορκίας ἠπείλει. ὁ δ’ ὅσον [ἂν] ἐνδοίη τῆς περὶ τὴν αἵρεσιν τοῦ χωρίου σπουδῆς, τοσοῦτο χαρίζεσθαι τοῖς φιλτάτοις ἡγούμενος πρὸς τὸ μὴ κακῶς πάσχειν, ἐξέλυε τὸ πρόθυμον. ἡ μέντοι μήτηρ ὀρέγουσα τὰς χεῖρας ἱκέτευε μὴ μαλακίζεσθαι δι’ αὐτήν, ἀλλὰ πολὺ πλέον ὀργῇ χρώμενον ἑλεῖν σπουδάσαι τὸ χωρίον καὶ τὸν ἐχθρὸν ὑπ’ αὐτῷ ποιήσαντα τιμωρῆσαι τοῖς φιλτάτοις· ἡδὺν γὰρ αὐτῇ τὸν μετ’ αἰκίας [εἶναι] θάνατον, εἰ δίκην ὑπόσχοι τῆς εἰς αὐτοὺς παρανομίας ὁ ταῦτα ποιῶν πολέμιος. τὸν δὲ Ὑρκανὸν ταῦτα μὲν λεγούσης τῆς μητρὸς ὁρμή τις ἐλάμβανεν πρὸς τὴν αἵρεσιν τοῦ φρουρίου, ἡνίκα δ’ αὐτὴν ἴδοι τυπτομένην καὶ σπαραττομένην, ἐξελύετο καὶ τῆς ἐπὶ τοῖς εἰς τὴν μητέρα πραττομένοις συμπαθείας ἥττων ἐγίνετο. ἑλκομένης δ’ οὕτως εἰς χρόνον τῆς πολιορκίας ἐνίσταται τὸ ἔτος ἐκεῖνο, καθ’ ὃ συμβαίνει τοὺς Ἰουδαίους ἀργεῖν· κατὰ δὲ ἑπτὰ ἔτη τοῦτο παρατηροῦσιν, ὡς ἐν ταῖς ἑβδομάσιν ἡμέραις. καὶ Πτολεμαῖος, ὑπὸ ταύτης ἀνεθεὶς τοῦ πολέμου τῆς αἰτίας ἀποκτείνει τοὺς ἀδελφοὺς τοῦ Ὑρκανοῦ καὶ τὴν μητέρα καὶ τοῦτο δράσας πρὸς Ζήνωνα φεύγει τὸν ἐπικληθέντα Κοτυλᾶν, τυραννεύοντα τῆς Φιλαδελφέων πόλεως.", "st": "13.8.1"}, {"sp": "N", "t": "Ἀντίοχος δὲ χαλεπῶς ἔχων ἐφ’ οἷς ὑπὸ Σίμωνος ἔπαθεν εἰς τὴν Ἰουδαίαν ἐνέβαλεν τετάρτῳ μὲν ἔτει τῆς βασιλείας αὐτοῦ, πρώτῳ δὲ τῆς Ὑρκανοῦ ἀρχῆς, ὀλυμπιάδι ἑκατοστῇ καὶ ἑξηκοστῇ καὶ δευτέρᾳ. δῃώσας δὲ τὴν χώραν τὸν Ὑρκανὸν εἰς αὐτὴν ἐνέκλεισε τὴν πόλιν, ἣν ἑπτὰ στρατοπέδοις περιλαβὼν ἤνυσε μὲν οὐδὲν ὅλως τὸ πρῶτον διά τε τὴν τῶν τειχῶν ὀχυρότητα καὶ δι’ ἀρετὴν τῶν ἐμπολιορκουμένων ἔτι γε μὴν ὕδατος ἀπορίαν, ἧς αὐτοὺς ἀπέλυσεν ὄμβρος κατενεχθεὶς πολὺς δυομένης πλειάδος. κατὰ δὲ τὸ βόρειον μέρος τοῦ τείχους, καθ’ ὃ συνέβαινεν αὐτὸ καὶ ἐπίπεδον εἶναι, πύργους ἀναστήσας ἑκατὸν τριωρόφους ἀνεβίβασεν ἐπ’ αὐτοὺς στρατιωτικὰ τάγματα. καὶ προσβολὰς ὁσημέραι ποιησάμενος τάφρον τε βαθεῖαν καὶ πολλὴν τὸ εὖρος καὶ διπλῆν τεμόμενος, ἀπετείχισεν τοὺς ἐνοικοῦντας. οἱ δὲ πολλὰς ἐκδρομὰς ἀντεπινοοῦντες, εἰ μὲν ἀφυλάκτοις που προσπέσοιεν τοῖς πολεμίοις, πολλὰ ἔδρων αὐτούς, αἰσθομένων δὲ ἀνεχώρουν εὐχερῶς. ἐπεὶ δὲ βλαβερὰν κατενόησεν Ὑρκανὸς τὴν πολυανθρωπίαν, ἀναλισκομένων τε τῶν ἐπιτηδείων τάχιον ὑπ’ αὐτῆς καὶ μηδενὸς οἷον εἰκὸς ἐκ πολυχειρίας ἔργου γιγνομένου, τὸ μὲν ἀχρεῖον αὐτῆς ἀποκρίνας ἐξέβαλεν, ὅσον δ’ ἦν ἀκμαῖον καὶ μάχιμον τοῦτο μόνον κατέσχεν. Ἀντίοχος μὲν οὖν τοὺς ἀπολεχθέντας ἐξελθεῖν ἐκώλυεν, οἱ δ’ ἐν τοῖς μεταξὺ τείχεσι κακούμενοι ταῖς βασάνοις ἀπέθνησκον οἰκτρῶς. ἐπιστάσης γε μὴν τῆς σκηνοπηγίας ἑορτῆς ἐλεοῦντες αὐτοὺς οἱ ἐντὸς πάλιν εἰσεδέξαντο. πέμψαντος δ’ Ὑρκανοῦ πρὸς Ἀντίοχον καὶ σπονδὰς ἡμερῶν ἑπτὰ διὰ τὴν ἑορτὴν ἀξιώσαντος γενέσθαι, τῇ πρὸς τὸ θεῖον εὐσεβείᾳ εἴκων σπένδεται καὶ προσέτι θυσίαν εἰσέπεμψε μεγαλοπρεπῆ, ταύρους χρυσοκέρωτας καὶ μεστὰ παντοίων ἀρωμάτων ἐκπώματα χρύσεά τε καὶ ἀργύρεα. καὶ τὴν μὲν θυσίαν δεξάμενοι παρὰ τῶν κομιζόντων οἱ πρὸς ταῖς πύλαις ὄντες ἄγουσιν εἰς τὸ ἱερόν, Ἀντίοχος δὲ τὴν στρατιὰν εἱστία, πλεῖστον Ἀντιόχου τοῦ Ἐπιφανοῦς διενέγκας, ὃς τὴν πόλιν ἑλὼν ὗς μὲν κατέθυσεν ἐπὶ τὸν βωμόν, τὸν νεὼν δὲ τῷ ζωμῷ τούτων περιέρρανε συγχέας τὰ Ἰουδαίων νόμιμα καὶ τὴν πάτριον αὐτῶν εὐσέβειαν, ἐφ’ οἷς ἐξεπολεμώθη τὸ ἔθνος καὶ ἀκαταλλάκτως εἶχεν. τοῦτον μέντοι τὸν Ἀντίοχον δι’ ὑπερβολὴν τῆς θρησκείας Εὐσεβῆ πάντες ἐκάλεσαν.", "st": "13.8.2"}, {"sp": "N", "t": "Ἀποδεξάμενος δὲ αὐτοῦ τὴν ἐπιείκειαν Ὑρκανὸς καὶ μαθὼν τὴν περὶ τὸ θεῖον σπουδὴν ἐπρεσβεύσατο πρὸς αὐτόν, ἀξιῶν τὴν πάτριον αὐτοῖς πολιτείαν ἀποδοῦναι. ὁ δὲ ἀπωσάμενος τὴν ἐπιβουλὴν τῶν μὲν παραινούντων ἐξελεῖν τὸ ἔθνος διὰ τὴν πρὸς ἄλλους αὐτῶν τῆς διαίτης ἀμιξίαν οὐκ ἐφρόντιζεν, πειθόμενος δὲ κατ’ εὐσέβειαν πάντα ποιεῖν τοῖς πρεσβευταῖς ἀπεκρίνατο, παραδοῦναι μὲν τὰ ὅπλα τοὺς πολιορκουμένους καὶ δασμὸν αὐτῷ τελεῖν Ἰόππης καὶ τῶν ἄλλων πόλεων πάρεξ τῆς Ἰουδαίας φρουράν τε δεξαμένους ἐπὶ τούτοις ἀπηλλάχθαι τοῦ πολέμου. οἱ δὲ τἆλλα μὲν ὑπομένειν, τὴν δὲ φρουρὰν οὐχ ὡμολόγουν διὰ τὴν ἀμιξίαν οὐκ ἐφικνούμενοι πρὸς ἄλλους. ἀντὶ μέντοι γε τῆς φρουρᾶς ὁμήρους ἐδίδοσαν καὶ τάλαντα ἀργυρίου πεντακόσια, ὧν εὐθὺς τὰ τριακόσια καὶ τοὺς ὁμήρους προσδεξαμένου τοῦ βασιλέως ἔδοσαν, ἐν οἷς ἦν καὶ Ὑρκανοῦ ἀδελφός, καθεῖλεν δὲ καὶ τὴν στεφάνην τῆς πόλεως. ἐπὶ τούτοις μὲν οὖν Ἀντίοχος τὴν πολιορκίαν λύσας ἀνεχώρησεν.", "st": "13.8.3"}, {"sp": "N", "t": "Ὑρκανὸς δὲ τὸν Δαυίδου τάφον ἀνοίξας, ὃς πλούτῳ τούς ποτε βασιλεῖς ὑπερέβαλεν, τρισχίλια μὲν ἀργυρίου τάλαντα ἐξεκόμισεν, ὁρμώμενος δ’ ὑπὸ τούτων πρῶτος Ἰουδαίων ξενοτροφεῖν ἤρξατο. γίνεται δ’ αὐτῷ καὶ πρὸς Ἀντίοχον φιλία καὶ συμμαχία, καὶ δεξάμενος αὐτὸν εἰς τὴν πόλιν ἀφθόνως πάντα τῇ στρατιᾷ καὶ φιλοτίμως παρέσχεν. καὶ ποιουμένῳ τὴν ἐπὶ Πάρθους αὐτῷ στρατείαν συνεξώρμησεν Ὑρκανός. μάρτυς δὲ τούτων ἡμῖν ἐστιν καὶ Νικόλαος ὁ Δαμασκηνὸς οὕτως ἱστορῶν· τρόπαιον δὲ στήσας Ἀντίοχος ἐπὶ τῷ Λύκῳ ποταμῷ νικήσας Ἰνδάτην τὸν Πάρθων στρατηγὸν αὐτόθι ἔμεινεν ἡμέρας δύο δεηθέντος Ὑρκανοῦ τοῦ Ἰουδαίου διά τινα ἑορτὴν πάτριον, ἐν ᾗ τοῖς Ἰουδαίοις οὐκ ἦν νόμιμον ἐξοδεύειν. καὶ ταῦτα μὲν οὐ ψεύδεται λέγων· ἐνέστη γὰρ ἡ πεντηκοστὴ ἑορτὴ μετὰ τὸ σάββατον, οὐκ ἔξεστι δ’ ἡμῖν οὔτε τοῖς σαββάτοις οὔτ’ ἐν τῇ ἑορτῇ ὁδεύειν. συμβαλὼν δ’ Ἀντίοχος Ἀρσάκῃ τῷ Πάρθῳ πολλήν τε τῆς στρατιᾶς ἀπέβαλεν καὶ αὐτὸς ἀπόλλυται, τὴν δὲ τῶν Σύρων βασιλείαν ὁ ἀδελφὸς αὐτοῦ διαδέχεται Δημήτριος Ἀρσάκου αὐτὸν ἐκ τῆς αἰχμαλωσίας ἀπολύσαντος καθ’ ὃν χρόνον Ἀντίοχος εἰς τὴν Παρθυηνὴν ἐνέβαλεν, ὡς καὶ πρότερον ἐν ἄλλοις δεδήλωται.", "st": "13.8.4"}, {"sp": "N", "t": "Ὑρκανὸς δὲ ἀκούσας τὸν Ἀντιόχου θάνατον εὐθὺς ἐπὶ τὰς ἐν Συρίᾳ πόλεις ἐξεστράτευσεν οἰόμενος αὐτὰς εὑρήσειν, ὅπερ ἦν, ἐρήμους τῶν μαχίμων καὶ ῥύεσθαι δυναμένων. Μήδαβαν μὲν οὖν πολλὰ τῆς στρατιᾶς αὐτῷ ταλαιπωρηθείσης ἕκτῳ μηνὶ εἷλεν, ἔπειτα καὶ Σαμόγαν καὶ τὰ πλησίον εὐθὺς αἱρεῖ Σίκιμά τε πρὸς τούτοις καὶ Γαριζεὶν τό τε Κουθαίων γένος, ὃ περιοικεῖ τὸν εἰκασθέντα τῷ ἐν Ἱεροσολύμοις ἱερῷ ναόν, ὃν Ἀλέξανδρος ἐπέτρεψεν οἰκοδομῆσαι Σαναβαλλέτῃ τῷ στρατηγῷ διὰ τὸν γαμβρὸν Μανασσῆν τὸν Ἰαδδοῦς τοῦ ἀρχιερέως ἀδελφόν, ὡς πρότερον δεδηλώκαμεν. συνέβη δὲ τὸν ναὸν τοῦτον ἔρημον γενέσθαι μετὰ ἔτη διακόσια. Ὑρκανὸς δὲ καὶ τῆς Ἰδουμαίας αἱρεῖ πόλεις Ἄδωρα καὶ Μάρισαν, καὶ ἅπαντας τοὺς Ἰδουμαίους ὑπὸ χεῖρα ποιησάμενος ἐπέτρεψεν αὐτοῖς μένειν ἐν τῇ χώρᾳ, εἰ περιτέμνοιντο τὰ αἰδοῖα καὶ τοῖς Ἰουδαίων νόμοις χρήσασθαι θέλοιεν. οἱ δὲ πόθῳ τῆς πατρίου γῆς καὶ τὴν περιτομὴν καὶ τὴν ἄλλην τοῦ βίου δίαιταν ὑπέμειναν τὴν αὐτὴν Ἰουδαίοις ποιήσασθαι. κἀκείνοις αὐτοῖς χρόνος ὑπῆρχεν ὥστε εἶναι τὸ λοιπὸν Ἰουδαίους.", "st": "13.9.1"}, {"sp": "N", "t": "Ὑρκανὸς δὲ ὁ ἀρχιερεὺς ἀνανεώσασθαι τὴν πρὸς Ῥωμαίους φιλίαν βουλόμενος πέμπει πρὸς αὐτοὺς πρεσβείαν. καὶ ἡ σύγκλητος δεξαμένη τὰ παρ’ αὐτοῦ γράμματα ποιεῖται πρὸς αὐτὸν φιλίαν τούτῳ τῷ τρόπῳ· Φάννιος Μάρκου υἱὸς στρατηγὸς βουλὴν ἤγαγεν πρὸ ὀκτὼ εἰδῶν Φεβρουαρίων ἐν Κομιτίῳ παρόντος Λουκίου Μαννίου Λουκίου υἱοῦ Μεντίνα καὶ Γαΐου Σεμπρωνίου πενναίου υἱοῦ Φαλέρνα περὶ ὧν ἐπρέσβευσεν Σίμων Δοσιθέου καὶ Ἀπολλώνιος Ἀλεξάνδρου καὶ Διόδωρος Ἰάσονος ἄνδρες καλοὶ καὶ ἀγαθοὶ πεμφθέντες ὑπὸ δήμου τοῦ Ἰουδαίων, [οἳ] καὶ διελέχθησαν περὶ φιλίας τῆς ὑπαρχούσης τούτοις καὶ συμμαχίας πρὸς Ῥωμαίους καὶ τῶν δημοσίων πραγμάτων, ὅπως τε Ἰόππη καὶ λιμένες καὶ Γάζωρα καὶ πηγαὶ καὶ ὅσας πόλεις αὐτῶν ἄλλας καὶ χωρία πολεμῶν ἔλαβεν Ἀντίοχος παρὰ τὸ τῆς συγκλήτου δόγμα ταῦτα ἀποκατασταθῇ, ἵνα τε τοῖς στρατιώταις τοῖς βασιλικοῖς μὴ ἐξῇ διὰ τῆς χώρας τῆς αὐτῶν καὶ τῶν ὑπηκόων αὐτῶν διέρχεσθαι, καὶ ὅπως τὰ κατὰ τὸν πόλεμον ἐκεῖνον ψηφισθέντα ὑπὸ Ἀντιόχου παρὰ τὸ τῆς συγκλήτου δόγμα ἄκυρα γένηται, ἵνα τε πρέσβεις πέμψαντες ἀποδοθῆναί τε αὐτοῖς ποιήσωσιν τὰ ὑπ’ Ἀντιόχου ἀφαιρεθέντα καὶ τὴν χώραν διατιμήσωνται τὴν ἐν τῷ πολέμῳ διεφθαρμένην, ὅπως τε αὐτοῖς πρός τε βασιλεῖς καὶ δήμους ἐλευθέρους γράμματα δῶσιν εἰς ἀσφάλειαν τῆς εἰς οἶκον ἐπανόδου. ἔδοξεν οὖν περὶ τούτων ταῦτα· ἀνανεώσασθαι φιλίαν καὶ συμμαχίαν πρὸς ἄνδρας ἀγαθοὺς καὶ ὑπὸ δήμου πεμφθέντας ἀγαθοῦ καὶ φίλου. περὶ μέντοι γραμμάτων ἀπεκρίναντο βουλεύσεσθαι, ὅταν ἀπὸ τῶν ἰδίων ἡ σύγκλητος εὐσχολήσῃ, σπουδάσειν τε τοῦ λοιποῦ μηδὲν εἰς αὐτοὺς ἀδίκημα τοιοῦτο γενέσθαι, δοῦναί τε αὐτοῖς τὸν στρατηγὸν Φάννιον χρήματα ἐκ τοῦ δημοσίου, ὅπως ἂν εἰς τὴν οἰκείαν ἐπανέλθοιεν. Φάννιος μὲν οὖν οὕτως ἀποπέμπει τοὺς τῶν Ἰουδαίων πρέσβεις χρήματά τε δοὺς αὐτοῖς ἐκ τοῦ δημοσίου καὶ δόγμα συγκλήτου πρὸς τοὺς διαπέμψοντας καὶ ἀσφαλῆ παρεξομένους τὴν οἴκαδε παρουσίαν.", "st": "13.9.2"}, {"sp": "N", "t": "Τὰ μὲν οὖν περὶ Ὑρκανὸν τὸν ἀρχιερέα ἐν τούτοις ὑπῆρχεν, Δημητρίῳ δὲ τῷ βασιλεῖ προθυμουμένῳ στρατεύειν ἐπὶ Ὑρκανὸν οὐκ ἐξεγένετο καιρὸς οὐδὲ ἀφορμὴ τῶν τε Σύρων καὶ τῶν στρατιωτῶν πρὸς αὐτὸν ἀπεχθανομένων, πονηρὸς γὰρ ἦν, καὶ πεμψάντων πρὸς Πτολεμαῖον τὸν Φύσκωνα ἐπικληθέντα πρέσβεις, ὅπως τινὰ τῶν ἐκ τοῦ Σελεύκου γένους παραδῷ αὐτοῖς ἀποληψόμενον τὴν βασιλείαν. τοῦ δὲ Πτολεμαίου πέμψαντος Ἀλέξανδρον μετὰ στρατιᾶς τὸν Ζεβίναν ἐπιλεγόμενον καὶ μάχης πρὸς τὸν Δημήτριον γενομένης, ὁ μὲν ἡττηθεὶς τῇ μάχῃ φεύγει πρὸς Κλεοπάτραν τὴν γυναῖκα εἰς Πτολεμαΐδα καὶ μὴ δεξαμένης αὐτὸν τῆς γυναικὸς ἐκεῖθεν ἀπελθὼν εἰς Τύρον ἁλίσκεται καὶ πολλὰ παθὼν ὑπὸ τῶν μισούντων ἀπέθανεν. Ἀλέξανδρος δὲ τὴν βασιλείαν παραλαβὼν φιλίαν ποιεῖται πρὸς Ὑρκανὸν τὸν ἀρχιερέα. ἔπειτα πολεμήσαντος αὐτῷ τοῦ Δημητρίου παιδὸς Ἀντιόχου τοῦ Γρυποῦ ἐπικληθέντος, ἡττηθεὶς τῇ μάχῃ διαφθείρεται.", "st": "13.9.3"}, {"sp": "N", "t": "Παραλαβὼν δὲ τὴν τῆς Συρίας βασιλείαν ὁ Ἀντίοχος ἐπὶ μὲν τὴν Ἰουδαίαν στρατεύειν εὐλαβὴς ἦν τὸν ἀδελφὸν ἀκούων τὸν ὁμομήτριον, Ἀντίοχος δὲ κἀκεῖνος ἐκαλεῖτο, δύναμιν ἐπ’ αὐτὸν ἀπὸ Κυζίκου συλλέγειν. μένων δὲ κατὰ χώραν ἔγνω παρασκευάζειν αὑτὸν πρὸς τὴν ἔφοδον τὴν τἀδελφοῦ, ὃς Κυζικηνὸς μὲν ἐπεκλήθη διὰ τὸ τραφῆναι ἐν ταύτῃ τῇ πόλει, πατρὸς δ’ ἦν Ἀντιόχου τοῦ Σωτῆρος ἐπικληθέντος, ὃς ἐν Πάρθοις ἀπέθανεν· οὗτος δὲ ἀδελφὸς ἦν Δημητρίου τοῦ Γρυποῦ πατρός. συνέβη μέντοι μίαν τοῖς δυσὶν ἀδελφοῖς γῆμαι Κλεοπάτραν, ὡς καὶ ἐν ἄλλοις ἱστορήκαμεν. ὁ δὲ Κυζικηνὸς Ἀντίοχος παραγενόμενος εἰς τὴν Συρίαν πολλοῖς ἔτεσιν πρὸς τὸν ἀδελφὸν πολεμῶν διετέλει. Ὑρκανὸς δὲ πάντα ἐκεῖνον τὸν χρόνον ἐν εἰρήνῃ διῆγεν· καὶ γὰρ αὐτὸς μετὰ τὴν Ἀντιόχου τελευτὴν τῶν Μακεδόνων ἀπέστη καὶ οὔτε ὡς ὑπήκοος οὔτε ὡς φίλος αὐτοῖς οὐδὲν ἔτι παρεῖχεν, ἀλλ’ ἦν αὐτῷ τὰ πράγματα ἐν ἐπιδόσει πολλῇ καὶ ἀκμῇ κατὰ τοὺς Ἀλεξάνδρου τοῦ Ζαβιναίου καιρούς, καὶ μάλιστ’ ἐπὶ τούτοις τοῖς ἀδελφοῖς. ὁ γὰρ πρὸς ἀλλήλους αὐτοῖς πόλεμος σχολὴν Ὑρκανῷ καρποῦσθαι τὴν Ἰουδαίαν ἐπ’ ἀδείας παρεῖχεν, ὡς ἄπειρόν τι χρημάτων πλῆθος συναγαγεῖν. τοῦ μέντοι γε Κυζικηνοῦ τὴν γῆν κακοῦντος φανερῶς καὶ αὐτὸς τὴν αὐτοῦ προαίρεσιν ἐπεδείκνυτο, καὶ τῶν ἀπ’ Αἰγύπτου συμμάχων ἔρημον ὁρῶν τὸν Ἀντίοχον καὶ αὐτόν τε πράττοντα κακῶς καὶ τὸν ἀδελφὸν αὐτοῦ ἐν τοῖς πρὸς ἀλλήλους ἀγῶσιν, ἀμφοτέρων κατεφρόνησεν.", "st": "13.10.1"}, {"sp": "N", "t": "Καὶ στρατεύει μὲν ἐπὶ Σαμάρειαν πόλιν ὀχυρωτάτην, περὶ ἧς, ὅτι καλεῖται νῦν Σεβαστὴ κτισθεῖσα ὑπὸ Ἡρώδου, κατὰ χώραν δηλώσομεν. προσβαλὼν δ’ αὐτῇ φιλοπόνως ἐπολιόρκει μισοπονηρῶν τοῖς Σαμαρεῦσιν ὑπὲρ ὧν Μαρισηνοὺς ἀποίκους ὄντας Ἰουδαίων καὶ συμμάχους ἠδίκησαν ὑπακούοντες τοῖς τῶν Σύρων βασιλεῦσιν. περιβαλὼν οὖν τάφρον πανταχόθεν τῇ πόλει καὶ διπλοῦν τεῖχος ὡς ἀπὸ σταδίων ὀγδοήκοντα τοὺς υἱοὺς ἐφίστησιν Ἀντίγονον καὶ Ἀριστόβουλον. ὧν ἐπικειμένων εἰς τοῦτο ἀνάγκης ὑπὸ λιμοῦ προαχθῆναι τοὺς Σαμαρεῖς συνέπεσεν, ὡς ἅψασθαι μὲν καὶ τῶν ἀήθων, ἐπικαλέσασθαι δὲ βοηθὸν Ἀντίοχον τὸν Κυζικηνόν. ὃς ἑτοίμως ἐπὶ τὴν συμμαχίαν ἀφικόμενος ὑπὸ τῶν περὶ Ἀριστόβουλον ἡττᾶται, διωχθεὶς δ’ ἄχρι Σκυθοπόλεως ὑπὸ τῶν ἀδελφῶν διέφυγεν. οἱ δ’ ἐπὶ τοὺς Σαμαρεῖς ὑποστρέψαντες συγκλείουσι πάλιν εἰς τὸ τεῖχος αὐτούς, ὡς καὶ δεύτερον ἐπικαλέσασθαι σύμμαχον πέμψαντες τὸν αὐτὸν Ἀντίοχον. ὃς παρὰ Πτολεμαίου τοῦ Λαθούρου μεταπεμψάμενος ἄνδρας εἰς ἑξακισχιλίους, οὓς ἀκούσης τῆς μητρὸς ἐκεῖνος καὶ ὅσον οὔπω τῆς ἀρχῆς αὐτὸν ἐκβεβληκυίας ἐξαπέστειλεν, τὸ μὲν πρῶτον ἐπιὼν ἐπόρθει τὴν Ὑρκανοῦ χώραν μετὰ τῶν Αἰγυπτίων λῃστρικῶς, μάχεσθαι μὲν αὐτῷ κατὰ πρόσωπον οὐ τολμῶν, οὐ γὰρ ἦν ἀξιόχρεως ἡ δύναμις αὐτοῦ, νομίζων δὲ τῇ κακώσει τῆς γῆς ἀναγκάσειν Ὑρκανὸν λῦσαι τὴν τῆς Σαμαρείας πολιορκίαν. ἐπεὶ δὲ πολλοὺς τῶν στρατιωτῶν ἀπώλλυεν ἐνέδραις περιπίπτων, ἀπῆρεν εἰς Τρίπολιν Καλλιμάνδρῳ καὶ Ἐπικράτει τὸν πρὸς τοὺς Ἰουδαίους πόλεμον ἐπιτρέψας.", "st": "13.10.2"}, {"sp": "N", "t": "Καλλίμανδρος μὲν οὖν θρασύτερον τοῖς πολεμίοις προσενεχθεὶς εἰς φυγὴν τραπόμενος παραχρῆμα διεφθάρη. Ἐπικράτης δὲ ὑπὸ φιλοχρηματίας τήν τε Σκυθόπολιν καὶ τὰ ἄλλα πρὸς ταύτῃ χωρία προύδωκε φανερῶς τοῖς Ἰουδαίοις, τὴν δὲ Σαμαρείας πολιορκίαν διαλύειν οὐκ ἠδύνατο. Ὑρκανὸς μὲν οὖν τὴν πόλιν ἑλὼν ἐνιαυτῷ πολιορκήσας οὐκ ἠρκέσθη μόνῳ τούτῳ, ἀλλὰ καὶ πᾶσαν αὐτὴν ἠφάνισεν ἐπίκλυστον τοῖς χειμάρροις ποιήσας· διασκάψας γὰρ αὐτὴν ὥστ’ εἰς χαράδρας μεταπεσεῖν τὰ σημεῖα τοῦ γενέσθαι ποτὲ πόλιν αὐτὴν ἀφείλετο. παράδοξον δέ τι καὶ περὶ τοῦ ἀρχιερέως Ὑρκανοῦ λέγεται, τίνα τρόπον αὐτῷ τὸ θεῖον εἰς λόγους ἦλθεν· φασὶν γάρ, ὅτι κατ’ ἐκείνην τὴν ἡμέραν, καθ’ ἣν οἱ παῖδες αὐτοῦ τῷ Κυζικηνῷ συνέβαλον, αὐτὸς ἐν τῷ ναῷ θυμιῶν μόνος ὢν ἀρχιερεὺς ἀκούσειε φωνῆς, ὡς οἱ παῖδες αὐτοῦ νενικήκασιν ἀρτίως τὸν Ἀντίοχον. καὶ τοῦτο προελθὼν ἐκ τοῦ ναοῦ παντὶ τῷ πλήθει φανερὸν ἐποίησεν, καὶ συνέβη οὕτως γενέσθαι. καὶ τὰ μὲν περὶ Ὑρκανὸν ἐν τούτοις ἦν.", "st": "13.10.3"}, {"sp": "N", "t": "Κατὰ δὲ τοῦτον ἔτυχε τὸν καιρὸν μὴ μόνον τοὺς ἐν Ἱεροσολύμοις καὶ τῇ χώρᾳ Ἰουδαίους εὐπραγεῖν, ἀλλὰ καὶ τοὺς ἐν Ἀλεξανδρείᾳ κατοικοῦντας καὶ ἐν Αἰγύπτῳ καὶ Κύπρῳ· Κλεοπάτρα γὰρ ἡ βασίλισσα πρὸς τὸν υἱὸν στασιάζουσα Πτολεμαῖον τὸν Λάθουρον ἐπιλεγόμενον κατέστησεν ἡγεμόνας Χελκίαν καὶ Ἀνανίαν υἱοὺς ὄντας Ὀνίου τοῦ οἰκοδομήσαντος τὸν ναὸν ἐν τῷ Ἡλιοπολίτῃ νομῷ πρὸς τὸν ἐν τοῖς Ἱεροσολύμοις, ὡς καὶ πρόσθεν δεδηλώκαμεν. παραδοῦσα δὲ τούτοις ἡ Κλεοπάτρα τὴν στρατιὰν οὐδὲν δίχα τῆς τούτων γνώμης ἔπραττεν, ὡς μαρτυρεῖ καὶ Στράβων ἡμῖν ὁ Καππάδοξ λέγων οὕτως· οἱ γὰρ πλείους, οἵ τε συνελθόντες καὶ οἱ ὕστερον ἐπιπεμπόμενοι παρὰ τῆς Κλεοπάτρας εἰς Κύπρον, μετεβάλοντο παραχρῆμα πρὸς τὸν Πτολεμαῖον· μόνοι δὲ οἱ ἐκ τῆς Ὀνίου γενόμενοι Ἰουδαῖοι συνέμενον διὰ τὸ τοὺς πολίτας αὐτῶν εὐδοκιμεῖν μάλιστα παρὰ τῇ βασιλίσσῃ Χελκίαν τε καὶ Ἀνανίαν. ταῦτα μὲν οὖν ὁ Στράβων φησίν.", "st": "13.10.4"}, {"sp": "N", "t": "Ὑρκανῷ δὲ φθόνον ἐκίνησεν παρὰ τῶν Ἰουδαίων ἡ εὐπραγία, μάλιστα δ’ οἱ Φαρισαῖοι κακῶς πρὸς αὐτὸν εἶχον, αἵρεσις ὄντες μία τῶν Ἰουδαίων, ὡς καὶ ἐν τοῖς ἐπάνω δεδηλώκαμεν. τοσαύτην δὲ ἔχουσι τὴν ἰσχὺν παρὰ τῷ πλήθει, ὡς καὶ κατὰ βασιλέως τι λέγοντες καὶ κατ’ ἀρχιερέως εὐθὺς πιστεύεσθαι. μαθητὴς δὲ αὐτῶν ἦν καὶ Ὑρκανὸς καὶ σφόδρα ὑπ’ αὐτῶν ἠγαπᾶτο. καὶ δὴ καλέσας αὐτοὺς ἐφ’ ἑστίασιν καὶ φιλοφρόνως ὑποδεξάμενος, ἐπεὶ σφόδρα ἡδομένους ἑώρα, λέγειν ἤρξατο πρὸς αὐτούς, ὡς ἴσασιν μὲν αὐτὸν βουλόμενον εἶναι δίκαιον καὶ πάντα ποιοῦντα ἐξ ὧν ἀρέσειεν ἂν τῷ θεῷ καὶ αὐτοῖς· οἱ γὰρ Φαρισαῖοι φιλοσοφοῦσιν· ἠξίου γε μήν, εἰ βλέπουσιν αὐτὸν ἁμαρτάνοντα καὶ τῆς ὁδοῦ τῆς δικαίας ἐκτρεπόμενον εἰς αὐτὴν ἐπαναγαγεῖν καὶ ἐπανορθοῦν. τῶν δὲ μαρτυρησάντων αὐτῷ πᾶσαν ἀρετὴν ὁ μὲν ἥσθη τοῖς ἐπαίνοις, εἷς δέ τις τῶν κατακειμένων Ἐλεάζαρος ὄνομα, κακοήθης ὢν φύσει καὶ στάσει χαίρων ἐπεί, φησίν, ἠξίωσας γνῶναι τὴν ἀλήθειαν, θέλεις δὲ εἶναι δίκαιος, τὴν ἀρχιερωσύνην ἀπόθου, καὶ μόνον ἀρκείτω σοι τὸ ἄρχειν τοῦ λαοῦ. τὴν δ’ αἰτίαν αὐτοῦ πυθομένου, δι’ ἣν ἀποθοῖτο τὴν ἀρχιερωσύνην ὅτι, φησίν, ἀκούομεν παρὰ τῶν πρεσβυτέρων αἰχμάλωτόν σου γεγονέναι τὴν μητέρα βασιλεύοντος Ἀντιόχου τοῦ Ἐπιφανοῦς. ψευδὴς λόγος ἦν· καὶ πρὸς αὐτὸν Ὑρκανὸς παρωξύνθη καὶ πάντες δ’ οἱ Φαρισαῖοι σφοδρῶς ἠγανάκτησαν.", "st": "13.10.5"}, {"sp": "N", "t": "Τῶν δ’ ἐκ τῶν Σαδδουκαίων τῆς αἱρέσεως, οἳ τὴν ἐναντίαν τοῖς Φαρισαίοις προαίρεσιν ἔχουσιν, Ἰωνάθης τις ἐν τοῖς μάλιστα φίλος ὢν Ὑρκανῷ τῇ κοινῇ πάντων Φαρισαίων γνώμῃ ποιήσασθαι τὰς βλασφημίας τὸν Ἐλεάζαρον ἔλεγεν· καὶ τοῦτ’ ἔσεσθαι φανερὸν αὐτῷ πυθομένῳ παρ’ ἐκείνων, τίνος ἄξιός ἐστιν ἐπὶ τοῖς εἰρημένοις κολάσεως. τοῦ δὲ Ὑρκανοῦ τοὺς Φαρισαίους ἐρομένου, τίνος αὐτὸν ἄξιον ἡγοῦνται τιμωρίας· πειραθήσεσθαι γὰρ οὐ μετὰ τῆς ἐκείνων γνώμης γεγονέναι τὰς βλασφημίας τιμησαμένων αὐτὸν τῷ μέτρῳ τῆς δίκης, πληγῶν ἔφασαν καὶ δεσμῶν· οὐ γὰρ ἐδόκει λοιδορίας ἕνεκα θανάτῳ ζημιοῦν, ἄλλως τε καὶ φύσει πρὸς τὰς κολάσεις ἐπιεικῶς ἔχουσιν οἱ Φαρισαῖοι. πρὸς τοῦτο λίαν ἐχαλέπηνεν καὶ δοκοῦν ἐκείνοις ποιήσασθαι τὰς βλασφημίας τὸν ἄνθρωπον ἐνόμισεν. μάλιστα δ’ αὐτὸν ἐπιπαρώξυνεν Ἰωνάθης καὶ διέθηκεν οὕτως, ὥστε τῇ Σαδδουκαίων ἐποίησεν προσθέσθαι μοίρᾳ τῶν Φαρισαίων ἀποστάντα καὶ τά τε ὑπ’ αὐτῶν κατασταθέντα νόμιμα τῷ δήμῳ καταλῦσαι καὶ τοὺς φυλάττοντας αὐτὰ κολάσαι. μῖσος οὖν ἐντεῦθεν αὐτῷ τε καὶ τοῖς υἱοῖς παρὰ τοῦ πλήθους ἐγένετο. περὶ μέντοι τούτων αὖθις ἐροῦμεν. νῦν δὲ δηλῶσαι βούλομαι, ὅτι νόμιμά τινα παρέδοσαν τῷ δήμῳ οἱ Φαρισαῖοι ἐκ πατέρων διαδοχῆς, ἅπερ οὐκ ἀναγέγραπται ἐν τοῖς Μωυσέως νόμοις, καὶ διὰ τοῦτο ταῦτα τὸ Σαδδουκαίων γένος ἐκβάλλει, λέγον ἐκεῖνα δεῖν ἡγεῖσθαι νόμιμα τὰ γεγραμμένα, τὰ δ’ ἐκ παραδόσεως τῶν πατέρων μὴ τηρεῖν. καὶ περὶ τούτων ζητήσεις αὐτοῖς καὶ διαφορὰς γίνεσθαι συνέβαινεν μεγάλας, τῶν μὲν Σαδδουκαίων τοὺς εὐπόρους μόνον πειθόντων τὸ δὲ δημοτικὸν οὐχ ἑπόμενον αὐτοῖς ἐχόντων, τῶν δὲ Φαρισαίων τὸ πλῆθος σύμμαχον ἐχόντων. ἀλλὰ περὶ μὲν τούτων τῶν δύο καὶ τῶν Ἐσσηνῶν ἐν τῇ δευτέρᾳ μου τῶν Ἰουδαϊκῶν ἀκριβῶς δεδήλωται.", "st": "13.10.6"}, {"sp": "N", "t": "Ὑρκανὸς δὲ παύσας τὴν στάσιν καὶ μετ’ αὐτὴν βιώσας εὐδαιμόνως καὶ τὴν ἀρχὴν διοικησάμενος ἄριστον τρόπον ἔτεσιν ἑνὶ καὶ τριάκοντα τελευτᾷ καταλιπὼν υἱοὺς πέντε, τριῶν τῶν μεγίστων ἄξιος ὑπὸ τοῦ θεοῦ κριθείς, ἀρχῆς τοῦ ἔθνους καὶ τῆς ἀρχιερατικῆς τιμῆς καὶ προφητείας· συνῆν γὰρ αὐτῷ τὸ θεῖον καὶ τὴν τῶν μελλόντων πρόγνωσιν παρεῖχεν αὐτῷ τε εἰδέναι καὶ προλέγειν οὕτως, ὥστε καὶ περὶ τῶν δύο τῶν πρεσβυτέρων παίδων ὅτι μὴ μενοῦσιν τῶν πραγμάτων κύριοι προεῖπεν. ὧν τὴν καταστροφὴν εἰς τὸ μαθεῖν ὅσον τῆς τοῦ πατρὸς ὑπέβησαν εὐτυχίας ἄξιον ἀφηγήσασθαι.", "st": "13.10.7"}, {"sp": "N", "t": "Τελευτήσαντος γὰρ αὐτοῖς τοῦ πατρὸς ὁ πρεσβύτατος Ἀριστόβουλος τὴν ἀρχὴν εἰς βασιλείαν μεταθεῖναι δόξας, ἔκρινεν γὰρ οὕτω, διάδημα πρῶτος ἐπιτίθεται μετὰ τετρακοσίων ἀριθμὸν ἐτῶν καὶ ὀγδοήκοντα καὶ ἑνὸς καὶ μηνῶν τριῶν ἀφ’ οὗ τῆς ὑπὸ Βαβυλωνίοις δουλείας ἀπαλλαγεὶς ὁ λαὸς εἰς τὴν οἰκείαν κατῆλθεν. στέργων δὲ τῶν ἀδελφῶν τὸν μετ’ αὐτὸν Ἀντίγονον τοῦτον μὲν τῶν ὁμοίων ἠξίου, τοὺς δὲ ἄλλους εἶχεν ἐν δεσμοῖς. εἶρξε δὲ καὶ τὴν μητέρα περὶ τῆς ἀρχῆς αὐτῷ διενεχθεῖσαν, ἐκείνην γὰρ Ὑρκανὸς τῶν ὅλων κυρίαν καταλείπει, καὶ μέχρι τοσαύτης ὠμότητος προῆλθεν, ὥστ’ αὐτὴν καὶ λιμῷ διέφθειρεν δεδεμένην. προστίθησιν δὲ τῇ μητρὶ καὶ τὸν ἀδελφὸν Ἀντίγονον, ὃν στέργειν ἐδόκει μάλιστα καὶ κοινωνὸν εἶχεν τῆς βασιλείας, ἐκ διαβολῶν ἀπαλλοτριωθεὶς πρὸς αὐτόν, αἷς τὸ μὲν πρῶτον οὐκ ἐπίστευεν, τὰ μὲν ὑπὸ τοῦ φιλεῖν αὐτὸν οὐ προσέχων τοῖς λεγομένοις, τὰ δὲ καὶ φθονούμενον ἡγούμενος διαβάλλεσθαι. τοῦ δὲ Ἀντιγόνου ποτὲ λαμπρῶς ἀπὸ στρατείας ἐπανελθόντος καὶ τῆς ἑορτῆς, καθ’ ἣν σκηνοπηγοῦσιν τῷ θεῷ, κατ’ ἐκεῖνον τὸν καιρὸν ἐνστάσης, ἔτυχεν τὸν μὲν Ἀριστόβουλον εἰς νόσον καταπεσεῖν, τὸν δὲ Ἀντίγονον ἐπιτελοῦντα τὴν ἑορτὴν ἀναβῆναι λαμπρῶς σφόδρα κεκοσμημένον μετὰ τῶν περὶ αὐτὸν ὁπλιτῶν εἰς τὸ ἱερὸν καὶ τὰ πλείω περὶ τῆς σωτηρίας τἀδελφοῦ εὔχεσθαι, τοὺς δὲ πονηροὺς καὶ διαστῆσαι τὴν ὁμόνοιαν αὐτῶν ἐσπουδακότας ἀφορμῇ χρησαμένους τῇ τε περὶ τὴν πομπὴν τοῦ Ἀντιγόνου φιλοτιμίᾳ καὶ τοῖς ὑπ’ αὐτοῦ κατωρθωμένοις ἐλθεῖν πρὸς τὸν βασιλέα καὶ κακοήθως ἐπὶ τὸ μεῖζον ἐξαίρειν τὰ περὶ τὴν πομπὴν τὴν ἐν τῇ ἑορτῇ, καὶ ὡς οὐ κατ’ ἰδιώτην ἕκαστον ἦν τῶν γινομένων, ἀλλὰ φρονήματος ἔνδειξιν ἔχειν βασιλικοῦ τὰ πραττόμενα, καὶ ὡς κτείνειν αὐτὸν μέλλοι μετὰ στίφους ἐληλυθὼς καρτεροῦ, λογιζόμενον εὐήθως αὐτὸν βασιλεύειν ἐνὸν τιμῆς μεταλαμβάνοντα δοκεῖν μεγάλων τυγχάνειν.", "st": "13.11.1"}, {"sp": "N", "t": "Ἀριστόβουλος δὲ τούτοις ἄκων πειθόμενος καὶ τοῦ ἀνύποπτος εἶναι τἀδελφῷ προνοῶν καὶ τῆς ἀσφαλείας ἅμα φροντίζων, διίστησι τοὺς σωματοφύλακας ἔν τινι τῶν ὑπογείων ἀφωτίστῳ, κατέκειτο δὲ ἐν τῇ βάρει μετονομασθείσῃ δὲ Ἀντωνίᾳ, καὶ προσέταξεν ἀνόπλου μὲν ἅπτεσθαι μηδένα, κτείνειν δὲ τὸν Ἀντίγονον, ἂν ὡπλισμένος πρὸς αὐτὸν εἰσίῃ. πέμπει μέντοι πρὸς Ἀντίγονον αὐτὸς ἄνοπλον αὐτὸν ἀξιῶν ἥκειν. ἡ δὲ βασίλισσα καὶ οἱ συνεπιβουλεύοντες αὐτῇ κατ’ Ἀντιγόνου πείθουσι τὸν πεμφθέντα τἀναντία λέγειν, ὡς ὁ ἀδελφὸς ἀκούσας, ὅτι κατασκευάσειεν ὅπλα καὶ κόσμον πολεμικόν, παραγίνεσθαι πρὸς αὐτὸν παρακαλεῖ ὡπλισμένον, ὅπως ἴδοι τὴν κατασκευήν. ὁ δ’ Ἀντίγονος μηδὲν ὑπιδόμενος κακοῦργον, ἀλλὰ θαρρῶν τῇ παρὰ τἀδελφοῦ διαθέσει, ὡς εἶχεν ἐνδεδυμένος τὴν πανοπλίαν παρεγένετο πρὸς τὸν Ἀριστόβουλον ἐπιδείξων αὐτῷ τὰ ὅπλα. γενόμενον δ’ αὐτὸν κατὰ τὸν Στράτωνος λεγόμενον πύργον, οὗ συνέβαινεν ἀφώτιστον εἶναι σφόδρα τὴν πάροδον, ἀποκτείνουσιν οἱ σωματοφύλακες. διέδειξέν γε μὴν ὁ τούτου θάνατος, ὅτι μηδὲν μήτε φθόνου μήτε διαβολῆς ἰσχυρότερον, μηδ’ ὅ τι μᾶλλον εὔνοιαν καὶ φυσικὴν οἰκειότητα διίστησιν, ἢ ταῦτα τὰ πάθη. μάλιστα δ’ ἄν τις θαυμάσειεν καὶ Ἰούδαν τινά, Ἐσσηνὸν μὲν τὸ γένος, οὐδέποτε δ’ ἐν οἷς προεῖπεν διαψευσάμενον τἀληθές· οὗτος γὰρ ἰδὼν τὸν Ἀντίγονον παριόντα τὸ ἱερὸν ἀνεβόησεν ἐν τοῖς ἑταίροις αὐτοῦ καὶ γνωρίμοις, οἳ διδασκαλίας ἕνεκα τοῦ προλέγειν τὰ μέλλοντα παρέμενον, ὡς ἀποθανεῖν αὐτῷ καλὸν διεψευσμένῳ ζῶντος Ἀντιγόνου, ὃν σήμερον τεθνήξεσθαι προειπὼν ἐν τῷ καλουμένῳ Στράτωνος πύργῳ περιόντα ὁρᾷ, καὶ τοῦ μὲν χωρίου περὶ σταδίους ἀπέχοντος νῦν ἑξακοσίους, ὅπου φονευθήσεσθαι προεῖπεν αὐτόν, τῆς δ’ ἡμέρας ἤδη τὸ πλεῖστον ἠνυσμένον, ὥστ’ αὐτῷ κινδυνεύειν τὸ μάντευμα ψεῦδος εἶναι. ταῦτ’ οὖν λέγοντος αὐτοῦ καὶ κατηφοῦντος ἀγγέλλεται τεθνεὼς Ἀντίγονος ἐν τῷ ὑπογείῳ, ὃ καὶ αὐτὸ Στράτωνος ἐκαλεῖτο πύργος, ὁμώνυμον τῇ παραλίῳ Καισαρείᾳ. τὸν μὲν οὖν μάντιν τοῦτο διετάραξεν.", "st": "13.11.2"}, {"sp": "N", "t": "Ἀριστόβουλον δὲ τῆς ἀδελφοκτονίας εὐθὺς εἰσῆλθεν μετάνοια καὶ νόσος ἐπ’ αὐτῇ τῆς διανοίας ὑπὸ τοῦ μύσους κεκακωμένης, ὡς διαφθαρέντων αὐτῷ ὑπὸ ἀκράτου τῆς ὀδύνης τῶν ἐντὸς αἷμα ἀναφέρειν. ὃ τῶν διακονουμένων τις παίδων κατὰ δαιμόνιον οἶμαι πρόνοιαν εἰς τὸν αὐτὸν τόπον, οὗ σφαγέντος Ἀντιγόνου σπίλους ἔτι τοῦ αἵματος ἐκείνου συνέβαινεν εἶναι, κομίζων ὀλισθὼν ἐξέχεεν. γενομένης δὲ βοῆς παρὰ τῶν ἰδόντων ὡς τοῦ παιδὸς ἐξεπίτηδες ἐκχέαντος ἐκεῖ τὸ αἷμα, ἀκούσας Ἀριστόβουλος τὴν αἰτίαν ἐπύθετο, καὶ μὴ λεγόντων ἔτι μᾶλλον ἐπετείνετο μαθεῖν, φύσει τῶν ἀνθρώπων ὑπονοούντων ἐν τοῖς τοιούτοις εἶναι χείρονα τὰ σιγώμενα. ὡς δ’ ἀπειλοῦντος καὶ βιαζομένου τοῖς φόβοις τἀληθὲς εἶπον, προχεῖται μὲν αὐτῷ πληγέντι τὴν διάνοιαν ὑπὸ τοῦ συνειδότος πολλὰ δάκρυα, βύθιον δὲ ἀνοιμώξας, οὐκ ἄρ’, εἶπεν, λήσειν ἐπ’ ἀσεβέσιν οὕτω καὶ μιαροῖς τολμήμασι τὸν θεὸν ἔμελλον, ἀλλά με ταχεῖα ποινὴ συγγενοῦς φόνου μετελήλυθεν. καὶ μέχρι τίνος, ὦ σῶμα ἀναιδέστατον, ψυχὴν ὀφειλομένην ἀδελφοῦ καὶ μητρὸς καθέξεις δαίμοσιν; τί δ’ οὐκ ἀθρόαν αὐτὴν ταύτην ἀποδίδως, κατὰ μέρος δ’ ἐπισπένδω τοὐμὸν αἷμα τοῖς μιαιφονηθεῖσιν; ταῦτ’ εἰπὼν ἐπαποθνήσκει τοῖς λόγοις βασιλεύσας ἐνιαυτόν, χρηματίσας μὲν Φιλέλλην, πολλὰ δ’ εὐεργετήσας τὴν πατρίδα, πολεμήσας Ἰτουραίους καὶ πολλὴν αὐτῶν τῆς χώρας τῇ Ἰουδαίᾳ προσκτησάμενος ἀναγκάσας τε τοὺς ἐνοικοῦντας, εἰ βούλονται μένειν ἐν τῇ χώρᾳ, περιτέμνεσθαι καὶ κατὰ τοὺς Ἰουδαίων νόμους ζῆν. φύσει δ’ ἐπιεικεῖ κέχρητο καὶ σφόδρα ἦν αἰδοῦς ἥττων, ὡς μαρτυρεῖ τούτῳ καὶ Στράβων ἐκ τοῦ Τιμαγένους ὀνόματος λέγων οὕτως· ἐπιεικής τε ἐγένετο οὗτος ὁ ἀνὴρ καὶ πολλὰ τοῖς Ἰουδαίοις χρήσιμος· χώραν τε γὰρ αὐτοῖς προσεκτήσατο καὶ τὸ μέρος τοῦ τῶν Ἰτουραίων ἔθνους ᾠκειώσατο δεσμῷ συνάψας τῇ τῶν αἰδοίων περιτομῇ.", "st": "13.11.3"}, {"sp": "N", "t": "Τελευτήσαντος δὲ Ἀριστοβούλου Σαλίνα ἡ γυνὴ αὐτοῦ, λεγομένη δὲ ὑπὸ Ἑλλήνων Ἀλεξάνδρα, λύσασα τοὺς ἀδελφοὺς αὐτοῦ, δεδεμένους γὰρ αὐτοὺς εἶχεν Ἀριστόβουλος, ὡς προειρήκαμεν, Ἰαναῖον τὸν καὶ Ἀλέξανδρον βασιλέα καθίστησιν τὸν καὶ καθ’ ἡλικίαν προύχοντα καὶ μετριότητα, ᾧ καὶ συνέβη γεννηθέντι εὐθὺς μισηθῆναι ὑπὸ τοῦ πατρὸς καὶ μέχρι τῆς τελευτῆς αὐτοῦ μηκέτι εἰς ὄψιν ἀφικέσθαι. τὸ δ’ αἴτιον τοῦ μίσους τοιόνδε λέγεται γενέσθαι· στέργων μάλιστα τῶν παίδων Ὑρκανὸς τοὺς πρεσβυτέρους Ἀντίγονον καὶ Ἀριστόβουλον φανέντα κατὰ τοὺς ὕπνους αὐτῷ τὸν θεὸν ἐπηρώτα, τίς αὐτοῦ τῶν παίδων μέλλει ἔσεσθαι διάδοχος. τοῦ δὲ θεοῦ τοὺς τούτου χαρακτῆρας δείξαντος, λυπηθεὶς ὅτι τῶν ἀγαθῶν αὐτοῦ πάντων οὗτος ἔσται κληρονόμος, γενόμενον εἴασεν ἐν τῇ Γαλιλαίᾳ τρέφεσθαι. ὁ μέντοι θεὸς οὐ διεψεύσατο τὸν Ὑρκανόν. τὴν δὲ βασιλείαν μετὰ τὴν Ἀριστοβούλου τελευτὴν οὗτος παραλαβὼν τὸν μὲν τῶν ἀδελφῶν ἐπιχειροῦντα τῇ βασιλείᾳ διεχρήσατο, τὸν δ’ ἕτερον ἀπραγμόνως ζῆν προαιρούμενον εἶχεν ἐν τιμῇ.", "st": "13.12.1"}, {"sp": "N", "t": "Καταστησάμενος δὲ τὴν ἀρχὴν ὃν ᾤετο συμφέρειν αὐτῷ τρόπον στρατεύει ἐπὶ Πτολεμαΐδα, τῇ δὲ μάχῃ κρατήσας ἐνέκλεισε τοὺς ἀνθρώπους εἰς τὴν πόλιν καὶ περικαθίσας αὐτοὺς ἐπολιόρκει. τῶν γὰρ ἐν τῇ παραλίᾳ Πτολεμαῒς αὐτῷ καὶ Γάζα μόναι χειρωθῆναι ὑπελείποντο, καὶ Ζώιλος δὲ ὁ κατασχὼν τὸν Στράτωνος πύργον τύραννος καὶ Δῶρα. τοῦ δὲ Φιλομήτορος Ἀντιόχου καὶ τοῦ ἀδελφοῦ αὐτοῦ Ἀντιόχου, ὃς ἐπεκαλεῖτο Κυζικηνός, πολεμούντων ἀλλήλους καὶ τὴν αὐτῶν δύναμιν ἀπολλύντων ἦν οὐδεμία τοῖς Πτολεμαεῦσιν βοήθεια παρ’ αὐτῶν. ἀλλὰ πονουμένοις τῇ πολιορκίᾳ Ζώιλος ὁ τὸν Στράτωνος πύργον κατεσχηκὼς [παρῆν] καὶ τὰ Δῶρα σύνταγμα τρέφων στρατιωτικὸν καὶ τυραννίδι ἐπιχειρῶν διὰ τὴν τῶν βασιλέων πρὸς ἀλλήλους ἅμιλλαν μικρὰ τοῖς Πτολεμαιεῦσι παρεβοήθει· οὐδὲ γὰρ οἱ βασιλεῖς οὕτως εἶχον οἰκείως πρὸς αὐτούς, ὥστ’ ἐλπίσαι τινὰ παρ’ αὐτῶν ὠφέλειαν. ἑκάτεροι γὰρ ταὐτὸν τοῖς ἀθληταῖς ἔπασχον, οἳ τῇ δυνάμει μὲν ἀπηγορευκότες αἰσχυνόμενοι δὲ παραχωρῆσαι διετέλουν ἀργίᾳ καὶ ἀναπαύσει διαφέροντες τὸν ἀγῶνα. λοιπὴ δ’ αὐτοῖς ἐλπὶς ἦν ἡ παρὰ τῶν Αἰγύπτου βασιλέων καὶ τοῦ Κύπρον ἔχοντος Πτολεμαίου τοῦ Λαθούρου, ὃς ὑπὸ τῆς μητρὸς Κλεοπάτρας τῆς ἀρχῆς ἐκπεσὼν εἰς Κύπρον παρεγένετο. πέμψαντες οὖν πρὸς τοῦτον οἱ Πτολεμαιεῖς παρεκάλουν ἐλθόντα σύμμαχον ἐκ τῶν Ἀλεξάνδρου χειρῶν αὐτοὺς ῥύσασθαι κινδυνεύοντας. ἐπελπισάντων δ’ αὐτὸν τῶν πρέσβεων, ὡς διαβὰς εἰς Συρίαν ἕξει Γαζαίους συνεστῶτας μετὰ τῶν Πτολεμαιῶν καὶ Ζώιλον, ἔτι γε μὴν Σιδωνίους καὶ πολλοὺς ἄλλους αὐτῷ συλλήψεσθαι λεγόντων, ἐπαρθεὶς πρὸς τὸν ἔκπλουν ἔσπευδεν.", "st": "13.12.2"}, {"sp": "N", "t": "Ἐν τούτῳ δὲ τοὺς Πτολεμαιᾶς Δημαίνετος πιθανὸς ὢν αὐτοῖς τότε καὶ δημαγωγῶν μεταβαλέσθαι τὰς γνώμας ἐποίησεν, ἄμεινον εἶναι φήσας ἐπ’ ἀδήλῳ τῷ γενησομένῳ διακινδυνεύειν πρὸς τοὺς Ἰουδαίους μᾶλλον ἢ φανερὰν εἰσδέξασθαι δουλείαν δεσπότῃ παραδόντας αὑτούς, καὶ πρὸς τούτῳ μὴ τὸν παρόντα μόνον ἔχειν πόλεμον, ἀλλὰ καὶ πολὺ μείζω τὸν ἀπ’ Αἰγύπτου. τὴν γὰρ Κλεοπάτραν οὐ περιόψεσθαι δύναμιν αὐτῷ κατασκευαζόμενον Πτολεμαῖον ἐκ γειτόνων, ἀλλ’ ἥξειν ἐπ’ αὐτοὺς μετὰ μεγάλης στρατιᾶς· σπουδάσαι γὰρ αὐτὴν ὥστε καὶ τῆς Κύπρου τὸν υἱὸν ἐκβαλεῖν· εἶναι δὲ Πτολεμαίῳ μὲν διαμαρτόντι τῆς ἐλπίδος ἀποφυγὴν πάλιν τὴν Κύπρον, αὐτοῖς δὲ κινδύνων τὸν ἔσχατον. ὁ μὲν οὖν Πτολεμαῖος κατὰ τὸν πόρον μαθὼν τὴν τῶν Πτολεμαιῶν μεταβολὴν οὐδὲν ἧττον ἔπλευσεν καὶ καταχθεὶς εἰς τὴν καλουμένην Συκάμινον ἐνταυθοῖ τὴν δύναμιν ἐξεβίβασεν. ἦν δὲ ὁ πᾶς στρατὸς αὐτῷ πεζοί τε ἅμα καὶ ἱππεῦσιν περὶ τρισμυρίους, οὓς προαγαγὼν πλησίον τῆς Πτολεμαΐδος καὶ στρατοπεδευσάμενος, ἐπεὶ μήτε τοὺς παρ’ αὐτοῦ πρέσβεις ἐδέχοντο μήτε τῶν λόγων ἠκροῶντο, μεγάλως ἐφρόντιζεν.", "st": "13.12.3"}, {"sp": "N", "t": "Ἐλθόντων δὲ πρὸς αὐτὸν Ζωίλου τε καὶ τῶν Γαζαίων καὶ δεομένων συμμαχεῖν αὐτοῖς πορθουμένης αὐτοῖς τῆς χώρας ὑπὸ τῶν Ἰουδαίων καὶ Ἀλεξάνδρου, λύει μὲν τὴν πολιορκίαν δείσας τὸν Πτολεμαῖον ὁ Ἀλέξανδρος, ἀπαγαγὼν δὲ τὴν στρατιὰν εἰς τὴν οἰκείαν ἐστρατήγει τὸ λοιπὸν λάθρα μὲν τὴν Κλεοπάτραν ἐπὶ τὸν Πτολεμαῖον μεταπεμπόμενος, φανερῶς δὲ φιλίαν καὶ συμμαχίαν πρὸς αὐτὸν ὑποκρινόμενος. καὶ τετρακόσια δὲ ἀργυρίου τάλαντα δώσειν ὑπέσχετο χάριν ἀντὶ τούτων αἰτῶν Ζώιλον ἐκποδὼν ποιήσασθαι τὸν τύραννον καὶ τὴν χώραν τοῖς Ἰουδαίοις προσνεῖμαι. τότε μὲν οὖν ὁ Πτολεμαῖος ἡδέως τὴν πρὸς Ἀλέξανδρον ποιησάμενος φιλίαν χειροῦται τὸν Ζώιλον. ὕστερον δὲ ἀκούσας λάθρα διαπεμψάμενον αὐτὸν πρὸς τὴν μητέρα αὐτοῦ Κλεοπάτραν λύει τοὺς γεγενημένους πρὸς αὐτὸν ὅρκους καὶ προσβαλὼν ἐπολιόρκει τὴν Πτολεμαΐδα μὴ δεξαμένην αὐτόν. καταλιπὼν δ’ ἐπὶ τῆς πολιορκίας στρατηγοὺς καὶ μέρος τι τῆς δυνάμεως αὐτὸς τῷ λοιπῷ τὴν Ἰουδαίαν καταστρεψόμενος ὥρμησεν. ὁ δὲ Ἀλέξανδρος τὴν τοῦ Πτολεμαίου διάνοιαν μαθὼν συνήθροισεν καὶ αὐτὸς περὶ πέντε μυριάδας τῶν ἐγχωρίων, ὡς δ’ ἔνιοι συγγραφεῖς εἰρήκασιν ὀκτώ, καὶ ἀναλαβὼν τὴν δύναμιν ἀπήντα τῷ Πτολεμαίῳ. Πτολεμαῖος δ’ ἐξαίφνης ἐπιπεσὼν Ἀσωχειτω τῆς Γαλιλαίας πόλει σάββασιν αἱρεῖ κατὰ κράτος αὐτὴν καὶ περὶ μύρια σώματα καὶ πολλὴν ἑτέραν ἔλαβε λείαν.", "st": "13.12.4"}, {"sp": "N", "t": "Πειράσας δὲ καὶ Σέπφωριν μικρὸν ἄπωθεν τῆς πεπορθημένης πολλοὺς ἀποβαλὼν ᾔει πολεμήσων Ἀλεξάνδρῳ. ὑπήντησε δ’ αὐτῷ πρὸς τῷ Ἰορδάνῃ ποταμῷ Ἀλέξανδρος περί τινα τόπον λεγόμενον Ἀσωφὼν οὐ πόρρωθεν τοῦ Ἰορδάνου ποταμοῦ καὶ βάλλεται στρατόπεδον πλησίον τῶν πολεμίων. εἶχεν μέντοι τοὺς προμαχομένους ὀκτακισχιλίους, οὓς ἑκατονταμάχους προσηγόρευσεν, ἐπιχάλκοις χρωμένους τοῖς θυρεοῖς. ἦσαν δὲ καὶ τοῖς τοῦ Πτολεμαίου προμαχοῦσιν ἐπίχαλκοι αἱ ἀσπίδες. τοῖς μέντοι γε ἄλλοις ἔλαττον ἔχοντες οἱ τοῦ Πτολεμαίου εὐλαβέστερον συνῆψαν εἰς τὸν κίνδυνον. θάρσος δὲ αὐτοῖς οὐκ ὀλίγον ἐνεποίησεν ὁ τακτικὸς Φιλοστέφανος διαβῆναι κελεύσας τὸν ποταμόν, οὗ μεταξὺ ἦσαν ἐστρατοπεδευκότες. Ἀλεξάνδρῳ δὲ κωλύειν αὐτῶν τὴν διάβασιν οὐκ ἔδοξεν· ἐνόμιζεν γάρ, εἰ κατὰ νώτου λάβοιεν τὸν ποταμόν, ῥᾷον αἱρήσειν τοὺς πολεμίους φεύγειν ἐκ τῆς μάχης οὐ δυναμένους. κατ’ ἀρχὰς μὲν οὖν παρ’ ἀμφοτέρων ἦν ἔργα χειρῶν καὶ προθυμίας παραπλήσια καὶ πολὺς ἐγένετο φόνος ἐξ ἑκατέρων τῶν στρατευμάτων, ὑπερτέρων δὲ τῶν Ἀλεξάνδρου γινομένων Φιλοστέφανος διελὼν τὴν δύναμιν δεξιῶς τοῖς ἐνδιδοῦσιν ἐπεκούρει. μηδενὸς δὲ τῷ κλιθέντι μέρει τῶν Ἰουδαίων προσβοηθοῦντος τούτους μὲν συνέβαινε φεύγειν μὴ βοηθούντων τῶν πλησίον ἀλλὰ κοινωνούντων τῆς φυγῆς, οἱ δὲ τοῦ Πτολεμαίου τὰ ἐναντία τούτων ἔπραττον· ἑπόμενοι γὰρ ἔκτεινον τοὺς Ἰουδαίους, καὶ τὸ τελευταῖον τραπέντας αὐτοὺς ἅπαντας ἐδίωκον φονεύοντες ἕως οὗ καὶ ὁ σίδηρος αὐτοῖς ἠμβλύνθη κτείνουσιν καὶ αἱ χεῖρες παρείθησαν. τρισμυρίους γοῦν ἔφασαν αὐτῶν ἀποθανεῖν, Τιμαγένης δὲ πεντακισμυρίους εἴρηκεν, τῶν δὲ ἄλλων τοὺς μὲν αἰχμαλώτους ληφθῆναι, τοὺς δ’ εἰς τὰ οἰκεῖα διαφεύγειν χωρία.", "st": "13.12.5"}, {"sp": "N", "t": "Πτολεμαῖος δὲ μετὰ τὴν νίκην προσκαταδραμὼν τὴν χώραν ὀψίας ἐπιγενομένης ἔν τισι κώμαις τῆς Ἰουδαίας κατέμεινεν, ἃς γυναικῶν εὑρὼν μεστὰς καὶ νηπίων ἐκέλευσεν τοὺς στρατιώτας ἀποσφάττοντας αὐτοὺς καὶ κρεουργοῦντας ἔπειτα εἰς λέβητας ζέοντας ἐνιέντας τὰ μέλη ἀπάρχεσθαι. τοῦτο δὲ προσέταξεν, ἵν’ οἱ διαφυγόντες ἐκ τῆς μάχης καὶ πρὸς αὑτοὺς ἐλθόντες σαρκοφάγους ὑπολάβωσιν εἶναι τοὺς πολεμίους, καὶ διὰ τοῦτο ἔτι μᾶλλον αὐτοὺς καταπλαγῶσι ταῦτ’ ἰδόντες. λέγει δὲ καὶ Στράβων καὶ Νικόλαος, ὅτι τοῦτον αὐτοῖς ἐχρήσαντο τὸν τρόπον, καθὼς κἀγὼ προείρηκα. ἔλαβον δὲ καὶ τὴν Πτολεμαΐδα κατὰ κράτος, ὡς καὶ ἐν ἄλλοις φανερὸν πεποιήκαμεν.", "st": "13.12.6"}, {"sp": "N", "t": "Κλεοπάτρα δ’ ὁρῶσα τὸν υἱὸν αὐξανόμενον καὶ τήν τε Ἰουδαίαν ἀδεῶς πορθοῦντα καὶ τὴν Γαζαίων πόλιν ὑπήκοον ἔχοντα, περιιδεῖν οὐκ ἔγνω τοῦτον ἐπὶ ταῖς πύλαις ὄντα καὶ ποθοῦντα τὴν τῶν Αἰγυπτίων μείζω γενόμενον, ἀλλὰ παραχρῆμα μετὰ καὶ ναυτικῆς καὶ πεζῆς δυνάμεως ἐπ’ αὐτὸν ἐξώρμησεν ἡγεμόνας τῆς ὅλης στρατιᾶς ἀποδείξασα Χελκίαν καὶ Ἀνανίαν τοὺς Ἰουδαίους, τὰ δὲ πολλὰ τοῦ πλούτου καὶ τοὺς υἱωνοὺς καὶ διαθήκας πέμψασα Κῴοις παρέθετο. κελεύσασα δὲ τὸν υἱὸν Ἀλέξανδρον στόλῳ μεγάλῳ παραπλεῖν εἰς Φοινίκην ἡ Κλεοπάτρα μετὰ πάσης αὐτὴ τῆς δυνάμεως ἧκεν εἰς Πτολεμαΐδα, μὴ δεξαμένων δὲ αὐτὴν τῶν Πτολεμαιῶν πολιορκεῖ τὴν πόλιν. Πτολεμαῖος δ’ ἐκ τῆς Συρίας ἀπελθὼν ἐπὶ τὴν Αἴγυπτον ἔσπευσεν, αἰφνιδίως αὐτὴν οἰόμενος κενὴν οὖσαν στρατιᾶς καθέξειν· ἀλλὰ διαμαρτάνει τῆς ἐλπίδος. κατὰ τοῦτον δὴ τὸν χρόνον συνέβη καὶ Χελκίαν τὸν ἕτερον τῶν τῆς Κλεοπάτρας ἡγεμόνων ἀποθανεῖν περὶ κοίλην Συρίαν διώκοντα Πτολεμαῖον.", "st": "13.13.1"}, {"sp": "N", "t": "Ἀκούσασα δ’ ἡ Κλεοπάτρα τὴν ἐπιχείρησιν τὴν τοῦ υἱοῦ καὶ ὅτι τὰ περὶ τὴν Αἴγυπτον οὐχ ὃν προσεδόκα τρόπον προκεχώρηκεν αὐτῷ, πέμψασα μέρος τῆς στρατιᾶς ἐξέβαλεν αὐτὸν ἀπὸ τῆς χώρας. καὶ ὁ μὲν ἐκ τῆς Αἰγύπτου πάλιν ὑποστρέψας τὸν χειμῶνα διέτριψεν ἐν Γάζῃ. Κλεοπάτρα δ’ ἐν τούτῳ τὴν ἐν Πτολεμαΐδι φρουρὰν ἐκ πολιορκίας λαμβάνει καὶ τὴν πόλιν. Ἀλεξάνδρου δ’ αὐτὴν μετὰ δώρων περιελθόντος καὶ θεραπείας ὁποίας ἄξιον ἦν πεπονθότα μὲν κακῶς ὑπὸ Πτολεμαίου, καταφυγῆς δ’ οὐκ ἄλλης ἢ ταύτης εὐποροῦντα, τινὲς μὲν τῶν φίλων καὶ ταῦτα συνεβούλευον αὐτῇ λαβεῖν καὶ τὴν χώραν ἐπελθούσῃ κατασχεῖν καὶ μὴ περιιδεῖν ἐπ’ ἀνδρὶ ἑνὶ τοσοῦτο πλῆθος ἀγαθῶν Ἰουδαίων κείμενον. Ἀνανίας δὲ συνεβούλευσε τούτοις ἐναντία, λέγων ἄδικα ποιήσειν αὐτήν, εἰ σύμμαχον ἄνθρωπον ἀφαιρήσεται τῆς ἰδίας ἐξουσίας καὶ ταῦτα συγγενῆ ἡμέτερον· οὐ γὰρ ἀγνοεῖν βούλομαί σε, φησίν, εἰ τὸ πρὸς τοῦτον ἄδικον ἐχθροὺς ἅπαντας ἡμᾶς σοι τοὺς Ἰουδαίους κατασκευάζει. ταῦτα δὲ Ἀνανία παραινέσαντος ἡ Κλεοπάτρα πείθεται μηδὲν ἀδικῆσαι τὸν Ἀλέξανδρον, ἀλλὰ συμμαχίαν πρὸς αὐτὸν ἐποιήσατο ἐν Σκυθοπόλει τῆς κοίλης Συρίας.", "st": "13.13.2"}, {"sp": "N", "t": "Ὁ δὲ τῶν ἐκ Πτολεμαίου φόβων ἐλευθερωθεὶς στρατεύεται μὲν εὐθὺς ἐπὶ τὴν κοίλην Συρίαν, αἱρεῖ δὲ Γάδαρα πολιορκήσας δέκα μησίν, αἱρεῖ δὲ καὶ Ἀμαθοῦντα μέγιστον ἔρυμα τῶν ὑπὲρ τὸν Ἰορδάνην κατῳκημένων, ἔνθα καὶ τὰ κάλλιστα καὶ σπουδῆς ἄξια Θεόδωρος ὁ Ζήνωνος εἶχεν. ὃς οὐ προσδοκῶσιν ἐπιπεσὼν τοῖς Ἰουδαίοις μυρίους αὐτῶν ἀποκτείνει καὶ τὴν ἀποσκευὴν Ἀλεξάνδρου διαρπάζει. ταῦτα μὲν οὖν οὐ καταπλήττει τὸν Ἀλέξανδρον, ἀλλ’ ἐπιστρατεύει τοῖς θαλαττίοις μέρεσιν, Ῥαφείᾳ καὶ Ἀνθηδόνι, ἣν ὕστερον βασιλεὺς Ἡρώδης Ἀγριππιάδα προσηγόρευσεν, καὶ κατὰ κράτος εἷλεν καὶ ταύτην. ὁρῶν δὲ τὸν Πτολεμαῖον ἐκ τῆς Γάζης εἰς Κύπρον ἀνακεχωρηκότα, τὴν δὲ μητέρα αὐτοῦ Κλεοπάτραν εἰς Αἴγυπτον, ὀργιζόμενος δὲ τοῖς Γαζαίοις, ὅτι Πτολεμαῖον ἐπεκαλέσαντο βοηθόν, ἐπολιόρκει τὴν πόλιν καὶ τὴν χώραν αὐτῶν προενόμευσεν. Ἀπολλοδότου δὲ τοῦ στρατηγοῦ τῶν Γαζαίων μετὰ δισχιλίων ξένων καὶ μυρίων οἰκετῶν νύκτωρ ἐπιπεσόντος τῷ τῶν Ἰουδαίων στρατοπέδῳ ἐφ’ ὅσον μὲν ὑπῆρχεν ἡ νὺξ ἐνίκων οἱ Γαζαῖοι δόκησιν παρασχόντες τοῖς πολεμίοις ὡς ἐπεληλυθότος αὐτοῖς Πτολεμαίου, γενομένης δὲ ἡμέρας καὶ τῆς δόξης ἐλεγχθείσης μαθόντες οἱ Ἰουδαῖοι τἀληθὲς ἐπισυστρέφονται καὶ τοῖς Γαζαίοις προσβαλόντες ἀναιροῦσιν αὐτῶν περὶ χιλίους. τῶν δὲ Γαζαίων ἀντεχόντων καὶ μήτε ὑπὸ τῆς ἐνδείας μήτε ὑπὸ τοῦ πλήθους τῶν ἀναιρουμένων ἐνδιδόντων, πᾶν γὰρ ὁτιοῦν ὑπέμενον παθεῖν ἢ ὑπὸ τῷ πολεμίῳ γενέσθαι, προσεπήγειρεν δ’ αὐτῶν τὴν προθυμίαν καὶ Ἀρέτας ὁ Ἀράβων βασιλεὺς ἐπίδοξος ὢν ἥξειν αὐτοῖς σύμμαχος. ἀλλὰ συνέβη πρῶτον τὸν Ἀπολλόδοτον διαφθαρῆναι· Λυσίμαχος γὰρ ἀδελφὸς αὐτοῦ ζηλοτυπῶν αὐτὸν ἐπὶ τῷ παρὰ τοῖς πολίταις εὐδοκιμεῖν, κτείνας αὐτὸν καὶ στρατιωτικὸν συγκροτήσας ἐνδίδωσιν Ἀλεξάνδρῳ τὴν πόλιν. ὁ δ’ εὐθὺς μὲν εἰσελθὼν ἠρέμει, μετὰ δὲ ταῦτα τὴν δύναμιν ἐπαφῆκε τοῖς Γαζαίοις ἐπιτρέψας τιμωρεῖν αὐτούς· οἱ δὲ ἄλλοι ἀλλαχῆ τρεπόμενοι τοὺς Γαζαίους ἀπέκτειναν. ἦσαν δ’ οὐδ’ ἐκεῖνοι τὰς ψυχὰς ἀγεννεῖς, ἀλλὰ καὶ τοῖς παραπίπτουσιν ἀμυνόμενοι τοὺς Ἰουδαίους οὐκ ἐλάττονας αὐτῶν διέφθειραν. ἔνιοι δὲ μονούμενοι τὰς οἰκίας ἐνεπίμπρασαν, ὡς μηδὲν ἐξ αὐτῶν λάφυρον εἶναι τοῖς πολεμίοις λαβεῖν. οἱ δὲ καὶ τῶν τέκνων καὶ τῶν γυναικῶν αὐτόχειρες ἐγένοντο τῆς ὑπὸ τοῖς ἐχθροῖς αὐτὰ δουλείας οὕτως ἀπαλλάττειν ἠναγκασμένοι. τῶν δὲ βουλευτῶν ἦσαν οἱ πάντες πεντακόσιοι συμφυγόντες εἰς τὸ τοῦ Ἀπόλλωνος ἱερόν· συνεδρευόντων γὰρ τὴν ἐπίθεσιν συνέβη γενέσθαι· ὁ δὲ Ἀλέξανδρος τούτους τε ἀναιρεῖ καὶ τὴν πόλιν αὐτοῖς ἐπικατασκάψας ὑπέστρεψεν εἰς Ἱεροσόλυμα ἐνιαυτῷ πολιορκήσας.", "st": "13.13.3"}, {"sp": "N", "t": "Ὑπὸ τὸν αὐτὸν δὲ τοῦτον καιρὸν καὶ Ἀντίοχος ὁ ἐπικληθεὶς Γρυπὸς ἀποθνήσκει ὑπὸ Ἡρακλέωνος ἐπιβουλευθείς, βιώσας μὲν ἔτη τεσσαράκοντα καὶ πέντε, βασιλεύσας δὲ ἐννέα καὶ εἴκοσι. διαδεξάμενος δὲ τὴν βασιλείαν αὐτοῦ ὁ παῖς Σέλευκος ἐπολέμει μὲν τῷ τοῦ πατρὸς ἀδελφῷ Ἀντιόχῳ, ὃς ἐπεκαλεῖτο Κυζικηνός, νικήσας δ’ αὐτὸν καὶ λαβὼν ἀπέκτεινεν. μετ’ οὐ πολὺ δὲ τοῦ Κυζικηνοῦ παῖς Ἀντίοχος, ὁ Εὐσεβὴς καλούμενος, παραγενηθεὶς εἰς Ἄραδον καὶ περιθέμενος διάδημα πολεμεῖ τῷ Σελεύκῳ, καὶ κρατήσας ἐξήλασεν αὐτὸν ἐκ πάσης τῆς Συρίας. ὁ δὲ φυγὼν εἰς Κιλικίαν καὶ γενόμενος ἐν τῇ Μόψου ἑστίᾳ πάλιν αὐτοὺς εἰσέπραττε χρήματα. ὁ δὲ τῶν Μοψεστέων δῆμος ἀγανακτήσας ὑφῆψεν αὐτοῦ τὰ βασίλεια καὶ διέφθειρεν αὐτὸν μετὰ τῶν φίλων. Ἀντιόχου δὲ τοῦ Κυζικηνοῦ παιδὸς βασιλεύοντος τῆς Συρίας Ἀντίοχος ὁ Σελεύκου ἀδελφὸς ἐκφέρει πόλεμον πρὸς αὐτὸν καὶ νικηθεὶς ἀπόλλυται μετὰ τῆς στρατιᾶς. μετὰ δ’ αὐτὸν ὁ ἀδελφὸς αὐτοῦ Φίλιππος ἐπιθέμενος διάδημα μέρους τινὸς τῆς Συρίας ἐβασίλευσεν. Πτολεμαῖος δὲ ὁ Λάθουρος τὸν τρίτον αὐτῶν ἀδελφὸν Δημήτριον τὸν Ἄκαιρον λεγόμενον ἐκ Κνίδου μεταπεμψάμενος κατέστησεν ἐν Δαμασκῷ βασιλέα. τούτοις δὲ τοῖς δυσὶν ἀδελφοῖς καρτερῶς ἀνθιστάμενος Ἀντίοχος ταχέως ἀπέθανεν· Λαοδίκῃ γὰρ ἐλθὼν σύμμαχος τῇ τῶν Σαμηνῶν βασιλίσσῃ Πάρθους πολεμούσῃ μαχόμενος ἀνδρείως ἔπεσεν. τὴν δὲ Συρίαν οἱ δύο κατεῖχον ἀδελφοὶ Δημήτριος καὶ Φίλιππος, καθὼς ἐν ἄλλοις δεδήλωται.", "st": "13.13.4"}, {"sp": "N", "t": "Ἀλέξανδρος δὲ τῶν οἰκείων πρὸς αὐτὸν στασιασάντων, ἐπανέστη γὰρ αὐτῷ τὸ ἔθνος ἑορτῆς ἀγομένης καὶ ἑστῶτος αὐτοῦ ἐπὶ τοῦ βωμοῦ καὶ θύειν μέλλοντος κιτρίοις αὐτὸν ἔβαλλον, νόμου ὄντος παρὰ τοῖς Ἰουδαίοις ἐν τῇ σκηνοπηγίᾳ ἔχειν ἕκαστον θύρσους ἐκ φοινίκων καὶ κιτρίων, δεδηλώκαμεν δὲ καὶ ταῦτα ἐν ἄλλοις, προσεξελοιδόρησαν δ’ αὐτὸν ὡς ἐξ αἰχμαλώτων γεγονότα καὶ τῆς τιμῆς καὶ τοῦ θύειν ἀνάξιον, ἐπὶ τούτοις ὀργισθεὶς κτείνει μὲν αὐτῶν περὶ ἑξακισχιλίους, δρύφακτον δὲ ξύλινον περὶ τὸν βωμὸν καὶ τὸν ναὸν βαλόμενος μέχρι τοῦ θριγκοῦ, εἰς ὃν μόνοις ἐξῆν τοῖς ἱερεῦσιν εἰσιέναι, τούτῳ τὴν τοῦ πλήθους ἐπ’ αὐτὸν ἀπέφραττεν εἴσοδον. ἔτρεφεν δὲ καὶ ξένους Πισίδας καὶ Κίλικας· Σύροις γὰρ πολέμιος ὢν οὐκ ἐχρῆτο. καταστρεψάμενος δὲ τῶν Ἀράβων Μωαβίτας καὶ Γαλααδίτας εἰς φόρου ἀπαγωγήν, κατερείπει καὶ Ἀμαθοῦντα Θεοδώρου μὴ τολμῶντος αὐτῷ συμβαλεῖν. συνάψας δὲ μάχην πρὸς Ὀβέδαν τὸν Ἀράβων βασιλέα καὶ πεσὼν εἰς ἐνέδραν ἐν χωρίοις τραχέσι καὶ δυσβάτοις ὑπὸ πλήθους καμήλων εἰς βαθεῖαν κατερράχθη φάραγγα κατὰ Γάδαρα κώμην τῆς ϊουδάνιδος καὶ μόλις αὐτὸς διασώζεται, φεύγων δ’ ἐκεῖθεν εἰς Ἱεροσόλυμα παραγίνεται. καὶ πρὸς τὴν κακοπραγίαν αὐτοῦ ἐπιθεμένου τοῦ ἔθνους πολεμήσας πρὸς αὐτὸ ἔτεσιν ἓξ ἀναιρεῖ τῶν Ἰουδαίων οὐκ ἔλαττον πέντε μυριάδας. παρακαλοῦντος δὲ παῦσαι τὴν πρὸς αὐτὸν δυσμένειαν ἔτι μᾶλλον ἐμίσουν αὐτὸν διὰ τὰ συμβεβηκότα. πυνθανομένου δ’ αὐτοῦ τί βούλονται, πάντες γενέσθαι ἐβόησαν ἀποθανεῖν αὐτόν, καὶ πρὸς Δημήτριον τὸν Ἄκαιρον ἔπεμψαν παρακαλοῦντες ἐπὶ συμμαχίαν.", "st": "13.13.5"}, {"sp": "N", "t": "Ὁ δὲ μετὰ στρατιᾶς ἐλθὼν καὶ παραλαβὼν τοὺς ἐπικαλεσαμένους περὶ Σίκιμα πόλιν ἐστρατοπέδευσεν. Ἀλέξανδρος δὲ μετὰ μισθοφόρων ἑξακισχιλίων καὶ διακοσίων Ἰουδαίων τε περὶ δισμυρίους οἳ ἐφρόνουν τὰ ἐκείνου παραλαβὼν ἀντεπῄει τῷ Δημητρίῳ· τούτῳ δ’ ἦσαν ἱππεῖς μὲν τρισχίλιοι, πεζῶν δὲ τέσσαρες μυριάδες. πολλὰ μὲν οὖν ἑκατέροις ἐπράχθη, τοῦ μὲν ἀποστῆσαι τοὺς μισθοφόρους ὡς ὄντας Ἕλληνας πειρωμένου, τοῦ δὲ τοὺς σὺν Δημητρίῳ Ἰουδαίους. μηδετέρου δὲ πεῖσαι δυνηθέντος, ἀλλ’ εἰς μάχην συμβαλόντων, νικᾷ Δημήτριος, καὶ ἀποθνήσκουσι μὲν οἱ Ἀλεξάνδρου μισθοφόροι πάντες πίστεως ἅμα καὶ ἀνδρείας ἐπίδειξιν ποιησάμενοι, πολλοὶ δὲ καὶ τῶν Δημητρίου στρατιωτῶν.", "st": "13.14.1"}, {"sp": "N", "t": "Φεύγοντος δ’ Ἀλεξάνδρου εἰς τὰ ὄρη κατὰ οἶκτον τῆς μεταβολῆς συλλέγονται παρ’ αὐτὸν Ἰουδαίων ἑξακισχίλιοι. καὶ τότε μὲν δείσας ὑποχωρεῖ Δημήτριος. μετὰ ταῦτα δὲ οἱ Ἰουδαῖοι ἐπολέμουν Ἀλεξάνδρῳ καὶ νικώμενοι πολλοὶ ἀπέθνησκον ἐν ταῖς μάχαις. κατακλείσας δὲ τοὺς δυνατωτάτους αὐτᾶν ἐν Βαιθομμει πόλει ἐπολιόρκει, λαβὼν δὲ τὴν πόλιν καὶ γενόμενος ἐγκρατὴς αὐτῶν ἀνήγαγεν εἰς Ἱεροσόλυμα καὶ πάντων ὠμότατον ἔργον ἔδρασεν· ἑστιώμενος γὰρ ἐν ἀπόπτῳ μετὰ τῶν παλλακίδων ἀνασταυρῶσαι προσέταξεν αὐτῶν ὡς ὀκτακοσίους, τοὺς δὲ παῖδας αὐτῶν καὶ τὰς γυναῖκας ἔτι ζώντων παρὰ τὰς ἐκείνων ὄψεις ἀπέσφαττεν, ὑπὲρ μὲν ὧν ἠδίκητο ἀμυνόμενος, ἄλλως δὲ ὑπὲρ ἄνθρωπον ταύτην εἰσπραττόμενος τὴν δίκην, εἰ καὶ τὰ μάλιστα, ὅπερ ἦν εἰκός, ἐταλαιπωρήθη τοῖς πρὸς αὐτοὺς πολέμοις καὶ εἰς τοὔσχατον ἧκε κινδύνου ψυχῆς τε πέρι καὶ βασιλείας, οὐκ ἀρκουμένων ἀγωνίζεσθαι κατὰ σφᾶς αὐτούς, ἀλλὰ καὶ ἀλλοφύλους ἐπαγόντων καὶ τὸ τελευταῖον εἰς τοῦτο ἀνάγκης ἀγαγόντων, ὥστε ἣν κατεστρέψατο γῆν ἐν Γαλααδίτιδι καὶ Μωαβίτιδι καὶ τὰ χωρία τῶν Ἀράβων τῷ βασιλεῖ παραδοῦναι, ὅπως ἂν μὴ ξυνάρηται σφίσι τὸν κατ’ αὐτοῦ πόλεμον, ἄλλα τε μυρία ἐς ὕβριν αὐτοῦ καὶ ἐπήρειαν πραξάντων. ἀλλ’ [οὖν οὐκ] ἐπιτηδείως δοκεῖ ταῦτα δρᾶσαι, ὥστε διὰ τὴν τῆς ὠμότητος ὑπερβολὴν ἐπικληθῆναι αὐτὸν ὑπὸ τῶν Ἰουδαίων Θρακίδαν. οἱ δ’ ἀντιστασιῶται αὐτοῦ τὸ πλῆθος ὄντες περὶ ὀκτακισχιλίους φεύγουσιν νυκτὸς καὶ παρ’ ὃν ἔζη χρόνον Ἀλέξανδρος ἦσαν ἐν τῇ φυγῇ. καὶ οὗτος μὲν ἀπηλλαγμένος τῆς ἐκ τούτων ταραχῆς μετὰ πάσης τὸ λοιπὸν ἠρεμίας ἐβασίλευσεν.", "st": "13.14.2"}, {"sp": "N", "t": "Δημήτριος δ’ ἐκ τῆς Ἰουδαίας ἀπελθὼν εἰς Βέροιαν ἐπολιόρκει τὸν ἀδελφὸν αὐτοῦ Φίλιππον ὄντων αὐτῷ πεζῶν μὲν μυρίων, χιλίων δὲ ἱππέων. Στράτων δ’ ὁ τῆς Βεροίας τύραννος Φιλίππῳ συμμαχῶν Ἄζιζον τὸν Ἀράβων φύλαρχον ἐπεκαλεῖτο καὶ Μιθριδάτην τὸν Σινάκην τὸν Παρθυαίων ὕπαρχον. ὧν ἀφικομένων μετὰ πολλῆς δυνάμεως καὶ πολιορκούντων Δημήτριον ἐντὸς τοῦ χαρακώματος, εἴσω τοῖς τε τοξεύμασι καὶ τῇ δίψῃ συνέχοντες αὐτὸν ἠνάγκασαν τοὺς σὺν αὐτῷ σφᾶς παραδοῦναι. λαφυραγωγήσαντες δὲ τὰ ἐν τῇ χώρᾳ καὶ τὸν Δημήτριον παραλαβόντες τὸν μὲν τῷ Μιθριδάτῃ τῷ τότε βασιλεύοντι Πάρθων ἔπεμψαν, τῶν δ’ αἰχμαλώτων οὓς Ἀντιοχέων εἶναι πολίτας συνέβαινε τούτους προῖκα τοῖς Ἀντιοχεῦσιν ἀπέδωκαν. Μιθριδάτης δ’ ὁ τῶν Πάρθων βασιλεὺς Δημήτριον εἶχεν ἐν τιμῇ τῇ πάσῃ μέχρι νόσῳ κατέστρεψε Δημήτριος τὸν βίον. Φίλιππος δὲ ἀπὸ τῆς μάχης εὐθὺς εἰς Ἀντιόχειαν ἐλθὼν καὶ κατασχὼν αὐτὴν ἐβασίλευσεν τῆς Συρίας.", "st": "13.14.3"}, {"sp": "N", "t": "Ἔπειτα Ἀντίοχος ὁ κληθεὶς Διόνυσος ἀδελφὸς ὢν Φιλίππου, τῆς ἀρχῆς ἀντιποιούμενος εἰς Δαμασκὸν παραγίνεται, καὶ τῶν ἐκεῖ πραγμάτων ἐγκρατὴς γενόμενος ἐβασίλευσεν. ἐκστρατεύσαντος δὲ ἐπὶ τοὺς Ἄραβας αὐτοῦ Φίλιππος ὁ ἀδελφὸς τοῦτ’ ἀκούσας ἐπὶ Δαμασκὸν ἦλθεν. Μιλησίου δ’, ὃς καταλέλειπτο τῆς ἄκρας φύλαξ καὶ τῶν Δαμασκηνῶν, παραδόντος αὐτῷ τὴν πόλιν, ἀχάριστος εἰς αὐτὸν γενόμενος καὶ μηδὲν ὧν ἐλπίσας ἐδέξατο αὐτὸν παρασχών, ἀλλὰ τῷ παρ’ αὐτοῦ φόβῳ βουληθεὶς δοκεῖν παραλαβεῖν τὴν πόλιν ἢ τῇ χάριτι τῇ Μιλησίου δωρούμενος αὐτὸν οἷς ἐχρῆν, ὑπωπτεύετο καὶ πάλιν ἐκπίπτει τῆς Δαμασκοῦ· ἐξορμήσαντος γὰρ αὐτοῦ εἰς ἱππόδρομον ἀπέκλεισεν ὁ Μιλήσιος καὶ τὴν Δαμασκὸν Ἀντιόχῳ διεφύλαξεν. ὃς ἀκούσας τὰ περὶ τὸν Φίλιππον ὑπέστρεψεν ἐκ τῆς Ἀραβίας, στρατεύεται δ’ εὐθὺς ἐλθὼν ἐπὶ τὴν Ἰουδαίαν ὁπλίταις μὲν ὀκτακισχιλίοις, ἱππεῦσι δὲ ὀκτακοσίοις. δείσας δὲ Ἀλέξανδρος τὴν ἔφοδον αὐτοῦ τάφρον ὀρύττει βαθεῖαν ἀπὸ τῆς Χαβερσαβᾶ ἀρξάμενος, ἣ νῦν Ἀντιπατρὶς καλεῖται, ἄχρι τῆς εἰς Ἰόππην θαλάσσης, ᾗ καὶ μόνον ἦν ἐπίμαχον· τεῖχός τ’ ἐγείρας καὶ πύργους ἀναστήσας ξυλίνους καὶ μεταπύργια ἐπὶ σταδίους ἑκατὸν ἑξήκοντα ἐξεδέχετο τὸν Ἀντίοχον. ὁ δὲ ταῦτα πάντα ἐμπρήσας διεβίβαζε ταύτῃ τὴν δύναμιν ἐπὶ τὴν Ἀραβίαν. ἀναχωροῦντος δὲ τοῦ Ἄραβος τὰ πρῶτα, ἔπειτα μετὰ μυρίων ἱππέων ἐξαίφνης ἐπιφανέντος ὑπαντήσας τούτοις Ἀντίοχος καρτερῶς ἐμάχετο, καὶ δὴ νικῶν ἀπέθανεν παραβοηθῶν τῷ πονοῦντι μέρει. πεσόντος δ’ Ἀντιόχου καὶ τὸ στράτευμα φεύγει εἰς Κανὰ κώμην, ἔνθα τὸ πλεῖον αὐτῶν λιμῷ φθείρεται.", "st": "13.15.1"}, {"sp": "N", "t": "Βασιλεύει δὲ μετ’ αὐτὸν τῆς κοίλης Συρίας Ἀρέτας κληθεὶς εἰς τὴν ἀρχὴν ὑπὸ τῶν τὴν Δαμασκὸν ἐχόντων διὰ τὸ πρὸς Πτολεμαῖον τὸν Μενναίου μῖσος. στρατεύσας δ’ ἐκεῖθεν ἐπὶ τὴν Ἰουδαίαν καὶ περὶ Ἄδιδα χωρίον μάχῃ νικήσας Ἀλέξανδρον ἐπὶ συνθήκαις ἀνεχώρησεν ἐκ τῆς Ἰουδαίας.", "st": "13.15.2"}, {"sp": "N", "t": "Ἀλέξανδρος δ’ ἐλάσας αὖθις ἐπὶ Δίαν πόλιν αἱρεῖ ταύτην, καὶ στρατεύσας ἐπὶ Ἔσσαν, οὗ τὰ πλείστου ἄξια Ζήνωνι συνέβαινεν εἶναι, τρισὶν μὲν περιβάλλει τείχεσιν τὸ χωρίον, ἀμαχὶ δὲ [λαβὼν] τὴν πόλιν ἐπὶ Γαύλαναν καὶ Σελεύκειαν ἐξώρμησεν. παραλαβὼν δὲ καὶ ταύτας προσεξεῖλεν καὶ τὴν Ἀντιόχου λεγομένην φάραγγα καὶ Γάμαλα τὸ φρούριον. ἐγκαλῶν δὲ πολλὰ Δημητρίῳ τῷ τῶν τόπων ἄρχοντι περιέδυσεν αὐτόν, καὶ τρίτον ἤδη πεπληρωκὼς ἔτος τῆς στρατείας εἰς τὴν οἰκείαν ὑπέστρεψεν προθύμως αὐτὸν τῶν Ἰουδαίων διὰ τὴν εὐπραγίαν δεχομένων.", "st": "13.15.3"}, {"sp": "N", "t": "Κατὰ δὴ τοῦτον τὸν καιρὸν ἤδη τῶν Σύρων καὶ Ἰδουμαίων καὶ Φοινίκων πόλεις εἶχον οἱ Ἰουδαῖοι πρὸς θαλάσσῃ μὲν Στράτωνος πύργον Ἀπολλωνίαν Ἰόππην Ἰάμνειαν Ἄζωτον Γάζαν Ἀνθηδόνα Ῥάφειαν Ῥινοκόρουρα, ἐν δὲ τῇ μεσογαίᾳ κατὰ τὴν Ἰδουμαίαν Ἄδωρα καὶ Μάρισαν καὶ ὅλην Ἰδουμαίαν, Σαμάρειαν Καρμήλιον ὄρος καὶ τὸ Ἰταβύριον ὄρος Σκυθόπολιν Γάδαρα, Γαυλανίτιδας Σελεύκειαν Γάβαλα, Μωαβίτιδας Ἠσεβὼν Μήδαβα Λεμβὰ Ορωναιμαγελεθων Ζόαρα Κιλίκων αὐλῶνα Πέλλαν, ταύτην κατέσκαψεν ὑποσχομένων τῶν ἐνοικούντων ἐς πάτρια τῶν Ἰουδαίων ἔθη μεταβαλεῖσθαι, ἄλλας τε πόλεις πρωτευούσας τῆς Συρίας ἦσαν κατεστραμμένοι.", "st": "13.15.4"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα ὁ βασιλεὺς Ἀλέξανδρος ἐκ μέθης εἰς νόσον καταπεσὼν καὶ τρισὶν ἔτεσιν τεταρταίῳ πυρετῷ συσχεθεὶς οὐκ ἀπέστη τῶν στρατειῶν, ἕως οὗ τοῖς πόνοις ἐξαναλωθεὶς ἀπέθανεν ἐν τοῖς Γερασηνῶν ὅροις πολιορκῶν Ῥάγαβα φρούριον πέραν τοῦ Ἰορδάνου. ὁρῶσα δ’ αὐτὸν ἡ βασίλισσα πρὸς τῷ τελευτᾶν ὄντα καὶ μηδεμίαν ὑπογράφοντα μηκέτι σωτηρίας ἐλπίδα, κλαίουσα καὶ κοπτομένη τῆς μελλούσης ἐρημίας αὐτήν τε καὶ τοὺς παῖδας ἀπωδύρετο καί τίνι καταλείπεις οὕτως ἐμέ τε καὶ τὰ τέκνα τῆς παρ’ ἄλλων βοηθείας δεόμενα πρὸς αὐτὸν ἔλεγεν καὶ ταῦτ’ εἰδώς, πῶς διάκειται πρὸς σὲ δυσμενῶς τὸ ἔθνος. ὁ δὲ συνεβούλευεν αὐτῇ πείθεσθαι μὲν οἷς ὑποθήσεται πρὸς τὸ τὴν βασιλείαν ἀσφαλῶς κατέχειν μετὰ τῶν τέκνων, κρύψαι δὲ τὸν θάνατον αὐτοῦ πρὸς τοὺς στρατιώτας, ἕως ἂν ἐξέλῃ τὸ χωρίον. ἔπειτα ὡς ἀπὸ νίκης λαμπρῶς εἰς τὰ Ἱεροσόλυμα παραγινομένην τοῖς Φαρισαίοις ἐξουσίαν τινὰ παρασχεῖν· τούτους γὰρ ἐπαινοῦντας αὐτὴν ἀντὶ τῆς τιμῆς εὔνουν καταστήσειν αὐτῇ τὸ ἔθνος, δύνασθαι δὲ πολὺ παρὰ τοῖς Ἰουδαίοις τούτους ἔφασκε βλάψαι τε μισοῦντας καὶ φίλους διακειμένους ὠφελῆσαι· μάλιστα γὰρ πιστεύεσθαι παρὰ τῷ πλήθει περὶ ὧν ἂν κἂν φθονῶσίν τι χαλεπὸν λέγωσιν, αὐτόν τε προσκροῦσαι τῷ ἔθνει διὰ τούτους ἔλεγεν ὑβρισθέντας ὑπ’ αὐτοῦ. σὺ τοίνυν, εἶπεν, ἐν τοῖς Ἱεροσολύμοις γενομένη μετάπεμψαι μὲν τοὺς στασιώτας αὐτῶν, ἐπιδείξασα δὲ τὸ σῶμα τοὐμὸν ἐκείνοις ὅπως μοι βούλονται χρῆσθαι μετὰ πολλῆς ἀξιοπιστίας ἐπίτρεπε, εἴτε καθυβρίζειν ἀταφίᾳ μου θελήσουσι τὸν νεκρὸν ὡς πολλὰ πεπονθότες ἐξ ἐμοῦ, εἴτ’ ἄλλην τινὰ κατ’ ὀργὴν αἰκίαν τῷ σώματι προσφέρειν. ὑπόσχου τε καὶ μηδὲν δίχα τῆς ἐκείνων γνώμης ἐν τῇ βασιλείᾳ διαπράξεσθαι. ταῦτά σου πρὸς αὐτοὺς εἰπούσης ἐγώ τε λαμπροτέρας ἀξιωθήσομαι πρὸς αὐτῶν κηδείας ἧς ἂν ἔτυχον ἐκ σοῦ, μηδὲν διὰ τὸ ἐξεῖναι ποιεῖν μου κακῶς τὸν νεκρὸν διαθεῖναι θελησάντων, σύ τε βεβαίως ἄρξεις. ταῦτα παραινέσας τῇ γυναικὶ τελευτᾷ βασιλεύσας ἔτη ἑπτὰ καὶ εἴκοσι, βιώσας δ’ ἓν καὶ πεντήκοντα.", "st": "13.15.5"}, {"sp": "N", "t": "Ἡ δὲ Ἀλεξάνδρα τὸ φρούριον ἐξελοῦσα κατὰ τὰς τοῦ· ἀνδρὸς ὑποθήκας τοῖς τε Φαρισαίοις διελέχθη καὶ πάντα ἐπ’ ἐκείνοις θεμένη τά τε περὶ τοῦ νεκροῦ καὶ τῆς βασιλείας, τῆς μὲν ὀργῆς αὐτοὺς τῆς πρὸς Ἀλέξανδρον ἔπαυσεν, εὔνους δ’ ἐποίησεν καὶ φίλους. οἱ δ’ εἰς τὸ πλῆθος παρελθόντες ἐδημηγόρουν τὰς πράξεις τὰς Ἀλεξάνδρου διηγούμενοι, καὶ ὅτι δίκαιος αὐτοῖς ἀπόλοιτο βασιλεύς, καὶ τὸν δῆμον εἰς πένθος καὶ τὴν ὑπὲρ αὐτοῦ κατήφειαν ἐξεκαλέσαντο τοῖς ἐπαίνοις, ὥστε καὶ λαμπρότερον ἤ τινα τῶν πρὸ αὐτοῦ βασιλέων αὐτὸν ἐκήδευσαν. δύο μέντοι γε υἱοὺς Ἀλέξανδρος κατέλιπεν Ὑρκανὸν καὶ Ἀριστόβουλον, τὴν δὲ βασιλείαν εἰς τὴν Ἀλεξάνδραν διέθετο. τῶν δὲ παίδων Ὑρκανὸς μὲν ἀσθενὴς ἦν πράγματα διοικεῖν καὶ βίον ἡσύχιον μᾶλλον ἠγαπηκώς, ὁ δὲ νεώτερος Ἀριστόβουλος δραστήριός τε ἦν καὶ θαρσαλέος. ἐστέργετο μὲν οὖν ὑπὸ τοῦ πλήθους ἡ γυνὴ διὰ τὸ δοκεῖν ἐφ’ οἷς ὁ ἀνὴρ αὐτῆς ἐξήμαρτεν δυσχεραίνειν.", "st": "13.16.1"}, {"sp": "N", "t": "Ἡ δὲ ἀρχιερέα μὲν ἀπεδείκνυεν Ὑρκανὸν διὰ τὴν ἡλικίαν, πολὺ μέντοι πλέον διὰ τὸ ἄπραγμον αὐτοῦ, καὶ πάντα τοῖς Φαρισαίοις ἐπέτρεπεν ποιεῖν, οἷς καὶ τὸ πλῆθος ἐκέλευσεν πειθαρχεῖν καὶ εἴ τι δὲ καὶ τῶν νομίμων Ὑρκανὸς ὁ πενθερὸς αὐτῆς κατέλυσεν ὧν εἰσήνεγκαν οἱ Φαρισαῖοι κατὰ τὴν πατρῴαν παράδοσιν, τοῦτο πάλιν ἀποκατέστησεν. τὸ μὲν οὖν ὄνομα τῆς βασιλείας εἶχεν αὐτή, τὴν δὲ δύναμιν οἱ Φαρισαῖοι· καὶ γὰρ φυγάδας οὗτοι κατῆγον καὶ δεσμώτας ἔλυον καὶ καθάπαξ οὐδὲν δεσποτῶν διέφερον. ἐποιεῖτο μέντοι καὶ ἡ γυνὴ τῆς βασιλείας πρόνοιαν, καὶ πολὺ μισθοφορικὸν συνίστησιν, καὶ τὴν ἰδίαν δύναμιν ἀπέδειξεν διπλασίονα, ὡς καταπλῆξαι τοὺς πέριξ τυράννους καὶ λαβεῖν ὅμηρα αὐτῶν. ἠρέμει δ’ ἡ χώρα πᾶσα πάρεξ τῶν Φαρισαίων· οὗτοι γὰρ ἐπετάρασσον τὴν βασίλειαν πείθοντες, ὅπως κτείνειεν τοὺς Ἀλεξάνδρῳ παραινέσαντας ἀνελεῖν τοὺς ὀκτακοσίους. εἶτα αὐτοὶ τούτων ἕνα σφάττουσιν Διογένην καὶ μετ’ αὐτὸν ἄλλους ἐπ’ ἄλλοις, ἕως οὗ οἱ δυνατοὶ παρελθόντες εἰς τὸ βασίλειον καὶ μετ’ αὐτῶν Ἀριστόβουλος, ἐῴκει γὰρ τοῖς γινομένοις δυσανασχετῶν καὶ δῆλος ἦν, καθάπαξ εἰ ἀφορμῆς λάβοιτο, μὴ ἐπιτρέψων τῇ μητρί, ἀνεμίμνησκον ὅσα κατώρθωσαν τοσούτοις κινδύνοις, δι’ ὧν τὸ βέβαιον τῆς ἐν σφίσι πίστεως πρὸς τὸν δεσπότην ἐπεδείξαντο, ἀνθ’ ὧν ὑπ’ αὐτοῦ μεγίστων ἠξιώθησαν. καὶ ἐδέοντο μὴ ἄχρι τοῦ παντὸς ἔμπαλιν τρέψαι σφίσι τὰς ἐλπίδας· ἀποφυγόντας γὰρ τὸν ἐκ πολεμίων κίνδυνον ἐν τῇ οἰκείᾳ ὑπ’ ἐχθρῶν δίκην βοσκημάτων κόπτεσθαι μηδεμιᾶς τιμωρίας οὔσης. ἔλεγόν τε ὡς, εἰ μὲν ἀρκεσθεῖεν τοῖς ἀνῃρημένοις οἱ ἀντίδικοι, διὰ τὸ πρὸς τοὺς δεσπότας γνήσιον μετρίως οἴσειν τὰ ξυμβάντα, εἰ δ’ αὖ μέλλοιεν ταὐτὰ μετιέναι, ᾐτοῦντο μάλιστα μὲν δοθῆναι σφίσιν ἀπαλλαγήν· οὐδὲ γὰρ ἂν ὑπομεῖναι χωρὶς αὐτῆς πορίσασθαι τὸ σωτήριον, ἀλλ’ ἀσμενίζειν θνήσκοντες πρὸς τοῖς βασιλείοις, ὡς μὴ συγγνοῖεν ἀπιστίαν αὐτοῖς. αἶσχός τε εἶναι σφίσι τε καὶ τῇ βασιλευούσῃ, εἰ πρὸς αὐτῆς ἀμελούμενοι ὑπὸ τῶν ἐχθρῶν τοῦ ἀνδρὸς ἐκδεχθείησαν· ἀντὶ παντὸς γὰρ τιμήσεσθαι Ἀρέταν τε τὸν Ἄραβα καὶ τοὺς μονάρχους, εἰ ἀποξενολογήσειεν τοσούσδε ἄνδρας, οἷς ἦν τάχα που φρικῶδες αὐτῶν καὶ τοὔνομα τὸ πρὶν ἀκουσθῆναι. εἰ δὲ μή, τό γε δεύτερον, εἰ τοὺς Φαρισαίους αὐτῇ προτιμᾶν ἔγνωσται, κατατάξαι ἕκαστον αὐτῶν ἐν τοῖς φρουρίοις· εἰ γὰρ ὧδε δαίμων τις ἐπενεμέσησεν τῷ Ἀλεξάνδρου οἴκῳ, αὐτούς γε μὴν ἂν ἀποδεῖξαι καὶ ἐν ταπεινῷ σχήματι βιοτεύοντας.", "st": "13.16.2"}, {"sp": "N", "t": "Πολλὰ τοιαῦτα λεγόντων καὶ εἰς οἶκτον τῶν τεθνεώτων καὶ τῶν κινδυνευόντων τοὺς Ἀλεξάνδρου δαίμονας ἐπικαλουμένων, ἅπαντες οἱ περιεστῶτες ὥρμησαν εἰς δάκρυα, καὶ μάλιστα Ἀριστόβουλος ὅπως ἔχοι γνώμης ἐδήλου πολλὰ τὴν μητέρα κακίζων. ἀλλὰ γὰρ ἐκεῖνοι μὲν αὐτοὶ σφίσι τῶν συμφορῶν ἐγένοντο αἴτιοι, κατὰ φιλαρχίαν ἐκλελυσσηκυίᾳ γυναικὶ παρὰ τὸ εἰκὸς βασιλεύειν γενεᾶς ἐν ἀκμῇ οὔσης ἐπιτρέψαντες· ἡ δὲ οὐκ ἔχουσα ὅ τι πράξειε μετὰ τοῦ εὐπρεποῦς τὴν φυλακὴν τῶν χωρίων σφίσιν ἐπέτρεψεν, ὅτι μὴ Ὑρκανίας καὶ Ἀλεξανδρείου καὶ Μαχαιροῦντος, ἔνθα τὰ πλείστου ἄξια ἦν αὐτῇ. καὶ μετ’ οὐ πολὺ τὸν υἱὸν Ἀριστόβουλον μετὰ στρατιᾶς ἐξέπεμψεν ἐπὶ Δαμασκὸν κατὰ Πτολεμαίου τοῦ Μενναίου λεγομένου, ὃς βαρὺς ἦν τῇ πόλει γείτων. ἀλλ’ οἱ μὲν οὐδὲν ἐργασάμενοι σπουδῆς ἄξιον ὑπέστρεψαν.", "st": "13.16.3"}, {"sp": "N", "t": "Κατὰ δὲ τοῦτον τὸν καιρὸν ἀγγέλλεται Τιγράνης στρατοῦ μυριάσι τριάκοντα ἐμβεβληκὼς εἰς τὴν Συρίαν καὶ ἐπὶ τῆς Ἰουδαίας ἀφιξόμενος. τοῦτο ὥσπερ εἰκὸς ἐφόβησε τὴν βασίλισσαν καὶ τὸ ἔθνος. δῶρα δὴ καὶ πολλὰ καὶ λόγου ἄξια πέμπουσιν αὐτῷ καὶ πρέσβεις πολιορκοῦντι Πτολεμαΐδα. βασίλισσα γὰρ Σελήνη ἡ καὶ Κλεοπάτρα καλουμένη τῶν ἐν τῇ Συρίᾳ κατέχειν, ἣ καὶ ἐνήγαγεν τοὺς ἐνοικοῦντας ἀποκλεῖσαι Τιγράνη νῦν ἐτύγχανεν καὶ ἐδέοντο χρηστὰ περὶ τῆς βασιλίσσης καὶ τοῦ ἔθνους συγγινώσκειν. ὁ δὲ ἀποδεξάμενος αὐτοὺς τῆς ἐκ διαστήματος θεραπείας ἐλπίδας ὑπέθετο χρηστάς. ἄρτι δὲ τῆς Πτολεμαΐδος ἑαλωκυίας ἀγγέλλεται Τιγράνῃ Λεύκολλον διώκοντα Μιθριδάτην ἐκείνου μὲν διαμαρτεῖν εἰς τοὺς Ἴβηρας ἀναφυγόντος, τὴν δὲ Ἀρμενίαν πορθήσαντα πολιορκεῖν Τιγράνης δὲ καὶ ταῦτ’ ἐπιγνοὺς ἀνεχώρει τὴν ἐπ’ οἴκου.", "st": "13.16.4"}, {"sp": "N", "t": "Μετὰ δὲ τοῦτο τῆς βασιλίσσης εἰς νόσον χαλεπὴν ἐμπεσούσης δόξαν Ἀριστοβούλῳ τοῖς πράγμασιν ἐπιτίθεσθαι τῆς νυκτὸς ὑπεξελθὼν μεθ’ ἑνὸς τῶν θεραπόντων ᾔει ἐπὶ τὰ φρούρια, ἵνα οἱ πατρῷοι κατετάχθησαν αὐτῷ φίλοι. πάλαι γὰρ ἀχθόμενος οἷς ἔπραττεν ἡ μήτηρ πολὺ μᾶλλον ἔδεισε, μὴ ἀποθανούσης ἐπὶ τοῖς Φαρισαίοις τὸ πᾶν γένος αὐτοῖς ὑπάρξειεν· ἑώρα γὰρ τὸ ἀδύνατον τοῦ μέλλοντος διαδέχεσθαι τὴν ἀρχὴν ἀδελφοῦ. ξυνῄδει δὲ ἡ γυνὴ μόνη τῇ πράξει, ἣν κατέλιπεν αὐτόθι μετὰ τῆς γενεᾶς. καὶ πρῶτον ἀφικόμενος εἰς Ἄγαβα, ἔνθα Γαλαίστης ἦν τῶν δυνατῶν, ὑπεδέχθη πρὸς αὐτοῦ. μεθ’ ἡμέραν δὲ αἴσθησις γίνεται τῇ βασιλίσσῃ τῆς Ἀριστοβούλου φυγῆς, καὶ μέχρι τινὸς ᾤετο γεγονέναι τὴν ἀναχώρησιν οὐκ ἐπὶ νεωτερισμῷ· ὡς μέντοι ἧκον ἀπαγγέλλοντες ἄλλοι ἐπ’ ἄλλοις, ὅτι κατειλήφει τὸ πρῶτον χωρίον καὶ τὸ δεύτερον καὶ ξύμπαντα, εὐθὺς γὰρ ἑνὸς ἀρξαμένου πάντα ἠπείγετο πρὸς τὸ ἐκείνου βούλημα, τότε δὴ ἐν μεγίσταις ταραχαῖς ὑπῆρχεν ἥ τε βασίλισσα καὶ τὸ ἔθνος. ᾔδεισαν γὰρ οὐ πόρρω τοῦ δύνασθαι τὴν ἀρχὴν αὐτῷ κρατῦναι τὸν Ἀριστόβουλον ὄντα, ἐδεδίεσάν τε, μὴ ποινὴν εἰσπράξαιτο ὧν παρῴνησαν αὐτῷ τὸν οἶκον. δόξαν οὖν τήν τε γυναῖκα αὐτοῦ καὶ γενεὰν εἰς τὸ ὑπὲρ τοῦ ἱεροῦ φρούριον κατέθεσαν. Ἀριστοβούλῳ δὲ ὡς ἂν ἐκ πολλῶν συχνὰ ἀνήχθη, ἀφ’ ὧν ἤδη καὶ κόσμος βασίλειος περὶ αὐτὸν ἦν· σχεδὸν γὰρ ἐν ἡμέραις δεκαπέντε χωρίων ἐκράτησεν εἰκοσιδύο, ὅθεν ἀφορμὰς ἔχων στρατιὰν ἤθροιζεν ἀπὸ Λιβάνου καὶ Τράχωνος καὶ τῶν μονάρχων· οἱ γὰρ ἄνθρωποι τῷ πλείονι ὑπαγόμενοι ῥᾳδίως ὑπήκουον· ἄλλως δὲ νομίζοντες, εἰ δὴ ξυλλάβοιεν αὐτῷ, τῶν μὴ προσδοκωμένων οὐχ ἧσσον καρπώσεσθαι τὴν βασιλείαν ὡς αὐτοὶ τοῦ κρατῆσαι πρόφασις γενηθέντες. τῶν δὲ Ἰουδαίων οἱ πρεσβύτεροι καὶ Ὑρκανὸς ἐσῄεσαν ὡς τὴν βασίλισσαν καὶ ἐδέοντο ὑποθέσθαι γνώμην περὶ τῶν ἐνεστώτων· τὸν γὰρ Ἀριστόβουλον τῶν πάντων σχεδὸν ἤδη κυριεύειν, ὁπότε χωρίων τοσούτων κρατήσειεν· ἄτοπον δέ, εἰ καὶ τὰ μάλιστα κάμνοι, περιούσης αὐτῆς κατὰ σφᾶς βουλεύεσθαι· περιεστάναι δὲ τὸν κίνδυνον οὐ διὰ μακροῦ σφίσιν. ἡ δὲ αὐτοὺς ἐκέλευσε πράττειν ὅ τι δοκοῦσι χρήσιμον εἶναι· πολλὰς δ’ ἀφορμὰς αὐτοῖς λείπεσθαι, τὸ ἔθνος ἐρρωμένον καὶ τὴν δύναμιν καὶ τὰ ἐν τοῖς γαζοφυλακίοις χρήματα· αὐτῇ μὲν γὰρ μικρὸν ἔτι μέλειν τῶν πραγμάτων ὡς ἂν ὑπολείποντος ἤδη τοῦ σώματος.", "st": "13.16.5"}, {"sp": "N", "t": "Ταῦτ’ εἰποῦσα μετ’ οὐ πολὺ ἐτελεύτησεν βασιλεύσασα ἔτη ἐννέα, τὰ δὲ σύμπαντα βιώσασα τρία καὶ ἑβδομήκοντα, γυνὴ τῷ ἀσθενεῖ τοῦ φύλου κατ’ οὐδὲν χρησαμένη· δεινὴ γὰρ εἰς τὸ φίλαρχον ἐν ταῖς μάλιστα γενομένη διήλεγξεν ἔργοις τό τε πρακτικὸν τῆς ἐν αὐτῇ γνώμης καὶ τὸ ἀσύνετον τῶν ἀεὶ πταιόντων περὶ τὰς δυναστείας ἀνδρῶν. τὸ γὰρ παρὸν κρεῖττον ἀξιοῦσα τοῦ μέλλοντος καὶ πάντα δεύτερα τιθεμένη τοῦ ἐγκρατῶς ἄρχειν, οὔτε καλοῦ οὔτε δικαίου ἕνεκά γε τούτων ἐπεστρέφετο. εἰς γοῦν τοῦτο τῷ οἴκῳ ἀτυχίας τὰ πράγματα περιέστησεν, ὥσθ’ ἣν μετὰ πλείστων κινδύνων καὶ ταλαιπωρίας περιεκτήσατο δυναστείαν ἐπιθυμίᾳ τῶν μὴ προσηκόντων γυναικὶ χρόνοις οὐ πολλοῖς ὕστερον ἀφαιρεθῆναι, τοῖς μὲν δυσμενῶς ἔχουσιν πρὸς τὸ γένος αὐτῶν τὴν αὐτὴν γνώμην προσθεῖσα, τὴν δὲ ἀρχὴν ἔρημον τῶν προκηδομένων ποιησαμένη. καὶ ξυμφορῶν δὲ ἐνέπλησε καὶ ταραχῆς ἐξ ὧν ζῶσα ἐπολιτεύσατο καὶ μετὰ τὴν τελευτὴν τὸ βασίλειον· οὐ μὴν ἀλλὰ καίπερ οὕτως ἄρξασα ἐν εἰρήνῃ καὶ ἀταραξίᾳ τὸ ἔθνος διεφύλαξεν. τὰ μὲν οὖν περὶ Ἀλεξάνδραν τὴν βασίλισσαν τοῦτο εἶχεν τὸ τέλος· ἔρχομαι δὲ λέξων τὰ τοῖς υἱέσιν αὐτῆς συμβεβηκότα Ἀριστοβούλῳ καὶ Ὑρκανῷ μετὰ τὴν ἐκείνης τελευτὴν ἐν τῇ μετὰ ταύτην μου βίβλῳ.", "st": "13.16.6"}, {"sp": "HDR", "t": "Βιβλίον ΙΔʹ", "st": "14"}, {"sp": "N", "t": "Τῶν δὲ περὶ Ἀλεξάνδραν τὴν βασίλισσαν καὶ τὸν θάνατον αὐτῆς ἐν τῇ πρὸ ταύτης ἡμῖν βίβλῳ δεδηλωμένων τὰ τούτοις ἀκόλουθα καὶ προσεχῆ νῦν ἐροῦμεν, οὐκ ἄλλου τινὸς ἢ τοῦ μηδὲν παραλιπεῖν τῶν πραγμάτων ἢ δι’ ἄγνοιαν ἢ διὰ κάματον τῆς μνήμης προμηθούμενοι. τὴν γὰρ ἱστορίαν καὶ τὴν μήνυσιν τῶν ἀγνοουμένων τοῖς πολλοῖς πραγμάτων διὰ τὴν ἀρχαιότητα δεῖ μὲν καὶ τὸ τῆς ἀπαγγελίας κάλλος, ὅσον δὴ τοῦτ’ ἔστιν ἔκ τε τῶν ὀνομάτων καὶ τῆς τούτων ἁρμονίας καὶ ὅσα πρὸς τούτοις συμβάλλεται κόσμον τῷ λόγῳ, τοῖς ἀναγνωσομένοις ἔχειν, ὡς ἂν μετὰ χάριτός τινος καὶ ἡδονῆς τὴν ἐμπειρίαν παραλαμβάνοιεν, πάντων δὲ μᾶλλον τῆς ἀκριβείας τοὺς συγγραφεῖς στοχάζεσθαι μηδὲν τοῦ τἀληθῆ λέγειν τοῖς περὶ ὧν οὐκ ἴσασιν αὐτοὶ πιστεύειν αὐτοῖς μέλλουσιν προτιμῶντας.", "st": "14.1.1"}, {"sp": "N", "t": "Παραλαβόντος γὰρ τὴν βασιλείαν Ὑρκανοῦ τῷ τρίτῳ ἔτει τῆς ἑβδόμης καὶ ἑβδομηκοστῆς πρὸς ταῖς ἑκατὸν ὀλυμπιάδος, ὑπατεύοντος Ῥωμαίων Κυίντου Ὁρτησίου καὶ Κυίντου Μετέλλου, ὃς δὴ καὶ Κρητικὸς ἐπεκαλεῖτο, πόλεμον εὐθὺς ἐκφέρει πρὸς αὐτὸν Ἀριστόβουλος, καὶ τῆς μάχης αὐτῷ γενομένης πρὸς Ἱεριχοῦντι πολλοὶ τῶν στρατιωτῶν αὐτοῦ πρὸς τὸν ἀδελφὸν αὐτομολοῦσιν. οὗ γενομένου φεύγει πρὸς τὴν ἀκρόπολιν Ὑρκανός, ἔνθα συνέβαινεν κατεῖρχθαι τὴν Ἀριστοβούλου γυναῖκα καὶ τοὺς παῖδας αὐτοῦ ὑπὸ τῆς μητρός, καθὼς προειρήκαμεν, καὶ τοὺς ἀντιστασιώτας δὲ καταφυγόντας εἰς τὸν τοῦ ἱεροῦ περίβολον αἱρεῖ προσβαλών. καὶ λόγους ποιησάμενος πρὸς τὸν ἀδελφὸν περὶ συμβάσεως καταλύεται τὴν ἔχθραν ἐπὶ τῷ βασιλεύειν μὲν Ἀριστόβουλον, αὐτὸν δὲ ζῆν ἀπραγμόνως καρπούμενον ἀδεῶς τὴν ὑπάρχουσαν αὐτῷ κτῆσιν. ταῦτα ἐπὶ τοῖς ἐν τῷ ἱερῷ συνθέμενοι καὶ ὅρκοις καὶ δεξιαῖς πιστωσάμενοι τὰς ὁμολογίας καὶ κατασπασάμενοι τοῦ πλήθους παντὸς ὁρῶντος ἀλλήλους ἀνεχώρησαν, ὁ μὲν εἰς τὰ βασίλεια, Ὑρκανὸς δ’ ὡς ἰδιώτης τυγχάνων εἰς τὴν οἰκίαν τὴν Ἀριστοβούλου.", "st": "14.1.2"}, {"sp": "N", "t": "Φίλος δέ τις Ὑρκανοῦ Ἰδουμαῖος Ἀντίπατρος λεγόμενος, πολλῶν μὲν εὐπόρει χρημάτων, δραστήριος δὲ ὢν τὴν φύσιν καὶ στασιαστὴς ἀλλοτρίως εἶχεν πρὸς τὸν Ἀριστόβουλον καὶ διαφόρως διὰ τὴν πρὸς τὸν Ὑρκανὸν εὔνοιαν. Νικόλαος μέντοι φησὶν ὁ Δαμασκηνὸς τοῦτον εἶναι γένος ἐκ τῶν πρώτων Ἰουδαίων τῶν ἐκ Βαβυλῶνος εἰς τὴν Ἰουδαίαν ἀφικομένων. ταῦτα δὲ λέγει χαριζόμενος Ἡρώδῃ τῷ παιδὶ αὐτοῦ βασιλεῖ τῶν Ἰουδαίων ἐκ τύχης τινὸς γενομένῳ, περὶ οὗ κατὰ καιρὸν δηλώσομεν. οὗτος τοίνυν ὁ Ἀντίπατρος Ἀντίπας τὸ πρῶτον ἐκαλεῖτο καὶ τῷ πατρὶ αὐτοῦ τοῦτο γὰρ ἦν τὸ ὄνομα, ὃν Ἀλεξάνδρου τοῦ βασιλέως καὶ τῆς γυναικὸς αὐτοῦ στρατηγὸν ἀποδειξάντων ὅλης τῆς Ἰδουμαίας ποιήσασθαι φιλίαν πρὸς τοὺς ὁμοροῦντας αὐτῷ Ἄραβας καὶ Γαζαίους καὶ Ἀσκαλωνίτας λέγουσιν πολλαῖς αὐτοὺς καὶ μεγάλαις ἐξιδιωσάμενον δωρεαῖς. τὴν οὖν Ἀριστοβούλου δυναστείαν ὁ νεώτερος Ἀντίπατρος ὑφορώμενος καὶ δεδιώς, μή τι πάθῃ διὰ τὸ πρὸς αὐτὸν μῖσος, ἐπισυνιστᾷ κατ’ αὐτοῦ κρύφα διαλεγόμενος τῶν Ἰουδαίων τοὺς δυναστεύοντας, ἄδικον εἶναι λέγων περιορᾶν Ἀριστόβουλον ἀδίκως ἔχοντα τὴν ἀρχήν, καὶ τὸν μὲν ἀδελφὸν ταύτης ἐκβεβληκότα πρεσβύτερον ὄντα, κατέχοντα δ’ αὐτὴν οὖσαν ἐκείνου διὰ τὸ πρεσβεῖον. τούτους τε συνεχῶς πρὸς τὸν Ὑρκανὸν ποιούμενος διετέλει τοὺς λόγους, καὶ ὅτι κινδυνεύσει τῷ ζῆν, εἰ μὴ φυλάξαιτο ποιήσας αὑτὸν ἐκποδών· τοὺς γὰρ φίλους τοὺς Ἀριστοβούλου μηδένα παραλείπειν καιρὸν ἔλεγεν συμβουλεύοντας αὐτὸν ἀνελεῖν ὡς τότε βεβαίως ἕξοντα τὴν ἀρχήν. τούτοις Ὑρκανὸς ἠπίστει τοῖς λόγοις φύσει χρηστὸς ὢν καὶ διαβολὴν δι’ ἐπιείκειαν οὐ προσιέμενος ῥᾳδίως. ἐποίει δ’ αὐτὸν τὸ ἄπραγμον καὶ τὸ παρειμένον τῆς διανοίας τοῖς ὁρῶσιν ἀγεννῆ καὶ ἄνανδρον δοκεῖν· τῆς δ’ ἐναντίας φύσεως ἦν Ἀριστόβουλος, δραστήριος καὶ διεγηγερμένος τὸ φρόνημα.", "st": "14.1.3"}, {"sp": "N", "t": "Ἐπειδὴ τοίνυν ὁ Ἀντίπατρος οὐ προσέχοντα ἑώρα τοῖς λόγοις τὸν Ὑρκανόν, οὐ διέλιπεν ἑκάστης ἡμέρας πλαττόμενος καὶ διαβάλλων πρὸς αὐτὸν τὸν Ἀριστόβουλον ὡς ἀποκτεῖναι θέλοντα, καὶ μόλις ἐγκείμενος πείθει πρὸς Ἀρέταν αὐτῷ συμβουλεύσας φυγεῖν τὸν Ἀράβων βασιλέα· πεισθέντι γὰρ ἔσεσθαι καὶ αὐτὸς σύμμαχος ὑπισχνεῖτο. ὁ δὲ ταῦτ’ ἀκούων συμφέρειν ἦν ἐπὶ τῷ πρὸς τὸν Ἀρέταν ἀποδρᾶναι, ἔστιν δὲ ὅμορος τῇ Ἰουδαίᾳ Ἀραβία, καὶ δὴ πέμπει πρῶτον Ὑρκανὸς πρὸς τὸν τῶν Ἀράβων βασιλέα τὸν Ἀντίπατρον ληψόμενον πίστεις, ὡς οὐκ ἐκδώσει τοῖς ἐχθροῖς ἱκέτην αὐτοῦ γενόμενον. λαβὼν δὲ τὰς πίστεις ὁ Ἀντίπατρος ὑπέστρεψε πρὸς Ὑρκανὸν εἰς Ἱεροσόλυμα, καὶ μετ’ οὐ πολὺ παραλαβὼν αὐτὸν καὶ τῆς πόλεως ὑπεξελθὼν νύκτωρ καὶ πολλὴν ἀνύσας ὁδὸν ἧκεν ἄγων εἰς τὴν καλουμένην Πέτραν, ὅπου τὰ βασίλεια ἦν τῷ Ἀρέτᾳ. μάλιστα δὲ ὢν φίλος τῷ βασιλεῖ κατάγειν τὸν Ὑρκανὸν εἰς τὴν Ἰουδαίαν παρεκάλει· καὶ τοῦθ’ ἑκάστης ἡμέρας ποιῶν καὶ οὐκ ἀνιείς, ἀλλὰ καὶ δωρεὰς προϊέμενος, πείθει τὸν Ἀρέταν. οὐ μὴν ἀλλὰ καὶ Ὑρκανὸς ὑπέσχετο αὐτῷ καταχθεὶς καὶ τὴν βασιλείαν κομισάμενος ἀποδώσειν τήν τε χώραν καὶ τὰς δώδεκα πόλεις, ἃς Ἀλέξανδρος ὁ πατὴρ αὐτοῦ τῶν Ἀράβων ἀφείλετο. ἦσαν δ’ αὗται Μήδαβα, Λιββα, Ναβαλώθ, Ἀραβαθα, Γαλανθώνη, Ζωϊρα, Ὠρωναιδιγωβασιλισσαρυδδα, Αλουσα, Ωρυβδα.", "st": "14.1.4"}, {"sp": "N", "t": "Τούτων αὐτῷ τῶν ὑποσχέσεων γενομένων ὁ Ἀρέτας ἐστράτευσεν ἐπὶ τὸν Ἀριστόβουλον μετὰ πέντε μυριάδων ἱππέων ἅμα καὶ πεζῆς στρατιᾶς, καὶ νικᾷ τῇ μάχῃ. πολλῶν δὲ μετὰ τὴν νίκην πρὸς Ὑρκανὸν αὐτομολησάντων μονωθεὶς ὁ Ἀριστόβουλος ἔφυγεν εἰς Ἱεροσόλυμα. ὁ δὲ τῶν Ἀράβων βασιλεὺς πᾶσαν τὴν στρατιὰν ἀγαγὼν καὶ προσβαλὼν τῷ ἱερῷ τὸν Ἀριστόβουλον ἐπολιόρκει προστιθεμένου καὶ τοῦ δήμου τῷ Ὑρκανῷ καὶ συμπολιορκοῦντος αὐτῷ, μόνων δὲ τῶν ἱερέων τῷ Ἀριστοβούλῳ προσμενόντων. ὁ μὲν οὖν Ἀρέτας ἑξῆς βαλόμενος στρατόπεδα τῶν Ἀράβων καὶ τῶν Ἰουδαίων ἰσχυρῶς ἐνέκειτο τῇ πολιορκίᾳ. τούτων δὲ γινομένων κατὰ τὸν καιρὸν τῆς τῶν ἀζύμων ἑορτῆς, ἣν πάσχα λέγομεν, οἱ δοκιμώτατοι τῶν Ἰουδαίων ἐκλιπόντες τὴν χώραν εἰς Αἴγυπτον ἔφυγον. Ὀνίαν δέ τινα ὄνομα δίκαιον ὄντα καὶ θεοφιλῆ, ὃς ἀνομβρίας ποτὲ οὔσης ηὔξατο τῷ θεῷ λῦσαι τὸν αὐχμὸν καὶ γενόμενος ἐπήκοος ὁ θεὸς ὗσεν, κρύψαντα ἑαυτὸν διὰ τὸ τὴν στάσιν ὁρᾶν ἰσχυρὰν ἐπιμένουσαν, ἀναχθέντα εἰς τὸ στρατόπεδον τῶν Ἰουδαίων ἠξίουν, ὡς ἔπαυσε τὴν ἀνομβρίαν εὐξάμενος, ἵν’ οὕτως ἀρὰς θῇ κατὰ Ἀριστοβούλου καὶ τῶν συστασιαστῶν αὐτοῦ. ἐπεὶ δὲ ἀντιλέγων καὶ παραιτούμενος ἐβιάσθη ὑπὸ τοῦ πλήθους, στὰς μέσος αὐτῶν εἶπεν· ὦ θεὲ βασιλεῦ τῶν ὅλων, ἐπεὶ οἱ μετ’ ἐμοῦ συνεστῶτες σὸς δῆμός ἐστιν καὶ οἱ πολιορκούμενοι δὲ ἱερεῖς σοί, δέομαι μήτε κατὰ τούτων ἐκείνοις ὑπακοῦσαι μήτε κατ’ ἐκείνων ἃ οὗτοι παρακαλοῦσιν εἰς τέλος ἀγαγεῖν. καὶ τὸν μὲν ταῦτ’ εὐξάμενον περιστάντες οἱ πονηροὶ τῶν Ἰουδαίων κατέλευσαν.", "st": "14.2.1"}, {"sp": "N", "t": "Ὁ δὲ θεὸς ταύτης αὐτοὺς παραχρῆμα ἐτιμωρήσατο τῆς ὠμότητος καὶ δίκην εἰσεπράξατο τοῦ Ὀνίου φόνου τούτῳ τῷ τρόπῳ· πολιορκουμένων τῶν ἱερέων καὶ τοῦ Ἀριστοβούλου συνέβη τὴν ἑορτὴν ἐπιστῆναι τὴν καλουμένην φάσκα, καθ’ ἣν ἔθος ἐστὶν ἡμῖν πολλὰ θύειν τῷ θεῷ. ἀποροῦντες δὲ θυμάτων οἱ περὶ τὸν Ἀριστόβουλον ἠξίωσαν αὐτοῖς τοὺς ὁμοφύλους παρασχεῖν χρήματα λαβόντας ἀντὶ τῶν θυμάτων ὅσα θέλουσιν. τῶν δέ, εἰ βούλονται λαβεῖν, χιλίας δραχμὰς ὑπὲρ ἑκάστης κεφαλῆς καταβαλεῖν κελευόντων, προθύμως ὅ τε Ἀριστόβουλος καὶ οἱ ἱερεῖς ὑπέστησαν καὶ διὰ τῶν τειχῶν καθιμήσαντες ἔδωκαν αὐτοῖς τὰ χρήματα. κἀκεῖνοι λαβόντες οὐκ ἀπέδωκαν τὰ θύματα, ἀλλ’ εἰς τοῦτο πονηρίας ἦλθον, ὥστε παραβῆναι τὰς πίστεις καὶ ἀσεβῆσαι τὸν θεὸν τὰ πρὸς τὰς θυσίας μὴ παρασχόντες τοῖς δεομένοις. παρασπονδηθέντες δὲ οἱ ἱερεῖς ηὔξαντο τὸν θεὸν δίκην αὐτῶν εἰσπράξασθαι παρὰ τῶν ὁμοφύλων, ὁ δὲ οὐκ ἀνεβάλετο τὴν τιμωρίαν, ἀλλὰ πνεῦμα πολὺ καὶ βίαιον ἐπιπέμψας τὸν καρπὸν ἁπάσης τῆς χώρας διέφθειρεν, ὡς τὸν μόδιον τοῦ σίτου τότε αὐτοὺς ἐξωνεῖσθαι δραχμῶν ἕνδεκα.", "st": "14.2.2"}, {"sp": "N", "t": "Ἐν τούτῳ πέμπει Σκαῦρον εἰς Συρίαν Πομπήιος αὐτὸς ὢν ἐν Ἀρμενίᾳ καὶ πολεμῶν ἔτι Τιγράνῃ. ὁ δὲ ἀφικόμενος εἰς Δαμασκὸν Λόλλιον καὶ Μέτελλον νεωστὶ τὴν πόλιν ᾑρηκότας εὑρὼν αὐτὸς εἰς τὴν Ἰουδαίαν ἠπείγετο. παραγενομένου δὲ πρέσβεις ἧκον πρὸς αὐτὸν παρά τε Ἀριστοβούλου καὶ Ὑρκανοῦ συμμαχεῖν ἀξιούντων ἑκατέροις. ὑπισχνουμένου δὲ Ἀριστοβούλου τετρακόσια δώσειν τάλαντα, τοῦ δὲ Ὑρκανοῦ τούτων οὐκ ἐλάττονα παρέξειν, προσδέχεται τὴν Ἀριστοβούλου ὑπόσχεσιν· καὶ γὰρ εὔπορος χρημάτων καὶ μεγαλόψυχος ἦν καὶ μετριωτέρων ἠξίου τυγχάνειν, ὁ δὲ πένης ἦν καὶ γλίσχρος καὶ περὶ μειζόνων τὴν ἄπιστον προύτεινεν ἐπαγγελίαν. οὐ γὰρ ἴσον ἦν βίᾳ πόλιν ἑλεῖν ἐν ταῖς μάλιστα ὀχυρὰν καὶ δυνατήν, ἢ φυγάδας ἐκβαλεῖν μετὰ τοῦ Ναβαταίων πλήθους οὐκ εὖ πρὸς πόλεμον διακειμένων. τούτῳ τοίνυν προσθέμενος διὰ τὰς προειρημένας αἰτίας λαβὼν τὰ χρήματα λύει τὴν πολιορκίαν, κελεύσας ἀναχωρεῖν τὸν Ἀρέταν ἢ πολέμιον αὐτὸν Ῥωμαίων ἀποδειχθήσεσθαι. καὶ Σκαῦρος μὲν εἰς Δαμασκὸν πάλιν ἀνεχώρησεν, Ἀριστόβουλος δὲ μετὰ πολλῆς δυνάμεως ἐπί τε Ἀρέταν καὶ Ὑρκανὸν ἐστράτευσεν καὶ συμβαλὼν αὐτοῖς περὶ τὸν καλούμενον Παπυρῶνα νικᾷ τῇ μάχῃ καὶ κτείνει περὶ ἑξακισχιλίους τῶν πολεμίων, μεθ’ ὧν ἔπεσεν καὶ Φαλλίων ὁ Ἀντιπάτρου ἀδελφός.", "st": "14.2.3"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ Πομπηίου εἰς Δαμασκὸν ἀφικομένου καὶ κοίλην Συρίαν ἐπιόντος ἧκον παρ’ αὐτὸν πρέσβεις ἐξ ὅλης Συρίας καὶ Αἰγύπτου καὶ ἐκ τῆς Ἰουδαίας· ἔπεμψε γὰρ αὐτῷ μέγα δῶρον Ἀριστόβουλος ἄμπελον χρυσῆν ἐκ πεντακοσίων ταλάντων. μέμνηται δὲ τοῦ δώρου καὶ Στράβων ὁ Καππάδοξ λέγων οὕτως· ἦλθεν δὲ καὶ ἐξ Αἰγύπτου πρεσβεία καὶ στέφανος ἀπὸ χρυσῶν τετρακισχιλίων καὶ ἐκ τῆς Ἰουδαίας εἴτε ἄμπελος εἴτε κῆπος· τερπωλὴν ὠνόμαζον τὸ δημιούργημα. τοῦτο μέντοι τὸ δῶρον ἱστορήκαμεν καὶ ἡμεῖς ἀνακείμενον ἐν Ῥώμῃ ἐν τῷ ἱερῷ τοῦ Διὸς τοῦ Καπετωλίου ἐπιγραφὴν ἔχον Ἀλεξάνδρου τοῦ τῶν Ἰουδαίων βασιλέως. ἐτιμήθη δὲ εἶναι πεντακοσίων ταλάντων Ἀριστόβουλον μὲν οὖν τοῦτο λέγεται πέμψαι τὸν Ἰουδαίων δυνάστην.", "st": "14.3.1"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ ἧκον πάλιν πρέσβεις πρὸς αὐτὸν Ἀντίπατρος μὲν ὑπὲρ Ὑρκανοῦ, Νικόδημος δὲ ὑπὲρ Ἀριστοβούλου, ὃς δὴ καὶ κατηγόρει τῶν λαβόντων χρήματα Γαβινίου μὲν πρότερον Σκαύρου δὲ ὕστερον, τοῦ μὲν τριακόσια τοῦ δὲ τετρακόσια τάλαντα, πρὸς τοῖς ἄλλοις καὶ τούτους ἐχθροὺς αὐτῷ κατασκευάζων. κελεύσας δὲ ἥκειν τοὺς διαμφισβητοῦντας ἐνισταμένου τοῦ ἔαρος ἀναλαβὼν τὴν δύναμιν ἐκ τῶν χειμαδίων ὥρμησεν ἐπὶ τῆς Δαμασκηνῆς. καὶ τήν τε ἄκραν ἐν παρόδῳ τὴν ἐν Ἀπαμείᾳ κατέσκαψεν, ἣν ὁ Κυζικηνὸς ἐτείχισεν Ἀντίοχος, καὶ τὴν Πτολεμαίου τοῦ Μενναίου χώραν κατενόησεν, ἀνδρὸς πονηροῦ καὶ οὐδὲν ἐλάσσονος Διονυσίου τοῦ Τριπολίτου τοῦ πελεκισθέντος, ᾧπερ καὶ κηδεύων ἐτύγχανεν, χιλίοις μέντοι ταλάντοις ἐξωνησαμένου τὴν ὑπὲρ τῶν ἁμαρτημάτων τιμωρίαν, οἷς Πομπήιος τοὺς στρατιώτας ἐμισθοδότησεν. ἐξεῖλεν δὲ καὶ Λυσιάδα χωρίον, οὗ τύραννος ἦν Σίλας ὁ Ἰουδαῖος. διελθὼν δὲ τὰς πόλεις τήν τε Ἡλιούπολιν καὶ τὴν Χαλκίδα καὶ τὸ διεῖργον ὄρος ὑπερβαλὼν τὴν κοίλην προσαγορευομένην Συρίαν ἀπὸ τῆς ἄλλης εἰς Δαμασκὸν ἧκεν. ἔνθα δὴ καὶ τῶν Ἰουδαίων διήκουσεν καὶ τῶν ἡγουμένων αὐτῶν, οἳ πρός τε ἀλλήλους διεφέροντο Ὑρκανὸς καὶ Ἀριστόβουλος καὶ τὸ ἔθνος πρὸς ἀμφοτέρους, τὸ μὲν οὐκ ἀξιοῦν βασιλεύεσθαι· πάτριον γὰρ εἶναι τοῖς ἱερεῦσι τοῦ τιμωμένου παρ’ αὐτοῖς θεοῦ πειθαρχεῖν, ὄντας δὲ τούτους ἀπογόνους τῶν ἱερέων εἰς ἄλλην μετάγειν ἀρχὴν τὸ ἔθνος ζητῆσαι, ὅπως καὶ δοῦλον γένοιτο. Ὑρκανὸς δὲ κατηγόρει, ὅτι πρεσβύτερος ὢν ἀφαιρεθείη τὸ πρεσβεῖον ὑπὸ Ἀριστοβούλου καὶ μικρὸν ἔχοι μέρος τῆς χώρας ὑφ’ αὑτῷ, τὴν δὲ ἄλλην βίᾳ λαβὼν Ἀριστόβουλος· τάς τε καταδρομὰς τὰς ἐπὶ τοὺς ὁμόρους καὶ τὰ πειρατήρια τὰ ἐν τῇ θαλάττῃ τοῦτον εἶναι τὸν συστήσαντα διέβαλεν, οὐκ ἂν οὐδ’ ἀποστῆναι λέγων τὸ ἔθνος αὐτοῦ, εἰ μὴ βίαιός τις καὶ ταραχώδης ὑπῆρχεν. συνηγόρουν δὲ αὐτῷ ταῦτα λέγοντι πλείους ἢ χίλιοι τῶν δοκιμωτάτων Ἰουδαίων Ἀντιπάτρου παρασκευάσαντος. ὁ δὲ τοῦ μὲν ἐκπεσεῖν αὐτὸν τῆς ἀρχῆς τὴν ἐκείνου φύσιν ᾐτιᾶτο ἄπρακτον οὖσαν καὶ διὰ τοῦτ’ εὐκαταφρόνητον, αὐτὸν δ’ ἔλεγεν φόβῳ τοῦ μὴ πρὸς ἄλλους μεταστῆναι τὴν ἀρχὴν ἐν ἀνάγκης αὐτὴν ὑπελθεῖν, προσαγορεύεσθαι δὲ αὐτὸν τοῦτο ὅπερ καὶ Ἀλέξανδρον τὸν πατέρα. καὶ δὴ μάρτυρας τούτων ἐκάλει τοὺς νέους καὶ σοβαρωτέρους, ὧν ἐβδελύττοντο τὰς πορφυρίδας καὶ τὰς κόμας καὶ τὰ φάλαρα καὶ τὸν ἄλλον κόσμον, ὃν ὥσπερ οὐ δίκην ὑφέξοντες, ἀλλ’ ὡς εἰς πομπὴν προϊόντες περιέκειντο.", "st": "14.3.2"}, {"sp": "N", "t": "Πομπήιος δὲ τούτων ἀκούσας καὶ καταγνοὺς Ἀριστοβούλου βίαν, τότε μὲν αὐτοὺς ἀπέπεμψεν διαλεχθεὶς πρᾴως, ἐλθὼν δ’ εἰς τὴν χώραν αὐτῶν ἔλεγεν διατάξειν ἕκαστα, ἐπειδὰν τὰ τῶν Ναβαταίων πρῶτον ἴδῃ. τέως δὲ ἐκέλευσεν ἡσυχίαν ἄγειν θεραπεύων ἅμα τὸν Ἀριστόβουλον, μὴ τὴν χώραν ἀποστήσῃ καὶ διακλεισθείη τῶν παρόδων. ἔτυχεν μέντοι τοῦτο ἐξ Ἀριστοβούλου γενόμενον· οὐ γὰρ ἀναμείνας οὐδὲν ὧν διελέχθη πρὸς αὐτὸν ὁ Πομπήιος εἰς Δειλον πόλιν ἦλθεν κἀκεῖθεν εἰς τὴν Ἰουδαίαν ἀπῆρεν.", "st": "14.3.3"}, {"sp": "N", "t": "Ὀργίζεται δ’ ἐπὶ τούτοις ὁ Πομπήιος, καὶ τὴν ἐπὶ τοὺς Ναβαταίους ἀναλαβὼν στρατιὰν ἔκ τε Δαμασκοῦ καὶ τῆς ἄλλης Συρίας ἐπικουρικὰ σὺν τοῖς ὑπάρχουσιν αὐτῷ Ῥωμαίων τάγμασιν ἐστράτευσεν ἐπὶ τὸν Ἀριστόβουλον. ὡς δὲ παραμειψάμενος Πέλλαν καὶ Σκυθόπολιν εἰς Κορέας ἧκεν, ἥτις ἐστὶν ἀρχὴ τῆς Ἰουδαίας διεξιόντι τὴν μεσόγειον, ἐνταῦθα εἴς τι περικαλλὲς ἔρυμα ἐπ’ ἄκρου τοῦ ὄρους ἱδρυμένον Ἀλεξάνδρειον Ἀριστοβούλου συμπεφευγότος, πέμψας ἐκέλευσεν ἥκειν πρὸς αὐτόν. ὁ δὲ παραινούντων πολλῶν μὴ πολεμεῖν Ῥωμαίοις κάτεισιν καὶ δικαιολογησάμενος πρὸς τὸν ἀδελφὸν περὶ τῆς ἀρχῆς πάλιν εἰς τὴν ἀκρόπολιν ἀναβαίνει Πομπηίου συγχωρήσαντος. καὶ τοῦτ’ ἐποίησεν δὶς καὶ τρίς, ἅμα μὲν κολακεύων τὴν ἀπ’ αὐτοῦ περὶ τῆς βασιλείας ἐλπίδα καὶ πρὸς ἕκαστον ὧν κελεύσειεν Πομπήιος ὑπακούειν ὑποκρινόμενος, ἅμα δὲ ἀναχωρῶν εἰς τὸ ἔρυμα ὑπὲρ τοῦ μὴ καταλύειν αὑτὸν καὶ πρὸς τὸ πολεμεῖν ἀφορμὴν αὑτῷ παρασκευαζόμενος, δεδιὼς μὴ τὴν ἀρχὴν εἰς Ὑρκανὸν περιστήσῃ. κελεύοντος δὲ Πομπηίου παραδιδόναι τὰ ἐρύματα καὶ τοῖς φρουράρχοις ἐπιστέλλειν τῇ ἑαυτοῦ χειρί, παραδέχεσθαι δὲ ἄλλως ἀπείρητο, πείθεται μέν, δυσανασχετῶν δ’ ἀνεχώρησεν εἰς Ἱεροσόλυμα καὶ ἐν παρασκευῇ τοῦ πολεμεῖν ἐγίνετο. καὶ μετ’ οὐ πολὺ Πομπηίῳ στρατιὰν ἐπ’ αὐτὸν ἄγοντι καθ’ ὁδὸν ἀφικόμενοί τινες ἐκ πόντου τὴν Μιθριδάτου τελευτὴν ἐμήνυον τὴν ἐκ Φαρνάκου τοῦ παιδὸς αὐτῷ γενομένην.", "st": "14.3.4"}, {"sp": "N", "t": "Στρατοπεδευσάμενος δὲ περὶ Ἱεριχοῦντα, οὗ τὸν φοίνικα συμβέβηκε τρέφεσθαι καὶ τὸ ὀποβάλσαμον μύρων ἀκρότατον, ὃ τῶν θάμνων τεμνομένων ὀξεῖ λίθῳ ἀναπιδύει ὥσπερ ὀπός, ἕωθεν ἐπὶ Ἱεροσολύμων ἐχώρει. καὶ μετανοήσας Ἀριστόβουλος ἀφικνεῖται πρὸς Πομπήιον, καὶ χρήματά τε διδοὺς καὶ τοῖς Ἱεροσολύμοις αὐτὸν εἰσδεχόμενος παρεκάλει παύσασθαι τοῦ πολέμου καὶ πράττειν μετ’ εἰρήνης ὅ τι βούλεται. συγγνοὺς δὲ ὁ Πομπήιος αὐτῷ δεομένῳ πέμπει Γαβίνιον καὶ στρατιώτας ἐπί τε τὰ χρήματα καὶ τὴν πόλιν. οὐ μὴν ἐπράχθη τι τούτων, ἀλλ’ ἐπανῆλθεν ὁ Γαβίνιος τῆς τε πόλεως ἀποκλεισθεὶς καὶ τὰ χρήματα μὴ λαβών, τῶν Ἀριστοβούλου στρατιωτῶν οὐκ ἐπιτρεψάντων τὰ συγκείμενα γενέσθαι. ὀργὴ δ’ ἐπὶ τούτοις Πομπήιον λαμβάνει, καὶ τὸν Ἀριστόβουλον ἐν φυλακῇ καταστήσας αὐτὸς ἐπὶ τὴν πόλιν ἔρχεται τὰ μὲν ἄλλα πάντα οὖσαν ὀχυράν, μόνῳ δὲ τῷ βορείῳ μέρει φαύλως ἔχουσαν· περιέρχεται γὰρ αὐτὴν φάραγξ εὐρεῖά τε καὶ βαθεῖα ἐντὸς ἀπολαμβάνουσα τὸ ἱερὸν λιθίνῳ περιβόλῳ καρτερῶς πάνυ τετειχισμένον.", "st": "14.4.1"}, {"sp": "N", "t": "Ἦν δὲ τῶν ἀνθρώπων ἔνδον στάσις οὐχ ὁμονοούντων περὶ τῶν ἐνεστώτων, ἀλλὰ τοῖς μὲν ἐδόκει παραδιδόναι Πομπηίῳ τὴν πόλιν, οἱ δὲ τὰ Ἀριστοβούλου φρονοῦντες ἀποκλείειν τε καὶ πολεμεῖν παρῄνουν τῷ κἀκεῖνον ἔχεσθαι δεδεμένον. φθάσαντες δὲ οὗτοι τὸ ἱερὸν καταλαμβάνουσι καὶ τὴν τείνουσαν ἀπ’ αὐτοῦ γέφυραν εἰς τὴν πόλιν εἰς πολιορκίαν εὐτρεπιζόμενοι. οἱ δὲ ἕτεροι δεξάμενοι τὴν στρατιὰν ἐνεχείρισαν Πομπηίῳ τήν τε πόλιν καὶ τὰ βασίλεια. Πομπήιος δὲ Πείσωνα τὸν ὑποστράτηγον πέμψας σὺν στρατιᾷ τήν τε πόλιν καὶ τὰ βασίλεια ἐφρούρει καὶ τὰς οἰκίας τὰς πρὸς τῷ ἱερῷ καὶ ὅσα ἦν ἔξω περὶ τὸ ἱερὸν ὠχύρου. καὶ τὸ μὲν πρῶτον λόγους συμβατηρίους τοῖς ἐντὸς προσέφερεν, οὐχ ὑπακουόντων δὲ εἰς ἃ προεκαλεῖτο τὰ πέριξ ἐτείχιζε χωρία πρὸς ἅπαντα Ὑρκανοῦ προθύμως ὑπηρετοῦντος. Πομπήιος δὲ ἕωθεν στρατοπεδεύεται κατὰ τὸ βόρειον τοῦ ἱεροῦ μέρος, ὅθεν ἦν ἐπίμαχον. ἀνεστήκεσαν δὲ καὶ ἐνταῦθα μεγάλοι πύργοι καὶ τάφρος τε ὀρώρυκτο καὶ βαθείᾳ περιείχετο φάραγγι· ἀπερρώγει γὰρ καὶ τὰ πρὸς τὴν πόλιν τῆς γεφύρας ἀνατετραμμένης ἐφ’ οὗ δὴ Πομπήιος καὶ τὸ χῶμα ὁσημέραι ταλαιπωρούμενος ἐγήγερτο τεμνόντων τὴν πέριξ ὕλην Ῥωμαίων. καὶ ἐπειδὴ τοῦτ’ εἶχεν ἱκανῶς μόλις πλησθείσης τῆς τάφρου διὰ βάθος ἄπειρον προσβαλὼν μηχανὰς καὶ ὄργανα ἐκ Τύρου κομισθέντα ἐπιστήσας κατήρασσε τὸ ἱερὸν τοῖς πετροβόλοις. εἰ δὲ μὴ πάτριον ἦν ἡμῖν ἀργεῖν τὰς ἑβδομάδας ἡμέρας, οὐκ ἂν ἠνύσθη τὸ χῶμα κωλυόντων ἐκείνων· ἄρχοντας μὲν γὰρ μάχης καὶ τύπτοντας ἀμύνασθαι δίδωσιν ὁ νόμος, ἄλλο δέ τι δρῶντας τοὺς πολεμίους οὐκ ἐᾷ.", "st": "14.4.2"}, {"sp": "N", "t": "Ὃ δὴ καὶ Ῥωμαῖοι συνιδόντες κατ’ ἐκείνας τὰς ἡμέρας, ἃ δὴ σάββατα καλοῦμεν, οὔτ’ ἔβαλλον τοὺς Ἰουδαίους οὔτε εἰς χεῖρας αὐτοῖς ὑπήντων, χοῦν δὲ καὶ πύργους ἀνίστασαν καὶ τὰ μηχανήματα προσῆγον, ὥστ’ αὐτοῖς εἰς τὴν ἐπιοῦσαν ἐνεργὰ ταῦτ’ εἶναι. μάθοι δ’ ἄν τις ἐντεῦθεν τὴν ὑπερβολὴν ἧς ἔχομεν περὶ τὸν θεὸν εὐσεβείας καὶ τὴν φυλακὴν τῶν νόμων, μηδὲν ὑπὸ τῆς πολιορκίας διὰ φόβον ἐμποδιζομένων πρὸς τὰς ἱερουργίας, ἀλλὰ δὶς τῆς ἡμέρας πρωΐ τε καὶ περὶ ἐνάτην ὥραν ἱερουργούντων ἐπὶ τοῦ βωμοῦ, καὶ μηδὲ εἴ τι περὶ τὰς προσβολὰς δύσκολον εἴη τὰς θυσίας παυόντων. καὶ γὰρ ἁλούσης τῆς πόλεως περὶ τρίτον μῆνα τῇ τῆς νηστείας ἡμέρᾳ κατὰ ἐνάτην καὶ ἑβδομηκοστὴν καὶ ἑκατοστὴν ὀλυμπιάδα ὑπατευόντων Γαΐου Ἀντωνίου καὶ Μάρκου Τυλλίου Κικέρωνος οἱ πολέμιοι μὲν εἰσπεσόντες ἔσφαττον τοὺς ἐν τῷ ἱερῷ, οἱ δὲ πρὸς ταῖς θυσίαις οὐδὲν ἧττον ἱερουργοῦντες διετέλουν, οὔτε ὑπὸ τοῦ φόβου τοῦ περὶ τῆς ψυχῆς οὔθ’ ὑπὸ τοῦ πλήθους τῶν ἤδη φονευομένων ἀναγκασθέντες ἀποδρᾶναι πᾶν θ’ ὅ τι δέοι παθεῖν τοῦτο παρ’ αὐτοῖς ὑπομεῖναι τοῖς βωμοῖς κρεῖττον εἶναι νομίζοντες ἢ παρελθεῖν τι τῶν νομίμων. ὅτι δὲ οὐ λόγος ταῦτα μόνον ἐστὶν ἐγκώμιον ψευδοῦς εὐσεβείας ἐμφανίζων, ἀλλ’ ἀλήθεια, μαρτυροῦσι πάντες οἱ τὰς κατὰ Πομπήιον πράξεις ἀναγράψαντες, ἐν οἷς καὶ Στράβων καὶ Νικόλαος καὶ πρὸς αὐτοῖς Τίτος Λίβιος ὁ τῆς Ῥωμαϊκῆς ἱστορίας συγγραφεύς.", "st": "14.4.3"}, {"sp": "N", "t": "Ἐπεὶ δὲ τοῦ μηχανήματος προσαχθέντος σεισθεὶς ὁ μέγιστος τῶν πύργων κατηνέχθη καὶ παρέρρηξέν τι χωρίον, εἰσεχέοντο μὲν οἱ πολέμιοι, πρῶτος δὲ αὐτῶν Κορνήλιος Φαῦστος Σύλλα παῖς σὺν τοῖς ἑαυτοῦ στρατιώταις ἐπέβη τοῦ τείχους, μετὰ δὲ αὐτὸν Φούριος ἑκατοντάρχης ἅμα τοῖς ἑπομένοις κατὰ θάτερον μέρος, διὰ μέσων δὲ Φάβιος καὶ αὐτὸς ἑκατοντάρχης σὺν στίφει καρτερῷ. φόνου δὲ ἦν τὰ πάντα ἀνάπλεα. καὶ τῶν Ἰουδαίων οἱ μὲν ὑπὸ Ῥωμαίων, οἱ δ’ ὑπὸ ἀλλήλων ἀνῃροῦντο, εἰσὶν δ’ οἳ καὶ κατὰ κρημνῶν ἑαυτοὺς ἐρρίπτουν καὶ πῦρ ἐνιέντες εἰς τὰς οἰκίας ἐνεπίμπραντο τὰ γινόμενα καρτερεῖν οὐχ ὑπομένοντες. ἔπεσον δὲ τῶν μὲν Ἰουδαίων εἰς μυρίους καὶ δισχιλίους, Ῥωμαίων δὲ πάνυ ὀλίγοι. ἐλήφθη δὲ αἰχμάλωτος καὶ Ἀψάλωμος, θεῖος ἅμα καὶ πενθερὸς Ἀριστοβούλου. παρηνομήθη δὲ οὐ σμικρὰ περὶ τὸν ναὸν ἄβατόν τε ὄντα ἐν τῷ πρὶν χρόνῳ καὶ ἀόρατον· παρῆλθεν γὰρ εἰς τὸ ἐντὸς ὁ Πομπήιος καὶ τῶν περὶ αὐτὸν οὐκ ὀλίγοι καὶ εἶδον ὅσα μὴ θεμιτὸν ἦν τοῖς ἄλλοις ἀνθρώποις ἢ μόνοις τοῖς ἀρχιερεῦσιν. ὄντων δὲ τραπέζης τε χρυσῆς καὶ λυχνίας ἱερᾶς καὶ σπονδείων καὶ πλήθους ἀρωμάτων, χωρὶς δὲ τούτων ἐν τοῖς θησαυροῖς ἱερῶν χρημάτων εἰς δύο χιλιάδας ταλάντων, οὐδενὸς ἥψατο δι’ εὐσέβειαν, ἀλλὰ κἀν τούτῳ ἀξίως ἔπραξεν τῆς περὶ αὐτὸν ἀρετῆς. τῇ τε ὑστεραίᾳ καθαίρειν παραγγείλας τὸ ἱερὸν τοῖς ναοπόλοις καὶ τὰ νόμιμα ἐπιφέρειν τῷ θεῷ τὴν ἀρχιερωσύνην ἀπέδωκεν Ὑρκανῷ διά τε τἆλλα ὅσα χρήσιμος ὑπῆρξεν αὐτῷ, καὶ ὅτι τοὺς κατὰ τὴν χώραν Ἰουδαίους Ἀριστοβούλῳ συμπολεμεῖν ἐκώλυσεν, καὶ τοὺς αἰτίους τοῦ πολέμου τῷ πελέκει διεχρήσατο. τὸν δὲ Φαῦστον καὶ τοὺς ἄλλους ὅσοι τῷ τείχει προθύμως ἐπέβησαν τῶν πρεπόντων ἀριστείων ἠξίωσεν. καὶ τὰ μὲν Ἱεροσόλυμα ὑποτελῆ φόρου Ῥωμαίοις ἐποίησεν, ἃς δὲ πρότερον οἱ ἔνοικοι πόλεις ἐχειρώσαντο τῆς κοίλης Συρίας ἀφελόμενος ὑπὸ τῷ σφετέρῳ στρατηγῷ ἔταξεν καὶ τὸ σύμπαν ἔθνος ἐπὶ μέγα πρότερον αἰρόμενον ἐντὸς τῶν ἰδίων ὅρων συνέστειλεν. καὶ Γάδαρα μὲν μικρὸν ἔμπροσθεν καταστραφεῖσαν ἀνέκτισεν Δημητρίῳ χαριζόμενος τῷ Γαδαρεῖ ἀπελευθέρῳ αὐτοῦ· τὰς δὲ λοιπὰς Ἵππον καὶ Σκυθόπολιν καὶ Πέλλαν καὶ Δῖον καὶ Σαμάρειαν ἔτι τε Μάρισαν καὶ Ἄζωτον καὶ Ἰάμνειαν καὶ Ἀρέθουσαν τοῖς οἰκήτορσιν ἀπέδωκεν. καὶ ταύτας μὲν ἐν τῇ μεσογείῳ χωρὶς τῶν κατεσκαμμένων, Γάζαν δὲ πρὸς τῇ θαλάττῃ καὶ Ἰόππην καὶ Δῶρα καὶ Στράτωνος πύργον, ἣ κτίσαντος αὐτὴν Ἡρώδου μεγαλοπρεπῶς καὶ λιμέσιν τε καὶ ναοῖς κοσμήσαντος, Καισάρεια μετωνομάσθη, πάσας ὁ Πομπήιος ἀφῆκεν ἐλευθέρας καὶ προσένειμεν τῇ ἐπαρχίᾳ.", "st": "14.4.4"}, {"sp": "N", "t": "Τούτου τοῦ πάθους τοῖς Ἱεροσολύμοις αἴτιοι κατέστησαν Ὑρκανὸς καὶ Ἀριστόβουλος πρὸς ἀλλήλους στασιάσαντες· τήν τε γὰρ ἐλευθερίαν ἀπεβάλομεν καὶ ὑπήκοοι Ῥωμαίοις κατέστημεν καὶ τὴν χώραν, ἣν τοῖς ὅπλοις ἐκτησάμεθα τοὺς Σύρους ἀφελόμενοι, ταύτην ἠναγκάσθημεν ἀποδοῦναι τοῖς Σύροις, καὶ προσέτι πλείω ἢ μύρια τάλαντα Ῥωμαῖοι ἐν βραχεῖ χρόνῳ παρ’ ἡμῶν εἰσεπράξαντο, καὶ ἡ βασιλεία πρότερον τοῖς κατὰ γένος ἀρχιερεῦσιν διδομένη, τιμὴ δημοτικῶν ἀνδρῶν ἐγένετο. καὶ περὶ μὲν τούτων κατὰ χώραν ἐροῦμεν. Πομπήιος δὲ τήν τε κοίλην ἄλλην Συρίαν ἕως Εὐφράτου ποταμοῦ καὶ Αἰγύπτου Σκαύρῳ παραδοὺς καὶ δύο τάγματα Ῥωμαίων ἐπὶ Κιλικίας ᾤχετο ἐπειγόμενος εἰς Ῥώμην. ἐπήγετο δὲ μετὰ τῆς γενεᾶς καὶ Ἀριστόβουλον δεδεμένον· δύο γὰρ ἦσαν αὐτῷ θυγατέρες καὶ τοσοῦτοι υἱεῖς, ὧν Ἀλέξανδρος μὲν ἀπέδρα, ὁ δὲ νεώτερος Ἀντίγονος συναπεκομίζετο εἰς Ῥώμην ἅμα ταῖς ἀδελφαῖς.", "st": "14.4.5"}, {"sp": "N", "t": "Σκαύρου δ’ ἐπὶ Πέτραν τῆς Ἀραβίας στρατεύσαντος καὶ διὰ τὸ δυσάλωτον εἶναι τὰ ἐν κύκλῳ δῃοῦντος αὐτῆς καὶ τοῦ στρατεύματος λιμήναντος Ἀντίπατρος κατ’ ἐντολὴν Ὑρκανοῦ σῖτον ἐκ τῆς Ἰουδαίας καὶ τὰ ἄλλα, ὅσων ἐνέδει, παρεῖχεν. πεμφθεὶς δὲ πρὸς Ἀρέταν πρεσβευτὴς ὑπὸ Σκαύρου διὰ τὴν ὑπάρχουσαν ξενίαν πείθει αὐτὸν ἀργύριον ὑπὲρ τοῦ μὴ δῃωθῆναι τὴν χώραν δοῦναι, καὶ αὐτὸς ἐγγυητὴς τριακοσίων ταλάντων γίνεται. καὶ ἐπὶ τούτοις ἔλυσε τὸν πόλεμον Σκαῦρος οὐχ ἧττον αὐτὸς ἢ συνέβαινεν Ἀρέταν ἐπιθυμεῖν τοῦτο γενέσθαι βουλόμενος.", "st": "14.5.1"}, {"sp": "N", "t": "Χρόνῳ δ’ ὕστερον Ἀλεξάνδρου τὴν Ἰουδαίαν κατατρέχοντος τοῦ Ἀριστοβούλου παιδὸς Γαβίνιος ἐκ Ῥώμης στρατηγὸς εἰς Συρίαν ἧκεν, ὃς ἄλλα τε λόγου ἄξια διεπράξατο καὶ ἐπ’ Ἀλέξανδρον ἐστράτευσεν, μηκέτι Ὑρκανοῦ πρὸς τὴν ἐκείνου ῥώμην ἀντέχειν δυναμένου, ἀλλ’ ἀνεγείρειν ἤδη καὶ τὸ τῶν Ἱεροσολύμων τεῖχος ἐπιχειροῦντος, ὅπερ καθεῖλεν Πομπήιος. ἀλλὰ τούτου μὲν αὐτὸν ἐπέσχον οἱ ἐνταῦθα Ῥωμαῖοι. περιιὼν δὲ ἐν κύκλῳ τὴν χώραν πολλοὺς ὥπλιζεν τῶν Ἰουδαίων καὶ συνέλεξεν ταχὺ μυρίους μὲν ὁπλίτας πεντακοσίους δὲ πρὸς τοῖς χιλίοις ἱππεῖς, Ἀλεξάνδρειόν τε ὠχύρου τὸ πρὸς ταῖς Κορέαις ἔρυμα καὶ Μαχαιροῦντα πρὸς τοῖς Ἀραβίοις ὄρεσιν. ἔρχεται οὖν ἐπ’ αὐτὸν Γαβίνιος Μᾶρκον Ἀντώνιον προπέμψας σὺν ἄλλοις ἡγεμόσιν· οἱ δὲ ὁπλίσαντες Ῥωμαίων τοὺς ἑπομένους καὶ σὺν τούτοις τοὺς ὑπηκόους Ἰουδαίους, ὧν Πειθόλαος ἡγεῖτο καὶ Μάλιχος, προσλαβόντες δὲ καὶ τὸ Ἀντιπάτρου ἑταιρικὸν ὑπήντων Ἀλεξάνδρῳ· ἠκολούθει δὲ καὶ Γαβίνιος σὺν τῇ φάλαγγι. καὶ ἀναχωρεῖ μὲν ἐγγὺς Ἱεροσολύμων Ἀλέξανδρος, συμπεσόντων δὲ ἀλλήλοις ἐκεῖ καὶ μάχης γενομένης κτείνουσι μὲν οἱ Ῥωμαῖοι τῶν πολεμίων περὶ τρισχιλίους, ζωγροῦσι δὲ οὐκ ἔλαττον.", "st": "14.5.2"}, {"sp": "N", "t": "Ἐν τούτῳ Γαβίνιος ἐπ’ Ἀλεξάνδρειον ἐλθὼν προυκαλεῖτο τοὺς ἔνδον εἰς διαλύσεις συγγνώσεσθαι περὶ τῶν πρόσθεν αὐτοῖς ἡμαρτημένων ὁμολογῶν. στρατοπεδευομένων δὲ πολλῶν πρὸ τοῦ ἐρύματος πολεμίων, ἐφ’ οὓς ἀνῄεσαν οἱ Ῥωμαῖοι, Μᾶρκος Ἀντώνιος ἐπιφανῶς ἀγωνισάμενος καὶ πολλοὺς ἀποκτείνας ἔδοξεν ἠριστευκέναι. Γαβίνιος μὲν οὖν μέρος τῆς στρατιᾶς ἐνταυθοῖ καταλιπών, ἕως ἂν ἐκπολιορκηθῇ τὸ χωρίον, αὐτὸς ἐπῄει τὴν ἄλλην Ἰουδαίαν, καὶ ὅσαις ἐπετύγχανεν καθῃρημέναις τῶν πόλεων κτίζειν παρεκελεύετο. καὶ ἀνεκτίσθησαν Σαμάρεια καὶ Ἄζωτος καὶ Σκυθόπολις καὶ Ἀνθηδὼν καὶ Ῥάφεια καὶ Ἄδωρα Μάρισά τε καὶ Γάζα καὶ ἄλλαι οὐκ ὀλίγαι. τῶν δὲ ἀνθρώπων πειθομένων οἷς ὁ Γαβίνιος προσέταττεν βεβαίως οἰκηθῆναι τότε συνέβαινε τὰς πόλεις πολὺν χρόνον ἐρήμους γενομένας.", "st": "14.5.3"}, {"sp": "N", "t": "Ταῦτα δὲ διαπραξάμενος κατὰ τὴν χώραν ἐπάνεισιν ἐπὶ τὸ Ἀλεξάνδρειον, καὶ τὴν πολιορκίαν αὐτοῦ κρατύνοντος διαπρεσβεύεται πρὸς αὐτὸν Ἀλέξανδρος συγγινώσκειν τε αὐτῷ τῶν ἡμαρτημένων δεόμενος καὶ παραδιδοὺς τῶν ἐρυμάτων Ὑρκανίαν τε καὶ Μαχαιροῦντα, ὕστερον δὲ καὶ Ἀλεξάνδρειον. καὶ ταῦτα μὲν Γαβίνιος κατέσκαψεν. τῆς δ’ Ἀλεξάνδρου μητρὸς πρὸς αὐτὸν ἐλθούσης, ἣ ἐφρόνει τὰ Ῥωμαίων τοῦ τε ἀνδρὸς αὐτῆς καὶ τῶν ἄλλων τέκνων ἐν Ῥώμῃ ἐχομένων, συνεχώρησεν αὐτῇ ταῦτα ἅπερ ἠξίου, καὶ διοικησάμενος τὰ πρὸς αὐτὴν Ὑρκανὸν κατήγαγεν εἰς Ἱεροσόλυμα σχήσοντα τὴν τοῦ ἱεροῦ ἐπιμέλειαν. πέντε δὲ συνέδρια καταστήσας εἰς ἴσας μοίρας διένειμε τὸ ἔθνος, καὶ ἐπολιτεύοντο οἱ μὲν ἐν Ἱεροσολύμοις οἱ δὲ ἐν Γαδάροις οἱ δὲ ἐν Ἀμαθοῦντι, τέταρτοι δ’ ἦσαν ἐν Ἱεριχοῦντι, καὶ τὸ πέμπτον ἐν Σαπφώροις τῆς Γαλιλαίας. καὶ οἱ μὲν ἀπηλλαγμένοι δυναστείας ἐν ἀριστοκρατίᾳ διῆγον.", "st": "14.5.4"}, {"sp": "N", "t": "Ἀριστοβούλου δὲ διαδράντος ἐκ Ῥώμης εἰς τὴν Ἰουδαίαν καὶ τὸ Ἀλεξάνδρειον, ὅπερ ἦν νεωστὶ κατεσκαμμένον, ἀνακτίζειν προαιρουμένου, πέμπει Γαβίνιος ἐπ’ αὐτὸν στρατιώτας καὶ ἡγεμόνας Σισένναν τε καὶ Ἀντώνιον καὶ Σερουίλιον κωλύσοντάς τε τὸ χωρίον αὐτὸν κατασχεῖν καὶ συλληψομένους αὐτόν. πολλοὶ δ’ Ἀριστοβούλῳ τῶν Ἰουδαίων κατὰ τὴν παλαιὰν εὔκλειαν προσέρρεον καὶ δὴ καὶ νεωτέροις χαίροντες ἀεὶ πράγμασιν· Πειθόλαος γοῦν τις ὑποστράτηγος ἐν Ἱεροσολύμοις ὢν μετὰ χιλίων ηὐτομόλησεν πρὸς αὐτόν· οἱ δὲ πολλοὶ τῶν προστιθεμένων ἦσαν ἄνοπλοι. διεγνώκει δ’ εἰς Μαχαιροῦντα ἀπανίστασθαι Ἀριστόβουλος· τούτους μὲν οὖν ἀπέλυσεν ἀπόρους ὄντας· οὐ γὰρ ἐγίνοντο αὐτῷ χρήσιμοι πρὸς τὰ ἔργα· τοὺς δ’ ὡπλισμένους περὶ ὀκτακισχιλίους ὄντας ἀναλαβὼν ᾤχετο. καὶ προσπεσόντων αὐτοῖς τῶν Ῥωμαίων καρτερῶς ἡττῶνται τῇ μάχῃ γενναίως οἱ Ἰουδαῖοι καὶ προθύμως ἀγωνισάμενοι, βιασαμένων τε τῶν πολεμίων εἰς φυγὴν τρέπονται. καὶ φονεύονται μὲν αὐτῶν εἰς πεντακισχιλίους, οἱ δὲ λοιποὶ σκεδασθέντες ὡς ἐδύναντο σώζειν αὑτοὺς ἐπειρῶντο. χιλίων μέντοι πλείονας ἔχων Ἀριστόβουλος εἰς Μαχαιροῦντα διέφυγεν ὠχύρου τε τὸ χωρίον καὶ πράττων κακῶς οὐδὲν ἧττον ἐλπίδος ἀγαθῆς εἴχετο. δύο δ’ ἡμέρας ἀντισχὼν τῇ πολιορκίᾳ καὶ πολλὰ τραύματα λαβὼν αἰχμάλωτος μετ’ Ἀντιγόνου τοῦ παιδός, ὃς δὴ καὶ συνέφυγεν ἐκ Ῥώμης αὐτῷ, πρὸς Γαβίνιον ἄγεται. καὶ τοιαύτῃ μὲν Ἀριστόβουλος χρησάμενος τύχῃ πάλιν εἰς Ῥώμην ἀναπέμπεται καὶ δεθεὶς αὐτόθι κατείχετο, βασιλεύσας μὲν καὶ ἀρχιερατεύσας ἔτη τρία καὶ μῆνας ἕξ, ἀνὴρ δὲ λαμπρὸς καὶ μεγαλόψυχος γενόμενος. τὰ μέντοι τέκνα αὐτοῦ ἀνῆκεν ἡ σύγκλητος Γαβινίου γράψαντος τοῦθ’ ὑπεσχῆσθαι τῇ μητρὶ παραδούσῃ τὰ ἐρύματα. καὶ ταῦτα μὲν εἰς τὴν Ἰουδαίαν ἐπανέρχεται.", "st": "14.6.1"}, {"sp": "N", "t": "Γαβινίῳ δὲ ἐπὶ Πάρθους στρατεύοντι καὶ τὸν Εὐφράτην ἤδη πεπεραιωμένῳ μετέδοξεν εἰς τὴν Αἴγυπτον ὑποστρέψαντι καταστῆσαι Πτολεμαῖον εἰς αὐτήν. καὶ ταῦτα μὲν καὶ ἐν ἄλλοις δεδήλωται. Γαβινίῳ μέντοι κατὰ τὴν στρατείαν ἣν ἐφ’ Ὑρκανὸν ἐστείλατο Ἀντίπατρος ὑπηρέτησεν σῖτον καὶ ὅπλα καὶ χρήματα, καὶ τοὺς ὑπὲρ Πηλούσιον τῶν Ἰουδαίων οὗτος αὐτῷ προσηγάγετο καὶ συμμάχους ἐποίησεν φύλακας ὄντας τῶν εἰς τὴν Αἴγυπτον ἐμβολῶν. ἐπανελθὼν δ’ ἐκ τῆς Αἰγύπτου καταλαμβάνει τὴν Συρίαν στάσει καὶ ταραχῇ νοσοῦσαν· ὁ γὰρ Ἀριστοβούλου παῖς Ἀλέξανδρος παρελθὼν ἐξ ὑστέρου πάλιν εἰς τὴν ἀρχὴν κατὰ βίαν πολλοὺς μὲν τῶν Ἰουδαίων ἀπέστησεν, στρατεύματι δὲ μεγάλῳ τὴν χώραν ἐπερχόμενος ἔκτεινε πάντας ὅσους ἐπιτύχοι τῶν Ῥωμαίων εἴς τε ὄρος τὸ καλούμενον Γαριζεὶν συμφυγόντας προσέκειτο πολιορκῶν.", "st": "14.6.2"}, {"sp": "N", "t": "Ὁ δὲ Γαβίνιος τοιαῦτα τὰ κατὰ τὴν Συρίαν καταλαβὼν Ἀντίπατρον, συνετὸς γὰρ ἦν, πέμπει πρὸς τοὺς νενοσηκότας, εἰ παῦσαι δυνηθείη τῆς παραφροσύνης αὐτοὺς καὶ πεῖσαι πρὸς τὸν ἀμείνω λογισμὸν ἐπανελθεῖν. ὁ δ’ ἐλθὼν πολλοὺς μὲν ἐσωφρόνισεν καὶ προσηγάγετο τῷ δέοντι, τὸν δὲ Ἀλέξανδρον οὐκ ἠδυνήθη κατασχεῖν· στρατοῦ γὰρ ἔχων οὗτος μυριάδας τρεῖς Ἰουδαίων ἀπήντησεν Γαβινίῳ καὶ συμβαλὼν ἡττᾶται πεσόντων αὐτῷ μυρίων περὶ τὸ Ἰταβύριον ὄρος.", "st": "14.6.3"}, {"sp": "N", "t": "Καταστησάμενος δὲ Γαβίνιος τὰ κατὰ τὴν Ἱεροσολυμιτῶν πόλιν, ὡς ἦν Ἀντιπάτρῳ θέλοντι, ἐπὶ τὴν Ναβαταίων ἔρχεται, καὶ κρατεῖ μὲν τούτων τῇ μάχῃ, Πάρθων δὲ φυγάδας Μιθριδάτην καὶ Ὀρσάνην ἐλθόντας προύπεμψεν, τῷ δὲ λόγῳ ἀπέδρασαν αὐτόν. καὶ Γαβίνιος μὲν ἔργα μεγάλα καὶ λαμπρὰ κατὰ τὴν στρατηγίαν δράσας ἀπῆρεν εἰς Ῥώμην Κράσσῳ παραδοὺς τὴν ἀρχήν. περὶ δὲ τῆς Πομπηίου καὶ Γαβινίου στρατείας ἐπὶ Ἰουδαίους γράφει Νικόλαος ὁ Δαμασκηνὸς καὶ Στράβων ὁ Καππάδοξ οὐδὲν ἕτερος ἑτέρου καινότερον λέγων.", "st": "14.6.4"}, {"sp": "N", "t": "Κράσσος δὲ ἐπὶ Πάρθους μέλλων στρατεύειν ἧκεν εἰς τὴν Ἰουδαίαν καὶ τὰ ἐν τῷ ἱερῷ χρήματα, ἃ Πομπήιος καταλελοίπει, δισχίλια δ’ ἦν τάλαντα, βαστάσας οἷός τε ἦν καὶ τὸν χρυσὸν ἅπαντα, τάλαντα δ’ οὗτος ἦν ὀκτακισχίλια, περιδύειν τοῦ ναοῦ. λαμβάνει δὲ καὶ δοκὸν ὁλοσφύρητον χρυσῆν ἐκ μνῶν τριακοσίων πεποιημένην· ἡ δὲ μνᾶ παρ’ ἡμῖν ἰσχύει λίτρας δύο ἥμισυ. παρέδωκε δ’ αὐτῷ ταύτην τὴν δοκὸν ὁ τῶν χρημάτων φύλαξ ἱερεὺς Ἐλεάζαρος ὄνομα, οὐ διὰ πονηρίαν, ἀγαθὸς γὰρ ἦν καὶ δίκαιος, ἀλλὰ πεπιστευμένος τὴν τῶν καταπετασμάτων τοῦ ναοῦ φυλακὴν ὄντων θαυμασίων τὸ κάλλος καὶ πολυτελῶν τὴν κατασκευὴν ἐκ δὲ τῆς δοκοῦ ταύτης κρεμαμένων, ἐπεὶ τὸν Κράσσον ἑώρα περὶ τὴν τοῦ χρυσίου γινόμενον συλλογήν, δείσας περὶ τῷ παντὶ κόσμῳ [καὶ] τοῦ ναοῦ τὴν δοκὸν αὐτῷ τὴν χρυσῆν λύτρον ἀντὶ πάντων ἔδωκεν, ὅρκους παρ’ αὐτοῦ λαβὼν μηδὲν ἄλλο κινήσειν τῶν ἐκ τοῦ ναοῦ, μόνῳ δὲ ἀρκεσθήσεσθαι τῷ ὑπ’ αὐτοῦ δοθησομένῳ πολλῶν ὄντι μυριάδων ἀξίῳ. ἡ δὲ δοκὸς αὕτη ἦν ἐν ξυλίνῃ δοκῷ κενῇ, καὶ τοῦτο τοὺς μὲν ἄλλους ἐλάνθανεν ἅπαντας, ὁ δὲ Ἐλεάζαρος μόνος ἠπίστατο. ὁ μέντοι Κράσσος καὶ ταύτην ὡς οὐδενὸς ἁψόμενος ἄλλου τῶν ἐν τῷ ἱερῷ λαμβάνει, καὶ παραβὰς τοὺς ὅρκους ἅπαντα τὸν ἐν τῷ ναῷ χρυσὸν ἐξεφόρησεν.", "st": "14.7.1"}, {"sp": "N", "t": "Θαυμάσῃ δὲ μηδείς, εἰ τοσοῦτος ἦν πλοῦτος ἐν τῷ ἡμετέρῳ ἱερῷ πάντων τῶν κατὰ τὴν οἰκουμένην Ἰουδαίων καὶ σεβομένων τὸν θεὸν ἔτι δὲ καὶ τῶν ἀπὸ τῆς Ἀσίας καὶ τῆς Εὐρώπης εἰς αὐτὸ συμφερόντων ἐκ πολλῶν πάνυ χρόνων. οὐκ ἔστι δὲ ἀμάρτυρον τὸ μέγεθος τῶν προειρημένων χρημάτων, οὐδ’ ὑπὸ ἀλαζονείας ἡμετέρας καὶ περιττολογίας ἐπὶ τοσοῦτον ἐξαίρεται πλῆθος, ἀλλὰ πολλοί τε ἄλλοι τῶν συγγραφέων ἡμῖν μαρτυροῦσιν καὶ Στράβων ὁ Καππάδοξ λέγων οὕτως· πέμψας δὲ Μιθριδάτης [εἰς Κῶ] ἔλαβε τὰ χρήματα, ἃ παρέθετο ἐκεῖ Κλεοπάτρα βασίλισσα, καὶ τὰ τῶν Ἰουδαίων ὀκτακόσια τάλαντα. ἡμῖν δὲ δημόσια χρήματα οὐκ ἔστιν ἢ μόνα τὰ τοῦ θεοῦ, καὶ δῆλον, ὅτι ταῦτα μετήνεγκαν εἰς Κῶ τὰ χρήματα οἱ ἐν τῇ Ἀσίᾳ Ἰουδαῖοι διὰ τὸν Μιθριδάτου φόβον· οὐ γὰρ εἰκὸς τοὺς ἐν τῇ Ἰουδαίᾳ πόλιν τε ὀχυρὰν ἔχοντας καὶ τὸν ναὸν πέμπειν χρήματα εἰς Κῶ, ἀλλ’ οὐδὲ τοὺς ἐν Ἀλεξανδρείᾳ κατοικοῦντας Ἰουδαίους πιθανὸν τοῦτ’ ἐστὶ ποιῆσαι μηδὲν Μιθριδάτην δεδιότας. μαρτυρεῖ δὲ καὶ ἐν ἑτέρῳ τόπῳ ὁ αὐτὸς Στράβων, ὅτι καθ’ ὃν καιρὸν διέβη Σύλλας εἰς τὴν Ἑλλάδα πολεμήσων Μιθριδάτῃ καὶ Λεύκολλον πέμψας ἐπὶ τὴν ἐν Κυρήνῃ στάσιν τοῦ ἔθνους ἡμῶν ἡ οἰκουμένη πεπλήρωτο, λέγων οὕτως· τέτταρες δ’ ἦσαν ἐν τῇ πόλει τῶν Κυρηναίων, ἥ τε τῶν πολιτῶν καὶ ἡ τῶν γεωργῶν τρίτη δ’ ἡ τῶν μετοίκων τετάρτη δ’ ἡ τῶν Ἰουδαίων. αὕτη δ’ εἰς πᾶσαν πόλιν ἤδη καὶ παρελήλυθεν καὶ τόπον οὐκ ἔστι ῥᾳδίως εὑρεῖν τῆς οἰκουμένης, ὃς οὐ παραδέδεκται τοῦτο τὸ φῦλον μηδ’ ἐπικρατεῖται ὑπ’ αὐτοῦ. τήν τε Αἴγυπτον καὶ τὴν Κυρηναίων ἅτε τῶν αὐτῶν ἡγεμόνων τυχοῦσαν τῶν τε ἄλλων συχνὰ ζηλῶσαι συνέβη καὶ δὴ τὰ συντάγματα τῶν Ἰουδαίων θρέψαι διαφερόντως καὶ συναυξῆσαι χρώμενα τοῖς πατρίοις τῶν Ἰουδαίων νόμοις. ἐν γοῦν Αἰγύπτῳ κατοικία τῶν Ἰουδαίων ἐστὶν ἀποδεδειγμένη χωρὶς καὶ τῆς Ἀλεξανδρέων πόλεως ἀφώρισται μέγα μέρος τῷ ἔθνει τούτῳ. καθίσταται δὲ καὶ ἐθνάρχης αὐτῶν, ὃς διοικεῖ τε τὸ ἔθνος καὶ διαιτᾷ κρίσεις καὶ συμβολαίων ἐπιμελεῖται καὶ προσταγμάτων, ὡς ἂν πολιτείας ἄρχων αὐτοτελοῦς. ἐν Αἰγύπτῳ μὲν οὖν ἴσχυσε τὸ ἔθνος διὰ τὸ Αἰγυπτίους εἶναι τὸ ἐξ ἀρχῆς τοὺς Ἰουδαίους καὶ διὰ τὸ πλησίον ἔσεσθαι τὴν κατοικίαν τοὺς ἀπελθόντας ἐκεῖθεν, εἰς δὲ τὴν Κυρηναίαν μετέβη διὰ τὸ καὶ ταύτην ὅμορον εἶναι τῇ τῶν Αἰγυπτίων [ἀρχῇ] καθάπερ τὴν Ἰουδαίαν μᾶλλον δὲ τῆς ἀρχῆς ἐκείνης πρότερον. Στράβων μὲν δὴ ταῦτα λέγει.", "st": "14.7.2"}, {"sp": "N", "t": "Κράσσος δὲ πάντα διοικήσας ὃν αὐτὸς ἐβούλετο τρόπον ἐξώρμησεν ἐπὶ τὴν Παρθυαίαν· καὶ αὐτὸς μὲν σὺν ἅπαντι διεφθάρη τῷ στρατῷ, ὡς καὶ ἐν ἄλλοις δεδήλωται, Κάσσιος δὲ εἰς Συρίαν φυγὼν καὶ περιποιησάμενος αὐτὴν Πάρθοις ἐμποδὼν ἦν ἐκτρέχουσιν ἐπ’ αὐτὴν διὰ τὴν κατὰ Κράσσου νίκην. αὖθις δ’ εἰς Τύρον ἀφικόμενος ἀνέβη καὶ εἰς τὴν Ἰουδαίαν. Ταριχέας μὲν οὖν εὐθὺς προσπεσὼν αἱρεῖ καὶ περὶ τρισμυρίους ἀνθρώπους ἀνδραποδίζει, Πειθόλαον δὲ τὸν τὴν Ἀριστοβούλου στάσιν διαδεδεγμένον κτείνει πρὸς τοῦτ’ αὐτὸν Ἀντιπάτρου παραστησαμένου, ᾧ πολύ τε καὶ παρ’ αὐτῷ συνέβαινε δύνασθαι καὶ πλείστου τότε ἄξιος ἦν καὶ παρὰ Ἰουδαίων οἷς παρὼν ἄγεται γυναῖκα τῶν ἐπισήμων ἐξ Ἀραβίας Κύπρον ὄνομα, ἐξ ἧς αὐτῷ τέσσαρες ἐγένοντο παῖδες, Φασάηλος καὶ Ἡρώδης, ὃς ὕστερον βασιλεὺς γίνεται, Ἰώσηπός τε καὶ Φερώρας, θυγάτηρ τε Σαλώμη. οὗτος ὁ Ἀντίπατρος ἐπεποίητο καὶ πρὸς τοὺς ἄλλους δυνάστας φιλίαν τε καὶ ξενίαν, μάλιστα δὲ πρὸς τὸν Ἀράβων, ᾧ καὶ τὰ τέκνα πολεμῶν πρὸς Ἀριστόβουλον παρέθετο. Κάσσιος μὲν οὖν ἀναστρατευσάμενος ἐπὶ τὸν Εὐφράτην ἠπείγετο ὑπαντιάσων τοῖς ἐκεῖθεν ἐπιοῦσιν, ὡς καὶ ὑπ’ ἄλλων δεδήλωται.", "st": "14.7.3"}, {"sp": "N", "t": "Χρόνῳ δ’ ὕστερον Καῖσαρ κατασχὼν Ῥώμην μετὰ τὸ Πομπήιον καὶ τὴν σύγκλητον φυγεῖν πέραν τοῦ Ἰονίου παραλύσας τῶν δεσμῶν Ἀριστόβουλον εἰς Συρίαν πέμπειν διεγνώκει δύο παραδοὺς αὐτῷ τάγματα, ὡς ἂν εὐτρεπίζοι τὰ κατ’ αὐτὴν δυνατὸς ὤν. Ἀριστόβουλος δ’ οὐκ ὤνατο τῶν ἐλπίδων, ἐφ’ αἷς ἔτυχε τῆς παρὰ Καίσαρος ἐξουσίας, ἀλλ’ αὐτὸν φθάσαντες οἱ τὰ Πομπηίου φρονοῦντες φαρμάκῳ διαφθείρουσιν, θάπτουσι δ’ αὐτὸν οἱ τὰ Καίσαρος θεραπεύοντες πράγματα, καὶ ὁ νεκρὸς ἔκειτο ἐν μέλιτι κεκηδευμένος ἐπὶ χρόνον πολὺν ἕως Ἀντώνιος αὐτὸν ὕστερον ἀποπέμψας εἰς τὴν Ἰουδαίαν ἐν ταῖς βασιλικαῖς θήκαις ἐποίησεν τεθῆναι. Σκιπίων δ’ ἐπιστείλαντος αὐτῷ Πομπηίου ἀποκτεῖναι Ἀλέξανδρον τὸν Ἀριστοβούλου αἰτιασάμενος τὸν νεανίσκον ἐπὶ τοῖς τὸ πρῶτον εἰς Ῥωμαίους ἐξημαρτημένοις τῷ πελέκει διεχρήσατο. καὶ ὁ μὲν οὕτως ἐν Ἀντιοχείᾳ τελευτᾷ. τοὺς δ’ ἀδελφοὺς αὐτοῦ Πτολεμαῖος ὁ Μενναίου παρέλαβεν δυναστεύων Χαλκίδος τῆς ὑπὸ τῷ Λιβάνῳ ὄρει, καὶ πέμψας τὸν υἱὸν Φιλιππίωνα εἰς Ἀσκάλωνα παρὰ τὴν Ἀριστοβούλου γυναῖκα ἐκέλευσεν αὐτῇ συναποστέλλειν τὸν υἱὸν Ἀντίγονον καὶ τὰς θυγατέρας, ὧν τῆς ἑτέρας ἐρασθεὶς Ἀλεξάνδρας ὁ Φιλιππίων ἄγεται γυναῖκα. μετὰ δὲ ταῦτα ἀνελὼν αὐτὸν ὁ πατὴρ Πτολεμαῖος γαμεῖ τε τὴν Ἀλεξάνδραν καὶ τῶν ἀδελφῶν αὐτῆς πρόνοιαν ποιούμενος διετέλει.", "st": "14.7.4"}, {"sp": "N", "t": "Μετὰ δὲ τὸν Πομπηίου θάνατον καὶ τὴν νίκην τὴν ἐπ’ αὐτῷ Καίσαρι πολεμοῦντι κατ’ Αἴγυπτον πολλὰ χρήσιμον αὑτὸν παρέσχεν Ἀντίπατρος ὁ τῶν Ἰουδαίων ἐπιμελητὴς ἐξ ἐντολῆς Ὑρκανοῦ. Μιθριδάτῃ τε γὰρ τῷ Περγαμηνῷ κομίζοντι ἐπικουρικὸν καὶ ἀδυνάτως ἔχοντι διὰ Πηλουσίου ποιήσασθαι τὴν πορείαν, περὶ δὲ Ἀσκάλωνα διατρίβοντι, ἧκεν Ἀντίπατρος ἄγων Ἰουδαίων ὁπλίτας τρισχιλίους ἐξ Ἀραβίας τε συμμάχους ἐλθεῖν ἐπραγματεύσατο τοὺς ἐν τέλει· καὶ δι’ αὐτὸν οἱ κατὰ τὴν Συρίαν ἅπαντες ἐπεκούρουν ἀπολείπεσθαι τῆς ὑπὲρ Καίσαρος προθυμίας οὐ θέλοντες, Ἰάμβλιχός τε ὁ δυνάστης καὶ Πτολεμαῖος ὁ Σοαίμου Λίβανον ὄρος οἰκῶν αἵ τε πόλεις σχεδὸν ἅπασαι. Μιθριδάτης δὲ ἄρας ἐκ Συρίας εἰς Πηλούσιον ἀφικνεῖται καὶ μὴ δεχομένων αὐτὸν τῶν ἀνθρώπων ἐπολιόρκει τὴν πόλιν. ἠρίστευσε δὲ Ἀντίπατρος κατασύρας τι τοῦ τείχους καὶ ὁδὸν εἰσπεσεῖν παρέσχετο τοῖς ἄλλοις εἰς τὴν πόλιν. καὶ τὸ μὲν Πηλούσιον οὕτως εἶχεν. τοὺς δὲ περὶ Ἀντίπατρον καὶ Μιθριδάτην ἀπιόντας πρὸς Καίσαρα διεκώλυον οἱ Ἰουδαῖοι οἱ τὴν Ὀνίου [χώραν] λεγομένην κατοικοῦντες. πείθει δὲ καὶ τούτους τὰ αὐτῶν φρονῆσαι κατὰ τὸ ὁμόφυλον Ἀντίπατρος καὶ μάλιστα ἐπιδείξας αὐτοῖς τὰς Ὑρκανοῦ τοῦ ἀρχιερέως ἐπιστολάς, ἐν αἷς αὐτοὺς φίλους εἶναι Καίσαρος παρεκάλει καὶ ξένια καὶ πάντα τὰ ἐπιτήδεια χορηγεῖν τῷ στρατῷ. καὶ οἱ μὲν ὡς ἑώρων Ἀντίπατρον καὶ τὸν ἀρχιερέα συνθέλοντας ὑπήκουον. τούτους δὲ προσθεμένους ἀκούσαντες οἱ περὶ Μέμφιν ἐκάλουν καὶ αὐτοὶ τὸν Μιθριδάτην πρὸς ἑαυτούς· κἀκεῖνος ἐλθὼν καὶ τούτους παραλαμβάνει.", "st": "14.8.1"}, {"sp": "N", "t": "Ἐπεὶ δὲ τὸ καλούμενον Δέλτα ἤδη περιεληλύθει, συμβάλλει τοῖς πολεμίοις περὶ τὸ καλούμενον Ἰουδαίων στρατόπεδον. εἶχε δὲ τὸ μὲν δεξιὸν κέρας Μιθριδάτης, τὸ δ’ εὐώνυμον Ἀντίπατρος. συμπεσόντων δὲ εἰς μάχην κλίνεται τὸ τοῦ Μιθριδάτου κέρας καὶ παθεῖν ἂν ἐκινδύνευσεν τὰ δεινότατα, εἰ μὴ παρὰ τὴν ᾐόνα τοῦ ποταμοῦ σὺν τοῖς οἰκείοις στρατιώταις Ἀντίπατρος παραθέων νενικηκὼς ἤδη τοὺς πολεμίους τὸν μὲν ῥύεται, προτρέπει δ’ εἰς φυγὴν τοὺς νενικηκότας Αἰγυπτίους. αἱρεῖ δ’ αὐτῶν καὶ τὸ στρατόπεδον ἐπιμείνας τῇ διώξει, τόν τε Μιθριδάτην ἐκάλει πλεῖστον ἐν τῇ τροπῇ διασχόντα. ἔπεσον δὲ τῶν μὲν περὶ τοῦτον ὀκτακόσιοι, τῶν δ’ Ἀντιπάτρου πεντήκοντα. Μιθριδάτης δὲ περὶ τούτων ἐπιστέλλει Καίσαρι τῆς τε νίκης αὐτοῖς ἅμα καὶ τῆς σωτηρίας αἴτιον τὸν Ἀντίπατρον ἀποφαίνων, ὥστε τὸν Καίσαρα τότε μὲν ἐπαινεῖν αὐτόν, κεχρῆσθαι δὲ παρὰ πάντα τὸν πόλεμον εἰς τὰ κινδυνωδέστατα τῷ Ἀντιπάτρῳ· καὶ δὴ καὶ τρωθῆναι συνέβη παρὰ τοὺς ἀγῶνας αὐτῷ.", "st": "14.8.2"}, {"sp": "N", "t": "Καταλύσας μέντοι Καῖσαρ μετὰ χρόνον τὸν πόλεμον καὶ εἰς Συρίαν ἀποπλεύσας ἐτίμησεν μεγάλως, Ὑρκανῷ μὲν τὴν ἀρχιερωσύνην βεβαιώσας, Ἀντιπάτρῳ δὲ πολιτείαν ἐν Ῥώμῃ δοὺς καὶ ἀτέλειαν πανταχοῦ. λέγεται δ’ ὑπὸ πολλῶν Ὑρκανὸν ταύτης κοινωνῆσαι τῆς στρατείας καὶ ἐλθεῖν εἰς Αἴγυπτον, μαρτυρεῖ δέ μου τῷ λόγῳ καὶ Στράβων ὁ Καππάδοξ λέγων ἐξ Ἀσινίου ὀνόματος οὕτως· μετὰ τὸν Μιθριδάτην εἰσβαλεῖν εἰς τὴν Αἴγυπτον καὶ Ὑρκανὸν τὸν τῶν Ἰουδαίων ἀρχιερέα. ὁ δ’ αὐτὸς οὗτος Στράβων καὶ ἐν ἑτέροις πάλιν ἐξ Ὑψικράτους ὀνόματος λέγει οὕτως· τὸν δὲ Μιθριδάτην ἐξελθεῖν μόνον, κληθέντα δ’ εἰς Ἀσκάλωνα Ἀντίπατρον ὑπ’ αὐτοῦ τὸν τῆς Ἰουδαίας ἐπιμελητὴν τρισχιλίους αὐτῷ στρατιώτας συμπαρασκευάσαι καὶ τοὺς ἄλλους δυνάστας προτρέψαι, κοινωνῆσαι δὲ τῆς στρατείας καὶ Ὑρκανὸν τὸν ἀρχιερέα. ταῦτα μὲν Στράβων φησίν.", "st": "14.8.3"}, {"sp": "N", "t": "Ἐλθὼν δὲ καὶ Ἀντίγονος ὁ Ἀριστοβούλου πρὸς Καίσαρα τήν τε τοῦ πατρὸς ἀπωδύρετο τύχην καὶ ὡς δι’ αὐτὸν ἀποθάνοι φαρμάκοις ἀναιρεθεὶς Ἀριστόβουλος καὶ ὁ ἀδελφὸς αὐτοῦ κτείναντος πελέκει Σκιπίωνος, ἐδεῖτό τε λαβεῖν οἶκτον αὐτοῦ τῆς ἀρχῆς ἐκβεβλημένου, Ὑρκανοῦ δὲ ἐπὶ τούτοις καὶ Ἀντιπάτρου κατηγόρει βιαίως ἐξηγουμένων τοῦ ἔθνους καὶ εἰς αὐτὸν παρανομησάντων. παρὼν δ’ Ἀντίπατρος ἀπελογεῖτο μὲν ὑπὲρ ὧν ἑώρα τὴν κατηγορίαν κατ’ αὐτοῦ γεγενημένην, νεωτεριστὰς δ’ ἀπέφαινε τοὺς περὶ τὸν Ἀντίγονον καὶ στασιώδεις, ὅσα τε πονήσειεν αὐτὸς καὶ συνεργήσειεν ὑπεμίμνησκεν ἐπὶ τοῖς στρατεύμασιν ποιούμενος τοὺς λόγους ὧν αὐτὸς ἦν μάρτυς. δικαίως τε ἔλεγεν Ἀριστόβουλον μὲν εἰς Ῥώμην ἀνάσπαστον γεγονέναι πολέμιον ἀεὶ καὶ μηδέποτε εὔνουν ὑπάρξαντα Ῥωμαίοις, τὸν δ’ ἀδελφὸν αὐτοῦ κολασθέντα ἐπὶ λῃστείᾳ ὑπὸ Σκιπίωνος τυχεῖν ὧν ἄξιος ἦν, ἀλλ’ οὐ κατὰ βίαν καὶ ἀδικίαν τοῦτο παθεῖν τοῦ δράσαντος.", "st": "14.8.4"}, {"sp": "N", "t": "Τούτους Ἀντιπάτρου ποιησαμένου τοὺς λόγους Καῖσαρ Ὑρκανὸν μὲν ἀποδείκνυσιν ἀρχιερέα, Ἀντιπάτρῳ δ’ ἐφίησιν δυναστείαν ἣν αὐτὸς προαιρεῖται. τούτου δὲ ἐπ’ αὐτῷ ποιησαμένου τὴν κρίσιν, ἐπίτροπον αὐτὸν ἀποδείκνυσιν τῆς Ἰουδαίας. ἐπιτρέπει δὲ καὶ Ὑρκανῷ τὰ τῆς πατρίδος ἀναστῆσαι τείχη ταύτην αἰτησαμένῳ τὴν χάριν· ἔτι γὰρ ἐρήριπτο Πομπηίου καταβαλόντος· καὶ ταῦτα ἐπιστέλλει τοῖς ὑπάτοις εἰς Ῥώμην ἀναγράψαι ἐν τῷ Καπετωλίῳ. καὶ τὸ γενόμενον ὑπὸ τῆς συγκλήτου δόγμα τοῦτον ἔχει τὸν τρόπον· Λεύκιος Οὐαλέριος Λευκίου υἱὸς στρατηγὸς συνεβουλεύσατο τῇ συγκλήτῳ εἴδοις Δεκεμβρίαις ἐν τῷ τῆς Ὁμονοίας ναῷ. γραφομένῳ τῷ δόγματι παρῆσαν Λούκιος Κωπώνιος Λευκίου υἱὸς Κολλίνα καὶ Παπείριος Κυρίνα. περὶ ὧν Ἀλέξανδρος Ἰάσονος καὶ Νουμήνιος Ἀντιόχου καὶ Ἀλέξανδρος Δωροθέου Ἰουδαίων πρεσβευταί, ἄνδρες ἀγαθοὶ καὶ σύμμαχοι διελέχθησαν ἀνανεούμενοι τὰς προϋπηργμένας πρὸς Ῥωμαίους χάριτας καὶ τὴν φιλίαν, καὶ ἀσπίδα χρυσῆν σύμβολον τῆς συμμαχίας γενομένην ἀνήνεγκαν ἀπὸ χρυσῶν μυριάδων πέντε, καὶ γράμματ’ αὐτοῖς ἠξίωσαν δοθῆναι πρός τε τὰς αὐτονομουμένας πόλεις καὶ πρὸς βασιλεῖς ὑπὲρ τοῦ τὴν χώραν αὐτῶν καὶ τοὺς λιμένας ἀδείας τυγχάνειν καὶ μηδὲν ἀδικεῖσθαι, ἔδοξεν συνθέσθαι φιλίαν καὶ χάριτας πρὸς αὐτούς, καὶ ὅσων ἐδεήθησαν τυχεῖν ταῦτ’ αὐτοῖς παρασχεῖν καὶ τὴν κομισθεῖσαν ἀσπίδα προσδέξασθαι. ταῦτα ἐγένετο ἐπὶ Ὑρκανοῦ ἀρχιερέως καὶ ἐθνάρχου ἔτους ἐνάτου μηνὸς Πανέμου. Εὕρατο δὲ καὶ παρὰ τοῦ τῶν Ἀθηναίων δήμου τιμὰς Ὑρκανὸς πολλὰ καὶ αὐτὸς εἰς αὐτοὺς χρήσιμος γενόμενος, ἔπεμψάν τε αὐτῷ ψήφισμα τοῦτον περιέχον τὸν τρόπον· ἐπὶ πρυτάνεως καὶ ἱερέως Διονυσίου τοῦ Ἀσκληπιάδου μηνὸς Πανέμου πέμπτῃ ἀπιόντος ἐπεδόθη [τοῖς στρατηγοῖς] ψήφισμα Ἀθηναίων. ἐπὶ Ἀγαθοκλέους ἄρχοντος Εὐκλῆς Μενάνδρου Ἀλιμούσιος ἐγραμμάτευε Μουνυχιῶνος ἑνδεκάτῃ τῆς πρυτανείας ἐκκλησίας ἀγομένης ἐν τῷ θεάτρῳ τῶν προέδρων ἐπεψήφισεν Δωρόθεος Ἐρχιεὺς καὶ οἱ συμπρόεδροι τῷ δήμῳ, Διονύσιος Διονυσίου εἶπεν· ἐπειδὴ Ὑρκανὸς Ἀλεξάνδρου ἀρχιερεὺς καὶ ἐθνάρχης τῶν Ἰουδαίων διατελεῖ κοινῇ τε τῷ δήμῳ καὶ ἰδίᾳ τῶν πολιτῶν ἑκάστῳ εὔνους ὢν καὶ πάσῃ χρώμενος περὶ αὐτοὺς σπουδῇ καὶ τοὺς παραγινομένους Ἀθηναίων ἢ κατὰ πρεσβείαν ἢ κατ’ ἰδίαν πρὸς αὐτὸν ὑποδέχεται φιλοφρόνως καὶ προπέμπει τῆς ἀσφαλοῦς αὐτῶν ἐπανόδου προνοούμενος, ἐμαρτυρήθη μὲν καὶ πρότερον περὶ τούτων, δεδόχθαι δὲ καὶ νῦν Διονυσίου τοῦ Θεοδώρου Σουνιέως εἰσηγησαμένου καὶ περὶ τῆς τἀνδρὸς ἀρετῆς ὑπομνήσαντος τὸν δῆμον, καὶ ὅτι προαίρεσιν ἔχει ποιεῖν ἡμᾶς ὅ τι ποτ’ ἂν δύνηται ἀγαθόν, τιμῆσαι τὸν ἄνδρα χρυσῷ στεφάνῳ ἀριστείῳ κατὰ τὸν νόμον, καὶ στῆσαι αὐτοῦ εἰκόνα χαλκῆν ἐν τῷ τεμένει τοῦ Δήμου καὶ τῶν Χαρίτων, ἀνειπεῖν δὲ τὸν στέφανον ἐν τῷ θεάτρῳ Διονυσίοις τραγῳδῶν τῶν καινῶν ἀγομένων καὶ Παναθηναίων καὶ Ἐλευσινίων καὶ ἐν τοῖς γυμνικοῖς ἀγῶσιν, ἐπιμεληθῆναι δὲ τοὺς στρατηγοὺς διαμένοντί τε αὐτῷ καὶ φυλάττοντι τὴν πρὸς ἡμᾶς εὔνοιαν εἶναι πᾶν ὅ τι ἂν ἐπινοήσωμεν εἰς τιμὴν καὶ χάριν τῆς τἀνδρὸς σπουδῆς καὶ φιλοτιμίας, ἵνα τούτων γινομένων φαίνηται ὁ δῆμος ἡμῶν ἀποδεχόμενος τοὺς ἀγαθοὺς καὶ τῆς προσηκούσης ἀμοιβῆς ἀξιῶν καὶ ζηλώσῃ τὴν περὶ ἡμᾶς σπουδὴν τῶν ἤδη τετιμημένων· ἑλέσθαι δὲ καὶ πρέσβεις ἐξ ἁπάντων Ἀθηναίων, οἵτινες τὸ ψήφισμά τε αὐτῷ κομιοῦσι καὶ παρακαλέσουσιν προσδεξάμενον τὰς τιμὰς πειρᾶσθαί τι ποιεῖν ἀγαθὸν ἡμῶν ἀεὶ τὴν πόλιν. αἱ μὲν οὖν παρὰ Ῥωμαίων καὶ τοῦ δήμου τοῦ Ἀθηναίων τιμαὶ πρὸς Ὑρκανὸν τὸν ἀρχιερέα καὶ διὰ τούτων ἡμῖν δεδήλωνται.", "st": "14.8.5"}, {"sp": "N", "t": "Καῖσαρ δὲ διοικήσας τὰ κατὰ τὴν Συρίαν ἀπέπλευσεν. ὡς δὲ Καίσαρα προπέμψας ἐκ τῆς Συρίας Ἀντίπατρος εἰς τὴν Ἰουδαίαν ὑπέστρεψεν, ἀνεγείρει μὲν εὐθὺς τὸ τεῖχος ὑπὸ Πομπηίου καθῃρημένον καὶ τὸν κατὰ τὴν χώραν θόρυβον ἐπιὼν κατέστελλεν, ἀπειλῶν τε ἅμα καὶ συμβουλεύων ἠρεμεῖν· τοὺς μὲν γὰρ τὰ Ὑρκανοῦ φρονοῦντας ἐν εὑδίᾳ διάξειν καὶ βιώσεσθαι τῶν ἰδίων ἀπολαύοντας κτημάτων ἀταράχως, προστιθεμένους δὲ ταῖς ἐκ τοῦ νεωτερίζειν ἐλπίσιν καὶ τοῖς ἀπ’ αὐτῶν κέρδεσιν προσανέχοντας αὐτὸν μὲν ἕξειν ἀντὶ προστάτου δεσπότην, Ὑρκανὸν δὲ ἀντὶ βασιλέως τύραννον, Ῥωμαίους δὲ καὶ Καίσαρα πικροὺς ἀνθ’ ἡγεμόνων πολεμίους· οὐ γὰρ ἀνέξεσθαι μετακινούμενον ὃν αὐτοὶ κατέστησαν. ταῦτα λέγων καθίστα τὰ κατὰ τὴν χώραν.", "st": "14.9.1"}, {"sp": "N", "t": "Βραδὺν δ’ ὁρῶν καὶ νωθῆ τὸν Ὑρκανὸν Φασάηλον μὲν τὸν πρεσβύτατον τῶν παίδων Ἱεροσολύμων καὶ τῶν πέριξ στρατηγὸν ἀποδείκνυσιν, τῷ δὲ μετ’ αὐτὸν Ἡρώδῃ τὴν Γαλιλαίαν ἐπέτρεψεν νέῳ παντάπασιν ὄντι· πεντεκαίδεκα γὰρ ἐγεγόνει μόνα ἔτη. βλάπτει δὲ οὐδὲν αὐτὸν ἡ νεότης, ἀλλ’ ὢν τὸ φρόνημα γενναῖος ὁ νεανίας ἀφορμὴν εὑρίσκει παραχρῆμα εἰς ἐπίδειξιν τῆς ἀρετῆς. καταλαβὼν γὰρ Ἐζεκίαν τὸν ἀρχιλῃστὴν τὰ προσεχῆ τῆς Συρίας κατατρέχοντα σὺν μεγάλῳ στίφει, τοῦτον συλλαβὼν κτείνει καὶ πολλοὺς τῶν σὺν αὐτῷ λῃστῶν. σφόδρα δὲ αὐτοῦ τὸ ἔργον τοῦτο ἠγάπησαν οἱ Σύροι· ποθοῦσι γὰρ αὐτοῖς ἀπηλλάχθαι τοῦ λῃστηρίου τὴν χώραν ἐκαθάρευσεν. ὕμνουν γοῦν αὐτὸν ἐπὶ τούτῳ κατά τε κώμας καὶ κατὰ πόλεις ὡς εἰρήνην αὐτοῖς παρεσχηκότα καὶ ἀσφαλῆ τῶν κτημάτων ἀπόλαυσιν. ἐγένετο δὲ διὰ τοῦτο καὶ Σέξστῳ Καίσαρι γνώριμος ὄντι συγγενεῖ τοῦ μεγάλου Καίσαρος καὶ διέποντι τὴν Συρίαν. ζῆλος δ’ ἐμπίπτει τῶν Ἡρώδῃ πεπραγμένων Φασαήλῳ τῷ ἀδελφῷ, καὶ πρὸς τὴν εὐδοκίμησιν αὐτοῦ κινηθεὶς ἐφιλοτιμεῖτο μὴ ἀπολειφθῆναι τῆς ὁμοίας εὐφημίας, καὶ τοὺς ἐν τοῖς Ἱεροσολύμοις εὐνουστέρους ἐποιεῖτο, δι’ αὐτοῦ μὲν ἔχων τὴν πόλιν, οὔτε δὲ ἀπειροκάλως τοῖς πράγμασι προσφερόμενος οὔτ’ ἐξυβρίζων εἰς τὴν ἐξουσίαν. ταῦτ’ Ἀντίπατρον ἐποίει θεραπείας παρὰ τοῦ ἔθνους τυγχάνειν βασιλικῆς καὶ τιμῶν οἵων ἄν τις μεταλαμβάνοι τῶν ὅλων ὢν δεσπότης. ὑπὸ μέντοι τῆς ἐκ τούτων λαμπρότητος οὐδὲν οἷα φιλεῖ συμβαίνειν πολλάκις τῆς πρὸς Ὑρκανὸν εὐνοίας παρέβη καὶ πίστεως.", "st": "14.9.2"}, {"sp": "N", "t": "Οἱ δ’ ἐν τέλει τῶν Ἰουδαίων ὁρῶντες τὸν Ἀντίπατρον καὶ τοὺς υἱοὺς αὐτοῦ μεγάλως αὐξανομένους εὐνοίᾳ τε τῇ παρὰ τοῦ ἔθνους καὶ προσόδῳ τῇ τε παρὰ τῆς Ἰουδαίας καὶ τῶν Ὑρκανοῦ χρημάτων, κακοήθως εἶχον πρὸς αὐτόν· καὶ γὰρ φιλίαν ὁ Ἀντίπατρος ἦν πεποιημένος πρὸς τοὺς Ῥωμαίων αὐτοκράτορας καὶ χρήματα πείσας πέμψαι τὸν Ὑρκανὸν αὐτὸς λαβὼν νοσφίζεται τὴν δωρεάν· ὡς ἰδίαν γὰρ ἀλλ’ οὐχ ὡς Ὑρκανοῦ διδόντος ἔπεμψεν. ταῦθ’ Ὑρκανὸς ἀκούων οὐκ ἐφρόντιζεν, ἐν δέει δὲ ἦσαν οἱ πρῶτοι τῶν Ἰουδαίων ὁρῶντες τὸν Ἡρώδην βίαιον καὶ τολμηρὸν καὶ τυραννίδος γλιχόμενον· καὶ προσελθόντες Ὑρκανῷ φανερῶς ἤδη κατηγόρουν Ἀντιπάτρου, καί μέχρι πότε, ἔφασαν, ἐπὶ τοῖς πραττομένοις ἡσυχάσεις; ἦ οὐχ ὁρᾷς Ἀντίπατρον μὲν καὶ τοὺς παῖδας αὐτοῦ τὴν ἀρχὴν διεζωσμένους, σαυτὸν μέντοι τῆς βασιλείας ὄνομα μόνον ἀκούοντα; ἀλλὰ μὴ λανθανέτω σε ταῦτα μηδὲ ἀκίνδυνος εἶναι νόμιζε ῥαθυμῶν περί τε σαυτῷ καὶ τῇ βασιλείᾳ· οὐ γὰρ ἐπίτροποί σοι τῶν πραγμάτων Ἀντίπατρος καὶ οἱ παῖδες αὐτοῦ νῦν εἰσιν, μηδὲ ἀπάτα σαυτὸν τοῦτο οἰόμενος, ἀλλὰ δεσπόται φανερῶς ἀνωμολόγηνται· καὶ γὰρ Ἡρώδης ὁ παῖς αὐτοῦ Ἐζεκίαν ἀπέκτεινεν καὶ πολλοὺς σὺν αὐτῷ παραβὰς τὸν ἡμέτερον νόμον, ὃς κεκώλυκεν ἄνθρωπον ἀναιρεῖν καὶ πονηρὸν ὄντα, εἰ μὴ πρότερον κατακριθείη τοῦτο παθεῖν ὑπὸ τοῦ συνεδρίου. μὴ λαβὼν δὲ ἐξουσίαν παρὰ σοῦ ταῦτα ἐτόλμησεν.", "st": "14.9.3"}, {"sp": "N", "t": "Ὑρκανὸς δὲ ἀκούσας ταῦτα πείθεται· προσεξῆψαν δὲ αὐτοῦ τὴν ὀργὴν καὶ αἱ μητέρες τῶν ὑπὸ Ἡρώδου πεφονευμένων· αὗται γὰρ καθ’ ἑκάστην ἡμέραν ἐν τῷ ἱερῷ παρακαλοῦσαι τὸν βασιλέα καὶ τὸν δῆμον, ἵνα δίκην Ἡρώδης ἐν τῷ συνεδρίῳ τῶν πεπραγμένων ὑπόσχῃ, διετέλουν. κινηθεὶς οὖν ὑπὸ τούτων Ὑρκανὸς Ἡρώδην ἐκάλει δικασόμενον ὑπὲρ ὧν διεβάλλετο. ὁ δὲ ἧκεν τοῦ πατρὸς αὐτῷ παραινέσαντος μὴ ὡς ἰδιώτῃ μετὰ δ’ ἀσφαλείας εἰσελθεῖν καὶ φυλακῆς τῆς περὶ τὸ σῶμα, τά τε κατὰ τὴν Γαλιλαίαν ὡς ἐνόμισεν αὐτῷ συμφέρειν ἀσφαλίσασθαι. τοῦτον τὸν τρόπον ἁρμοσάμενος καὶ μετὰ στίφους ἀποχρῶντος αὐτῷ πρὸς τὴν ὁδόν, ὡς μήτε ἐπίφοβος Ὑρκανῷ δόξειε μετὰ μείζονος παραγενόμενος τάγματος μήτε γυμνὸς καὶ ἀφύλακτος, ᾔει πρὸς τὴν δίκην. Σέξστος μέντοι ὁ τῆς Συρίας ἡγεμὼν γράφει παρακαλῶν Ὑρκανὸν ἀπολῦσαι τὸν Ἡρώδην ἐκ τῆς δίκης καὶ προσαπειλῶν παρακούσαντι. τῷ δ’ ἦν ἀφορμὴ τὸ παρὰ τοῦ Σέξστου γράμμα πρὸς τὸ μηδὲν ἐκ τοῦ συνεδρίου παθόντα ἀπολῦσαι τὸν Ἡρώδην· ἠγάπα γὰρ αὐτὸν ὡς υἱόν. καταστὰς δὲ ἐν τῷ συνεδρίῳ μετὰ τοῦ σὺν αὐτῷ τάγματος Ἡρώδης κατέπληξεν ἅπαντας καὶ κατηγορεῖν ἐθάρρει τὸ λοιπὸν οὐδεὶς τῶν πρὶν ἀφικέσθαι διαβαλλόντων, ἀλλ’ ἦν ἡσυχία καὶ τοῦ τί χρὴ ποιεῖν ἀπορία. διακειμένων δ’ οὕτως εἷς τις Σαμαίας ὄνομα, δίκαιος ἀνὴρ καὶ διὰ τοῦτο τοῦ δεδιέναι κρείττων, ἀναστὰς εἶπεν· ἄνδρες σύνεδροι καὶ βασιλεῦ, εἰς δίκην μὲν οὔτ’ αὐτὸς οἶδά τινα τῶν πώποτε εἰς ὑμᾶς κεκλημένων οὕτω παραστάντα οὔτε ὑμᾶς ἔχειν εἰπεῖν ὑπολαμβάνω, ἀλλὰ πᾶς ὁστισδηποτοῦν ἀφῖκται εἰς τὸ συνέδριον τοῦτο κριθησόμενος ταπεινὸς παρίσταται καὶ σχήματι δεδοικότος καὶ ἔλεον θηρωμένου παρ’ ὑμῶν, κόμην τ’ ἐπιθρέψας καὶ ἐσθῆτα μέλαιναν ἐνδεδυμένος. ὁ δὲ βέλτιστος Ἡρώδης φόνου δίκην φεύγων καὶ ἐπ’ αἰτίᾳ τοιαύτῃ κεκλημένος ἕστηκε τὴν πορφύραν περικείμενος καὶ τὴν κεφαλὴν κεκοσμημένος τῇ συνθέσει τῆς κόμης καὶ περὶ αὐτὸν ἔχων ὁπλίτας, ἵνα ἂν κατακρίνωμεν αὐτοῦ κατὰ τὸν νόμον, κτείνῃ μὲν ἡμᾶς, αὐτὸν δὲ σώσῃ βιασάμενος τὸ δίκαιον. ἀλλ’ Ἡρώδην μὲν ἐπὶ τούτοις οὐκ ἂν μεμψαίμην, εἰ τὸ αὐτοῦ συμφέρον ποιεῖται περὶ πλείονος ἢ τὸ νόμιμον, ὑμᾶς δὲ καὶ τὸν βασιλέα τοσαύτην ἄδειαν αὐτῷ παρασχόντας. ἴστε μέντοι τὸν θεὸν μέγαν, καὶ οὗτος, ὃν νῦν δι’ Ὑρκανὸν ἀπολῦσαι βούλεσθε, κολάσει ὑμᾶς τε καὶ αὐτὸν τὸν βασιλέα. διήμαρτεν δ’ οὐδὲν τῶν εἰρημένων. ὁ γὰρ Ἡρώδης τὴν βασιλείαν παραλαβὼν πάντας ἀπέκτεινεν τοὺς ἐν τῷ συνεδρίῳ καὶ Ὑρκανὸν αὐτὸν χωρὶς τοῦ Σαμαίου· σφόδρα γὰρ αὐτὸν διὰ τὴν δικαιοσύνην ἐτίμησεν καὶ ὅτι τῆς πόλεως μετὰ ταῦτα πολιορκουμένης ὑπό τε Ἡρώδου καὶ Σοσσίου παρῄνεσεν τῷ δήμῳ δέξασθαι τὸν Ἡρώδην εἰπὼν διὰ τὰς ἁμαρτίας οὐ δύνασθαι διαφυγεῖν αὐτόν. καὶ περὶ μὲν τούτων κατὰ χώραν ἐροῦμεν.", "st": "14.9.4"}, {"sp": "N", "t": "Ὑρκανὸς δὲ ὁρῶν ὡρμημένους πρὸς τὴν ἀναίρεσιν τὴν Ἡρώδου τοὺς ἐν τῷ συνεδρίῳ τὴν δίκην εἰς ἄλλην ἡμέραν ἀνεβάλετο, καὶ πέμψας κρύφα πρὸς Ἡρώδην συνεβούλευσεν αὐτῷ φυγεῖν ἐκ τῆς πόλεως· οὕτω γὰρ τὸν κίνδυνον διαφεύξεσθαι. καὶ ὁ μὲν ἀνεχώρησεν εἰς Δαμασκὸν ὡς φεύγων τὸν βασιλέα, καὶ παραγενόμενος πρὸς Σέξτον Καίσαρα καὶ τὰ κατ’ αὐτὸν ἀσφαλισάμενος οὕτως εἶχεν, ὡς εἰ καλοῖτο πάλιν εἰς τὸ συνέδριον ἐπὶ δίκην οὐχ ὑπακουσόμενος. ἠγανάκτουν δὲ οἱ ἐν τῷ συνεδρίῳ καὶ τὸν Ὑρκανὸν ἐπειρῶντο διδάσκειν, ὅτι ταῦτα πάντα εἴη κατ’ αὐτοῦ. τὸν δ’ οὐκ ἐλάνθανε μέν, πράττειν δ’ οὐδὲν εἶχεν ὑπὸ ἀνανδρίας καὶ ἀνοίας. Σέξστου δὲ ποιήσαντος Ἡρώδην στρατηγὸν κοίλης Συρίας, χρημάτων γὰρ αὐτῷ τοῦτο ἀπέδοτο, Ὑρκανὸς ἦν ἐν φόβῳ, μὴ στρατεύσηται Ἡρώδης ἐπ’ αὐτόν. οὐ πολὺ δὲ τοῦ δέους ἐβράδυνεν, ἀλλ’ ἧκεν ἄγων ἐπ’ αὐτὸν Ἡρώδης στρατιὰν ὀργιζόμενος τῆς δίκης αὐτῷ καὶ τοῦ κληθῆναι πρὸς τὸ λόγον ὑποσχεῖν ἐν τῷ συνεδρίῳ. διεκώλυσαν δ’ αὐτὸν προσβαλεῖν τοῖς Ἱεροσολύμοις ὑπαντήσαντες ὅ τε πατὴρ Ἀντίπατρος καὶ ὁ ἀδελφός, καὶ τὴν ὁρμὴν αὐτοῦ καταπαύσαντες καὶ παρακαλέσαντες ἔργῳ μὲν ἐγχειρεῖν μηδενί, καταπληξάμενον δὲ ἀπειλῇ μόνον μὴ χωρῆσαι περαιτέρω κατὰ τοῦ παρασχόντος αὐτῷ εἰς τοῦτο παρελθεῖν τὸ ἀξίωμα. ἠξίουν τε περὶ τοῦ κληθέντα ἐπὶ δίκην ἐλθεῖν ἀγανακτοῦντα μεμνῆσθαι καὶ τῆς ἀφέσεως καὶ χάριν αὐτῆς εἰδέναι καὶ μὴ πρὸς μὲν τὸ σκυθρωπότερον ἀπαντᾶν, περὶ δὲ τῆς σωτηρίας ἀχαριστεῖν· λογίζεσθαι δ’ ὡς, εἰ καὶ πολέμου ῥοπὰς βραβεύει τὸ θεῖον, πλέον ἐστὶ τῆς στρατείας τὸ ἄδικον, διὸ καὶ τὴν νίκην μὴ πάντῃ προσδοκᾶν μέλλοντα πολεμεῖν βασιλεῖ καὶ συντρόφῳ, καὶ πολλὰ μὲν εὐεργετήσαντι, μηδὲν δὲ χαλεπὸν αὐτὸν εἰργασμένῳ, περὶ δὲ ὧν ἐγκαλεῖ διὰ πονηροὺς συμβούλους ἀλλὰ μὴ δι’ αὐτὸν ὑπόνοιαν αὐτῷ καὶ σκιὰν δυσκόλου τινὸς παρεσχημένῳ. πείθεται τούτοις Ἡρώδης ὑπολαβὼν εἰς τὰς ἐλπίδας ἀποχρῆν αὐτῷ τὸ καὶ τὴν ἰσχὺν ἐπιδείξασθαι τῷ ἔθνει μόνον. καὶ τὰ μὲν κατὰ τὴν Ἰουδαίαν οὕτως εἶχεν.", "st": "14.9.5"}, {"sp": "N", "t": "Καῖσαρ δ’ ἐλθὼν εἰς Ῥώμην ἕτοιμος ἦν πλεῖν ἐπ’ Ἀφρικῆς πολεμήσων Σκιπίωνι καὶ Κάτωνι, πέμψας δ’ Ὑρκανὸς πρὸς αὐτὸν παρεκάλει βεβαιώσασθαι τὴν πρὸς αὐτὸν φιλίαν καὶ συμμαχίαν. ἔδοξεν δ’ ἀναγκαῖον εἶναί μοι πάσας ἐκθέσθαι τὰς γεγενημένας Ῥωμαίοις καὶ τοῖς αὐτοκράτορσιν αὐτῶν τιμὰς καὶ συμμαχίας πρὸς τὸ ἔθνος ἡμῶν, ἵνα μὴ λανθάνῃ τοὺς ἄλλους ἅπαντας, ὅτι καὶ οἱ τῆς Ἀσίας καὶ οἱ τῆς Εὐρώπης βασιλεῖς διὰ σπουδῆς ἔσχον ἡμᾶς τήν τε ἀνδρείαν ἡμῶν καὶ τὴν πίστιν ἀγαπήσαντες. ἐπεὶ δὲ πολλοὶ διὰ τὴν πρὸς ἡμᾶς δυσμένειαν ἀπιστοῦσι τοῖς ὑπὸ Περσῶν καὶ Μακεδόνων ἀναγεγραμμένοις περὶ ἡμῶν τῷ μηκέτ’ αὐτὰ πανταχοῦ μηδ’ ἐν τοῖς δημοσίοις ἀποκεῖσθαι τόποις, ἀλλὰ παρ’ ἡμῖν τε αὐτοῖς καί τισιν ἄλλοις τῶν βαρβάρων, πρὸς δὲ τὰ ὑπὸ Ῥωμαίων δόγματα οὐκ ἔστιν ἀντειπεῖν· ἔν τε γὰρ δημοσίοις ἀνάκειται τόποις τῶν πόλεων καὶ ἔτι νῦν ἐν τῷ Καπετωλίῳ χαλκαῖς στήλαις ἐγγέγραπται, οὐ μὴν ἀλλὰ καὶ Καῖσαρ Ἰούλιος τοῖς ἐν Ἀλεξανδρείᾳ Ἰουδαίοις ποιήσας χαλκῆν στήλην ἐδήλωσεν, ὅτι Ἀλεξανδρέων πολῖταί εἰσιν, ἐκ τούτων ποιήσομαι καὶ τὴν ἀπόδειξιν. παραθήσομαι δὲ τὰ γενόμενα ὑπό τε τῆς συγκλήτου δόγματα καὶ Ἰουλίου Καίσαρος πρός τε Ὑρκανὸν καὶ τὸ ἔθνος ἡμῶν.", "st": "14.10.1"}, {"sp": "N", "t": "Γάιος Ἰούλιος Καῖσαρ αὐτοκράτωρ καὶ ἀρχιερεὺς δικτάτωρ τὸ δεύτερον Σιδωνίων ἄρχουσιν βουλῇ δήμῳ χαίρειν. εἰ ἔρρωσθε εὖ ἂν ἔχοι, κἀγὼ δὲ ἔρρωμαι σὺν τῷ στρατοπέδῳ. τῆς γενομένης ἀναγραφῆς ἐν τῇ δέλτῳ πρὸς Ὑρκανὸν υἱὸν Ἀλεξάνδρου ἀρχιερέα καὶ ἐθνάρχην Ἰουδαίων πέπομφα ὑμῖν τὸ ἀντίγραφον, ἵν’ ἐν τοῖς δημοσίοις ὑμῶν ἀνακέηται γράμμασιν. βούλομαι δὲ καὶ ἑλληνιστὶ καὶ ῥωμαϊστὶ ἐν δέλτῳ χαλκῇ τοῦτο ἀνατεθῆναι. ἔστιν δὴ τοῦτο· Ἰούλιος Καῖσαρ αὐτοκράτωρ τὸ δεύτερον καὶ ἀρχιερεὺς μετὰ συμβουλίου γνώμης ἐπέκρινα. ἐπεὶ Ὑρκανὸς Ἀλεξάνδρου Ἰουδαῖος καὶ νῦν καὶ ἐν τοῖς ἔμπροσθεν χρόνοις ἔν τε εἰρήνῃ καὶ πολέμῳ πίστιν τε καὶ σπουδὴν περὶ τὰ ἡμέτερα πράγματα ἐπεδείξατο, ὡς αὐτῷ πολλοὶ μεμαρτυρήκασιν αὐτοκράτορες, καὶ ἐν τῷ ἔγγιστα ἐν Ἀλεξανδρείᾳ πολέμῳ μετὰ χιλίων πεντακοσίων στρατιωτῶν ἧκεν σύμμαχος καὶ πρὸς Μιθριδάτην ἀποσταλεὶς ὑπ’ ἐμοῦ πάντας ἀνδρείᾳ τοὺς ἐν τάξει ὑπερέβαλεν, διὰ ταύτας τὰς αἰτίας Ὑρκανὸν Ἀλεξάνδρου καὶ τὰ τέκνα αὐτοῦ ἐθνάρχας Ἰουδαίων εἶναι ἀρχιερωσύνην τε Ἰουδαίων διὰ παντὸς ἔχειν κατὰ τὰ πάτρια ἔθη, εἶναί τε αὐτὸν καὶ τοὺς παῖδας αὐτοῦ συμμάχους ἡμῖν ἔτι τε καὶ ἐν τοῖς κατ’ ἄνδρα φίλοις ἀριθμεῖσθαι, ὅσα τε κατὰ τοὺς ἰδίους αὐτῶν νόμους ἐστὶν ἀρχιερατικὰ φιλάνθρωπα, ταῦτα κελεύω κατέχειν αὐτὸν καὶ τὰ τέκνα αὐτοῦ· ἄν τε μεταξὺ γένηταί τις ζήτησις περὶ τῆς Ἰουδαίων ἀγωγῆς, ἀρέσκει μοι κρίσιν γίνεσθαι [παρ’ αὐτοῖς]. παραχειμασίαν δὲ ἢ χρήματα πράσσεσθαι οὐ δοκιμάζω.", "st": "14.10.2"}, {"sp": "N", "t": "Γαΐου Καίσαρος αὐτοκράτορος ὑπάτου δεδομένα συγκεχωρημένα προσκεκριμένα ἐστὶν οὕτως ἔχοντα. ὅπως τὰ τέκνα αὐτοῦ τοῦ Ἰουδαίων ἔθνους ἄρχῃ, καὶ τοὺς δεδομένους τόπους καρπίζωνται, καὶ ὁ ἀρχιερεὺς αὐτὸς καὶ ἐθνάρχης τῶν Ἰουδαίων προϊστῆται τῶν ἀδικουμένων. πέμψαι δὲ πρὸς Ὑρκανὸν τὸν Ἀλεξάνδρου υἱὸν ἀρχιερέα τῶν Ἰουδαίων καὶ πρεσβευτὰς τοὺς περὶ φιλίας καὶ συμμαχίας διαλεξομένους· ἀνατεθῆναι δὲ καὶ χαλκῆν δέλτον ταῦτα περιέχουσαν ἔν τε τῷ Καπετωλίῳ καὶ Σιδῶνι καὶ Τύρῳ καὶ ἐν Ἀσκάλωνι καὶ ἐν τοῖς ναοῖς ἐγκεχαραγμένην γράμμασιν Ῥωμαϊκοῖς καὶ Ἑλληνικοῖς. ὅπως τε τὸ δόγμα τοῦτο πᾶσι τοῖς κατὰ τὴν πόλιν ταμίαις καὶ τοῖς τούτων ἡγουμένοις εἴς τε τοὺς φίλους ἀνενέγκωσιν καὶ ξένια τοῖς πρεσβευταῖς παρασχεῖν καὶ τὰ διατάγματα διαπέμψαι πανταχοῦ.", "st": "14.10.3"}, {"sp": "N", "t": "Γάιος Καῖσαρ αὐτοκράτωρ δικτάτωρ ὕπατος τιμῆς καὶ ἀρετῆς καὶ φιλανθρωπίας ἕνεκεν συνεχώρησεν ἐπὶ συμφέροντι καὶ τῇ συγκλήτῳ καὶ τῷ δήμῳ τῶν Ῥωμαίων Ὑρκανὸν Ἀλεξάνδρου υἱὸν καὶ τέκνα αὐτοῦ ἀρχιερεῖς τε καὶ ἱερεῖς Ἱεροσολύμων καὶ τοῦ ἔθνους εἶναι ἐπὶ τοῖς δικαίοις, οἷς καὶ οἱ πρόγονοι αὐτῶν τὴν ἀρχιερωσύνην διακατέσχον.", "st": "14.10.4"}, {"sp": "N", "t": "Γάιος Καῖσαρ ὕπατος τὸ πέμπτον ἔκρινεν τούτους ἔχειν καὶ τειχίσαι τὴν Ἱεροσολυμιτῶν πόλιν, καὶ κατέχειν αὐτὴν Ὑρκανὸν Ἀλεξάνδρου ἀρχιερέα Ἰουδαίων καὶ ἐθνάρχην ὡς ἂν αὐτὸς προαιρῆται. ὅπως τε Ἰουδαίοις ἐν τῷ δευτέρῳ τῆς μισθώσεως [ἔτει] τῆς προσόδου κόρον ὑπεξέλωνται καὶ μήτε ἐργολαβῶσί τινες μήτε φόρους τοὺς αὐτοὺς τελῶσιν.", "st": "14.10.5"}, {"sp": "N", "t": "Γάιος Καῖσαρ αὐτοκράτωρ τὸ δεύτερον ἔστησεν κατ’ ἐνιαυτὸν ὅπως τελῶσιν ὑπὲρ τῆς Ἱεροσολυμιτῶν πόλεως Ἰόππης ὑπεξαιρουμένης χωρὶς τοῦ ἑβδόμου ἔτους, ὃν σαββατικὸν ἐνιαυτὸν προσαγορεύουσιν, ἐπεὶ ἐν αὐτῷ μήτε τὸν ἀπὸ τῶν δένδρων καρπὸν λαμβάνουσιν μήτε σπείρουσιν. καὶ ἵνα ἐν Σιδῶνι τῷ δευτέρῳ ἔτει τὸν φόρον ἀποδιδῶσιν τὸ τέταρτον τῶν σπειρομένων, πρὸς τούτοις ἔτι καὶ Ὑρκανῷ καὶ τοῖς τέκνοις αὐτοῦ τὰς δεκάτας τελῶσιν, ἃς ἐτέλουν καὶ τοῖς προγόνοις αὐτῶν. καὶ ὅπως μηδεὶς μήτε ἄρχων μήτε ἀντάρχων μήτε στρατηγὸς ἢ πρεσβευτὴς ἐν τοῖς ὅροις τῶν Ἰουδαίων ἀνιστὰς συμμαχίαν καὶ στρατιώτας ἐξῇ τούτῳ χρήματα εἰσπράττεσθαι ἢ εἰς παραχειμασίαν ἢ ἄλλῳ τινὶ ὀνόματι, ἀλλ’ εἶναι πανταχόθεν ἀνεπηρεάστους. ὅσα τε μετὰ ταῦτα ἔσχον ἢ ἐπρίαντο καὶ διακατέσχον καὶ ἐνεμήθησαν, ταῦτα πάντα αὐτοὺς ἔχειν. Ἰόππην τε πόλιν, ἣν ἀπ’ ἀρχῆς ἔσχον οἱ Ἰουδαῖοι ποιούμενοι τὴν πρὸς Ῥωμαίους φιλίαν αὐτῶν εἶναι, καθὼς καὶ τὸ πρῶτον, ἡμῖν ἀρέσκει, φόρους τε ὑπὲρ ταύτης τῆς πόλεως Ὑρκανὸν Ἀλεξάνδρου υἱὸν καὶ παῖδας αὐτοῦ παρὰ τῶν τὴν γῆν νεμομένων χώρας λιμένος ἐξαγωγίου κατ’ ἐνιαυτὸν Σιδῶνι μοδίους δισμυρίους χοε ὑπεξαιρουμένου τοῦ ἑβδόμου ἔτους, ὃν σαββατικὸν καλοῦσιν, καθ’ ὃν οὔτε ἀροῦσιν οὔτε τὸν ἀπὸ τῶν δένδρων καρπὸν λαμβάνουσιν. τάς τε κώμας τὰς ἐν τῷ μεγάλῳ πεδίῳ, ἃς Ὑρκανὸς καὶ οἱ πρόγονοι πρότερον αὐτοῦ διακατέσχον, ἀρέσκει τῇ συγκλήτῳ ταῦτα Ὑρκανὸν καὶ Ἰουδαίους ἔχειν ἐπὶ τοῖς δικαίοις οἷς καὶ πρότερον εἶχον. μένειν δὲ καὶ τὰ ἀπ’ ἀρχῆς δίκαια, ὅσα πρὸς ἀλλήλους Ἰουδαίοις καὶ τοῖς ἀρχιερεῦσιν καὶ ἱερεῦσιν ἦν τά τε φιλάνθρωπα ὅσα τε τοῦ δήμου ψηφισαμένου καὶ τῆς συγκλήτου ἔσχον. ἐπὶ τούτοις τε τοῖς δικαίοις χρῆσθαι αὐτοῖς ἐξεῖναι ἐν Λύδδοις. τούς τε τόπους καὶ χώραν καὶ ἐποίκια, ὅσα βασιλεῦσι Συρίας καὶ Φοινίκης συμμάχοις οὖσι Ῥωμαίων κατὰ δωρεὰν ὑπῆρχε καρποῦσθαι, ταῦτα δοκιμάζει ἡ σύγκλητος Ὑρκανὸν τὸν ἐθνάρχην καὶ Ἰουδαίους ἔχειν. δεδόσθαι δὲ Ὑρκανῷ καὶ παισὶ τοῖς αὐτοῦ καὶ πρεσβευταῖς τοῖς ὑπ’ αὐτοῦ πεμφθεῖσιν ἔν τε πυγμῇ μονομάχων καὶ θηρίων καθεζομένοις μετὰ τῶν συγκλητικῶν θεωρεῖν αἰτησαμένους παρὰ δικτάτορος ἢ παρὰ ἱππάρχου παρελθεῖν εἰς τὴν σύγκλητον εἰσάγωσιν καὶ τὰ ἀποκρίματα αὐτοῖς ἀποδιδῶσιν ἐν ἡμέραις δέκα ταῖς ἁπάσαις, ἀφ’ ἧς ἂν τὸ δόγμα γένηται.", "st": "14.10.6"}, {"sp": "N", "t": "Γάιος Καῖσαρ αὐτοκράτωρ δικτάτωρ τὸ τέταρτον ὕπατός τε τὸ πέμπτον δικτάτωρ ἀποδεδειγμένος διὰ βίου λόγους ἐποιήσατο περὶ τῶν δικαίων τῶν Ὑρκανοῦ τοῦ Ἀλεξάνδρου ἀρχιερέως Ἰουδαίων καὶ ἐθνάρχου τοιούτους· [τῶν] πρὸ ἐμοῦ αὐτοκρατόρων ἐν ταῖς ἐπαρχίαις μαρτυρησάντων Ὑρκανῷ ἀρχιερεῖ Ἰουδαίων καὶ Ἰουδαίοις ἐπί τε συγκλήτου καὶ δήμου Ῥωμαίων, εὐχαριστήσαντος δὲ καὶ τοῦ δήμου καὶ τῆς συγκλήτου αὐτοῖς, καλῶς ἔχει καὶ ἡμᾶς ἀπομνημονεύειν καὶ προνοεῖν, ὡς Ὑρκανῷ καὶ τῷ ἔθνει τῶν Ἰουδαίων καὶ τοῖς Ὑρκανοῦ παισὶν ὑπὸ συγκλήτου καὶ δήμου Ῥωμαίων ἀξία τῆς πρὸς ἡμᾶς εὐνοίας αὐτῶν καὶ ὧν εὐεργέτησαν ἡμᾶς χάρις ἀνταποδοθῇ.", "st": "14.10.7"}, {"sp": "N", "t": "Ἰούλιος Γάιος ὑιοσο στρατηγὸς ὕπατος Ῥωμαίων Παριανῶν ἄρχουσι βουλῇ δήμῳ χαίρειν. ἐνέτυχόν μοι οἱ Ἰουδαῖοι ἐν Δήλῳ καί τινες τῶν παροίκων Ἰουδαίων παρόντων καὶ τῶν ὑμετέρων πρέσβεων καὶ ἐνεφάνισαν, ὡς ὑμεῖς ψηφίσματι κωλύετε αὐτοὺς τοῖς πατρίοις ἔθεσι καὶ ἱεροῖς χρῆσθαι. ἐμοὶ τοίνυν οὐκ ἀρέσκει κατὰ τῶν ἡμετέρων φίλων καὶ συμμάχων τοιαῦτα γίνεσθαι ψηφίσματα καὶ κωλύεσθαι αὐτοὺς ζῆν κατὰ τὰ αὐτῶν ἔθη καὶ χρήματα εἰς σύνδειπνα καὶ τὰ ἱερὰ εἰσφέρειν, τοῦτο ποιεῖν αὐτῶν μηδ’ ἐν Ῥώμῃ κεκωλυμένων. καὶ γὰρ Γάιος Καῖσαρ ὁ ἡμέτερος στρατηγὸς [καὶ] ὕπατος ἐν τῷ διατάγματι κωλύων θιάσους συνάγεσθαι κατὰ πόλιν μόνους τούτους οὐκ ἐκώλυσεν οὔτε χρήματα συνεισφέρειν οὔτε σύνδειπνα ποιεῖν. ὁμοίως δὲ κἀγὼ τοὺς ἄλλους θιάσους κωλύων τούτοις μόνοις ἐπιτρέπω κατὰ τὰ πάτρια ἔθη καὶ νόμιμα συνάγεσθαί τε καὶ ἑστιᾶσθαι. καὶ ὑμᾶς οὖν καλῶς ἔχει, εἴ τι κατὰ τῶν ἡμετέρων φίλων καὶ συμμάχων ψήφισμα ἐποιήσατε, τοῦτο ἀκυρῶσαι διὰ τὴν περὶ ἡμᾶς αὐτῶν ἀρετὴν καὶ εὔνοιαν.", "st": "14.10.8"}, {"sp": "N", "t": "Μετὰ δὲ τὸν Γαΐου θάνατον Μᾶρκος Ἀντώνιος καὶ Πόπλιος Δολαβέλλας ὕπατοι ὄντες τήν τε σύγκλητον συνήγαγον καὶ τοὺς παρ’ Ὑρκανοῦ πρέσβεις παραγαγόντες διελέχθησαν περὶ ὧν ἠξίουν καὶ φιλίαν πρὸς αὐτοὺς ἐποίησαν, καὶ πάντα συγχωρεῖν αὐτοῖς ἡ σύγκλητος ἐψηφίσατο ὅσων τυγχάνειν ἐβούλοντο. παρατέθειμαι δὲ καὶ τὸ δόγμα, ὅπως τὴν ἀπόδειξιν τῶν λεγομένων ἐγγύθεν ἔχωσιν οἱ ἀναγινώσκοντες τὴν πραγματείαν. ἦν δὲ τοιοῦτον·", "st": "14.10.9"}, {"sp": "N", "t": "Δόγμα συγκλήτου ἐκ τοῦ ταμιείου ἀντιγεγραμμένον ἐκ τῶν δέλτων τῶν δημοσίων τῶν ταμιευτικῶν Κοΐντω Ῥουτιλίω Κοΐντω Κορνηλίω ταμίαις κατὰ πόλιν, δέλτῳ δευτέρᾳ καὶ ἐκ τῶν πρώτων πρώτῃ. πρὸ τριῶν εἰδῶν Ἀπριλλίων ἐν τῷ ναῷ τῆς Ὁμονοίας. γραφομένῳ παρῆσαν Λούκιος Καλπούρνιος Μενηνία Πείσων, Σερουίνιος Παπίνιος Λεμωνία Κούιντος, Γάιος Κανείνιος Τηρητίνα Ῥέβιλος, Πόπλιος Τηδήτιος Λευκίου υἱὸς Πολλία, Λεύκιος Ἀπούλιος Λευκίου υἱὸς Σεργία, Φλάβιος Λευκίου Λεμωνία, Πόπλιος Πλαύτιος Ποπλίου Παπειρία, Μᾶρκος Σέλλιος Μάρκου Μαικία, Λεύκιος Ἐρούκιος Λουκίου Στηλητίνα, Μᾶρκος Κούιντος Μάρκου υἱὸς Πολλία Πλανκῖνος, Πούπλιος Σέρριος Πόπλιος Δολοβέλλας Μᾶρκος Ἀντώνιος ὕπατοι λόγους ἐποιήσαντο περὶ ὧν δόγματι συγκλήτου Γάιος Καῖσαρ ὑπὲρ Ἰουδαίων ἔκρινεν καὶ εἰς τὸ ταμιεῖον οὐκ ἔφθασεν ἀνενεχθῆναι, περὶ τούτων ἀρέσκει ἡμῖν γενέσθαι, ὡς καὶ Ποπλίῳ Δολαβέλλᾳ καὶ Μάρκῳ Ἀντωνίῳ τοῖς ὑπάτοις ἔδοξεν, ἀνενεγκεῖν τε ταῦτα εἰς δέλτους καὶ πρὸς τοὺς κατὰ πόλιν ταμίας, ὅπως φροντίσωσιν καὶ αὐτοὶ εἰς δέλτους ἀναθεῖναι διπτύχους. ἐγένετο πρὸ πέντε εἰδῶν Φεβρουαρίων ἐν τῷ ναῷ τῆς Ὁμονοίας. οἱ δὲ πρεσβεύοντες παρὰ Ὑρκανοῦ τοῦ ἀρχιερέως ἦσαν οὗτοι· Λυσίμαχος Παυσανίου Ἀλέξανδρος Θεοδώρου Πάτροκλος Χαιρέου Ἰωάννης Ὀνείου.", "st": "14.10.10"}, {"sp": "N", "t": "Ἔπεμψεν δὲ τούτων Ὑρκανὸς τῶν πρεσβευτῶν ἕνα καὶ πρὸς Δολαβέλλαν τὸν τῆς Ἀσίας τότε ἡγεμόνα, παρακαλῶν ἀπολῦσαι τοὺς Ἰουδαίους τῆς στρατείας καὶ τὰ πάτρια τηρεῖν ἔθη καὶ κατὰ ταῦτα ζῆν ἐπιτρέπειν· οὗ τυχεῖν αὐτῷ ῥᾳδίως ἐγένετο· λαβὼν γὰρ ὁ Δολοβέλλας τὰ παρὰ τοῦ Ὑρκανοῦ γράμματα, μηδὲ βουλευσάμενος ἐπιστέλλει τοῖς κατὰ τὴν Ἀσίαν ἅπασιν γράψας τῇ Ἐφεσίων πόλει πρωτευούσῃ τῆς Ἀσίας περὶ τῶν Ἰουδαίων. ἡ δὲ ἐπιστολὴ τοῦτον περιεῖχεν τὸν τρόπον·", "st": "14.10.11"}, {"sp": "N", "t": "Ἐπὶ πρυτάνεως Ἀρτέμωνος μηνὸς Ληναιῶνος προτέρᾳ. Δολοβέλλας αὐτοκράτωρ Ἐφεσίων ἄρχουσι βουλῇ δήμῳ χαίρειν. Ἀλέξανδρος Θεοδώρου πρεσβευτὴς Ὑρκανοῦ τοῦ Ἀλεξάνδρου υἱοῦ ἀρχιερέως καὶ ἐθνάρχου τῶν Ἰουδαίων ἐνεφάνισέν μοι περὶ τοῦ μὴ δύνασθαι στρατεύεσθαι τοὺς πολίτας αὐτοῦ διὰ τὸ μήτε ὅπλα βαστάζειν δύνασθαι μήτε ὁδοιπορεῖν ἐν ταῖς ἡμέραις τῶν σαββάτων, μήτε τροφῶν τῶν πατρίων καὶ συνήθων κατὰ τούτους εὐπορεῖν. ἐγώ τε οὖν αὐτοῖς, καθὼς καὶ οἱ πρὸ ἐμοῦ ἡγεμόνες, δίδωμι τὴν ἀστρατείαν καὶ συγχωρῶ χρῆσθαι τοῖς πατρίοις ἐθισμοῖς ἱερῶν ἕνεκα καὶ ἁγίοις συναγομένοις, καθὼς αὐτοῖς νόμιμον, καὶ τῶν πρὸς τὰς θυσίας ἀφαιρεμάτων, ὑμᾶς τε βούλομαι ταῦτα γράψαι κατὰ πόλεις.", "st": "14.10.12"}, {"sp": "N", "t": "Καὶ ταῦτα μὲν ὁ Δολαβέλλας Ὑρκανοῦ πρεσβευσαμένου πρὸς αὐτὸν ἐχαρίσατο τοῖς ἡμετέροις. Λεύκιος δὲ Λέντλος ὕπατος εἶπεν· πολίτας Ῥωμαίων Ἰουδαίους ἱερὰ Ἰουδαϊκὰ ἔχοντας καὶ ποιοῦντας ἐν Ἐφέσῳ πρὸ τοῦ βήματος δεισιδαιμονίας ἕνεκα στρατείας ἀπέλυσα πρὸ δώδεκα καλανδῶν Ὀκτωβρίων Λευκίω Λέντλω Γαΐω Μαρκέλλω ὑπάτοις. παρῆσαν Τίτος Ἄμπιος Τίτου υἱὸς Βάλβος Ὁρατία πρεσβευτής, Τίτος Τόνγιος Τίτου υἱὸς Κροστομίνα, Κόιντος Καίσιος Κοΐντου, Τίτος Πομπήιος Τίτου Λογγῖνος, Γάιος Σερουίλιος Γαΐου υἱὸς Τηρητίνα Βράκκος χιλίαρχος, Πόπλιος Κλούσιος Ποπλίου Ἐτωρία [Γάλλος], Γάιος Σέντιος Γαΐου υἱὸς Σαβατίνα.", "st": "14.10.13"}, {"sp": "N", "t": "Τίτος Ἄμπιος Τίτου υἱὸς Βάλβος πρεσβευτὴς καὶ ἀντιστράτηγος Ἐφεσίων ἄρχουσι βουλῇ δήμῳ χαίρειν. Ἰουδαίους τοὺς ἐν τῇ Ἀσίᾳ Λεύκιος Λέντλος ὁ ὕπατος ἐμοῦ ἐντυχόντος ἀπέλυσεν τῆς στρατείας. αἰτησάμενος δὲ μετὰ ταῦτα καὶ παρὰ Φαννίου τοῦ ἀντιστρατήγου καὶ παρὰ Λευκίου Ἀντωνίου τοῦ ἀντιταμίου ἐπέτυχον ὑμᾶς τε βούλομαι φροντίσαι, ἵνα μή τις αὐτοῖς διενοχλῇ.", "st": "14.10.14"}, {"sp": "N", "t": "Ψήφισμα Δηλίων. ἐπ’ ἄρχοντος Βοιωτοῦ μηνὸς Θαργηλιῶνος εἰκοστῇ χρηματισμὸς στρατηγῶν. Μᾶρκος Πείσων πρεσβευτὴς ἐνδημῶν ἐν τῇ πόλει ἡμῶν ὁ καὶ τεταγμένος ἐπὶ τῆς στρατολογίας προσκαλεσάμενος ἡμᾶς καὶ ἱκανοὺς τῶν πολιτῶν προσέταξεν, ἵνα εἴ τινές εἰσιν Ἰουδαῖοι πολῖται Ῥωμαίων τούτοις μηδεὶς ἐνοχλῇ περὶ στρατείας, διὰ τὸ τὸν ὕπατον Λούκιον Κορνήλιον Λέντλον δεισιδαιμονίας ἕνεκα ἀπολελυκέναι τοὺς Ἰουδαίους τῆς στρατείας. διὸ πείθεσθαι ἡμᾶς δεῖ τῷ στρατηγῷ. ὅμοια δὲ τούτοις καὶ Σαρδιανοὶ περὶ ἡμῶν ἐψηφίσαντο.", "st": "14.10.15"}, {"sp": "N", "t": "Γάιος Φάννιος Γαΐου υἱὸς στρατηγὸς ὕπατος Κῴων ἄρχουσι χαίρειν. βούλομαι ὑμᾶς εἰδέναι, ὅτι πρέσβεις Ἰουδαίων μοι προσῆλθον ἀξιοῦντες λαβεῖν τὰ συγκλήτου δόγματα τὰ περὶ αὐτῶν γεγονότα. ὑποτέτακται δὲ τὰ δεδογμένα. ὑμᾶς οὖν θέλω φροντίσαι καὶ προνοῆσαι τῶν ἀνθρώπων κατὰ τὸ τῆς συγκλήτου δόγμα, ὅπως διὰ τῆς ὑμετέρας χώρας εἰς τὴν οἰκείαν ἀσφαλῶς ἀνακομισθῶσιν.", "st": "14.10.16"}, {"sp": "N", "t": "Λεύκιος Λέντλος ὕπατος λέγει· πολίτας Ῥωμαίων Ἰουδαίους, οἵτινές μοι ἱερὰ ἔχειν καὶ ποιεῖν Ἰουδαϊκὰ ἐν Ἐφέσῳ ἐδόκουν, δεισιδαιμονίας ἕνεκα ἀπέλυσα. τοῦτο ἐγένετο πρὸ δώδεκα καλανδῶν Κουιντιλίων.", "st": "14.10.17"}, {"sp": "N", "t": "Λούκιος Ἀντώνιος Μάρκου υἱὸς ἀντιταμίας καὶ ἀντιστράτηγος Σαρδιανῶν ἄρχουσι βουλῇ δήμῳ χαίρειν. Ἰουδαῖοι πολῖται ἡμέτεροι προσελθόντες μοι ἐπέδειξαν αὐτοὺς σύνοδον ἔχειν ἰδίαν κατὰ τοὺς πατρίους νόμους ἀπ’ ἀρχῆς καὶ τόπον ἴδιον, ἐν ᾧ τά τε πράγματα καὶ τὰς πρὸς ἀλλήλους ἀντιλογίας κρίνουσιν, τοῦτό τε αἰτησαμένοις ἵν’ ἐξῇ ποιεῖν αὐτοῖς τηρῆσαι καὶ ἐπιτρέψαι ἔκρινα.", "st": "14.10.18"}, {"sp": "N", "t": "Μᾶρκος Πόπλιος σπιρίου υἱὸς καὶ Μᾶρκος Μάρκου Ποπλίου υἱὸς Λουκίου λέγουσιν. Λέντλῳ τἀνθυπάτῳ προσελθόντες ἐδιδάξαμεν αὐτὸν περὶ ὧν Δοσίθεος Κλεοπατρίδου Ἀλεξανδρεὺς λόγους ἐποιήσατο, ὅπως πολίτας Ῥωμαίων Ἰουδαίους ἱερὰ Ἰουδαϊκὰ ποιεῖν εἰωθότας, ἂν αὐτῷ φανῇ, δεισιδαιμονίας ἕνεκα ἀπολύσῃ· καὶ ἀπέλυσε πρὸ δώδεκα καλανδῶν Κουιντιλίων Λευκίω Λέντλω Γαΐω Μαρκέλλω ὑπάτοις. παρῆσαν Τίτος Ἄμπιος Τίτου υἱὸς Βάλβος Ὁρατία πρεσβευτής, Τίτος Τόνγιος Κροστομίνα, Κόιντος Καίσιος Κοΐντου, Τίτος Πήιος Τίτου υἱὸς Κορνηλία Λογγῖνος, Γάιος Σερουίλιος Γαΐου Τηρητείνα Βρόκχος χιλίαρχος, Πόπλιος Κλούσιος Ποπλίου υἱὸς Ἐτωρία Γάλλος, Γάιος Τεύτιος Γαΐου Αἰμιλία χιλίαρχος, Σέξστος Ἀτίλιος Σέξστου υἱὸς Αἰμιλία Σέσρανος, Γάιος Πομπήιος Γαΐου υἱὸς Σαβατίνα, Τίτος Ἄμπιος Τίτου Μένανδρος, Πόπλιος Σερουίλιος Ποπλίου υἱὸς Στράβων, Λεύκιος Πάκκιος Λευκίου Κολλίνα Καπίτων, Αὖλος Φούριος Αὔλου υἱὸς Τέρτιος, Ἄππιος Μηνᾶς. ἐπὶ τούτων ὁ Λέντλος δόγμα ἐξέθετο· πολίτας Ῥωμαίων Ἰουδαίους, οἵτινες ἱερὰ Ἰουδαϊκὰ ποιεῖν εἰώθασιν, ἐν Ἐφέσῳ πρὸ τοῦ βήματος δεισιδαιμονίας ἕνεκα ἀπέλυσα.", "st": "14.10.19"}, {"sp": "N", "t": "Λαοδικέων ἄρχοντες Γαΐῳ Ῥαβελλίῳ Γαΐου υἱῷ ὑπάτῳ χαίρειν. Σώπατρος Ὑρκανοῦ τοῦ ἀρχιερέως πρεσβευτὴς ἀπέδωκεν ἡμῖν τὴν παρὰ σοῦ ἐπιστολήν, δι’ ἧς ἐδήλου ἡμῖν παρὰ Ὑρκανοῦ τοῦ Ἰουδαίων ἀρχιερέως ἐληλυθότας τινὰς γράμματα κομίσαι περὶ τοῦ ἔθνους αὐτῶν γεγραμμένα, ἵνα τά τε σάββατα αὐτοῖς ἐξῇ ἄγειν καὶ τὰ λοιπὰ ἱερὰ ἐπιτελεῖν κατὰ τοὺς πατρίους νόμους, ὅπως τε μηδεὶς αὐτοῖς ἐπιτάσσῃ διὰ τὸ φίλους αὐτοὺς ἡμετέρους εἶναι καὶ συμμάχους, ἀδικήσῃ τε μηδὲ εἷς αὐτοὺς ἐν τῇ ἡμετέρᾳ ἐπαρχίᾳ, ὡς Τραλλιανῶν τε ἀντειπόντων κατὰ πρόσωπον μὴ ἀρέσκεσθαι τοῖς περὶ αὐτῶν δεδογμένοις ἐπέταξας ταῦτα οὕτως γίνεσθαι· παρακεκλῆσθαι δέ σε, ὥστε καὶ ἡμῖν γράψαι περὶ αὐτῶν. ἡμεῖς οὖν κατακολουθοῦντες τοῖς ἐπεσταλμένοις ὑπὸ σοῦ τήν τε ἐπιστολὴν τὴν ἀποδοθεῖσαν ἐδεξάμεθα καὶ κατεχωρίσαμεν εἰς τὰ δημόσια ἡμῶν γράμματα καὶ περὶ τῶν ἄλλων ὧν ἐπέσταλκας προνοήσομεν, ὥστε μηδὲν μεμφθῆναι.", "st": "14.10.20"}, {"sp": "N", "t": "Πόπλιος Σερουίλιος Ποπλίου υἱὸς Γάλβας ἀνθύπατος Μιλησίων ἄρχουσι βουλῇ δήμῳ χαίρειν. Πρύτανις Ἑρμοῦ υἱὸς πολίτης ὑμέτερος προσελθών μοι ἐν Τράλλεσιν ἄγοντι τὴν ἀγόραιον ἐδήλου παρὰ τὴν ἡμετέραν γνώμην Ἰουδαίοις ὑμᾶς προσφέρεσθαι καὶ κωλύειν αὐτοὺς τά τε σάββατα ἄγειν καὶ τὰ ἱερὰ τὰ πάτρια τελεῖν καὶ τοὺς καρποὺς μεταχειρίζεσθαι, καθὼς ἔθος ἐστὶν αὐτοῖς, αὐτόν τε κατὰ τοὺς νόμους εὐθυνκέναι τὸ [δίκαιον] ψήφισμα. βούλομαι οὖν ὑμᾶς εἰδέναι, ὅτι διακούσας ἐγὼ λόγων ἐξ ἀντικαταστάσεως γενομένων ἐπέκρινα μὴ κωλύεσθαι Ἰουδαίους τοῖς αὐτῶν ἔθεσι χρῆσθαι.", "st": "14.10.21"}, {"sp": "N", "t": "Ψήφισμα Περγαμηνῶν. ἐπὶ πρυτάνεως Κρατίππου μηνὸς Δαισίου [πρώτῃ] γνώμη στρατηγῶν. ἐπεὶ Ῥωμαῖοι κατακολουθοῦντες τῇ τῶν προγόνων ἀγωγῇ τοὺς ὑπὲρ τῆς κοινῆς ἁπάντων ἀνθρώπων ἀσφαλείας κινδύνους ἀναδέχονται καὶ φιλοτιμοῦνται τοὺς συμμάχους καὶ φίλους ἐν εὐδαιμονίᾳ καὶ βεβαίᾳ καταστῆσαι εἰρήνῃ, πέμψαντος πρὸς αὐτοὺς τοῦ ἔθνους τοῦ Ἰουδαίων καὶ Ὑρκανοῦ τοῦ ἀρχιερέως αὐτῶν πρέσβεις Στράτωνα Θεοδότου Ἀπολλώνιον Ἀλεξάνδρου Αἰνείαν Ἀντιπάτρου Ἀριστόβουλον Ἀμύντου Σωσίπατρον Φιλίππου ἄνδρας καλοὺς καὶ ἀγαθούς, καὶ περὶ τῶν κατὰ μέρη ἐμφανισάντων ἐδογμάτισεν ἡ σύγκλητος περὶ ὧν ἐποιήσαντο τοὺς λόγους, ὅπως μηδὲν ἀδικῇ Ἀντίοχος ὁ βασιλεὺς Ἀντιόχου υἱὸς Ἰουδαίους συμμάχους Ῥωμαίων, ὅπως τε φρούρια καὶ λιμένας καὶ χώραν καὶ εἴ τι ἄλλο ἀφείλετο αὐτῶν ἀποδοθῇ καὶ ἐξῇ αὐτοῖς ἐκ τῶν λιμένων μηδ’ ἐξαγαγεῖν, ἵνα τε μηδεὶς ἀτελὴς ᾖ ἐκ τῆς Ἰουδαίων χώρας ἢ τῶν λιμένων αὐτῶν ἐξάγων βασιλεὺς ἢ δῆμος ἢ μόνος Πτολεμαῖος ὁ Ἀλεξανδρέων βασιλεὺς διὰ τὸ εἶναι σύμμαχος ἡμέτερος καὶ φίλος, καὶ τὴν ἐν Ἰόππῃ φρουρὰν ἐκβαλεῖν, καθὼς ἐδεήθησαν· τῆς βουλῆς ἡμῶν Λούκιος Πέττιος ἀνὴρ καλὸς καὶ ἀγαθὸς προσέταξεν, ἵνα φροντίσωμεν ταῦτα οὕτως γενέσθαι, καθὼς ἡ σύγκλητος ἐδογμάτισεν, προνοῆσαί τε τῆς ἀσφαλοῦς εἰς οἶκον τῶν πρεσβευτῶν ἀνακομιδῆς. ἀπεδεξάμεθα δὲ καὶ ἐπὶ τὴν βουλὴν καὶ τὴν ἐκκλησίαν τὸν Θεόδωρον, ἀπολαβόντες δὲ τὴν ἐπιστολὴν παρ’ αὐτοῦ καὶ τὸ τῆς συγκλήτου δόγμα, καὶ ποιησαμένου μετὰ πολλῆς σπουδῆς τοὺς λόγους καὶ τὴν Ὑρκανοῦ ἐμφανίσαντος ἀρετὴν καὶ μεγαλοψυχίαν, καὶ ὅτι κοινῇ πάντας εὐεργετεῖ καὶ κατ’ ἰδίαν τοὺς πρὸς αὐτὸν ἀφικομένους, τά τε γράμματα εἰς τὰ δημόσια ἡμῶν ἀπεθέμεθα καὶ αὐτοὶ πάντα ποιεῖν ὑπὲρ Ἰουδαίων σύμμαχοι ὄντες Ῥωμαίων κατὰ τὸ τῆς συγκλήτου δόγμα ἐψηφισάμεθα. ἐδεήθη δὲ καὶ Θεόδωρος τὴν ἐπιστολὴν ἡμῖν ἀποδοὺς τῶν ἡμετέρων στρατηγῶν, ἵνα πέμψωσι πρὸς Ὑρκανὸν τὸ ἀντίγραφον τοῦ ψηφίσματος καὶ πρέσβεις δηλώσοντας τὴν τοῦ ἡμετέρου δήμου σπουδὴν καὶ παρακαλέσοντας συντηρεῖν τε καὶ αὔξειν αὐτὸν τὴν πρὸς ἡμᾶς φιλίαν καὶ ἀγαθοῦ τινος αἴτιον γίνεσθαι, ὡς ἀμοιβάς τε τὰς προσηκούσας ἀποληψόμενον μεμνημένον τε ὡς καὶ ἐν τοῖς κατὰ Ἄβραμον καιροῖς, ὃς ἦν πάντων Ἑβραίων πατήρ, οἱ πρόγονοι ἡμῶν ἦσαν αὐτοῖς φίλοι, καθὼς καὶ ἐν τοῖς δημοσίοις εὑρίσκομεν γράμμασιν.", "st": "14.10.22"}, {"sp": "N", "t": "Ψήφισμα Ἁλικαρνασέων. ἐπὶ ἱερέως Μέμνονος τοῦ Ἀριστείδου, κατὰ δὲ ποίησιν Εὐωνύμου, Ἀνθεστηριῶνος ἔδοξε τῷ δήμῳ εἰσηγησαμένου Μάρκου Ἀλεξάνδρου. ἐπεὶ [τὸ] πρὸς τὸ θεῖον εὐσεβές τε καὶ ὅσιον ἐν ἅπαντι καιρῷ διὰ σπουδῆς ἔχομεν κατακολουθοῦντες τῷ δήμῳ τῶν Ῥωμαίων πάντων ἀνθρώπων ὄντι εὐεργέτῃ καὶ οἷς περὶ τῆς Ἰουδαίων φιλίας καὶ συμμαχίας πρὸς τὴν πόλιν ἔγραψεν, ὅπως συντελῶνται αὐτοῖς αἱ εἰς τὸν θεὸν ἱεροποιίαι καὶ ἑορταὶ αἱ εἰθισμέναι καὶ σύνοδοι, δεδόχθαι καὶ ἡμῖν Ἰουδαίων τοὺς βουλομένους ἄνδρας τε καὶ γυναῖκας τά τε σάββατα ἄγειν καὶ τὰ ἱερὰ συντελεῖν κατὰ τοὺς Ἰουδαίων νόμους καὶ τὰς προσευχὰς ποιεῖσθαι πρὸς τῇ θαλάττῃ κατὰ τὸ πάτριον ἔθος. ἂν δέ τις κωλύσῃ ἢ ἄρχων ἢ ἰδιώτης, τῷδε τῷ ζημιώματι ὑπεύθυνος ἔστω καὶ ὀφειλέτω τῇ πόλει.", "st": "14.10.23"}, {"sp": "N", "t": "Ψήφισμα Σαρδιανῶν. ἔδοξε τῇ βουλῇ καὶ τῷ δήμῳ στρατηγῶν εἰσηγησαμένων. ἐπεὶ οἱ κατοικοῦντες ἡμῶν ἐν τῇ πόλει ἀπ’ ἀρχῆς Ἰουδαῖοι πολῖται πολλὰ καὶ μεγάλα φιλάνθρωπα ἐσχηκότες διὰ παντὸς παρὰ τοῦ δήμου καὶ νῦν εἰσελθόντες ἐπὶ τὴν βουλὴν καὶ τὸν δῆμον παρεκάλεσαν, ἀποκαθισταμένων αὐτοῖς τῶν νόμων καὶ τῆς ἐλευθερίας ὑπὸ τῆς συγκλήτου καὶ τοῦ δήμου τοῦ Ῥωμαίων ἵνα κατὰ τὰ νομιζόμενα ἔθη συνάγωνται καὶ πολιτεύωνται καὶ διαδικάζωνται πρὸς αὑτούς, δοθῇ τε καὶ τόπος αὐτοῖς, εἰς ὃν συλλεγόμενοι μετὰ γυναικῶν καὶ τέκνων ἐπιτελοῦσιν τὰς πατρίους εὐχὰς καὶ θυσίας τῷ θεῷ· δεδόχθαι τῇ βουλῇ καὶ τῷ δήμῳ συγκεχωρῆσθαι αὐτοῖς συνερχομένοις ἐν ταῖς ἀποδεδειγμέναις ἡμέραις πράσσειν τὰ κατὰ τοὺς αὐτῶν νόμους, ἀφορισθῆναι δ’ αὐτοῖς καὶ τόπον ὑπὸ τῶν στρατηγῶν εἰς οἰκοδομίαν καὶ οἴκησιν αὐτῶν, ὃν ἂν ὑπολάβωσιν πρὸς τοῦτ’ ἐπιτήδειον εἶναι, ὅπως τε τοῖς τῆς πόλεως ἀγορανόμοις ἐπιμελὲς ᾖ καὶ τὰ ἐκείνοις πρὸς τροφὴν ἐπιτήδεια ποιεῖν εἰσάγεσθαι.", "st": "14.10.24"}, {"sp": "N", "t": "Ψήφισμα Ἐφεσίων. ἐπὶ πρυτάνεως Μηνοφίλου μηνὸς Ἀρτεμισίου τῇ προτέρᾳ ἔδοξε τῷ δήμῳ, Νικάνωρ Εὐφήμου εἶπεν εἰσηγησαμένων τῶν στρατηγῶν. ἐπεὶ ἐντυχόντων τῶν ἐν τῇ πόλει Ἰουδαίων Μάρκῳ Ἰουλίῳ Ποντίου υἱῷ Βρούτῳ ἀνθυπάτῳ, ὅπως ἄγωσι τὰ σάββατα καὶ πάντα ποιῶσιν κατὰ τὰ πάτρια αὐτῶν ἔθη μηδενὸς αὐτοῖς ἐμποδὼν γινομένου, ὁ στρατηγὸς συνεχώρησεν, δεδόχθαι τῷ δήμῳ, τοῦ πράγματος Ῥωμαίοις ἀνήκοντος, μηδένα κωλύεσθαι παρατηρεῖν τὴν τῶν σαββάτων ἡμέραν μηδὲ πράττεσθαι ἐπιτίμιον, ἐπιτετράφθαι δ’ αὐτοῖς πάντα ποιεῖν κατὰ τοὺς ἰδίους αὐτῶν νόμους.", "st": "14.10.25"}, {"sp": "N", "t": "Πολλὰ μὲν οὖν ἐστιν καὶ ἄλλα τοιαῦτα τῇ συγκλήτῳ καὶ τοῖς αὐτοκράτορσι τοῖς Ῥωμαίων δόγματα πρὸς Ὑρκανὸν καὶ τὸ ἔθνος ἡμῶν γεγενημένα καὶ πόλεσιν ψηφίσματα καὶ γράμματα πρὸς τὰς περὶ τῶν ἡμετέρων δικαίων ἐπιστολὰς ἀντιπεφωνημένα τοῖς ἡγεμόσιν, περὶ ὧν ἁπάντων ἐξ ὧν παρατεθείμεθα πιστεύειν τοῖς ἀναγνωσομένοις οὐ βασκάνως ἡμῶν τὴν γραφὴν πάρεστιν. ἐπεὶ γὰρ ἐναργῆ καὶ βλεπόμενα τεκμήρια παρεχόμεθα τῆς πρὸς Ῥωμαίους ἡμῖν φιλίας γενομένης ἐπιδεικνύντες αὐτὰ χαλκαῖς στήλαις καὶ δέλτοις ἐν τῷ Καπετωλίῳ μέχρι νῦν διαμένοντα καὶ διαμενοῦντα, τὴν μὲν πάντων παράθεσιν ὡς περιττήν τε ἅμα καὶ ἀτερπῆ παρῃτησάμην, οὐδένα δ’ οὕτως ἡγησάμην σκαιόν, ὃς οὐχὶ καὶ περὶ τῆς Ῥωμαίων ἡμῖν πιστεύσει φιλανθρωπίας, ὅτι ταύτην καὶ διὰ πλειόνων ἐπεδείξαντο πρὸς ἡμᾶς δογμάτων, καὶ ἡμᾶς οὐχ ὑπολήψεται περὶ ὧν εἶναί φαμεν ἀληθεύειν ἐξ ὧν ἐπεδείξαμεν. τὴν μὲν οὖν πρὸς Ῥωμαίους φιλίαν καὶ συμμαχίαν κατ’ ἐκείνους τοὺς καιροὺς γενομένην δεδηλώκαμεν.", "st": "14.10.26"}, {"sp": "N", "t": "Συνέβη δ’ ὑπὸ τὸν αὐτὸν καιρὸν ταραχθῆναι τὰ κατὰ τὴν Συρίαν ἐξ αἰτίας τοιαύτης· Βάσσος Καικίλιος εἷς τῶν τὰ Πομπηίου φρονούντων ἐπιβουλὴν συνθεὶς ἐπὶ Σέξστον Καίσαρα κτείνει μὲν ἐκεῖνον, αὐτὸς δὲ τὸ στράτευμα αὐτοῦ παραλαβὼν ἐκράτει τῶν πραγμάτων, πόλεμός τε μέγας περὶ τὴν Ἀπάμειαν συνέστη τῶν Καίσαρος στρατηγῶν ἐπ’ αὐτὸν ἐλθόντων μετά τε ἱππέων καὶ πεζῆς δυνάμεως. τούτοις δὲ καὶ Ἀντίπατρος συμμαχίαν ἔπεμψεν μετὰ τῶν τέκνων κατὰ μνήμην ὧν εὐεργετήθησαν ὑπὸ Καίσαρος καὶ διὰ τοῦτο τιμωρεῖν αὐτῷ καὶ δίκην παρὰ τοῦ πεφονευκότος εἰσπράξασθαι δίκαιον ἡγούμενος. χρονιζομένου δὲ τοῦ πολέμου Μοῦρκος μὲν ἦλθεν ἐκ Ῥώμης εἰς τὴν ἀρχὴν τὴν Σέξστου, Καῖσαρ δ’ ὑπὸ τῶν περὶ Κάσσιον καὶ Βροῦτον ἐν τῷ βουλευτηρίῳ κτείνεται κατασχὼν τὴν ἀρχὴν ἔτη τρία καὶ μῆνας ἕξ. τοῦτο μὲν οὖν καὶ ἐν ἄλλοις δεδήλωται.", "st": "14.11.1"}, {"sp": "N", "t": "Τοῦ δ’ ἐπὶ τῷ Καίσαρος θανάτῳ πολέμου συνερρωγότος καὶ τῶν ἐν τέλει πάντων ἐπὶ στρατιᾶς συλλογὴν ἄλλου ἄλλῃ διεσπαρμένων, ἀφικνεῖται Κάσσιος εἰς Συρίαν παραληψόμενος τὰ περὶ τὴν Ἀπάμειαν στρατόπεδα· καὶ λύσας τὴν πολιορκίαν ἀμφοτέρους προσάγεται τόν τε Βάσσον καὶ τὸν Μοῦρκον τάς τε πόλεις ἐπερχόμενος ὅπλα τε καὶ στρατιώτας συνήθροιζεν καὶ φόρους αὐταῖς μεγάλους ἐπετίθει· μάλιστα δὲ τὴν Ἰουδαίαν ἐκάκωσεν ἑπτακόσια τάλαντα ἀργυρίου πραττόμενος. Ἀντίπατρος δ’ ὁρῶν ἐν μεγάλῳ φόβῳ καὶ ταραχῇ τὰ πράγματα μερίζει τὴν τῶν χρημάτων εἴσπραξιν καὶ ἑκατέρῳ τῶν υἱῶν συνάγειν δίδωσιν τὰ μὲν Μαλίχῳ κακοήθως πρὸς αὐτὸν διακειμένῳ, τὰ δὲ ἄλλοις προσέταξεν εἰσπράττεσθαι. καὶ πρῶτος Ἡρώδης ἀπὸ τῆς Γαλιλαίας εἰσπραξάμενος ὅσα ἦν αὐτῷ προστεταγμένα φίλος ἦν εἰς τὰ μάλιστα Κασσίῳ· σῶφρον γὰρ ἔδοξεν αὐτῷ Ῥωμαίους ἤδη θεραπεύειν καὶ τὴν παρ’ αὐτῶν κατασκευάζειν εὔνοιαν ἐκ τῶν ἀλλοτρίων πόνων. ἐπιπράσκοντο δ’ αὔτανδροι οἱ τῶν ἄλλων [πόλεων] ἐπιμεληταί, καὶ τέσσαρας πόλεις ἐξηνδραπόδισε τότε Κάσσιος, ὧν ἦσαν αἱ δυνατώταται Γόφνα τε καὶ Ἀμμαοῦς, πρὸς ταύταις δὲ Λύδδα καὶ Θάμνα. ἐπεξῆλθε δ’ ἂν ὑπ’ ὀργῆς Κάσσιος ὥστε καὶ Μάλιχον ἀνελεῖν, ὥρμητο γὰρ ἐπ’ αὐτόν, εἰ μὴ Ὑρκανὸς δι’ Ἀντιπάτρου ἑκατὸν τάλαντα ἐκ τῶν ἰδίων αὐτῷ πέμψας ἐπέσχε τῆς ὁρμῆς.", "st": "14.11.2"}, {"sp": "N", "t": "Ἐπεὶ δὲ Κάσσιος ἐκ τῆς Ἰουδαίας ἀπῆρεν, Μάλιχος ἐπεβούλευσεν Ἀντιπάτρῳ τὴν τούτου τελευτὴν ἀσφάλειαν Ὑρκανοῦ τῆς ἀρχῆς εἶναι νομίζων. οὐ μὴν ἔλαθεν τὸν Ἀντίπατρον ταῦτα φρονῶν, ἀλλ’ αἰσθόμενος γὰρ ἐκεῖνος ἐχώρει πέραν Ἰορδάνου καὶ στρατὸν Ἀράβιον ἅμα καὶ ἐγχώριον συνήθροιζεν. δεινὸς δὲ ὢν ὁ Μάλιχος ἠρνεῖτο μὲν τὴν ἐπιβουλήν, ἀπολογούμενος δὲ μεθ’ ὅρκων αὐτῷ τε καὶ τοῖς παισίν, καὶ ὡς Φασαήλου μὲν Ἱεροσόλυμα φρουροῦντος, Ἡρώδου δὲ ἔχοντος τὴν φυλακὴν τῶν ὅπλων οὐδ’ ἂν εἰς νοῦν ἐβάλετο τοιοῦτον οὐδὲν ὁρῶν τὴν ἀπορίαν, καταλλάσσεται πρὸς τὸν Ἀντίπατρον, καὶ συνέβησαν Μούρκου κατὰ Συρίαν στρατηγοῦντος, ὃς αἰσθόμενος νεωτεροποιοῦντα τὰ κατὰ τὴν Ἰουδαίαν τὸν Μάλιχον ἦλθε μὲν ὡς παρὰ μικρὸν αὐτὸν ἀνελεῖν, Ἀντιπάτρου δὲ παρακαλέσαντος περιέσωσεν.", "st": "14.11.3"}, {"sp": "N", "t": "Ἦν δὲ ἄρα φονέα περισώσας Ἀντίπατρος αὐτοῦ τὸν Μάλιχον· Κάσσιος μὲν γὰρ καὶ Μοῦρκος στρατὸν ἀθροίζοντες τὴν ἐπιμέλειαν ἅπασαν ἐνεχείρισαν Ἡρώδῃ καὶ στρατηγὸν αὐτὸν κοίλης Συρίας ἐποίησαν πλοῖα δόντες καὶ δύναμιν ἱππικήν τε καὶ πεζικήν, ὑποσχόμενοί τε καὶ βασιλέα τῆς Ἰουδαίας ἀναδείξειν μετὰ τὸν πόλεμον· συνειστήκει γὰρ τότε πρός τε Ἀντώνιον καὶ τὸν νέον Καίσαρα. Μάλιχος δὲ δείσας τότε μάλιστα τὸν Ἀντίπατρον ἐκποδὼν ἐποιεῖτο, καὶ πείσας ἀργυρίῳ τὸν Ὑρκανοῦ οἰνοχόον, παρ’ ᾧ ἑκάτεροι εἱστιῶντο, φαρμάκῳ κτείνει τὸν ἄνδρα, καὶ ὁπλίτας ἔχων εὐτρέπιζεν τὰ κατὰ τὴν πόλιν. γνόντων δὲ τὴν ἐπιβουλὴν τὴν κατὰ τοῦ πατρὸς Ἡρώδου καὶ Φασαήλου καὶ χαλεπῶς ἐχόντων, ἠρνεῖτο πάλιν ὁ Μάλιχος καὶ ἔξαρνος ἦν τοῦ φόνου. καὶ Ἀντίπατρος μὲν εὐσεβείᾳ τε καὶ δικαιοσύνῃ διενεγκὼν καὶ τῇ περὶ τὴν πατρίδα σπουδῇ τοῦτον ἐτελεύτησεν τὸν τρόπον. τῶν δὲ παίδων αὐτοῦ Ἡρώδης μὲν εὐθὺς ἔγνω τιμωρεῖν τῷ πατρὶ μετὰ στρατιᾶς ἐπὶ Μάλιχον ἐλθών. Φασαήλῳ δὲ τῷ πρεσβυτέρῳ δόλῳ μᾶλλον ἐδόκει περιγίνεσθαι τἀνδρός, μὴ πολέμου κατάρχειν νομισθῶσιν ἐμφυλίου. τήν τε οὖν ἀπολογίαν τὴν Μαλίχου προσδέχεται καὶ πιστεύειν ὑποκρίνεται μηδὲν αὐτὸν περὶ τὸν Ἀντιπάτρου θάνατον κακουργῆσαι, τάφον τε ἐκόσμει τῷ πατρί. καὶ παραγενόμενος Ἡρώδης εἰς Σαμάρειαν καὶ καταλαβὼν αὐτὴν κεκακωμένην ἀνεκτᾶτο καὶ τὰ νείκη διέλυε τοῖς ἀνθρώποις.", "st": "14.11.4"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δ’ ἐνστάσης τῆς ἐν Ἱεροσολύμοις ἑορτῆς παρεγίνετο σὺν τοῖς στρατιώταις εἰς τὴν πόλιν, καὶ δείσας ὁ Μάλιχος ἀνέπεισεν Ὑρκανὸν μὴ ἐπιτρέπειν αὐτῷ εἰσιέναι. καὶ πείθεται μὲν Ὑρκανός, προβέβλητο δὲ αἰτίαν τῆς ἀποκωλύσεως τὸ μὴ δεῖν ὄχλον ἀλλοδαπὸν ἁγνεύοντος εἰσδέχεσθαι τοῦ πλήθους. ὀλίγον δὲ φροντίσας Ἡρώδης τῶν ἀγγέλων νύκτωρ εἴσεισιν εἰς τὴν πόλιν καὶ φοβερὸς ἦν τῷ Μαλίχῳ, ὁ δ’ οὐκ ἀνίησιν τὴν ὑπόκρισιν, ἀλλ’ ἐδάκρυεν τὸν Ἀντίπατρον καὶ ἀνεκαλεῖτο φανερῶς ὡς φίλος, κρύφα δὲ φυλακὴν τοῦ σώματος ἐποιεῖτο. ἔδοξε δὲ καὶ τοῖς περὶ Ἡρώδην μὴ ἀπελέγχειν αὐτοῦ τὴν προσποίησιν, ἀλλὰ καὶ αὐτοὺς εἰς τὸ ἀνύποπτον ἀντιφιλοφρονεῖσθαι τὸν Μάλιχον.", "st": "14.11.5"}, {"sp": "N", "t": "Κασσίῳ μέντοι περὶ τῆς τελευτῆς τοῦ πατρὸς Ἡρώδης ἐπέστελλεν, κἀκεῖνος εἰδώς, οἷος εἴη τὸν τρόπον Μάλιχος, ἀντεπιστέλλει τιμωρεῖν τῷ πατρί, καὶ λάθρα διαπέμπει πρὸς τοὺς ἐν Τύρῳ χιλιάρχους κελεύων αὐτοὺς συμπράττειν Ἡρώδῃ δίκαια μέλλοντι πράξειν. ὡς δὲ Λαοδίκειαν ᾑρηκότος Κασσίου πρὸς αὐτὸν ἀπῄεσαν κοινῇ στεφάνους τε αὐτῷ καὶ χρήματα κομίζοντες, Ἡρώδης μὲν προσεδόκα δώσειν τὸν Μάλιχον τιμωρίαν ἐκεῖ γενόμενον, ὁ δὲ περὶ Τύρον τῆς Φοινίκης ὑπιδόμενος τὸ πρᾶγμα μειζόνων ἐφήπτετο, καὶ τοῦ παιδὸς αὐτῷ ὁμηρεύοντος ἐν Τύρῳ παρελθὼν εἰς τὴν πόλιν ἔγνω τοῦτόν τε ὑπεκκλέψαι καὶ εἰς τὴν Ἰουδαίαν ἀπαίρειν σπεύδοντος ἐπ’ Ἀντώνιον Κασσίου τό τε ἔθνος ἀποστήσας αὐτὸς τὴν ἀρχὴν κατέχειν. τοῖς δὲ βεβουλευμένοις ὅ τε δαίμων ἀντέπραξεν καὶ δεινὸς ὢν Ἡρώδης τὴν προαίρεσιν αὐτοῦ κατανοῆσαι, ὃς προεισπέμψας θεράποντα τῷ μὲν δοκεῖν ἐπὶ δείπνου παρασκευήν, καὶ γὰρ ἑστιάσειν αὐτοὺς ἅπαντας προειρήκει, ταῖς δ’ ἀληθείαις πρὸς τοὺς χιλιάρχους, ἐξελθεῖν ἐπὶ Μάλιχον πείθει μετὰ ξιφιδίων. οἱ δ’ ἐπεξελθόντες καὶ πλησίον τῆς πόλεως αὐτῷ περιτυχόντες ἐπὶ τοῦ αἰγιαλοῦ κατακεντοῦσι τὸν ἄνδρα. Ὑρκανὸς μὲν οὖν ὑπ’ ἐκπλήξεως τοῦ γεγονότος εἰς ἀφωνίαν ἐτράπη, μόλις δ’ ἀνενεγκὼν ἐπυνθάνετο τῶν περὶ Ἡρώδην, ὅ τι ποτε εἴη τὸ γεγενημένον καὶ τίς ὁ Μάλιχον ἀνῃρηκώς. εἰπόντων δὲ Κάσσιον τοῦτο προστάξαι, ἐπῄνεσεν τὸ ἔργον, πονηρὸν γὰρ εἶναι πάνυ καὶ τῆς πατρίδος ἐπίβουλον. καὶ Μάλιχος μὲν ταύτην ὑπὲρ τῆς εἰς Ἀντίπατρον παρανομίας δίκην ἐξέτισεν.", "st": "14.11.6"}, {"sp": "N", "t": "Κασσίου δ’ ἐκ Συρίας ἀπάραντος ταραχὴ γίνεται κατὰ τὴν Ἰουδαίαν· Ἔλιξ γὰρ ὑπολειφθεὶς ἐν Ἱεροσολύμοις μετὰ στρατιᾶς ὥρμησεν ἐπὶ Φασάηλον ὅ τε δῆμος ἔνοπλος ἦν. Ἡρώδης δὲ παρὰ Φάβιον ἐπορεύετο ἐν Δαμασκῷ στρατηγοῦντα, καὶ βουλόμενος προσδραμεῖν πρὸς τὸν ἀδελφὸν ὑπὸ νόσου κωλύεται, ἕως οὗ Φασάηλος δι’ αὐτοῦ κρείττων Ἔλικος γενόμενος κατακλείει μὲν αὐτὸν εἰς πύργον, εἶτα δὲ ὑπόσπονδον ἀφίησιν, τόν τε Ὑρκανὸν ἐμέμφετο πολλὰ μὲν εὖ παθόντα ὑπ’ αὐτῶν συμπράττοντα δὲ τοῖς ἐχθροῖς. ὁ γὰρ ἀδελφὸς Μαλίχου τότε ἀποστήσας οὐκ ὀλίγα χωρία ἐφρούρει καὶ Μάσαδαν τὸ πάντων ἐρυμνότατον. ἐπὶ μὲν οὖν τοῦτον ῥαΐσας Ἡρώδης ἐκ τῆς νόσου παραγίνεται καὶ ἀφελόμενος αὐτοῦ πάντα ὅσα εἶχεν χωρία ὑπόσπονδον ἀπέλυσεν.", "st": "14.11.7"}, {"sp": "N", "t": "Ἀντίγονον δὲ τὸν Ἀριστοβούλου στρατιὰν ἀθροίσαντα καὶ Φάβιον τεθεραπευκότα χρήμασιν κατῆγεν Πτολεμαῖος ὁ Μενναίου διὰ τὸ κήδευμα. συνεμάχει δ’ αὐτῷ καὶ Μαρίων, ὃν Τυρίων καταλελοίπει τύραννον Κάσσιος· τυραννίσι γὰρ διαλαβὼν τὴν Συρίαν οὗτος ὁ ἀνὴρ ἐφρούρησεν. ὁ δὲ Μαρίων καὶ εἰς τὴν Γαλιλαίαν ὅμορον οὖσαν ἐνέβαλεν καὶ τρία καταλαβὼν ἐρύματα διὰ φρουρᾶς εἶχεν. ἐλθὼν δὲ καὶ ἐπὶ τοῦτον Ἡρώδης ἅπαντα μὲν αὐτὸν ἀφείλετο, τοὺς δὲ Τυρίων φρουροὺς φιλανθρώπως ἀπέλυσεν ἔστιν οἷς καὶ δωρεὰς δοὺς διὰ τὸ πρὸς τὴν πόλιν εὔνουν. ταῦτα διαπραξάμενος ὑπήντησεν Ἀντιγόνῳ καὶ μάχην αὐτῷ συνάψας νικᾷ καὶ ὅσον οὔπω τῶν ἄκρων ἐπιβάντα τῆς Ἰουδαίας ἐξέωσεν. εἰς Ἱεροσόλυμα δὲ παραγενόμενον στεφάνοις ἀνέδουν Ὑρκανός τε καὶ ὁ δῆμος. ἐγεγάμβρευτο δ’ ἤδη καθ’ ὁμολογίαν τῷ Ὑρκανοῦ γένει καὶ διὰ τοῦτο μᾶλλον αὐτοῦ προειστήκει μέλλων ἄγεσθαι τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου θυγατέρα, Ὑρκανοῦ δὲ θυγατριδῆν, ἐξ ἧς πατὴρ μὲν γίνεται τριῶν ἀρρένων, δύο δὲ θηλειῶν. ἦκτο δὲ πρότερον καὶ γυναῖκα δημότιν Δῶριν ὄνομα ἐκ τοῦ ἔθνους, ἐξ ἧς αὐτῷ πρεσβύτατος γίνεται Ἀντίπατρος.", "st": "14.12.1"}, {"sp": "N", "t": "Κάσσιον μὲν οὖν χειροῦνται Ἀντώνιός τε καὶ Καῖσαρ περὶ Φιλίππους, ὡς καὶ παρ’ ἄλλοις δεδήλωται. μετὰ δὲ τὴν νίκην Καῖσαρ μὲν ἐπ’ Ἰταλίας ἐχώρει, Ἀντώνιος δὲ εἰς τὴν Ἀσίαν ἀπῆρεν· γενομένῳ δὲ ἐν τῇ Βιθυνίᾳ αἱ πανταχόθεν ἀπήντων πρεσβεῖαι. παρῆσαν δὲ καὶ Ἰουδαίων οἱ ἐν τέλει κατηγοροῦντες τῶν περὶ Φασάηλον καὶ Ἡρώδην, πρόσχημα μὲν εἶναι λέγοντες τῆς βασιλείας Ὑρκανόν, τούτους δὲ τὴν πᾶσαν ἔχειν ἐξουσίαν. Ἡρώδην δὲ Ἀντώνιος διὰ πολλῆς εἶχε τιμῆς ἐλθόντα πρὸς αὐτὸν ἐπὶ ἀπολογίᾳ τῶν κατηγορούντων, καὶ διὰ τοῦτο συνέβη μηδὲ λόγου τυχεῖν τοὺς ἀντιστασιώτας· διεπέπρακτο δὲ τοῦτο χρήμασιν Ἡρώδης παρ’ Ἀντωνίου. ἐπεὶ δ’ εἰς Ἔφεσον ἧκεν Ἀντώνιος, ἔπεμψεν Ὑρκανὸς ὁ ἀρχιερεὺς καὶ τὸ ἔθνος τὸ ἡμέτερον πρεσβείαν πρὸς αὐτὸν στέφανόν τε κομίζουσαν χρυσοῦν καὶ παρακαλοῦσαν τοὺς αἰχμαλωτισθέντας ὑπὸ Κασσίου Ἰουδαίους οὐ νόμῳ πολέμου γράψαντα τοῖς κατὰ τὰς ἐπαρχίας ἐλευθέρους ἀπολῦσαι καὶ τὴν χώραν, ἣν ἐν τοῖς Κασσίου καιροῖς ἀφῃρέθησαν, ἀποδοῦναι. ταῦτα κρίνας Ἀντώνιος ἀξιοῦν δίκαια τοὺς Ἰουδαίους παραχρῆμα ἔγραψεν Ὑρκανῷ καὶ τοῖς Ἰουδαίοις, ἐπέστειλεν δὲ καὶ τοῖς Τυρίοις καὶ διάταγμα ἔπεμπε περιέχον ταῦτα.", "st": "14.12.2"}, {"sp": "N", "t": "Μᾶρκος Ἀντώνιος αὐτοκράτωρ Ὑρκανῷ ἀρχιερεῖ καὶ ἐθνάρχῃ καὶ τῷ Ἰουδαίων ἔθνει χαίρειν. εἰ ἔρρωσθε, εὖ ἂν ἔχοι, ἔρρωμαι δὲ καὶ αὐτὸς μετὰ τοῦ στρατεύματος. Λυσίμαχος Παυσανίου καὶ Ἰώσηπος Μενναίου καὶ Ἀλέξανδρος Θεοδώρου πρεσβευταὶ ἐν Ἐφέσῳ μοι συντυχόντες τήν τε ἔμπροσθεν ἐν Ῥώμῃ τελεσθεῖσαν αὐτοῖς πρεσβείαν ἀνενεώσαντο καὶ τὴν νῦν ὑπὲρ σοῦ καὶ τοῦ ἔθνους σπουδαίως διέθεντο, ἣν ἔχεις εὔνοιαν πρὸς ἡμᾶς ἐμφανίσαντες. πεπεισμένος οὖν καὶ ἐκ τῶν πραγμάτων καὶ ἐκ τῶν λόγων, ὅτι οἰκειότατα ἔχετε πρὸς ἡμᾶς, καὶ τὸ ἀραρὸς ὑμῶν ἦθος καὶ θεοσεβὲς κατανοήσας, ἴδιον ἥγημαι καταδραμόντων δὲ τὴν Ἀσίαν ἅπασαν τῶν ἐναντιωθέντων ἡμῖν τε καὶ τῷ δήμῳ τῶν Ῥωμαίων καὶ μήτε πόλεων μήτε ἡρῴων ἀποσχομένων μήτε ὅρκους οὓς ἐποιήσαντο φυλαξάντων, ἡμεῖς ὡς οὐχ ὑπὲρ ἰδίου μόνον ἀγῶνος, ἀλλ’ ὡς ὑπὲρ ἁπάντων κοινοῦ, τοὺς αἰτίους καὶ τῶν εἰς ἀνθρώπους παρανομιῶν καὶ τῶν εἰς θεοὺς ἁμαρτημάτων ἠμυνάμεθα, δι’ ἃ καὶ τὸν ἥλιον ἀπεστράφθαι δοκοῦμεν, ὃς καὶ αὐτὸς ἀηδῶς ἐπεῖδεν τὸ ἐπὶ Καίσαρι μύσος. ἀλλὰ τὰς ἐπιβουλὰς αὐτῶν τὰς θεημάχους, ἃς ὑπεδέξατο ἡ Μακεδονία καθάπερ ἴδιος αὐτοῖς τῶν ἀνοσίων τολμημάτων ἀήρ, καὶ τὴν σύγχυσιν τῆς ἡμιμανοῦς κακοηθείας κατὰ Φιλίππους τῆς Μακεδονίας συνεκρότουν, καὶ τόπους εὐφυεῖς καταλαμβανόμενοι μέχρι θαλάσσης ἀποτετειχισμένους ὄρεσιν, ὡς πύλῃ μιᾷ τὴν πάροδον ταμιεύεσθαι, τῶν θεῶν αὐτοὺς ἐπὶ τοῖς ἀδίκοις ἐγχειρήμασιν κατεψηφισμένων ἐκρατήσαμεν. καὶ Βροῦτος συμφυγὼν εἰς Φιλίππους καὶ συγκλεισθεὶς ὑφ’ ἡμῶν ἐκοινώνησεν Κασσίῳ τῆς ἀπωλείας. τούτων κεκολασμένων εἰρήνης τὸ λοιπὸν ἀπολαύσειν ἐλπίζομεν καὶ ἀναπεπαῦσθαι τὴν Ἀσίαν ἐκ τοῦ πολέμου. κοινὴν οὖν ποιούμεθα καὶ τοῖς συμμάχοις τὴν ὑπὸ θεοῦ δοθεῖσαν ἡμῖν εἰρήνην· ὥσπερ οὖν ἐκ νόσου μεγάλης τὸ τῆς Ἀσίας σῶμα νῦν διὰ τὴν ἡμετέραν νίκην ἀναφέρειν. ἔχων τοίνυν καὶ σὲ διὰ μνήμης καὶ τὸ ἔθνος αὔξειν φροντίσω τῶν ὑμῖν συμφερόντων. ἐξέθηκα δὲ καὶ γράμματα κατὰ πόλεις, ὅπως εἴ τινες ἐλεύθεροι ἢ δοῦλοι ὑπὸ δόρυ ἐπράθησαν ὑπὸ Γαΐου Κασσίου ἢ τῶν ὑπ’ αὐτῷ τεταγμένων ἀπολυθῶσιν οὗτοι, τοῖς τε ὑπ’ ἐμοῦ δοθεῖσιν καὶ Δολαβέλλα φιλανθρώποις χρῆσθαι ὑμᾶς βούλομαι. Τυρίους τε κωλύω βιαίους εἶναι περὶ ὑμᾶς καὶ ὅσα κατέχουσιν Ἰουδαίων ταῦτα ἀποκαταστῆσαι κελεύω. τὸν δὲ στέφανον ὃν ἔπεμψας ἐδεξάμην.", "st": "14.12.3"}, {"sp": "N", "t": "Μᾶρκος Ἀντώνιος αὐτοκράτωρ Τυρίων ἄρχουσι βουλῇ δήμῳ χαίρειν. ἐμφανισάντων μοι ἐν Ἐφέσῳ Ὑρκανοῦ τοῦ ἀρχιερέως καὶ ἐθνάρχου πρεσβευτῶν καὶ χώραν αὐτῶν ὑμᾶς κατέχειν λεγόντων, εἰς ἣν ἐνέβητε κατὰ τὴν τῶν ἐναντιουμένων ἡμῖν ἐπικράτειαν, ἐπεὶ τὸν ὑπὲρ τῆς ἡγεμονίας πόλεμον ἀνεδεξάμεθα καὶ τῶν εὐσεβῶν καὶ δικαίων ποιούμενοι πρόνοιαν ἠμυνάμεθα τοὺς μήτε χάριτος ἀπομνημονεύσαντας μήτε ὅρκους φυλάξαντας, βούλομαι καὶ τὴν ἀφ’ ὑμῶν εἰρήνην τοῖς συμμάχοις ἡμῶν ὑπάρχειν καὶ ὅσα παρὰ τῶν ἡμετέρων ἐλάβετε ἀνταγωνιστῶν μὴ συγχωρεῖν, [ἀλλὰ] ταῦτα ἀποδοθῆναι τοῖς ἀφῃρημένοις. οὔτε γὰρ ἐπαρχίας ἐκείνων οὐθεὶς οὔτε στρατόπεδα τῆς συγκλήτου δούσης ἔλαβεν, ἀλλὰ βίᾳ καθαρπάσαντες ἐχαρίσαντο βιαίως τοῖς πρὸς ἃ ἠδίκουν χρησίμοις αὐτοῖς γινομένοις. δίκην οὖν αὐτῶν δεδωκότων τούς τε συμμάχους τοὺς ἡμετέρους ὅσα ποτ’ εἶχον ἀξιοῦμεν ἀκωλύτους διακατέχειν καὶ ὑμᾶς, εἴ τινα χωρία Ὑρκανοῦ ὄντα τοῦ ἐθνάρχου Ἰουδαίων πρὸ μιᾶς ἡμέρας ἢ Γάιον Κάσσιον πόλεμον οὐ συγκεχωρημένον ἐπάγοντα ἐπιβῆναι τῆς ἐπαρχίας ἡμῶν νῦν ἔχετε, ἀποδοῦναι αὐτῷ βίαν τε αὐτοῖς μηδεμίαν προσφέρειν ἐπὶ τῷ ἀσθενεῖς αὐτοὺς ποιεῖν τῶν ἰδίων δεσπόζειν. εἰ δέ τινα ἔχετε πρὸς αὐτὸν δικαιολογίαν, ὅταν ἔλθωμεν ἐπὶ τοὺς τόπους ἐξέσται ὑμῖν ταύτῃ χρήσασθαι, ἡμῶν ἕκαστα τοῖς συμμάχοις ὁμοίως τοῖς κρίμασιν φυλασσόντων.", "st": "14.12.4"}, {"sp": "N", "t": "Μᾶρκος Ἀντώνιος αὐτοκράτωρ Τυρίων ἄρχουσι βουλῇ δήμῳ χαίρειν. διάταγμα ἐμὸν ἀπέσταλκα πρὸς ὑμᾶς, περὶ οὗ βούλομαι ὑμᾶς φροντίσαι, ἵνα αὐτὸ εἰς τὰς δημοσίας ἐντάξητε δέλτους γράμμασι Ῥωμαϊκοῖς καὶ Ἑλληνικοῖς καὶ ἐν τῷ ἐπιφανεστάτῳ ἔχητε αὐτὸ γεγραμμένον, ὅπως ὑπὸ πάντων ἀναγινώσκεσθαι δύνηται. Μᾶρκος Ἀντώνιος αὐτοκράτωρ τριῶν ἀνδρῶν καταστάντων περὶ τῶν δημοσίων πραγμάτων εἶπεν· ἐπεὶ Γάιος Κάσσιος ταύτῃ τῇ ὑποστάσει ἀλλοτρίαν ἐπαρχίαν κατεχομένην ὑπὸ στρατοπέδων καὶ συμμάχους ὄντας διήρπασεν καὶ ἐξεπολιόρκησεν τὸ Ἰουδαίων ἔθνος φίλον ὑπάρχον τοῦ Ῥωμαίων δήμου, τὴν ἀπόνοιαν τὴν ἐκείνου τοῖς ὅπλοις κρατήσαντες διατάγμασιν καὶ κρίμασιν ἐπανορθούμεθα τὰ ὑπ’ αὐτοῦ διηρπασμένα, ὥστε ἀποκατασταθῆναι ταῦτα τοῖς συμμάχοις ἡμῶν· καὶ ὅσα ἐπράθη Ἰουδαίων ἤτοι σώματα Ἰουδαίων ἢ κτῆσις ταῦτα ἀφεθήτω, τὰ μὲν σώματα ἐλεύθερα, ὡς ἦν ἀπ’ ἀρχῆς, ἡ δὲ κτῆσις τοῖς πρότερον κυρίοις. τὸν δ’ οὐχ ὑπακούσαντα τῷ ἐμῷ διατάγματι δίκην συστήσασθαι βούλομαι, κἂν ἁλῷ τότε κατὰ τὴν τοῦ πράγματος ἀξίαν μελήσει μοι ἐπεξελθεῖν τὸν οὐχ ὑπακούσαντα.", "st": "14.12.5"}, {"sp": "N", "t": "Τὸ δ’ αὐτὸ τοῦτο καὶ Σιδωνίοις καὶ Ἀντιοχεῦσιν καὶ Ἀραδίοις ἔγραψεν. παρεθέμεθα μὲν οὖν καὶ ταῦτα εὐκαίρως τεκμήρια γενησόμενα ἧς φαμὲν Ῥωμαίους ποιήσασθαι προνοίας ὑπὲρ τοῦ ἡμετέρου ἔθνους.", "st": "14.12.6"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα εἰς Συρίαν Ἀντωνίου παραγενομένου Κλεοπάτρα περὶ Κιλικίαν ἐντυχοῦσα δι’ ἔρωτος αὐτὸν ἐκεχείρωτο. καὶ δὴ πάλιν Ἰουδαίων ἑκατὸν οἱ δυνατώτατοι παραγίνονται πρὸς αὐτὸν κατηγοροῦντες Ἡρώδου καὶ τῶν περὶ αὐτὸν προστησάμενοι σφῶν τοὺς δεινοτάτους λέγειν. ἀντέλεγεν δὲ αὐτοῖς Μεσσάλας ὑπὲρ τῶν νεανίσκων παρόντος καὶ Ὑρκανοῦ, ὃς κηδεστὴς ἐτύγχανεν ἤδη γεγενημένος. ἀκροασάμενος δὲ ἀμφοτέρων Ἀντώνιος ἐπὶ Δάφνης πυνθάνεται Ὑρκανοῦ, πότεροι τοῦ ἔθνους ἄμεινον προΐστανται· φήσαντος δὲ τοὺς περὶ Ἡρώδην, Ἀντώνιος καὶ πάλαι οἰκείως ἔχων πρὸς αὐτοὺς διὰ τὴν πατρῴαν ξενίαν, ἣν ἡνίκα σὺν Γαβινίῳ παρῆν ἐπεποίητο πρὸς τὸν πατέρα αὐτῶν, τούτους μὲν ἀμφοτέρους τετράρχας καθίστησιν καὶ τὰ Ἰουδαίων αὐτοῖς ἐπιτρέπει πράγματα, γράφει δὲ καὶ γράμματα πεντεκαίδεκα τῶν ἀντιστασιαστῶν ἔδησεν, μέλλοντος δὲ καὶ κτείνειν αὐτοὺς παρῃτήσαντο οἱ περὶ Ἡρώδην.", "st": "14.13.1"}, {"sp": "N", "t": "Ἠρέμουν δ’ οὐδ’ οὕτως ἐπανελθόντες ἐκ τῆς πρεσβείας, ἀλλ’ ἀπήντων πάλιν Ἀντωνίῳ χίλιοι εἰς Τύρον ἐκεῖ δόξαντι ἀφικέσθαι. καὶ ὁ Ἀντώνιος πολλοῖς διεφθαρμένος ἤδη χρήμασιν ὑπό τε Ἡρώδου καὶ τοῦ ἀδελφοῦ αὐτοῦ τῷ κατὰ τόπον ἄρχοντι προσέταξεν κολάσαι τοὺς πρεσβευτὰς τῶν Ἰουδαίων νεωτέρων ἐπιθυμοῦντας πραγμάτων καὶ τοῖς περὶ Ἡρώδην συγκαθιστάναι τὴν ἀρχήν. ταχὺ δὲ Ἡρώδης, ἵδρυντο γὰρ ἐπὶ τῆς ψάμμου πρὸ τῆς πόλεως, προϊὼν ἀπιέναι παρεκελεύετο, συνῆν δ’ αὐτοῖς καὶ Ὑρκανός, ὡς μεγάλου κακοῦ εἰ προέλθοιεν εἰς φιλονεικίαν ἐσομένου. καὶ οἱ μὲν οὐκ ἐπείθοντο. παραχρῆμα δ’ ἐκδραμόντες Ῥωμαῖοι σὺν ἐγχειριδίοις τοὺς μὲν αὐτῶν ἀπέκτειναν, πλείους δὲ κατέτρωσαν, οἱ δὲ λοιποὶ διαφυγόντες ἐπ’ οἴκου ἡσύχαζον. τοῦ δὲ δήμου καταβοῶντος Ἡρώδου παροξυνθεὶς Ἀντώνιος τοὺς δεδεμένους ἀπέκτεινεν.", "st": "14.13.2"}, {"sp": "N", "t": "Δευτέρῳ δ’ ἔτει Συρίαν κατέσχον Πάκορός τε ὁ βασιλέως παῖς καὶ Βαζαφράνης σατράπης ὢν Πάρθων. τελευτᾷ δὲ καὶ Πτολεμαῖος ὁ Μενναίου καὶ τὴν ἀρχὴν ὁ παῖς αὐτοῦ Λυσανίας παραλαβὼν διαπράττεται φιλίαν πρὸς Ἀντίγονον τὸν Ἀριστοβούλου, πρὸς τοῦτο χρήσιμον τὸν σατράπην παραλαβὼν μέγα παρ’ αὐτῷ δυνάμενον. Ἀντίγονος δ’ ὑπισχνεῖτο χίλια τάλαντα καὶ πεντακοσίας γυναῖκας δώσειν Πάρθοις, εἰ τὴν ἀρχὴν Ὑρκανὸν ἀφελόμενοι παραδώσουσιν αὐτῷ καὶ τοὺς περὶ τὸν Ἡρώδην ἀνέλοιεν. οὐ μὴν ἔδωκεν· ἀλλ’ οἱ μὲν Πάρθοι διὰ τοῦτ’ ἐπὶ τὴν Ἰουδαίαν ἐστράτευσαν κατάγοντες Ἀντίγονον, Πάκορος μὲν διὰ τῆς παραθαλαττίου, ὁ δὲ σατράπης Βαζαφράνης διὰ τῆς μεσογείου. Τύριοι μὲν οὖν ἀποκλείουσι Πάκορον, Σιδώνιοι δὲ καὶ Πτολεμαεῖς ἐδέξαντο. ἴλην μέντοι Πάκορος ἱππέων εἰς τὴν Ἰουδαίαν ἐξέπεμψεν κατασκεψομένην τε τὰ κατὰ τὴν χώραν καὶ Ἀντιγόνῳ συμπράξουσαν, ἡγεμόνα τε ὁμώνυμον τοῦ βασιλέως οἰνοχόον. ἐκ δὲ τῶν περὶ Κάρμηλον τὸ ὄρος Ἰουδαίων πρὸς Ἀντίγονον ἐλθόντων καὶ συνεισβαλεῖν ἑτοίμως ἐχόντων, προσεδόκα δὲ τῆς χώρας μέρος τι λαβεῖν ὁ Ἀντίγονος, δρυμοὶ δὲ τὸ χωρίον καλεῖται, καί τινων ὑπαντιασάντων αὐτοὺς διεκπίπτουσιν εἰς Ἱεροσόλυμα οἱ ἄνθρωποι. προσγενομένων δέ τινων πολλοὶ συστραφέντες ἐπὶ τὰ βασίλεια ἧκον καὶ ταῦτα ἐπολιόρκουν. προσβοηθούντων δὲ τῶν περὶ Φασάηλον καὶ Ἡρώδην καὶ μάχης γενομένης κατὰ τὴν ἀγορὰν νικῶσιν οἱ νεανίσκοι τοὺς πολεμίους, καὶ συνδιώξαντες εἰς τὸ ἱερὸν πέμπουσιν ὁπλίτας τινὰς εἰς τὰς πλησίον οἰκίας φρουρήσοντας αὐτάς, οὓς ἐπαναστὰς ὁ δῆμος συμμάχων ὄντας ἐρήμους σὺν αὐτοῖς οἴκοις κατέπρησεν. ὑπὲρ μὲν οὖν τῆς ἀδικίας ταύτης Ἡρώδης μετ’ ὀλίγον τιμωρίαν παρὰ τῶν ἀντιστασιωτῶν λαμβάνει συμβαλὼν αὐτοῖς εἰς μάχην καὶ πολλοὺς αὐτῶν ἀποκτείνας.", "st": "14.13.3"}, {"sp": "N", "t": "Γινομένων δ’ ὁσημέραι ἀκροβολισμῶν αὐτοῖς ἀνέμενον οἱ πολέμιοι τὸν ἐκ τῆς χώρας ὄχλον εἰς τὴν καλουμένην πεντηκοστήν, ἑορτὴ δ’ ἐστίν, μέλλοντα ἥξειν. τῆς δ’ ἡμέρας ἐνστάσης πολλαὶ περὶ τὸ ἱερὸν ἀθροίζονται μυριάδες ἀνθρώπων ὡπλισμένων τε καὶ ἀνόπλων. κατεῖχον δὲ τὴν πόλιν καὶ τὸ ἱερὸν οἱ παρόντες πλὴν τῶν περὶ τὰ βασίλεια· ταῦτα γὰρ σὺν ὀλίγοις στρατιώταις οἱ περὶ Ἡρώδην ἐφρούρουν. Φασάηλος μὲν οὖν τὸ τεῖχος ἐφύλασσεν, Ἡρώδης δὲ λόχον ἔχων ἐπέξεισιν τοῖς πολεμίοις κατὰ τὸ προάστειον, καὶ καρτερῶς μαχεσάμενος πολλάς τε μυριάδας τρέπει, τῶν μὲν εἰς τὴν πόλιν φευγόντων, τῶν δ’ εἰς τὸ ἱερόν, ἔστιν δ’ ὧν εἰς τὸ ἔξω χαράκωμα· ἦν γάρ τι αὐτόθι· παρεβοήθει δὲ καὶ Φασάηλος. Πάκορος δ’ ὁ Πάρθων στρατηγὸς σὺν ἱππεῦσιν ὀλίγοις Ἀντιγόνου δεηθέντος εἰς τὴν πόλιν ἔρχεται, λόγῳ μὲν ὡς καταπαύσειεν τὴν στάσιν, τὸ δ’ ἀληθὲς συμπράξων ἐκείνῳ τὴν ἀρχήν. Φασαήλου δ’ ὑπαντήσαντος καὶ δεξαμένου ξενίᾳ Πάκορος πείθει πρεσβεύσασθαι παρὰ Βαζαφράνην αὐτόν, δόλον τινὰ τοῦτον συντιθείς. καὶ Φασάηλος οὐδὲν ὑπιδόμενος πείθεται μὴ ἐπαινοῦντος Ἡρώδου τοῖς πραττομένοις διὰ τὸ τῶν βαρβάρων ἄπιστον, ἀλλὰ καὶ Πακόρῳ καὶ τοῖς ἥκουσιν ἐπιτίθεσθαι κελεύοντος.", "st": "14.13.4"}, {"sp": "N", "t": "Ὤιχοντο δ’ οὖν πρεσβεύοντες Ὑρκανός τε καὶ Φασάηλος, Πάκορος δὲ καταλιπὼν Ἡρώδῃ διακοσίους ἱππεῖς καὶ δέκα τῶν λεγομένων ἐλευθέρων προύπεμψεν αὐτούς. γενομένοις δ’ ἐν τῇ Γαλιλαίᾳ μεθ’ ὅπλων ὑπαντῶσιν οἱ ταύτῃ τῶν πολεμίων ὑφεστῶτες. καὶ Βαζαφράνης τὸ μὲν πρῶτον αὐτοὺς ὑποδέχεται προθύμως καὶ δῶρα δίδωσιν, ἔπειτα ἐπεβούλευεν. πλησίον δὲ μετὰ ἱππέων ὑπὲρ θαλάττης οἱ περὶ Φασάηλον κατάγονται καὶ ἐνταῦθ’ ἀκούσαντες, ὡς Ἀντίγονος ὑπόσχοιτο χίλια τάλαντα καὶ γυναῖκας πεντακοσίας τοῖς Πάρθοις κατ’ αὐτῶν, δι’ ὑποψίας εἶχον ἤδη τοὺς βαρβάρους. οὐ μὴν ἀλλὰ καὶ νύκτωρ ἐπιβουλευομένους αὐτοὺς ἀπήγγειλέν τις φυλακῆς αὐτοὺς ἐκ τἀφανοῦς περιισταμένης, καὶ συνελήφθησαν ἄν, εἰ μὴ περιέμενον ἕως [ἂν] οἱ περὶ Ἱεροσόλυμα Πάρθοι Ἡρώδην συλλάβοιεν, μὴ προανῃρημένων τούτων ἐκεῖνος αἰσθόμενος διαφύγοι. καὶ ἦν ταῦθ’ οὕτως ἔχοντα καὶ οἱ φύλακες αὐτῶν ἑωρῶντο. Φασαήλῳ μὲν οὖν παρῄνουν τινὲς εὐθὺς ἀφιππάσασθαι καὶ μὴ περιμένειν, μάλιστα μέντοι πρὸς ταῦτα αὐτὸν Ὀφέλλιος ἐνῆγεν, ὃς ἀκηκόει παρὰ Σαραμάλλα τοῦ πλουσιωτάτου τῶν ἐν Συρίᾳ τότε καὶ πλοῖα πρὸς τὴν φυγὴν ὑπισχνεῖτο· ἐγγὺς γὰρ ἦν ἡ θάλασσα. ὁ δὲ Ὑρκανὸν ἀπολιπεῖν οὐκ ἠξίου οὐδὲ παρακινδυνεύειν τἀδελφῷ· προσελθὼν δὲ πρὸς τὸν Βαζαφράνην οὐ δίκαια ποιεῖν αὐτὸν ἔλεγεν τοιαῦτα βουλευόμενον περὶ αὐτῶν· χρημάτων τε γὰρ δεομένῳ πλείονα ἔσεσθαι παρ’ αὐτοῦ ὧν Ἀντίγονος δίδωσιν, καὶ ἄλλως δεινὸν εἶναι πρὸς αὐτὸν ἐπὶ πίστει συνελθόντας πρεσβευτὰς ἀποκτεῖναι μηδὲν ἀδικοῦντας. ὁ δὲ βάρβαρος ταῦτα λέγοντος ὤμνυεν μηδὲν ἀληθὲς εἶναι τῶν ὑπονοουμένων, ἀλλὰ ψευδεῖς αὐτὸν ὑποψίας ταράξαι, ἀπῄει τε πρὸς Πάκορον.", "st": "14.13.5"}, {"sp": "N", "t": "Οἰχομένου δὲ τῶν Πάρθων ἐδέσμευόν τινες Ὑρκανὸν καὶ Φασάηλον πολλὰ τῆς ἐπιορκίας κακίζοντα τοὺς Πάρθους. ὁ δ’ ἐπὶ τὸν Ἡρώδην ἀπεσταλμένος εὐνοῦχος ἐντολὰς εἶχεν προαγαγὼν αὐτὸν ἔξω τοῦ τείχους συλλαμβάνειν. ἔτυχον δὲ ἄγγελοι παρὰ Φασαήλου πεμφθέντες ἐπὶ δηλώσει τῆς τῶν Πάρθων ἀπιστίας, οὓς τῶν πολεμίων συλλαβόντων γνοὺς Ἡρώδης πρόσεισι Πακόρῳ καὶ Πάρθων τοῖς δυνατοῖς ὡς οὖσιν τῶν ἄλλων δεσπόταις. οἱ δὲ τὸ πᾶν εἰδότες ὑπεκρίνοντο δολερῶς καὶ δεῖν αὐτὸν ἔφασαν μετὰ σφῶν ἐξελθόντα πρὸ τοῦ τείχους ὑπαντᾶν τοῖς τὰ γράμματα κομίζουσιν· οὐδέπω γὰρ αὐτοὺς εἰλῆφθαι πρὸς τῶν ἀντιστασιωτῶν, ἥκειν μέντοι δηλοῦντας ὅσα κατορθώσειε Φασάηλος. τούτοις Ἡρώδης οὐκ ἐπίστευσεν· ἀκηκόει γὰρ τὴν σύλληψιν τἀδελφοῦ παρ’ ἑτέρων· καὶ παραινούσης δὲ τῆς Ὑρκανοῦ θυγατρός, ἧς ἐγγεγύητο τὴν παῖδα, ἔτι μᾶλλον ὑπώπτευε τοὺς Πάρθους. οἱ μὲν οὖν ἄλλοι ταύτῃ οὐ προσεῖχον, αὐτὸς δ’ ἐπίστευεν λίαν ἔμφρονι γυναικί.", "st": "14.13.6"}, {"sp": "N", "t": "Βουλευομένων δὲ τῶν Πάρθων, τί χρὴ ποιεῖν, οὐ γὰρ ἤρεσκεν αὐτοῖς ἐκ τοῦ φανεροῦ ἐπιχειρεῖν ἀνδρὶ τηλικούτῳ, καὶ ὑπερθεμένων εἰς τὴν ὑστεραίαν, ἐν τοιαύταις ταραχαῖς Ἡρώδης γενόμενος καὶ μᾶλλον οἷς ἤκουσεν περὶ τἀδελφοῦ καὶ τῆς Πάρθων ἐπιβουλῆς ἢ τοῖς ἐναντίοις προστιθέμενος, ἑσπέρας ἐπελθούσης ἔγνω ταύτῃ πρὸς φυγὴν χρήσασθαι καὶ μὴ διαμέλλειν ὡς ἐπ’ ἀδήλοις τοῖς ἀπὸ τῶν πολεμίων κινδύνοις. ἄρας οὖν σὺν οἷς εἶχεν ὁπλίταις καὶ τὰς γυναῖκας τοῖς ὑποζυγίοις ἐπιθέμενος μητέρα τε αὐτοῦ καὶ ἀδελφὴν καὶ ἣν ἔμελλεν ἄξεσθαι πρὸς γάμον Ἀλεξάνδρου θυγατέρα τοῦ Ἀριστοβούλου παιδὸς τήν τε ταύτης μητέρα, Ὑρκανοῦ δ’ ἦν θυγάτηρ, καὶ τὸν νεώτατον ἀδελφὸν τήν τε θεραπείαν πᾶσαν καὶ τὸν ἄλλον ὄχλον τὸν σὺν αὐτοῖς, ἐδίωκεν τὴν ἐπὶ Ἰδουμαίας λαθὼν τοὺς πολεμίους. ὧν οὐδεὶς ἂν οὕτως στερρὸς τὴν φύσιν εὑρέθη, ὃς τότε παρὼν τοῖς πραττομένοις οὐκ ἂν ᾤκτειρεν αὐτοὺς τῆς τύχης, γυναίων ἐπαγομένων νήπια τέκνα καὶ μετὰ δακρύων καὶ οἰμωγῆς ἀπολειπουσῶν τὴν πατρίδα καὶ φίλους ἐν δεσμοῖς καὶ περὶ αὐτῶν οὐδὲν ἔτι χρηστὸν προσδεχομένων.", "st": "14.13.7"}, {"sp": "N", "t": "Ἀλλ’ Ἡρώδης ἐπάνω τῆς ἐκ τοῦ δεινοῦ πληγῆς τὸ φρόνημα ποιησάμενος αὐτός τε ἦν πρὸς τὸ δεινὸν εὔψυχος καὶ παριὼν κατὰ τὴν ὁδὸν θαρρεῖν ἕκαστον παρεκελεύετο καὶ μὴ παρέχειν αὑτὸν ἔκδοτον τῇ λύπῃ· τοῦτο γὰρ αὐτοὺς βλάπτειν πρὸς τὴν φυγήν, ἐν ᾗ τὴν σωτηρίαν αὐτοῖς μόνῃ κεῖσθαι συμβέβηκεν. καὶ οἱ μὲν ὡς Ἡρώδης παρῄνει φέρειν τὴν συμφορὰν ἐπειρῶντο. μικροῦ δ’ αὑτὸν διεχρήσατο τοῦ ζεύγους περιτραπέντος καὶ τῆς μητρὸς αὐτῷ κινδυνευσάσης ἀποθανεῖν, διά τε τὸ ἐπ’ αὐτῇ πάθος καὶ διὰ τὸ φοβεῖσθαι, μὴ καταλάβωσιν αὐτὸν οἱ πολέμιοι διώκοντες τριβῆς περὶ τὸ πταῖσμα γενομένης. σπασάμενον γοῦν αὐτὸν τὸ ξίφος καὶ μέλλοντα πλήττειν αὑτὸν κατέσχον οἱ παρόντες, τῷ τε πλήθει κατισχύσαντες καὶ ὡς οὐκ ἐχρῆν αὐτοὺς ἐγκαταλιπεῖν ἐπὶ τοῖς ἐχθροῖς ἐσομένους λέγοντες· οὐ γὰρ εἶναι γενναίου τῶν δεινῶν αὑτὸν ἐλευθερώσαντα τοὺς φίλους ἐν αὐτοῖς ὑπεριδεῖν. βιασθεὶς οὖν ἀποσχέσθαι τοῦ κατ’ αὐτὸν τολμήματος αἰδοῖ τε τῶν λεγομένων καὶ πλήθει τῶν οὐκ ἐπιτρεπόντων αὐτοῦ τῇ χειρὶ διακονεῖν οἷς ἐντεθύμητο, ἀνακτησάμενος τὴν μητέρα καὶ θεραπείας ἧς ὁ καιρὸς ἤπειγεν ἀξιώσας ἐβάδιζεν τὴν προκειμένην ὁδὸν συντονωτέραν ποιούμενος τὴν πορείαν εἰς Μάσαδαν τὸ ἔρυμα. πολλὰς δὲ μάχας πρὸς τοὺς ἐπεξελθόντας καὶ διώκοντας τῶν Πάρθων μαχεσάμενος πάσας ἐνίκησεν.", "st": "14.13.8"}, {"sp": "N", "t": "Ἔμεινε δ’ αὐτῷ παρὰ τὴν φυγὴν οὐδὲ τὰ παρὰ τῶν Ἰουδαίων ἀσφαλῆ, συνεπέθεντο δὲ καὶ οὗτοι γενομένοις ἀπὸ σταδίων ἑξήκοντα τῆς πόλεως προσβάλλοντές τε καὶ εἰς χεῖρας ἐρχόμενοι κατὰ τὴν ὁδόν. οὓς δὴ καὶ τρεψάμενος καὶ κρατήσας οὐχ ὡς ἐν ἀπορίᾳ καὶ ἀνάγκῃ τις τοιαύτῃ καθεστώς, ἀλλ’ ὡς κάλλιστα καὶ μετὰ πολλοῦ τοῦ περιόντος πρὸς πόλεμον παρεσκευασμένος, ἐν ἐκείνῳ τῷ χωρίῳ, ἐν ᾧ τῶν Ἰουδαίων ἐκράτησε, μετὰ χρόνον βασιλεύσας ἔκτισε καὶ βασίλειον κατεσκεύασεν ἀξιολογώτατον καὶ πόλιν περὶ αὐτὸ Ἡρωδίαν προσαγορεύσας. γενομένῳ δὲ τῆς Ἰδουμαίας ἐν Θρήσᾳ χωρίῳ οὕτω καλουμένῳ ὁ ἀδελφὸς Ἰώσηπος ὑπήντησεν καὶ βουλὴν περὶ τῶν ὅλων ἦγε, τί χρὴ ποιεῖν, πολλοῦ μὲν πλήθους ἐπαγομένου καὶ δίχα τῶν μισθοφορούντων αὐτοῖς, τοῦ δὲ χωρίου τῆς Μεσάδας, εἰς ὃ προύκειτο συμφυγεῖν ἐλάττονος ὄντος ὑποδέξασθαι τοσοῦτον ὄχλον. τοὺς μὲν οὖν πλείους ἀπέλυσεν ὑπὲρ ἐννέα χιλιάδας ὄντας ἄλλον ἀλλαχῆ κελεύσας διὰ τῆς Ἰδουμαίας σώζειν αὑτούς, δοὺς ἐφόδια· ὅσοι δ’ ἦσαν κοῦφοι καὶ τοὺς ἀναγκαιοτάτους ἀναλαβὼν εἰς τὸ ἔρυμα παραγίνεται καὶ καταθέμενος αὐτόθι τάς τε γυναῖκας καὶ τοὺς ἑπομένους, ἦσαν δὲ ὡς ὀκτακόσιοι, σίτου τε ὄντος ἐν τῷ χωρίῳ καὶ ὕδατος καὶ τῶν ἄλλων ἐπιτηδείων ἁπάντων διαρκούντως αὐτοῖς ἐξώρμησεν αὐτὸς ἐπὶ Πέτρας τῆς Ἀραβίας. ἅμα δ’ ἡμέρᾳ τὰ μὲν ἄλλα πάντα τῶν Ἱεροσολύμων διήρπαζον οἱ Πάρθοι καὶ τὸ βασίλειον, μόνων δὲ ἀπείχοντο τῶν Ὑρκανοῦ χρημάτων· τὰ δ’ ἦν ὡς τριακόσια τάλαντα. πολλὰ δὲ τῶν Ἡρώδου διέφυγεν καὶ μάλισθ’ ὅσα προκομισθῆναι κατὰ προμήθειαν τἀνδρὸς εἰς τὴν Ἰδουμαίαν ἐφθάκει. τὰ μὲν οὖν κατὰ τὴν πόλιν οὐκ ἀπέχρησε τοῖς Πάρθοις, ἀλλὰ καὶ τὴν χώραν αὐτῶν ἐξιόντες ἐκάκουν καὶ Μάρισάν τε πόλιν δυνατὴν ἀνέστησαν.", "st": "14.13.9"}, {"sp": "N", "t": "Καὶ Ἀντίγονος μὲν οὕτως καταχθεὶς εἰς τὴν Ἰουδαίαν ὑπὸ τοῦ Πάρθων βασιλέως Ὑρκανὸν καὶ Φασάηλον δεσμώτας παραλαμβάνει. σφόδρα δ’ ἦν ἄθυμος τῶν γυναικῶν αὐτὸν διαφυγουσῶν, ἃς τοῖς πολεμίοις ἐνεθυμεῖτο δώσειν, τοῦτον αὐτοῖς τὸν μισθὸν μετὰ τῶν χρημάτων ὑποσχόμενος. φοβούμενος δὲ τὸν Ὑρκανόν, μὴ τὸ πλῆθος αὐτῷ τὴν βασιλείαν ἀποκαταστήσῃ, παραστάς, ἐτηρεῖτο δὲ ὑπὸ τῶν Πάρθων, ἐπιτέμνει αὐτοῦ τὰ ὦτα πραγματευόμενος μηκέτ’ αὖθις εἰς αὐτὸν ἀφικέσθαι τὴν ἀρχιερωσύνην διὰ τὸ λελωβῆσθαι, τοῦ νόμου τῶν ὁλοκλήρων εἶναι τὴν τιμὴν ἀξιοῦντος. Φασάηλον δ’ ἄν τις θαυμάσειε τῆς εὐψυχίας, ὃς γνοὺς αὑτὸν ἀποσφάττεσθαι μέλλοντα οὐχὶ τὸν θάνατον ἡγήσατο δεινόν, τὸ δ’ ὑπ’ ἐχθροῦ τοῦτο παθεῖν πικρότατον καὶ αἴσχιστον ὑπολαβών, τὰς χεῖρας οὐκ ἔχων ἐλευθέρας ὑπὸ δεσμῶν πρὸς ἀναίρεσιν πέτρᾳ προσαράξας τὴν κεφαλὴν ἐξήγαγε μὲν αὑτὸν ὡς ἐδόκει κάλλιστα τοῦ ζῆν παρὰ τοιαύτην ἀπορίαν, τῆς δ’ ἐξουσίας τοῦ κτεῖναι πρὸς ἡδονὴν αὐτὸν ἀφείλετο τὸν πολέμιον. λέγουσι δ’, ὡς τραύματος μεγάλου γενομένου φαρμάκοις αὐτὸν ὑποπέμψας ἰατροὺς Ἀντίγονος ὡς ἐπὶ θεραπείᾳ διέφθειρεν θανασίμοις χρησαμένων εἰς τὸ τραῦμα. πρὸ μέντοι τοῦ τελέως ἀφεῖναι τὴν ψυχὴν ὁ Φασάηλος ἀκούσας παρά τινος γυναίου τὸν ἀδελφὸν Ἡρώδην τοὺς πολεμίους διαπεφευγότα σφόδρα τὴν τελευτὴν εὐθύμως ὑπέμεινεν καταλιπὼν τὸν ἐκδικῆσαι τὸν θάνατον αὐτοῦ καὶ τοὺς ἐχθροὺς τιμωρήσασθαι δυνάμενον.", "st": "14.13.10"}, {"sp": "N", "t": "Ἡρώδην δὲ τὸ μέγεθος τῶν περιεστηκότων αὐτὸν κακῶν οὐ κατέπληττεν, ἀλλ’ ἐποίει δεινὸν εὑρίσκειν ἐπιβολὰς ἔργων παραβόλων. πρὸς γὰρ Μάλιχον τὸν Ἀράβων βασιλέα πολλὰ πρόσθεν εὐεργετημένον ἀπῄει τὴν ἀμοιβὴν κομιούμενος, ὅτε μάλιστα ἐδεῖτο, χρήματα ληψόμενος εἴτε δάνειον εἴτε δωρεὰν ὡς ἂν πολλῶν παρ’ αὐτοῦ τετυχηκότος. οὐ γὰρ εἰδὼς τὰ κατὰ τὸν ἀδελφὸν ἔσπευδεν λυτρώσασθαι παρὰ τῶν πολεμίων αὐτὸν λύτρον ὑπὲρ αὐτοῦ καταβαλὼν νόμισμα ἕως τριακοσίων ταλάντων. ἐπήγετο δὲ καὶ τὸν Φασαήλου παῖδα διὰ ταύτην τὴν αἰτίαν ἑπταετῆ τυγχάνοντα, παρασχὼν αὐτὸν ἐνέχυρον τοῖς Ἄραψιν. ἀγγέλων δ’ αὐτὸν ὑπαντησάντων παρὰ τοῦ Μαλίχου, δι’ ὧν ἐκέλευσεν αὐτὸν ἀναχωρεῖν· παρηγγελκέναι γὰρ αὐτῷ Πάρθους Ἡρώδην μὴ δέχεσθαι· ταύτῃ δ’ ἐχρῆτο προφάσει ὑπὲρ τοῦ μὴ ἀποδοῦναι τὰ χρέα καὶ τῶν ἐν τέλει παρὰ τοῖς Ἄραψιν εἰς τοῦτο ἐναγόντων, ὅπως ἀποστερήσωσιν τὰς παρακαταθήκας, ἃς παρὰ Ἀντιπάτρου λαβόντες ἔτυχον, ἀπεκρίνατο αὐτοῖς οὐδὲν ἐνοχλήσων ἀφικνεῖσθαι πρὸς αὐτούς, μόνον δὲ διαλεξόμενος περὶ τῶν ἀναγκαιοτάτων αὐτῷ πραγμάτων.", "st": "14.14.1"}, {"sp": "N", "t": "Ἔπειτα δόξαν ἀναχωρεῖν ἀπῄει μάλα σωφρόνως τὴν ἐπ’ Αἰγύπτου. καὶ τότε μὲν ἔν τινι ἱερῷ κατάγεται, καταλελοίπει γὰρ αὐτόθι πολλοὺς τῶν ἑπομένων, τῇ δ’ ὑστεραίᾳ παραγενόμενος εἰς Ῥινοκούρουρα ἐκεῖ καὶ τὰ περὶ τὸν ἀδελφὸν ἤκουσεν. Μαλίχῳ δὲ μεταγνόντι καὶ μεταθέοντι τὸν Ἡρώδην οὐδὲν τούτου περισσότερον ἐγένετο· πορρωτάτω γὰρ ἦν ἤδη σπεύδων τὴν ἐπὶ Πηλουσίου. ἐπεὶ δ’ αὐτὸν ἐλθόντα νῆες ὁρμοῦσαι αὐτόθι εἶργον τοῦ ἐπ’ Ἀλεξανδρείας πλοῦ, τοῖς ἡγεμόσιν ἐντυγχάνει, ὑφ’ ὧν κατ’ αἰδῶ καὶ πολλὴν ἐντροπὴν προπεμφθεὶς εἰς τὴν πόλιν, ὑπὸ Κλεοπάτρας κατείχετο. πεῖσαι μέντοι μένειν αὐτὸν οὐκ ἠδυνήθη εἰς Ῥώμην ἐπειγόμενον χειμῶνός τε ὄντος καὶ τῶν κατὰ τὴν Ἰταλίαν ἐν ταραχῇ καὶ σάλῳ πολλῷ δηλουμένων.", "st": "14.14.2"}, {"sp": "N", "t": "Ἀναχθεὶς οὖν ἐκεῖθεν ἐπὶ Παμφυλίας καὶ χειμῶνι σφοδρῷ περιπεσὼν μόλις εἰς Ῥόδον διασώζεται φορτίων ἀποβολῆς γενομένης. καὶ δύο μὲν ἐνταυθοῖ τῶν φίλων αὐτῷ συνήντησαν, Σαππῖνός τε καὶ Πτολεμαῖος. εὑρὼν δὲ τὴν πόλιν ὑπὸ τοῦ πρὸς Κάσσιον πολέμου κεκακωμένην οὐδ’ ἐν ἀπόροις ὢν εὖ ποιεῖν αὐτὴν ὤκνησεν, ἀλλὰ καὶ παρὰ δύναμιν αὐτὴν ἀνεκτᾶτο. τριήρη τε κατασκευάσας, καὶ ἀναχθεὶς ἐκεῖθεν σὺν τοῖς φίλοις ἐπ’ Ἰταλίας εἰς Βρεντέσιον κατάγεται. κἀκεῖθεν εἰς Ῥώμην ἀφικόμενος πρῶτον μὲν Ἀντωνίῳ φράζει τὰ συμβάντα αὐτῷ κατὰ τὴν Ἰουδαίαν, καὶ πῶς ὁ ἀδελφὸς αὐτοῦ Φασάηλος ὑπὸ Πάρθων ἀπόλοιτο συλληφθεὶς καὶ Ὑρκανὸς ὑπ’ αὐτῶν αἰχμάλωτος ἔχοιτο, καὶ ὡς Ἀντίγονον καταστήσειαν βασιλέα χρήματα δώσειν ὑποσχόμενον χίλια τάλαντα καὶ γυναῖκας πεντακοσίας, αἳ τῶν πρώτων κἀκ τοῦ γένους τοῦ αὐτῶν ἔμελλον ἔσεσθαι, καὶ ὅτι ταύτας νυκτὸς ἐκκομίσειεν καὶ διαφύγοι τὰς τῶν ἐχθρῶν χεῖρας πολλὰς ὑπομείνας ταλαιπωρίας. εἶτ’ ἐπιδιακινδυνεύειν † αὐτῷ τοὺς οἰκείους πολιορκουμένους πλεύσειέ τε διὰ χειμῶνος καὶ παντὸς καταφρονήσειε δεινοῦ σπεύδων ἐπὶ τὰς ἐλπίδας τὰς παρ’ αὐτοῦ καὶ τὴν μόνην βοήθειαν.", "st": "14.14.3"}, {"sp": "N", "t": "Ἀντώνιον δ’ οἶκτος εἰσέρχεται τῆς Ἡρώδου μεταβολῆς, καὶ τῷ κοινῷ χρησάμενος λογισμῷ περὶ τῶν ἐν ἀξιώματι τοσούτῳ καθεστώτων ὡς κἀκείνων ὑποκειμένων τῇ τύχῃ, τὰ μὲν κατὰ μνήμην τῆς Ἀντιπάτρου ξενίας, τὰ δὲ καὶ ὑπὸ χρημάτων ὧν αὐτῷ δώσειν Ἡρώδης, εἰ γένοιτο βασιλεύς, ὑπέσχετο καθὼς καὶ πρότερον τετράρχης ἀπεδέδεικτο, πολὺ μέντοι μᾶλλον διὰ τὸ πρὸς Ἀντίγονον μῖσος, στασιαστὴν γὰρ καὶ Ῥωμαίοις ἐχθρὸν αὐτὸν ὑπελάμβανεν, πρόθυμος ἦν οἷς Ἡρώδης παρεκάλει συλλαμβάνεσθαι. Καῖσαρ μὲν οὖν καὶ διὰ τὰς Ἀντιπάτρου στρατείας, ἃς κατ’ Αἴγυπτον αὐτοῦ τῷ πατρὶ συνδιήνεγκεν, καὶ τὴν ξενίαν καὶ τὴν ἐν ἅπασιν εὔνοιαν, καὶ χαριζόμενος δὲ Ἀντωνίῳ σφόδρα περὶ τὸν Ἡρώδην ἐσπουδακότι, πρὸς τὴν ἀξίωσιν καὶ τὴν ὧν ἐβούλετο Ἡρώδης συνεργίαν ἑτοιμότερος ἦν. συναγαγόντες δὲ τὴν βουλὴν Μεσσάλας καὶ μετ’ αὐτὸν Ἀτρατῖνος, παραστησάμενοι τὸν Ἡρώδην τάς τε τοῦ πατρὸς εὐεργεσίας αὐτοῦ διεξῄεσαν καὶ ἣν αὐτὸς πρὸς Ῥωμαίους εἶχεν εὔνοιαν ὑπεμίμνησκον, κατηγοροῦντες ἅμα καὶ πολέμιον ἀποφαίνοντες τὸν Ἀντίγονον οὐκ ἐξ ὧν τὸ πρῶτον προσέκρουσεν αὐτοῖς μόνον, ἀλλ’ ὅτι καὶ παρὰ Πάρθων τὴν ἀρχὴν λάβοι Ῥωμαίους ὑπεριδών. τῆς δὲ βουλῆς ἐπὶ τούτοις παρωξυμμένης παρελθὼν Ἀντώνιος ἐδίδασκεν αὐτούς, ὡς καὶ πρὸς τὸν κατὰ Πάρθων πόλεμον Ἡρώδην βασιλεύειν συμφέρει. καὶ δόξαν τοῦτο πᾶσι ψηφίζονται.", "st": "14.14.4"}, {"sp": "N", "t": "Καὶ τοῦτο τὸ μέγιστον ἦν τῆς Ἀντωνίου περὶ τὸν Ἡρώδην σπουδῆς, ὅτι μὴ μόνον αὐτῷ τὴν βασιλείαν οὐκ ἐλπίζοντι περιεποιήσατο, οὐ γὰρ πρὸς αὐτὸν ἀνέβη ταύτην αἰτησόμενος, οὐ γὰρ ἐνόμιζεν αὐτῷ τοὺς Ῥωμαίους παρέξειν τοῖς ἐκ τοῦ γένους ἔθος ἔχοντας αὐτὴν διδόναι, ἀλλὰ διὰ τὸ τῷ τῆς γυναικὸς ἀδελφῷ λαβεῖν ἀξιώσων Ἀλεξάνδρῳ υἱωνῷ τυγχάνοντι πρὸς μὲν πατρὸς Ἀριστοβούλου πρὸς δὲ μητρὸς Ὑρκανοῦ, ἀλλ’ ὅτι καὶ ἑπτὰ ταῖς πάσαις ἡμέραις παρέσχεν αὐτῷ τυχόντι τῶν οὐδὲ προσδοκηθέντων ἀπελθεῖν ἐκ τῆς Ἰταλίας. τοῦτον μὲν οὖν τὸν νεανίσκον Ἡρώδης ἀπέκτεινεν, ὡς κατὰ καιρὸν δηλώσομεν· λυθείσης δὲ τῆς βουλῆς μέσον ἔχοντες Ἡρώδην Ἀντώνιος καὶ Καῖσαρ ἐξῄεσαν προαγόντων ἅμα ταῖς ἄλλαις ἀρχαῖς τῶν ὑπάτων θύσοντές τε καὶ τὸ δόγμα καταθησόμενοι εἰς τὸ Καπετώλιον. ἑστιᾷ δὲ τὴν πρώτην ἡμέραν τῆς βασιλείας Ἀντώνιος. καὶ ὁ μὲν οὕτως τὴν βασιλείαν παραλαμβάνει τυχὼν αὐτῆς ἐπὶ τῆς ἑκατοστῆς καὶ ὀγδοηκοστῆς καὶ τετάρτης ὀλυμπιάδος ὑπατεύοντος Γναίου Δομετίου Καλβίνου τὸ δεύτερον καὶ Γαΐου Ἀσινίου Πωλίωνος.", "st": "14.14.5"}, {"sp": "N", "t": "Τοῦτον δὲ ἅπαντα τὸν χρόνον Ἀντίγονος ἐπολιόρκει τοὺς ἐν Μασάδα, τῶν μὲν ἄλλων ἐπιτηδείων αὐτοῖς ὑπαρχόντων, μόνου δὲ σπανίζοντος ὕδατος, ὡς διὰ τοῦτο καὶ τὸν ἀδελφὸν τὸν Ἡρώδου Ἰώσηπον σὺν διακοσίοις τῶν οἰκείων ἀποδρᾶναι βουλεύσασθαι πρὸς Ἄραβας· ἀκηκόει γὰρ ὡς Μάλχος τῶν εἰς Ἡρώδην ἁμαρτημάτων μετανοεῖ. κατέσχε δ’ αὐτὸν ὕσας διὰ τῆς νυκτὸς ὁ θεός· τῶν γὰρ ἐκδοχείων πλησθέντων τοῦ ὕδατος οὐκέτι τῆς φυγῆς ἐδεῖτο, ἀλλὰ τεθαρσηκότες ἤδη καὶ πλέον ἢ κατὰ τὴν εὐπορίαν τοῦ σπανίζοντος, ὡς ἐκ θεοῦ προνοίας ταύτης αὐτοῖς γεγενημένης, ἐπεξιόντες καὶ συμπλεκόμενοι τοῖς περὶ τὸν Ἀντίγονον τοῖς μὲν φανερῶς, τοῖς δὲ καὶ λάθρα, πολλοὺς αὐτῶν διέφθειραν. κἀν τούτῳ Βεντίδιος ὁ Ῥωμαίων στρατηγὸς πεμφθεὶς ἐκ Συρίας ὥστε Πάρθους ἀνείργειν, μετ’ ἐκείνους εἰς τὴν Ἰουδαίαν παρέβαλεν τῷ λόγῳ μὲν Ἰωσήπῳ συμμαχήσων, τὸ δ’ ὅλον ἦν αὐτῷ στρατήγημα χρήματα παρ’ Ἀντιγόνου λαβεῖν· ἔγγιστα γοῦν Ἱεροσολύμων στρατοπεδευόμενος ἀποχρώντως ἠργυρίσατο τὸν Ἀντίγονον. καὶ αὐτὸς μὲν ἀνεχώρησεν σὺν τῇ πλείονι δυνάμει, ἵνα δὲ μὴ κατάφωρον γένηται τὸ λῆμμα, Σίλωνα μετὰ μέρους τινὸς τῶν στρατιωτῶν κατέλιπεν, ὃν καὶ αὐτὸν ἐθεράπευεν Ἀντίγονος, ὅπως μηδὲν ἐνοχλοίη, προσδοκῶν καὶ πάλιν αὐτῷ Πάρθους ἐπαμυνεῖν.", "st": "14.14.6"}, {"sp": "N", "t": "Ἡρώδης δ’ ἐκ τῆς Ἰταλίας ἤδη καταπεπλευκὼς εἰς Πτολεμαΐδα καὶ συναγηοχὼς δύναμιν οὐκ ὀλίγην ξένων τε ἅμα καὶ ὁμοφύλων ἤλαυνε διὰ τῆς Γαλιλαίας ἐπὶ τὸν Ἀντίγονον. συνελάμβανον δ’ αὐτῷ Σίλων τε καὶ Βεντίδιος πεισθέντες ὑπὸ Δελλίου συγκατάγειν Ἡρώδην τοῦ πεμφθέντος ὑπ’ Ἀντωνίου. Βεντίδιος μὲν οὖν ἐτύγχανεν τὰς ταραχὰς τὰς διὰ Πάρθους ἐν ταῖς πόλεσιν οὔσας καθιστάμενος, Σίλων δ’ ἐν Ἰουδαίᾳ χρήμασιν ὑπ’ Ἀντιγόνου διεφθαρμένος. Ἡρώδῃ μέντοι προϊόντι καθ’ ἑκάστην ἡμέραν ἡ δύναμις ηὔξετο καὶ πᾶσα Γαλιλαία πλὴν ὀλίγων αὐτῷ προστέθειτο. ὡρμηκότα δ’ αὐτὸν ἐπὶ τοὺς ἐν Μεσάδα, ἀναγκαῖον γὰρ ἦν τὸ σῶσαι τοὺς ἐν τῷ φρουρίῳ πολιορκουμένους συγγενεῖς ὄντας, ἐμποδὼν Ἰόππη γίνεται· πολεμίαν γὰρ οὖσαν αὐτὴν ἐχρῆν ἐξελεῖν πρότερον, ὅπως μηδὲν ὑπολείπηται κατὰ νώτου τοῖς ἐχθροῖς ἔρυμα χωροῦντος ἐπὶ Ἱεροσολύμων. ποιησαμένου δὲ καὶ Σίλωνος ταύτην πρόφασιν τῆς ἀπαναστάσεως καὶ τῶν Ἰουδαίων διωκόντων αὐτὸν Ἡρώδης μετ’ ὀλίγου στίφους ἐπέξεισιν καὶ τρέπεται μὲν τοὺς Ἰουδαίους, Σίλωνα δὲ σώζει κακῶς ἀμυνόμενον, ἑλών τε τὴν Ἰόππην ἔσπευδεν ῥυσόμενος τοὺς ἐν Μασάδα οἰκείους. τῶν δ’ ἐπιχωρίων οἱ μὲν αὐτῷ διὰ τὴν πατρῴαν προσεχώρουν φιλίαν, οἱ δὲ διὰ τὴν αὐτοῦ δόξαν, ἄλλοι δὲ κατ’ ἀμοιβὴν τῆς παρ’ ἀμφοτέρων εὐεργεσίας, οἱ πλείους δὲ διὰ τὰς ἐλπίδας, ἃς ὡς ἐπὶ βασιλεῖ βεβαίῳ τὸ λοιπὸν εἶχον.", "st": "14.15.1"}, {"sp": "N", "t": "Ἤθροιστο δὴ δύναμις βαρεῖα, καὶ προϊόντος Ἀντίγονος τῶν παρόδων τοὺς ἐπιτηδείους τόπους ἐνέδραις καὶ λόχοις κατελάμβανεν καὶ καθάπαξ οὐδὲν ἐκ τούτου τοὺς πολεμίους ἢ μικρὰ παντάπασιν ἔβλαπτεν. Ἡρώδης δὲ τοὺς ἐκ Μασάδας οἰκείους παραλαβὼν καὶ Ῥῆσαν τὸ φρούριον ᾔει πρὸς τὰ Ἱεροσόλυμα, συνῆπτε δ’ αὐτῷ τὸ μετὰ Σίλωνος στρατιωτικὸν καὶ πολλοὶ τῶν ἐκ τῆς πόλεως τὴν ἰσχὺν καταπλαγέντες. στρατοπεδευσαμένου δὲ κατὰ τὸ πρὸς δύσιν τῆς πόλεως κλίμα οἱ κατὰ τοῦτο τεταγμένοι φύλακες ἠκόντιζόν τε καὶ ἐτόξευον εἰς αὐτούς, ἐνίων δὲ καὶ κατὰ στῖφος ἐξιόντων καὶ τοῖς προτεταγμένοις εἰς χεῖρας ἐρχομένων, Ἡρώδης τὸ μὲν πρῶτον ἐκέλευσεν κηρύσσειν περὶ τὸ τεῖχος, ὡς ἐπ’ ἀγαθῷ τε παρείη τοῦ δήμου καὶ ἐπὶ σωτηρίᾳ τῆς πόλεως, μηδὲν μηδὲ τοῖς φανεροῖς τῶν ἐχθρῶν μνησικακήσων, ἀλλὰ παρέξων καὶ τοῖς διαφορωτάτοις ἀμνηστίαν τῶν εἰς αὐτὸν ἁμαρτημάτων. τοῦ δὲ Ἀντιγόνου πρὸς τὰ ὑπὸ τοῦ Ἡρώδου κηρυχθέντα λέγοντος πρός τε Σίλωνα καὶ τὸ τῶν Ῥωμαίων στράτευμα, ὡς παρὰ τὴν αὐτῶν δικαιοσύνην Ἡρώδῃ δώσουσιν τὴν βασιλείαν ἰδιώτῃ τε ὄντι καὶ Ἰδουμαίῳ, τουτέστιν ἡμιιουδαίῳ, δέον τοῖς ἐκ τοῦ γένους οὖσι παρέχειν ὡς ἔθος ἐστὶν αὐτοῖς. καὶ γὰρ εἰ νυνὶ πρὸς αὐτὸν ἔχουσιν χαλεπῶς καὶ τὴν βασιλείαν ὡς λαβόντα παρὰ Πάρθων ἀφελέσθαι διεγνώκασιν, εἶναί γε πολλοὺς ἐκ τοῦ γένους αὐτοῦ τοὺς ληψομένους κατὰ τὸν νόμον τὴν βασιλείαν, οἳ μηδὲν ἐξημαρτηκότες αὐτοὶ πρὸς Ῥωμαίους καὶ ἱερεῖς ὄντες οὐκ ἂν εἰκότα πάσχοιεν τῆς τιμῆς στερόμενοι. ταῦτα πρὸς ἀλλήλους αὐτῶν λεγόντων καὶ προελθόντων εἰς βλασφημίας Ἀντίγονος ἀμύνασθαι τοὺς ἀπὸ τοῦ τείχους ἐπέτρεπεν τοῖς ἰδίοις. οἱ δὲ τοξεύοντες καὶ πολλῇ προθυμίᾳ κατ’ αὐτῶν χρώμενοι ῥᾳδίως αὐτοὺς ἀπὸ τῶν πύργων ἐτρέψαντο.", "st": "14.15.2"}, {"sp": "N", "t": "Τότε καὶ Σίλων ἀπεκαλύψατο τὴν δωροδοκίαν· καθῆκε γὰρ τῶν οἰκείων στρατιωτῶν οὐκ ὀλίγους σπάνιν τῶν ἐπιτηδείων καταβοᾶν καὶ χρήματα εἰς τροφὰς αἰτεῖν καὶ χειμάσοντας ἀπάγειν εἰς τοὺς ἐπιτηδείους τόπους, τῶν περὶ τὴν πόλιν ὄντων ἐρήμων διὰ τὸ ὑπὸ τῶν Ἀντιγόνου στρατιωτῶν ἀνεσκευάσθαι, ἐκίνει τε τὸ στρατόπεδον καὶ ἀναχωρεῖν ἐπειρᾶτο. Ἡρώδης δ’ ἐνέκειτο παρακαλῶν τούς τε ὑπὸ τῷ Σίλωνι ἡγεμόνας καὶ τοὺς στρατιώτας μὴ καταλιπεῖν αὐτόν, Καίσαρός τε καὶ Ἀντωνίου καὶ τῆς συγκλήτου προτρεψάντων αὐτόν· προνοήσειν γὰρ αὐτῶν τῆς εὐπορίας καὶ παρέξειν αὐτοῖς ἀφθονίαν ὧν ἐπιζητοῦσιν ῥᾳδίως. καὶ μετὰ τὴν δέησιν εὐθὺς ἐξορμήσας εἰς τὴν χώραν οὐκέτ’ οὐδεμίαν Σίλωνι τῆς ἀναχωρήσεως πρόφασιν ὑπελίπετο· πλῆθος γὰρ ὅσον οὐδ’ ἤλπισέν τις τῶν ἐπιτηδείων ἐκόμισεν, τοῖς τε περὶ Σαμάρειαν ᾠκειωμένοις πρὸς αὐτὸν ἐπέστειλεν σῖτα καὶ οἶνον καὶ ἔλαιον καὶ βοσκήματα τά τε ἄλλα πάντα κατάγειν εἰς Ἱεριχοῦντα τοῦ μηδὲ τὰς ἑξῆς ἡμέρας εἰς χορηγίαν τοὺς στρατιώτας ἐπιλιπεῖν. οὐκ ἐλάνθανε δὲ ταῦτ’ Ἀντίγονον, ἀλλ’ εὐθὺς ἀπέπεμψεν κατὰ τὴν χώραν τοὺς εἴρξοντας καὶ λοχήσοντας τοὺς σιτηγοῦντας, οἱ δὲ πειθόμενοι τοῖς Ἀντιγόνου προστάγμασιν καὶ πολὺ πλῆθος ὁπλιτῶν περὶ Ἱεριχοῦντα ἀθροίσαντες παρεφύλασσον ἐπὶ τῶν ὀρῶν καθεσθέντες τοὺς τὰ ἐπιτήδεια κομίζοντας. οὐ μὴν Ἡρώδης τούτων πραττομένων ἠρέμει, δέκα δὲ σπείρας ἀναλαβών, ὧν πέντε μὲν Ῥωμαίων, πέντε δὲ Ἰουδαίων ἦσαν, καὶ μισθοφόρους μιγάδας πρὸς οἷς ὀλίγους τῶν ἱππέων ἐπὶ Ἱεριχοῦντα παραγίνεται, καὶ τὴν μὲν πόλιν ἐκλελειμμένην καταλαβών, πεντακοσίους δὲ τὰ ἄκρα κατειληφότας σὺν γυναιξὶν καὶ γενεαῖς, τούτους μὲν ἀπέλυσεν λαβών, Ῥωμαῖοι δὲ εἰσπεσόντες διήρπασαν τὴν πόλιν μεσταῖς ἐπιτυγχάνοντες παντοίων κειμηλίων ταῖς οἰκίαις. Ἱεριχοῦντος μὲν οὖν φρουρὰν καταλιπὼν ὁ βασιλεὺς ὑπέστρεψεν καὶ χειμάσουσαν τὴν Ῥωμαίων στρατιὰν εἰς τὰς προσκεχωρηκυίας διαφῆκεν Ἰδουμαίαν καὶ Γαλιλαίαν καὶ Σαμάρειαν. ἔτυχεν δὲ καὶ Ἀντίγονος παρὰ Σίλωνος ἀντὶ τῆς δωροδοκίας ὥστε ὑποδέξασθαι τοῦ στρατοῦ μοῖραν ἐν Λύδδοις θεραπεύων Ἀντώνιον. καὶ Ῥωμαῖοι μὲν ἐν ἀφθόνοις διῆγον ἀνειμένοι τῶν ὅπλων.", "st": "14.15.3"}, {"sp": "N", "t": "Ἡρώδῃ δ’ οὐκ ἐδόκει μένειν ἐφ’ ἡσυχίας, ἀλλ’ ἐπὶ τὴν Ἰδουμαίαν τὸν ἀδελφὸν Ἰώσηπον σὺν δισχιλίοις ὁπλίταις καὶ τετρακοσίοις ἱππεῦσιν ἐξέπεμψεν, αὐτὸς δ’ εἰς Σαμάρειαν παραγενόμενος καὶ καταθέμενος αὐτόθι τήν τε μητέρα καὶ τοὺς συγγενεῖς ἐξεληλυθότας ἤδη ἐκ τῶν Μασάδων ἐπὶ Γαλιλαίας ᾤχετο ἐξαιρήσων τινὰ τῶν χωρίων ὑπ’ Ἀντιγόνου φρουραῖς κατειλημμένα. διελθὼν δὲ εἰς Σέπφωριν νίφοντος τοῦ θεοῦ καὶ τῶν Ἀντιγόνου φρουρῶν ὑπεξελθόντων ἐν ἀφθόνοις ἦν τοῖς ἐπιτηδείοις. εἶτ’ ἐκεῖθεν λῃστῶν τινων ἐν σπηλαίοις κατοικούντων ἱππέων ἐπ’ αὐτοὺς ἴλην ἐκπέμπει καὶ ὁπλιτικοῦ τρία τέλη παῦσαι κακουργοῦντας ἐγνωκώς· ἔγγιστα δ’ ἦν ταῦτα κώμης Ἀρβήλων λεγομένης. εἰς δὲ τεσσαρακοστὴν ἡμέραν αὐτὸς ἧκεν πανστρατιᾷ, καὶ θρασέως ἐξελθόντων τῶν πολεμίων κλίνεται μὲν τὸ εὐώνυμον αὐτῶν κέρας τῆς φάλαγγος, ἐπιφανεὶς δ’ αὐτὸς μετὰ στίφους τρέπει μὲν εἰς φυγὴν τοὺς πάλαι νικῶντας, ἀναστρέφει δὲ τοὺς φεύγοντας. ἐνέκειτο δὲ διώκων τοὺς πολεμίους ἄχρι Ἰορδάνου ποταμοῦ φεύγοντας κατ’ ἄλλας ὁδούς, καὶ προσάγεται μὲν πᾶσαν τὴν Γαλιλαίαν πλὴν τῶν ἐν τοῖς σπηλαίοις κατοικούντων, διανέμει δὲ καὶ ἀργύριον κατ’ ἄνδρα δοὺς ἑκατὸν καὶ πεντήκοντα δραχμάς, τοῖς δὲ ἡγεμόσιν πολὺ πλέον, εἰς τὰ χειμάδια διέπεμψεν. καὶ ἐν τούτῳ Σίλων ἧκεν παρ’ αὐτὸν καὶ οἱ ἡγεμόνες τῶν ἐν τοῖς χειμαδίοις Ἀντιγόνου τροφὰς παρέχειν οὐ θέλοντος· μῆνα γὰρ οὐ πλέον αὐτοὺς ὁ ἀνὴρ ἔθρεψεν, διέπεμψεν δὲ καὶ πρὸς τοὺς κύκλῳ κελεύων τὰ κατὰ τὴν χώραν ἀνασκευάσασθαι καὶ εἰς τὰ ὄρη φεύγειν, ὡς μηδὲν ἔχοντες Ῥωμαῖοι λιμῷ διαφθαρεῖεν. Ἡρώδης δὲ τὴν μὲν τούτων πρόνοιαν Φερώρᾳ τῷ νεωτάτῳ τῶν ἀδελφῶν ἐπιτρέπει κελεύσας αὐτὸν ἅμα τειχίζειν καὶ Ἀλεξάνδρειον. ὁ δὲ ταχέως τε τοὺς στρατιώτας ἐν ἀφθονίᾳ πολλῇ τῶν ἀναγκαίων ἐποίησεν τό τε Ἀλεξάνδρειον ἠρημωμένον ἀνέκτισεν.", "st": "14.15.4"}, {"sp": "N", "t": "Ὑπὸ δὲ τὸν αὐτὸν χρόνον Ἀντώνιος μὲν διέτριβεν ἐν Ἀθήναις, κατὰ δὲ Συρίαν Οὐεντίδιος Σίλωνα μεταπεμπόμενος ἐπὶ τοὺς Πάρθους ἐπέστελλεν πρῶτον μὲν Ἡρώδῃ συλλαμβάνεσθαι τοῦ πολέμου, ἔπειτα δὲ καὶ ἐπὶ τὸν σφέτερον καλεῖν τοὺς συμμάχους. ὁ δ’ ἐπὶ τοὺς ἐν τοῖς σπηλαίοις λῃστὰς ἐπειγόμενος Σίλωνα μὲν ἐξέπεμψεν Οὐεντιδίῳ, αὐτὸς δ’ ἐπ’ ἐκείνους ἐξώρμησεν. ἦν δ’ ἐν ὄρεσιν τὰ σπήλαια τελέως ἐξερρωγόσιν καὶ κατὰ τὸ μεσαίτατον ἀποκρήμνους ἔχοντα τὰς παρόδους καὶ πέτραις ὀξείαις ἐμπεριεχόμενα· ἐν δὴ τούτοις μετὰ πάντων τῶν οἰκείων ἐφώλευον. ὁ δὲ βασιλεὺς λάρνακας ἐπ’ αὐτοὺς πηξάμενος καθίει ταύτας σιδηραῖς ἁλύσεσιν ἐκδεδεμένας διὰ μηχανῆς ἀπὸ κορυφῆς τοῦ ὄρους, μήτε κάτωθεν ἀνιέναι διὰ τὴν ὀξύτητα τοῦ ὄρους δυναμένων μήτε ἄνωθεν καθέρπειν ἐπ’ αὐτούς. αἱ δὲ λάρνακες πλήρεις ὁπλιτῶν ὑπῆρχον ἅρπας μεγάλας ἐχόντων, αἷς ἔμελλον ἐπισπώμενοι τοὺς ἀνθεστῶτας τῶν λῃστῶν κτείνειν καταφερομένους. τὴν μέντοι γε κάθεσιν τῶν λαρνάκων σφαλερὰν εἶναι συνέβαινεν κατὰ βάθους ἀπείρου γινομένην· ἔνδον μέντοι καὶ τὰ ἐπιτήδεια παρῆν αὐτοῖς. ὡς δὲ καθιμήθησαν αἱ λάρνακες, ἐτόλμα δ’ οὐδεὶς προσελθεῖν τοῖς ἐπὶ τῶν στομίων, ἀλλ’ ὑπὸ δέους ἠρέμουν, μάχαιράν τις περιζωσάμενος τῶν ὁπλοφόρων καὶ ταῖν χεροῖν ἀμφοτέραιν δραξάμενος ἁλύσεως, ἀφ’ ἧς ἤρτητο ἡ λάρναξ, κατῄει ἐπὶ τὰ στόμια δυσχεράνας τὴν τριβὴν τῶν ἐπεξιέναι μὴ τολμώντων. καὶ γενόμενος κατά τι στόμιον πρῶτα μὲν παλτοῖς ἀνακόπτει τοὺς πολλοὺς τῶν ἐπὶ τοῦ στομίου, ἔπειτα ἅρπῃ τοὺς ἀνθεστῶτας ἐπισπασάμενος ὠθεῖ κατὰ τοῦ κρημνοῦ, καὶ τοῖς ἔνδον ἐπεισελθὼν ἀποσφάττει τε πολλοὺς καὶ εἰσελθὼν εἰς τὴν λάρνακα ἡσύχασεν. φόβος δὲ εἶχε τοὺς ἄλλους τῆς οἰμωγῆς ἀκούοντας καὶ περὶ τῆς σωτηρίας ἀπόγνωσις, τὸ μέντοι γε πᾶν ἔργον ἐπέσχεν ἐπεξελθοῦσιν· καὶ πολλοὶ συγχωρήσαντος τοῦ βασιλέως ἐπικηρυκευσάμενοι παρέδοσαν σφᾶς ὑπηκόους εἶναι. τῷ δ’ αὐτῷ τρόπῳ καὶ κατὰ τὴν ἐπιοῦσαν ἐχρήσαντο τῇ προσβολῇ, μᾶλλον ἔτι τῶν ἐν τοῖς πήγμασιν ἐπεξιόντων αὐτοῖς καὶ κατὰ θύρας μαχομένων πῦρ τε ἐνιέντων. ἐξαφθέντων τε τῶν ἄντρων, πολλὴ γὰρ ἦν ἐν αὐτοῖς ὕλη, πρεσβύτης τις ἀπειλημμένος ἔνδον σὺν ἑπτὰ τέκνοις καὶ γυναικί, δεομένων τούτων ἐᾶσαι σφᾶς ὑπεξελθεῖν πρὸς τοὺς πολεμίους, στὰς ἐπὶ τοῦ στομίου τὸν ἀεὶ πρῶτον ἐξιόντα τῶν παίδων ἀπέσφαττεν, εἰς ὃ πάντας διεχρήσατο, ἔπειτα δὲ καὶ τὴν γυναῖκα, καὶ ῥίψας κατὰ τοῦ κρημνοῦ τοὺς νεκροὺς ἐπικατέβαλεν ἑαυτὸν θάνατον πρὸ δουλείας ὑπομένων. πολλὰ δὲ πρῶτον ὠνείδισεν τὸν Ἡρώδην εἰς ταπεινότητα καί τοι τοῦ βασιλέως, ἦν γὰρ ἄποπτα αὐτῷ τὰ γινόμενα, δεξιάν τε προτείνοντος καὶ πᾶσαν ἄδειαν. τὰ μὲν οὖν σπήλαια τούτων γενομένων ἤδη πάντα ἐκεχείρωτο.", "st": "14.15.5"}, {"sp": "N", "t": "Καταστήσας δ’ ὁ βασιλεὺς τοῖς αὐτόθι στρατηγὸν Πτολεμαῖον εἰς Σαμάρειαν ᾤχετο σὺν ἱππεῦσιν ἑξακοσίοις ὁπλίταις δὲ τρισχιλίοις ὡς μάχῃ κριθησόμενος πρὸς Ἀντίγονον. οὐ μὴν τῷ Πτολεμαίῳ προυχώρησεν τὰ κατὰ τὴν στρατηγίαν, ἀλλ’ οἱ καὶ πρότερον τὴν Γαλιλαίαν ταράξαντες ἐπεξελθόντες αὐτὸν διεχρήσαντο καὶ τοῦτο δράσαντες συμφεύγουσιν εἴς τε τὰ ἕλη καὶ τὰ δύσβατα τῶν χωρίων, ἄγοντες καὶ διαρπάζοντες τὴν αὐτόθι πᾶσαν. τιμωρεῖται δὲ τούτους Ἡρώδης ἐπανελθών· τοὺς μὲν γὰρ ἀναιρεῖ τῶν ἀποστάντων, τοὺς δ’ ἀναφυγόντας εἰς ἐρυμνὰ χωρία πολιορκίᾳ παραστησάμενος αὐτούς τε ἀπέκτεινεν καὶ τὰ ἐρύματα κατέσκαψεν. ἐζημίωσε δὲ παύσας οὕτως τὴν νεωτεροποιίαν καὶ τὰς πόλεις ἑκατὸν ταλάντοις.", "st": "14.15.6"}, {"sp": "N", "t": "Ἐν δὲ τῷ μεταξὺ Πακόρου πεσόντος ἐν μάχῃ καὶ τῶν Πάρθων πταισάντων πέμπει βοηθὸν ὁ Βεντίδιος Ἡρώδῃ Μαχαιρᾶν σὺν δυσὶ τάγμασι καὶ χιλίοις ἱππεῦσιν ἐπισπεύδοντος Ἀντωνίου. Μαχαιρᾶς μὲν οὖν Ἀντιγόνου καλοῦντος αὐτὸν παρὰ τὴν Ἡρώδου γνώμην χρήμασι διεφθαρμένος ἀπῄει ὡς κατασκεψόμενος αὐτοῦ τὰ πράγματα. τὴν δὲ διάνοιαν ὑπιδόμενος αὐτοῦ τὴν τῆς ἀφίξεως Ἀντίγονος οὐδὲ προσεδέξατο, ἀλλὰ σφενδόναις βάλλων αὐτὸν ἀνεῖργεν, καὶ διεδήλου τὴν αὐτοῦ προαίρεσιν. αἰσθόμενος δὲ τὰ βέλτιστα Ἡρώδην αὐτῷ παραινοῦντα καὶ αὐτὸν διημαρτηκότα παρακούσαντα τῆς ἐκείνου συμβουλίας, ἀνεχώρει μὲν εἰς Ἀμμαοῦν πόλιν, οἷς δὲ κατὰ τὴν ὁδὸν Ἰουδαίοις περιετύγχανεν τούτους ἀπέσφαττεν ἐχθρούς τε καὶ φίλους ὀργιζόμενος ὑπὲρ ὧν πεπόνθει. παροξυνθεὶς δ’ ἐπὶ τούτοις ὁ βασιλεὺς ἐπὶ Σαμαρείας ᾔει· πρὸς γὰρ Ἀντώνιον ἐγνώκει περὶ τούτων ἀφικέσθαι· δεῖσθαι γὰρ οὐχὶ τοιούτων συμμάχων, οἳ βλάψουσι μᾶλλον αὐτὸν ἢ τοὺς πολεμίους· ἐξαρκεῖν δὲ καὶ αὐτῷ πρὸς τὴν Ἀντιγόνου καθαίρεσιν. παρακολουθῶν δ’ ὁ Μαχαιρᾶς ἐδεῖτο μένειν· εἰ δὲ οὕτως ὥρμηκεν, ἀλλὰ τόν γε ἀδελφὸν αὐτοῦ Ἰώσηπον παρακαθιστάνειν σφίσι προσπολεμοῦσιν Ἀντιγόνῳ. καὶ διαλλάττεται μὲν πολλὰ τοῦ Μαχαιρᾶ δεηθέντος, καταλιπὼν δὲ τὸν Ἰώσηπον αὐτόθι σὺν στρατῷ παρῄνεσεν μὴ ἀποκινδυνεύειν μηδὲ τῷ Μαχαιρᾷ διαφέρεσθαι.", "st": "14.15.7"}, {"sp": "N", "t": "Αὐτὸς δὲ πρὸς Ἀντώνιον ἔσπευδεν, ἐτύγχανεν γὰρ πολιορκῶν Σαμόσατα τὸ πρὸς τῷ Εὐφράτῃ χωρίον, σὺν ἱππόταις τε καὶ πεζοῖς κατὰ συμμαχίαν αὐτῷ παροῦσιν. παραγενόμενος δ’ εἰς Ἀντιόχειαν καὶ πολλοῖς ἐπιτυχὼν ἠθροισμένοις καὶ πρὸς Ἀντώνιον μὲν σπουδὴν βαδίζειν ἔχουσιν, ὑπὸ δέους δὲ διὰ τὸ κατὰ τὰς ὁδοὺς ἐπιτίθεσθαι τοὺς βαρβάρους καὶ πολλοὺς ἀναιρεῖν οὐ τολμῶντας ἐξορμᾶν, παραθαρσύνας αὐτὸς ἡγεμὼν γίνεται τῆς ὁδοῦ. κατὰ δὲ σταθμὸν δεύτερον τῶν Σαμοσάτων ἐλόχα μὲν αὐτόθι τῶν βαρβάρων ἐνέδρα τοὺς φοιτῶντας πρὸς Ἀντώνιον, δρυμῶν δὲ τὰς εἰσβολὰς τὰς εἰς τὰ πεδία διαλαμβανόντων προλοχίζουσιν αὐτόθι τῶν ἱππέων οὐκ ὀλίγους ἠρεμήσοντας ἕως ἂν εἰς τὸ ἱππήλατον οἱ διεξιόντες ἔλθοιεν. ὡς δ’ οἱ πρῶτοι διεξῆλθον, ὀπισθοφυλακεῖ μὲν Ἡρώδης, προσπίπτουσι δὲ ἐξαπιναίως οἱ ἐκ τῆς ἐνέδρας ὄντες εἰς πεντακοσίους, καὶ τρεψαμένων τοὺς πρώτους ἐπιδραμὼν ὁ βασιλεὺς τῇ ῥύμῃ τῇ περὶ αὐτὸν παραχρῆμα μὲν ἀνακόπτει τοὺς πολεμίους, ἐπεγείρει δὲ τὸ τῶν οἰκείων φρόνημα καὶ θαρραλέους ἀπεργάζεται, καὶ τῶν πάλαι φευγόντων ἐξ ὑποστροφῆς μαχομένων ἐκτείνοντο πάντοθεν οἱ βάρβαροι. ἐπέκειτο δ’ ὁ βασιλεὺς ἀναιρῶν καὶ τὰ διηρπασμένα, πολλὰ δ’ ἦν σκευοφόρα καὶ ἀνδράποδα, πάντα ἀνασωσάμενος προῄει. καὶ πλειόνων αὐτοῖς ἐπιθεμένων τῶν ἐν τοῖς δρυμῶσιν, οἳ πλησίον τῆς εἰς τὸ πεδίον ἐκβολῆς ἦσαν, καὶ τούτοις προσμίξας αὐτὸς μετὰ στίφους καρτεροῦ τρέπεται καὶ πολλοὺς αὐτῶν ἀποκτείνας ἀδεᾶ τοῖς ἑπομένοις ὁδὸν παρεῖχεν· οἱ δὲ σωτῆρα καὶ προστάτην αὐτὸν ἐκάλουν.", "st": "14.15.8"}, {"sp": "N", "t": "Ἐπεὶ δὲ πλησίον τῶν Σαμοσάτων γεγόνει, πέμπει τὸ στράτευμα ὑπαντησόμενον Ἀντώνιος σὺν τῷ οἰκείῳ κόσμῳ τιμὴν Ἡρώδῃ ταύτην ἀπονέμων καὶ ἐπικουρίας ἕνεκα· τὴν γὰρ τῶν βαρβάρων ἀκηκόει κατ’ αὐτῶν ἐπίθεσιν. καὶ δὴ παρόντα τε εἶδεν ἀσμένως καὶ τὰ κατὰ τὴν ὁδὸν αὐτῷ πεπραγμένα μαθὼν ἐδεξιοῦτο καὶ τῆς ἀρετῆς ἐθαύμαζεν, αὐτός τε περιλαβὼν αὐτὸν Ἀντώνιος ὡς εἶδεν ἠσπάζετο προυτίμα τε νεωστὶ βασιλέα ἀποδείξας. Ἀντιόχου δὲ μετ’ οὐ πολὺ τὸ ἔρυμα παραδόντος καὶ διὰ τοῦτο παυσαμένου τοῦ πολέμου Σοσσίῳ μὲν Ἀντώνιος παραδίδωσιν παρακελευσάμενος δὲ Ἡρώδῃ συμμαχεῖν αὐτὸς ἐπ’ Αἰγύπτου ἐχώρει. καὶ Σόσσιος μὲν δύο τάγματα ἐπικουρικὰ Ἡρώδῃ προύπεμψεν εἰς τὴν Ἰουδαίαν, αὐτὸς δὲ μετὰ τοῦ πλείονος στρατοῦ ἠκολούθει.", "st": "14.15.9"}, {"sp": "N", "t": "Ἔτυχεν δ’ ἤδη κατὰ τὴν Ἰουδαίαν τεθνεὼς Ἰώσηπος τρόπῳ τοιούτῳ· λήθην μὲν ὧν αὐτῷ παρήγγειλεν ὁ ἀδελφὸς πρὸς Ἀντώνιον ἀπερχόμενος λαμβάνει, στρατοπεδευσάμενος δὲ ἀνὰ τὰ ὄρη, πέντε γὰρ αὐτῷ σπείρας Μαχαιρᾶ δόντος ἐπὶ Ἱεριχοῦντος ἠπείγετο βουλόμενος ἐκθερίσαι τὸν σῖτον αὐτῶν, καὶ νεοσυλλέκτου τοῦ Ῥωμαίων στρατεύματος ὄντος, καὶ πολέμων ἀπείρως ἔχοντος καὶ γὰρ πολὺ ἐκ Συρίας ἦν τὸ κατειλεγμένον, ἐπιθεμένων αὐτόθι τῶν πολεμίων, ἀποληφθεὶς ἐν δυσχωρίαις αὐτός τε ἀποθνήσκει γενναίως μαχόμενος καὶ τὸ στράτευμα πᾶν ἀπέβαλεν· ἓξ γὰρ σπεῖραι διεφθάρησαν. κρατήσας δὲ τῶν νεκρῶν Ἀντίγονος ἀποτέμνει τὴν Ἰωσήπου κεφαλὴν πεντήκοντα ταλάντων αὐτὴν ῥυομένου Φερώρα τἀδελφοῦ. καὶ μετὰ τοῦτο ἀποστάντες Γαλιλαῖοι τῶν παρὰ σφίσι δυνατῶν τοὺς τὰ Ἡρώδου φρονοῦντας ἐν τῇ λίμνῃ κατεπόντωσαν, καὶ τῆς Ἰουδαίας πολλὰ ἐνεωτερίσθη. Μαχαιρᾶς δὲ χωρίον Ηττον ἐξωχύρου.", "st": "14.15.10"}, {"sp": "N", "t": "Παρῆσαν δ’ ἄγγελοι τῶν πεπραγμένων πρὸς τὸν βασιλέα καὶ ἐν Δάφνῃ τῆς Ἀντιοχείας ἐδήλωσαν αὐτῷ τὴν κατὰ τὸν ἀδελφὸν τύχην, προσδεχομένῳ μέντοι καὶ αὐτῷ διά τινας ὀνείρων ὄψεις τρανῶς προφαινούσας τὸν τοῦ ἀδελφοῦ θάνατον. ἐπειχθεὶς οὖν κατὰ τὴν πορείαν ὡς κατὰ Λίβανον τὸ ὄρος γίνεται, ὀκτακοσίους μὲν τῶν αὐτόθι προσλαμβάνει, ἔχων δὲ καὶ Ῥωμαϊκὸν ἓν τάγμα εἰς Πτολεμαΐδα παραγίνεται, κἀκεῖθεν νυκτὸς ἀναστὰς μετὰ τοῦ στρατοῦ προῄει διὰ τῆς Γαλιλαίας. ὑπήντων δ’ οἱ πολέμιοι καὶ κρατηθέντες τῇ μάχῃ κατεκλείσθησαν εἰς χωρίον, ὅθεν ἦσαν ὡρμηκότες τῇ προτεραίᾳ· προσβολὰς δὴ τοὐντεῦθεν [ἕωθεν] ἐποιεῖτο, καὶ πολλοῦ χειμῶνος καταρραγέντος οὐδὲν ποιεῖν δυνάμενος ἀπάγει τὴν στρατιὰν εἰς τὰς πλησίον κώμας. ἐλθόντος δ’ αὐτῷ παρ’ Ἀντωνίου καὶ δευτέρου τάγματος οἱ τὸ χωρίον ἔχοντες φοβηθέντες νυκτὸς ἐξέλιπον αὐτό. καὶ ὁ βασιλεὺς ἔσπευδεν ἐπὶ Ἱεριχοῦντος τιμωρήσασθαι κατὰ νοῦν ἔχων αὐτοὺς ὑπὲρ τἀδελφοῦ. ἐπεὶ δὲ κατέζευξεν, εἱστία μὲν τοὺς ἐν τέλει, μετὰ δὲ τὴν συνουσίαν παρῆλθεν εἰς τὸ δωμάτιον ἀπολύσας τοὺς παρόντας. ἐνταῦθα ἴδοι τις ἂν τοῦ βασιλέως τὴν ἐκ τοῦ θεοῦ εὔνοιαν· πίπτει μὲν γὰρ ἡ στέγη τοῦ οἰκήματος, οὐδένα δὲ ἀπολαβοῦσα διέφθειρεν, ὥστε πάντας πιστεῦσαι τὸν Ἡρώδην εἶναι θεοφιλῆ, μέγαν οὕτω καὶ παράδοξον διαφυγόντα κίνδυνον.", "st": "14.15.11"}, {"sp": "N", "t": "Τῇ δ’ ὑστεραίᾳ τῶν πολεμίων ἑξακισχίλιοι ἀπ’ ἄκρων κατιόντες τῶν ὀρῶν εἰς μάχην ἐφόβουν τοὺς Ῥωμαίους. οἱ δὲ γυμνῆτες προσιόντες τοῖς παλτοῖς ἔβαλλον καὶ λίθοις τοὺς περὶ τὸν βασιλέα ἐξεληλυθότας αὐτόν τε παλτῷ τις παρὰ τὴν λαπάραν ἔβαλεν. Ἀντίγονος δ’ ἐπὶ τὴν Σαμάρειαν πέμπει στρατηγὸν Πάππον ὄνομα σὺν δυνάμει πολλῇ βουλόμενος παρασχεῖν τοῖς πολεμίοις δόξαν πολεμοῦντος ἐκ περιουσίας. ἀλλ’ ὁ μὲν Μαχαιρᾷ τῷ στρατηγῷ προσεκάθητο· Ἡρώδης δὲ πέντε πόλεις καταλαβὼν τοὺς ἐγκαταληφθέντας περὶ δισχιλίους ὄντας ἐφόνευσεν αὐτάς τε τὰς πόλεις ἐμπρήσας ἐπανῆλθεν ἐπὶ τὸν Πάππον· ἐστρατοπεδεύσατο δ’ οὗτος περὶ κώμην Ἰσάνας καλουμένην καὶ πολλῶν αὐτῷ προσρεόντων ἐκ τῆς Ἱεριχοῦς καὶ τῆς ἄλλης Ἰουδαίας, ἐπεὶ πλησίον γίνεται, τῶν πολεμίων ἐπεξελθόντων αὐτοῖς ὑπὸ θράσους συμβαλὼν κρατεῖ τῇ μάχῃ, καὶ τιμωρῶν τἀδελφῷ φεύγουσιν εἰς τὴν κώμην εἵπετο κτείνων. πεπληρωμένων δὲ τῶν οἰκήσεων ὁπλιτῶν καί τινων ἀναφευγόντων ἐπὶ τὰς στέγας κρατεῖ τούτων, καὶ τοὺς ὀρόφους τῶν οἴκων ἀνασκάπτων ἔμπλεα τὰ κάτω τῶν στρατιωτῶν ἑώρα ἀθρόων ἀπειλημμένων. τούτους μὲν οὖν πέτραις ἄνωθεν βάλλοντες σωρηδὸν ἐπ’ ἀλλήλοις ἀνῄρουν· καὶ θέαμα τοῦτο δεινότατον ἦν κατὰ τόνδε τὸν πόλεμον νεκρῶν τὸ πλῆθος ἀπείρων ἐντὸς τῶν τειχῶν ἐπ’ ἀλλήλοις κειμένων. τοῦτο τὸ ἔργον μάλιστα τὰ φρονήματα τῶν πολεμίων ἔκλασεν καραδοκούντων τὸ μέλλον· ἑωρῶντο γὰρ παμπληθεῖς πόρρωθεν συγγενόμενοι περὶ τὴν κώμην· οἳ τότε ἔφευγον, καὶ εἰ μὴ χειμὼν ἐπέσχεν βαθύς, ἧκεν ἂν καὶ ἐπὶ Ἱεροσόλυμα ἡ βασιλέως στρατιὰ θαρροῦσα τῷ νενικηκέναι, καὶ τὸ πᾶν ἦν ἂν εἰργασμένη· καὶ γὰρ Ἀντίγονος ἤδη τὴν παντελῆ φυγὴν ἐσκόπει καὶ ἀπανάστασιν ἐκ τῆς πόλεως.", "st": "14.15.12"}, {"sp": "N", "t": "Τότε μὲν οὖν ὁ βασιλεύς, ὀψία γὰρ ἦν, δειπνοποιεῖσθαι κελεύει τοὺς στρατιώτας, αὐτὸς δέ, ἐκεκμήκει γάρ, εἰσελθὼν εἴς τι δωμάτιον περὶ λουτρὸν ἦν. ἔνθα καὶ κίνδυνος αὐτῷ μέγιστος συνέπεσεν, ὃν κατὰ θεοῦ πρόνοιαν διέφυγεν· γυμνοῦ γὰρ ὄντος αὐτοῦ καὶ μετὰ παιδὸς ἑνὸς ἀκολούθου λουομένου [ἐν τῷ] ἐντὸς οἰκήματι τῶν πολεμίων τινὲς ὡπλισμένοι συμπεφευγότες αὐτόθι διὰ φόβον μεταξὺ λουομένου ὁ πρῶτος ὑπεξέρχεται ξίφος ἔχων γυμνὸν καὶ διὰ θυρῶν χωρεῖ, καὶ μετὰ τοῦτον δεύτερος καὶ τρίτος ὁμοίως ὡπλισμένοι, οὐδὲν βλάψαντες τὸν βασιλέα ὑπ’ ἐκπλήξεως, ἀγαπῶντες δὲ τὸ μηδὲν αὐτοὶ παθόντες εἰς τὸ πρόσθεν διεκπεσεῖν. τῇ δ’ ὑστεραίᾳ τὴν μὲν Πάππου κεφαλήν, ἀνῄρητο γάρ, ἀποκόψας Φερώρᾳ ἔπεμψεν ποινὴν ἀνθ’ ὧν ὁ ἀδελφὸς αὐτοῦ πάθοι· οὗτος γὰρ ἦν αὐτόχειρ ἐκείνου γεγενημένος.", "st": "14.15.13"}, {"sp": "N", "t": "Λήξαντος δὲ τοῦ χειμῶνος ἄρας ἐκεῖθεν ἐγγὺς τῶν Ἱεροσολύμων ἔρχεται καὶ πλησίον στρατοπεδεύεται τῆς πόλεως· τρίτον δὲ ἔτος τοῦτο ἦν αὐτῷ ἐξ οὗ βασιλεὺς ἐν Ῥώμῃ ἀποδέδεικτο. ἀναστρατοπεδευσάμενος δὲ καὶ πλησίον ἐλθὼν τοῦ τείχους κατὰ τὸ ἐπιμαχώτατον πρὸ τοῦ ἱεροῦ στρατοπεδεύεται προσβαλεῖν διεγνωκώς, ὡς καὶ πρότερόν ποτε Πομπήιος. τρισὶν δὲ διαλαβὼν χώμασιν τὸν τόπον πύργους ἀνίστα πολλῇ τε χειρὶ πρὸς τὸ ἔργον χρώμενος καὶ τέμνων τὴν πέριξ ὕλην. παρακαταστήσας δὲ τοῖς ἔργοις τοὺς ἐπιτηδείους, ἱδρυμένης ἔτι τῆς στρατιᾶς αὐτὸς εἰς Σαμάρειαν ἐπὶ τὸν γάμον ᾤχετο ἀξόμενος τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου θυγατέρα· ταύτην γὰρ ἦν ἐγγεγυημένος, ὥς μοι καὶ πρότερον εἴρηται.", "st": "14.15.14"}, {"sp": "N", "t": "Μετὰ δὲ τοὺς γάμους ἦλθεν μὲν διὰ Φοινίκης Σόσσιος προεκπέμψας τὴν δύναμιν διὰ τῆς μεσογαίας, ἦλθεν δὲ καὶ ὁ στρατὸς πλῆθος ἱππέων τε καὶ πεζῶν, παρεγένετο δὲ καὶ ὁ βασιλεὺς ἐκ τῆς Σαμαρείτιδος οὐκ ὀλίγον πρὸς τῷ πάλαι στρατὸν ἄγων· περὶ τρισμυρίους γὰρ ἦσαν. πάντες δ’ ἐπὶ τὸ Ἱεροσολυμιτῶν ἠθροίζοντο τεῖχος, καὶ διεκάθητο πρὸς τῷ βορείῳ τείχει τῆς πόλεως στρατιᾶς ἕνδεκα μὲν οὖσα τέλη ὁπλιτικοῦ, ἓξ δὲ χιλιάδες ἱππέων, ἄλλα δὲ ἐπικουρικὰ ἀπὸ τῆς Συρίας, δύο δ’ ἡγεμόνες, Σόσσιος μὲν ὑπ’ Ἀντωνίου σταλεὶς σύμμαχος, Ἡρώδης δ’ ὑπὲρ αὐτοῦ, ὡς Ἀντίγονον ἀφελόμενος τὴν ἀρχὴν ἀποδειχθέντα ἐν Ῥώμῃ πολέμιον αὐτὸς ἀντ’ ἐκείνου βασιλεὺς εἴη κατὰ τὸ τῆς συγκλήτου δόγμα.", "st": "14.16.1"}, {"sp": "N", "t": "Μετὰ δὲ πολλῆς προθυμίας καὶ ἔριδος ἅτε σύμπαντος ἠθροισμένου τοῦ πλήθους οἱ Ἰουδαῖοι τοῖς περὶ τὸν Ἡρώδην ἀντεπολέμουν κατειληθέντες ἐντὸς τοῦ τείχους, πολλά τε ἐπεφήμιζον περὶ τὸ ἱερὸν καὶ πολλὰ ἐπ’ εὐφημίᾳ τοῦ δήμου, ὡς ῥυσομένου τῶν κινδύνων αὐτοὺς τοῦ θεοῦ. τά τε ἐκτὸς τῆς πόλεως ἀπεσκευάσαντο, ὡς μηδ’ ὅσα τροφὴ δύναιτο εἶναι ὑπολιπεῖν ἢ ἀνθρώποις ἢ ὑποζυγίοις, λῃστείαις τε λάθρα χρώμενοι ἀπορίαν παρέσχον. ταῦτα δ’ Ἡρώδης συνιδὼν πρὸς μὲν τὰς λῃστείας ἐν τοῖς ἐπικαιροτάτοις τόποις παρελόχιζεν, πρὸς δὲ τὰ ἐπιτήδεια πέμπων ὁπλιτικὰ τέλη πόρρωθεν ἀγορὰν συνεκόμιζεν, ὡς ὀλίγου χρόνου πολλὴν ἀφθονίαν αὐτοῖς γενέσθαι τῶν ἀναγκαίων. ἦρτο δὲ συνεχῶς ἤδη πολλῆς χειρὸς ἐργαζομένης καὶ τὰ τρία χώματα εὐπετῶς· θέρος τε γὰρ ἦν καὶ οὐδὲν ἐμποδὼν πρὸς τὴν ἀνάστασιν οὔτ’ ἀπὸ τοῦ ἀέρος οὔτ’ ἀπὸ τῶν ἐργαζομένων, τά τε μηχανήματα προσάγοντες κατέσειον τὸ τεῖχος καὶ πάσαις ἐχρῶντο πείραις. οὐ μὴν ἐξέπληττον τοὺς ἔνδον, ἀλλὰ ἀντετεχνῶντο κἀκεῖνοι πρὸς τὰ παρὰ τούτων γινόμενα οὐκ ὀλίγα, ἐπεκθέοντές τε τὰ μὲν ἡμίεργα ἐνεπίμπρασαν τὰ δ’ ἐξειργασμένα, εἴς τε χεῖρας ἰόντες οὐδὲν κακίους τὰς τόλμας Ῥωμαίων ἦσαν, ἐπιστήμῃ δ’ ἐλείποντο. πρός τε τὰς μηχανὰς ἀντετείχιζον ἐρειπομένων τῶν πρώτων οἰκοδομημάτων, ὑπὸ γῆν τε ἀπαντῶντες ἐν ταῖς μεταλλεύσεσιν διεμάχοντο, ἀπονοίᾳ δὲ τὸ πλέον ἢ προμηθείᾳ χρώμενοι προσελιπάρουν τῷ πολέμῳ εἰς τοὔσχατον, καὶ ταῦτα μεγάλου στρατοῦ περικαθημένου σφᾶς καὶ λιμῷ ταλαιπωρούμενοι καὶ σπάνει τῶν ἐπιτηδείων· τὸν γὰρ ἑβδοματικὸν ἐνιαυτὸν συνέβη κατὰ ταῦτ’ εἶναι. ἀναβαίνουσιν δὲ ἐπὶ τὸ τεῖχος πρῶτον μὲν λογάδες εἴκοσι, ἔπειτα δὲ ἑκατόνταρχοι Σοσσίου· ᾑρέθη γὰρ τὸ μὲν πρῶτον τεῖχος ἡμέραις τεσσαράκοντα, τὸ δὲ δεύτερον πεντεκαίδεκα· καί τινες τῶν περὶ τὸ ἱερὸν ἐνεπρήσθησαν στοῶν, ἃς Ἡρώδης Ἀντίγονον ἐμπρῆσαι διέβαλεν, μῖσος αὐτῷ πραγματευόμενος παρὰ τῶν Ἰουδαίων γενέσθαι. ᾑρημένου δὲ τοῦ ἔξωθεν ἱεροῦ καὶ τῆς κάτω πόλεως εἰς τὸ ἔσωθεν ἱερὸν καὶ τὴν ἄνω πόλιν οἱ Ἰουδαῖοι συνέφυγον, δείσαντες δὲ μὴ διακωλύσωσιν αὐτοὺς οἱ Ῥωμαῖοι τὰς καθημερινὰς θυσίας ἐπιτελεῖν τῷ θεῷ, πρεσβεύονται ἐπιτρέψαι παρακαλοῦντες θύματα αὐτοῖς μόνον εἰσκομίζεσθαι· ὁ δ’ ὡς ἐνδωσόντων αὐτῶν συνεχώρει ταῦτα. καὶ ἐπεὶ μηδὲν ἑώρα γινόμενον παρ’ αὐτῶν ὧν ὑπενόει, ἀλλὰ ἰσχυρῶς ἀντέχοντας ὑπὲρ τῆς Ἀντιγόνου βασιλείας, προσβαλὼν κατὰ κράτος εἷλεν τὴν πόλιν. καὶ πάντα εὐθὺς φόνων ἦν ἀνάπλεα τῶν μὲν Ῥωμαίων ἐπὶ τῇ τριβῇ τῆς πολιορκίας διωργισμένων, τοῦ δὲ περὶ Ἡρώδην Ἰουδαϊκοῦ μηδὲν ὑπολιπεῖν σπεύδοντος ἀντίπαλον. ἐσφάττοντο δὲ παμπληθεῖς ἔν τε τοῖς στενωποῖς καὶ κατὰ τὰς οἰκίας συνωθούμενοι καὶ τῷ ναῷ προσφεύγοντες, ἦν τε οὔτε νηπίων οὔτε γήρως ἔλεος οὔτε ἀσθενείας γυναικῶν φειδώ, ἀλλὰ καίτοι περιπέμποντος τοῦ βασιλέως καὶ φείδεσθαι παρακαλοῦντος οὐδεὶς ἐκράτησεν τῆς δεξιᾶς, ἀλλ’ ὥσπερ μεμηνότες πᾶσαν ἡλικίαν ἐπεξῄεσαν. ἔνθα καὶ Ἀντίγονος μήτε τῆς πάλαι μήτε τῆς τότε τύχης ἔννοιαν λαβὼν κάτεισι μὲν ἀπὸ τῆς βάρεως, προσπίπτει δὲ τοῖς Σοσσίου ποσίν, κἀκεῖνος μηδὲν αὐτὸν οἰκτείρας πρὸς τὴν μεταβολὴν ἐπεκρότησεν μὲν ἀκρατῶς καὶ Ἀντιγόνην ἐκάλεσεν, οὐ μὴν ὡς γυναῖκά γε φρουρᾶς ἐλεύθερον ἀφῆκεν, ἀλλ’ ὁ μὲν δεθεὶς ἐφυλάττετο.", "st": "14.16.2"}, {"sp": "N", "t": "Πρόνοια δ’ ἦν Ἡρώδῃ κρατοῦντι τῶν πολεμίων τοῦ κρατῆσαι καὶ τῶν ἀλλοφύλων συμμάχων· ὥρμητο γὰρ τὸ ξενικὸν πλῆθος ἐπὶ θέᾳ τοῦ τε ἱεροῦ καὶ τῶν κατὰ τὸν ναὸν ἁγίων. ὁ δὲ βασιλεὺς τοὺς μὲν παρακαλῶν τοὺς δ’ ἀπειλῶν ἔστιν δ’ οὓς καὶ τοῖς ὅπλοις ἀνέστελλεν, ἥττης χαλεπωτέραν ἡγούμενος τὴν νίκην, εἴ τι τῶν ἀθεάτων παρ’ αὐτῶν ὀφθείη. διεκώλυέ τε καὶ τὰς κατὰ τὴν πόλιν ἁρπαγάς, πολλὰ διατεινάμενος πρὸς Σόσσιον, εἰ χρημάτων τε καὶ ἀνδρῶν Ῥωμαῖοι τὴν πόλιν κενώσαντες καταλείψουσιν αὐτὸν ἐρημίας βασιλέα, καὶ ὡς ἐπὶ τοσούτῳ πολιτῶν φόνῳ βραχὺ καὶ τὴν τῆς οἰκουμένης ἡγεμονίαν ἀντάλλαγμα κρίνει. τοῦ δὲ ἀντὶ τῆς πολιορκίας τὰς ἁρπαγὰς δικαίως τοῖς στρατιώταις ἐπιτρέπειν φαμένου, αὐτὸς ἔφη διανεμεῖν ἐκ τῶν ἰδίων χρημάτων τοὺς μισθοὺς ἑκάστοις. οὕτως τε τὴν λοιπὴν ἐξωνησάμενος πόλιν τὰς ὑποσχέσεις ἐπλήρωσεν· λαμπρῶς μὲν γὰρ ἕκαστον στρατιώτην, ἀναλόγως δὲ τοὺς ἡγεμόνας, βασιλικώτατα δ’ αὐτὸν ἐδωρήσατο Σόσσιον, ὡς πάντας ἀπελθεῖν χρημάτων εὐποροῦντας.", "st": "14.16.3"}, {"sp": "N", "t": "Τοῦτο τὸ πάθος συνέβη τῇ Ἱεροσολυμιτῶν πόλει ὑπατεύοντος ἐν Ῥώμῃ Μάρκου Ἀγρίππα καὶ Κανιδίου Γάλλου ἐπὶ τῆς ἑκατοστῆς ὀγδοηκοστῆς καὶ πέμπτης ὀλυμπιάδος τῷ τρίτῳ μηνὶ τῇ ἑορτῇ τῆς νηστείας, ὥσπερ ἐκ περιτροπῆς τῆς γενομένης ἐπὶ Πομπηίου τοῖς Ἰουδαίοις συμφορᾶς· καὶ γὰρ ὑπ’ ἐκείνου τῇ αὐτῇ ἑάλωσαν ἡμέρᾳ μετὰ ἔτη εἰκοσιεπτά. Σόσσιος δὲ χρυσοῦν ἀναθεὶς τῷ θεῷ στέφανον ἀνέζευξεν ἀπὸ Ἱεροσολύμων Ἀντίγονον ἄγων δεσμώτην Ἀντωνίῳ. δείσας δὲ Ἡρώδης μὴ φυλαχθεὶς Ἀντίγονος ὑπ’ Ἀντωνίου καὶ κομισθεὶς εἰς Ῥώμην ὑπ’ αὐτοῦ δικαιολογήσηται πρὸς τὴν σύγκλητον, ἐπιδεικνὺς αὐτὸν μὲν ἐκ βασιλέων, Ἡρώδην δὲ ἰδιώτην, καὶ ὅτι προσῆκεν αὐτοῦ βασιλεύειν τοὺς παῖδας διὰ τὸ γένος, εἰ καὶ αὐτὸς εἰς Ῥωμαίους ἐξήμαρτεν· ταῦτα φοβούμενος πολλοῖς χρήμασι πείθει τὸν Ἀντώνιον ἀνελεῖν Ἀντίγονον. οὗ γενομένου τοῦ δέους μὲν Ἡρώδης ἀπαλλάσσεται, παύεται δ’ οὕτως ἡ τοῦ Ἀσσαμωναίου ἀρχὴ μετὰ ἔτη ἑκατὸν εἰκοσιέξ. οἶκος λαμπρὸς οὗτος ἦν καὶ διάσημος γένους τε ἕνεκα καὶ τῆς ἱερατικῆς τιμῆς ὧν τε ὑπὲρ τοῦ ἔθνους οἱ γονεῖς αὐτοῦ διεπράξαντο. ἀλλ’ οὗτοι μὲν διὰ τὴν πρὸς ἀλλήλους στάσιν τὴν ἀρχὴν ἀπέβαλον, μετέβη δ’ εἰς Ἡρώδην τὸν Ἀντιπάτρου οἰκίας ὄντα δημοτικῆς καὶ γένους ἰδιωτικοῦ καὶ ὑπακούοντος τοῖς βασιλεῦσιν. καὶ τοῦτο μὲν τὸ τέλος τῆς Ἀσσαμωναίων γενεᾶς παρειλήφαμεν.", "st": "14.16.4"}], []);})();
